--
-- Table structure for table `movies`
--

DROP TABLE IF EXISTS `movies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `movies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `release_year` smallint(6) NOT NULL,
  `directors_key` varchar(64) NOT NULL,
  `runtime_minutes` smallint(6) NOT NULL,
  `watched_on` date NOT NULL,
  `medium_id` int(11) DEFAULT NULL,
  `overall_score` tinyint(4) DEFAULT NULL,
  `story_score` tinyint(4) DEFAULT NULL,
  `picture_score` tinyint(4) DEFAULT NULL,
  `music_score` tinyint(4) DEFAULT NULL,
  `sound_score` tinyint(4) DEFAULT NULL,
  `review` mediumtext DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_movies_title_year_directors` (`title`,`release_year`,`directors_key`),
  KEY `ix_movies_medium_id` (`medium_id`),
  KEY `ix_movies_watched_on_title` (`watched_on` DESC,`title`,`id` DESC),
  CONSTRAINT `fk_movies_media` FOREIGN KEY (`medium_id`) REFERENCES `media` (`id`),
  CONSTRAINT `ck_movies_runtime_minutes` CHECK (`runtime_minutes` between 1 and 999),
  CONSTRAINT `ck_movies_overall_score` CHECK (`overall_score` is null or `overall_score` between 1 and 10),
  CONSTRAINT `ck_movies_story_score` CHECK (`story_score` is null or `story_score` between 1 and 10),
  CONSTRAINT `ck_movies_picture_score` CHECK (`picture_score` is null or `picture_score` between 1 and 10),
  CONSTRAINT `ck_movies_music_score` CHECK (`music_score` is null or `music_score` between 1 and 10),
  CONSTRAINT `ck_movies_sound_score` CHECK (`sound_score` is null or `sound_score` between 1 and 10)
) ENGINE=InnoDB AUTO_INCREMENT=1240 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `movies`
--

SET @OLD_AUTOCOMMIT=@@AUTOCOMMIT, @@AUTOCOMMIT=0;
LOCK TABLES `movies` WRITE;
/*!40000 ALTER TABLE `movies` DISABLE KEYS */;
INSERT INTO `movies` VALUES
(1,'The Bone Collector',1999,'1',117,'2000-10-02',2,7,7,8,9,8,'Goede muziek, voorspelbare film. Het thema is weinig origineel, maar toch is dit een redelijk meeslepende film. Toch onderscheidt deze film zich niet echt. Er is niet zoveel speciaals aan, maar wat er is, is heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(2,'The Sixth Sense',1999,'2',107,'2000-09-21',2,9,9,8,8,9,'Verrassend goed, goede muziek, goede acteurs. Een origineel thema dat optimaal uitgebuit wordt. Actie, humor, emotie,… Alles zit erin. Een klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(3,'Bringing out the Dead',2000,'3',116,'2000-11-25',2,7,6,6,5,7,'Eigenlijk meer een komedie. Kille Bronx-sfeer. Sterke acteerprestaties en heel wat humoristische momenten. Buiten het feit dat het niet is wat de omschrijving voorspelt, is dit een redelijke film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(4,'Teaching mrs. Tingle',2000,'4',96,'2000-11-26',3,5,6,8,5,5,'Teleurstellende film, genre Scream, maar leuk om te zien. Het is wel de zoveelste tienerfilm, die totaal niets nieuws brengt. Niet echt een aanrader, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(5,'Stigmata',2000,'5',98,'2000-12-09',2,8,9,10,7,9,'Genre Exorcist. Veel extra\'s en redelijke muziek. Goed gebruik van geluid. Om met een bende te bekijken. Het verhaal zit goed, en wordt perfect stukje bij beetje onthuld. Zeker een goede score waardig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(6,'Ressurection',1999,'6',112,'2000-12-21',2,7,8,9,5,6,'Begint als goedkope Seven-rip, maar evolueert naar goede film. Soort samenvoeging van \"The Bone Collector\" en \"Seven\". Weinig boeiend, en alleen goed als men eerder vermelde films nog niet heeft gezien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(7,'The Ninth Gate',2000,'7',125,'2000-12-26',2,7,9,7,4,5,'Een alternatieve film met ingewikkelde verhaallijn. Om eens iets anders te zien. Muziekeffect ontbreekt, weinig extra\'s, maar de film zelf is zeer goed. Jammer, maar met een groter budget had dit een klassieker kunnen zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(8,'Amistad',1997,'8',152,'2001-01-01',4,9,8,7,10,10,'Goede film, zonder meer. Meeslepend. Toch wat voorspelbaar en suggestief als het op de ontknoping aankomt. Je krijgt geen objectieve kijk op de zaak. Maar het is natuurlijk geen documentaire. Kortom: heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(9,'Dead Poets Society',1989,'9',124,'2001-01-04',3,8,8,8,5,7,'Film die nooit echt uit de inleiding raakt. Het eindigt voor je het weet. Toch aangrijpend en soms ook een beetje leerrijk. Robin Williams zet een sterke prestatie neer. Absoluut onvoorspelbare film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(10,'Donnie Brasco',1997,'10',126,'2001-01-11',4,9,9,6,8,9,'Meeslepende film met degelijk acteerwerk. Goed uitgetekende personages. Je kan je goed inleven in deze maffiafilm. Een FBI-agent die undercover een vriendschapsrelatie opbouwt met een maffioso met als gevolg een knagend geweten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(11,'Lost Souls',2001,'11',102,'2001-01-27',5,6,6,8,9,7,'Het is eigenlijk een zoveelste demonische thriller, met weinig nieuws. De karakters en personages zijn niet echt duidelijk. Alleen in de bioscoop zit de spanning er goed in. Voor als je niets anders hebt, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(14,'Money Plays',1997,'12',92,'2001-02-06',4,1,3,1,1,5,'Er gebeurt absoluut niets in deze film. Dit is een film waarbij je een inspanning moet leveren om hem volledig te bekijken. De grootste prutsfilm die ik ooit heb bekeken. Ik heb het einde met heel erg veel moeite gehaald.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(15,'Striking Distance',1993,'13',101,'2001-02-08',4,7,6,8,6,7,'Dit is een no brain actiefilm. De actiescènes hebben net dat iets meer wat in andere films ontbreekt. Dit maakt het angstaanjagend realistisch. De film zelf is er een om niet echt bij na te denken en gewoon te genieten van de knallende actie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(17,'American History X',1998,'14',119,'2001-01-20',8,9,10,8,9,7,'Dit is een megamachtige film. Het heeft een educatieve waarde door de originele aanpak van het racisme. Het is eens iets anders dan die \"gewone\" drama\'s. Deze film is goed om er enkele dagen niet goed van te zijn. Positief bedoeld.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(18,'The Gift',2000,'15',111,'2001-03-17',5,7,9,6,7,8,'Dit is een film over een bovennatuurlijk iets. Alles is goed in beeld gebracht, maar het is wel voorspelbaar. Het is leuk om een keer te zien en af en toe ook wel meeslepend, maar er zat meer in. 13-in-een-dozijn-film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(19,'What Lies Beneath',2000,'16',129,'2001-03-14',5,9,10,9,9,9,'Dit is een horrorthriller eerste klas. Een mega spookachtige spannende verschietachtige film, waarbij Scream plots op Plop in de Wolken lijkt. Een overdosis van deze film is echt wel dodelijk. Maar misschien is dit al veel minder erg in de huiskamer. Een van de absolute toppers!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(20,'Volcano',1997,'17',104,'2001-03-24',4,7,7,6,6,9,'Dit is een vlammende actiefilm met flitsende, maar soms wat mindere, special effects. Lekker spannend dus, maar kijk niet te kritisch. Het budget was nochtans hoog genoeg. Kijk dan liever naar Dante\'s Peak.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(21,'48 Hrs',1982,'18',97,'2001-03-24',4,6,6,5,7,6,'Dit is een, volgens mij, eerder zwakke film. De humor is soms ver te zoeken en de clichés druipen ervan af. Murphy heeft al beter gedaan. Niet echt iets om voor thuis te blijven. Ik begrijp niet waarom dit zo\'n klassieker is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(22,'The Silence of the Lambs',1991,'19',118,'2001-03-24',3,9,10,7,8,7,'Dit is een klassieker. Volledige ontleding van de karakters. Meeslepend tot en met. Goede muziek, extreem goed geacteerd. Je moet dit gezien hebben.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(23,'Double Team',1997,'20',90,'2001-04-06',4,8,9,9,5,7,'Spetterende actiefilm met een verhaal achter. Hier kun je over nadenken en is redelijk realistisch. Ook de humor is nadrukkelijk aanwezig. Onverwacht leuke film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(24,'Hollow Man',2000,'21',112,'2001-04-07',3,7,6,9,6,8,'Film waar je niet bij mag nadenken, want er zitten wat logische fouten in. Wel goed beeld en heel goede special effects. Met dit thema kon wel wat geloofwaardigers gemaakt worden. Jammer, maar helaas…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(25,'Traffic',2000,'22',147,'2001-04-03',5,8,9,10,6,7,'Alternatieve film. Enkele verhalen lopen door elkaar en zijn niet echt met elkaar gelinkt. Deze film is niet zo goed als je kijkt om een ontspanned feel-good verhaaltje te zien. Realisme en geloofwaardigheid is benadrukt. Dit leuke kijkstuk stemt tot nadenken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(26,'The Perfect Storm',2000,'23',125,'2001-04-30',3,6,7,7,9,6,'Klassieke rampenfilm naar waar gebeurde feiten opgedragen aan... blablabla. Niet echt een aanrader, wel om depri te worden. Slechts in noodgevallen te bekijken. Veel te traag en langdradig begin. Dan begint het spannender te worden, maar zonder pieken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(27,'The Edge',1997,'24',125,'2001-05-18',4,8,7,9,8,7,'Redelijke film. Niets speciaals aan. Wel eens leuk om te zien. Schitterende acteurs. Hollywood-gehalte bleef beperkt al kon wat slijm niet ontbreken. Indrukwekkende beelden. Verhaal is wel een beetje mager. Al bij al een matige film waar de muziek en de acteurs opvallen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(28,'American Pie',1999,'25',97,'2001-05-21',8,8,9,8,6,7,'Een indrukwekkende komedie. Teert iets te veel op de tienervisie, maar is toch een niveaufilm. Leuk om de sfeer erin te krijgen. Dit is ongetwijfeld de beste tienerfilm, maar het blijft een tienerfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(29,'Big Daddy',1999,'26',93,'2001-05-24',8,6,4,8,6,6,'Redelijk slappe komedie. Weinig originaliteit. Stuk of 2 goede scènes. Niet aan te raden, dus. Een commercieel uitgebuite film, zonder veel aandacht voor de film zelf.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(30,'Good Will Hunting',1997,'27',121,'2001-05-24',8,8,9,7,8,8,'Prachtig meeslepend drama dat handelt over een hoogbegaafde en zijn problemen. Leuk om volgen, vooral de psychologische steekproeven. Zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(32,'Unforgiven',1992,'28',130,'2001-05-26',4,8,8,8,7,9,'Deze film geeft een ander beeld van de Western. De cowboys zijn hier nu menselijk voorgesteld en het verhaal mag er ook wezen. Het is een aangename film om naar te kijken die absoluut niet gaat vervelen, ondanks zijn lange duur. In de categorie Alternatief scoort deze film goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(33,'GoldenEye',1995,'29',130,'2001-06-01',4,7,7,10,9,8,'Nog een Bondfilm. Klassiek patroon, overdreven veel explosies en onmogelijke actiescènes. Aangenaam om naar te kijken als er niet te veel moet nagedacht worden. In het Bondgenre is dit een topper door de fantastische speciale effecten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(34,'Live and Let Die',1973,'30',119,'2001-06-08',4,7,8,6,7,6,'Dit is een ouderwetse bondfilm. Je ziet duidelijk het verschil met de nieuwe: Het verhaal zit veel beter in elkaar omdat het gebaseerd is op een boek. Voor de rest is het een doodgewone Bondfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(35,'Sleepers',1996,'31',141,'2001-06-09',4,8,9,8,6,8,'Dit is een film die eigenlijk matig is. Ik verwachtte meer actie, maar het is een zuivere psychologische thriller. Het doet een aanslag op de American Dream van de jaren 60. Het is ook een katholieke film waar wraak het succesvolle hoofdthema is. Vind de tegenstelling…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(36,'Trainspotting',1996,'32',94,'2001-06-16',3,9,9,8,8,9,'Dit is een soort American Pie met minder tienergehalte en veel minder gecensureerd. Gewoon leuk om zien. Een echte klassieker, met drama en ook humor. Drugs worden eerst gepropageerd en daarna zie je de nadelen. Zoals American History X dus met meer humor.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(37,'Scary Movie',2000,'33',88,'2001-06-16',8,9,10,9,6,9,'Deze ongelooflijk goede parodie op allerlei andere tienerthrillers is echt geniaal. Een beetje filmkennis van vooraf is wel gewenst. Pure fun voor wie het tienergenre kotsbeu is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(38,'Born on the Fourth of July',1989,'34',140,'2001-07-02',4,8,9,6,7,8,'Dit is een echte filmklassieker. Het is eigenlijk geen oorlogsfilm, maar wel een anti-oorlogsfilm. De psychische overgang van geïndoctrineerde marinier naar getraumatiseerde oorlogstegenstander wordt meesterlijk weergegeven. Soms vallen de clichés op, maar dat is dan ook het enige minpunt van de film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(39,'The Great Escape',1963,'35',169,'2001-07-13',4,8,9,5,7,6,'Dit is een alternatieve oorlogsfilm. De lange duur valt onmiddellijk op, maar deze film verveelt nooit. Er is nog geen enkel Hollywoodcliché aanwezig. Verrassende verhaallijnen en grondige psychologische uittekeningen zijn veelal te vinden. Een film waarvan de beeldkwaliteit het enige nadeel is. En dat het haar van de gevangenen altijd goed ligt, ook na een ontsnappingspoging, is redelijk onecht. Toch is het beeld fantastisch vergeleken met films uit hetzelfde jaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(40,'The Crush',1993,'36',100,'2001-07-29',4,7,8,9,6,6,'Goede thriller over een zieke tiener die hopeloos verliefd is op een veel oudere man. De evolutie van onschuldig naar misdadig wordt mooi in beeld gebracht. Het is meeslepend en toch niet moeilijk. Alleen het einde valt tegen. En dat is toch een van de belangrijkste zaken…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(41,'Without Consent',1994,'37',100,'2001-07-30',4,6,7,6,6,6,'Dit drama is redelijk te doen, maar compleet voorspelbaar. Het begin is meeslepend, maar op het einde verwatert de kern van het verhaal en wordt het een gewoon drama zonder meerwaarde. Goed begin, slecht vervolg.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(42,'Down Periscope',1996,'38',92,'2001-07-30',3,8,8,8,7,8,'Dit is een komedie die het niet moet hebben van de absurde humor. Maar deze is toch heel goed. Het begin van de film is puur komedie en het einde is meer het typische B-komedie hollywoodverhaal. Al bij al een aanrader. Verstand op nul en achterover leunen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(43,'The Jewell of the Nile',1985,'39',115,'2001-07-30',3,5,5,4,6,5,'Deze voorganger van de Indiana Jones-series is ook qua kwaliteit de voorganger. Het verhaal is nooit meeslepend en zelfs niet spectaculair. Geen aanrader dus, maar als je echt niets anders te doen hebt…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(44,'The Hitcher',1986,'40',97,'2001-08-13',3,7,8,6,7,7,'Goeie thriller zonder meer. Soms mag je wel niet te veel nadenken. Er zitten veel kleine foutjes in bv. in tijd/ruimte en ook wat voorspelbare clichés. De herkenbaarheid en meeslependheid maakt deze film toch boeiend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(45,'Star Wars: Episode IV - A New Hope',1977,'41',121,'2001-08-14',3,9,10,7,8,7,'Deze absolute filmklassieker is het begin van een zesdelige reeks films. Boeiend zonder meer, beter dan verwacht. Ook de speciale effecten zijn ondanks de ouderdom nog acceptabel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(46,'Scary Movie 2',2001,'42',82,'2001-08-14',5,9,10,9,6,8,'Parodie op heel wat films. Dit zorgt ervoor dat de film een zwakker verhaal heeft dan zijn voorganger, maar dit schaad het komediegehalte niet. Net als Scary Movie is dit een echte aanrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(48,'Star Wars: Episode V - The Empire Strikes Back',1980,'43',124,'2001-08-14',3,9,7,8,8,8,'Dit is het vervolg van de eerste film (episode IV). Het verhaal is heel sterk en boeit ook enorm, maar ik kan me niet van de indruk ontdoen dat het een soort soapaflevering is en geen echte film. Het verhaal loopt gewoon door zonder inleiding en een afgesloten einde heeft het ook niet. Toch is deze film algemeen sterker dan zijn voorganger, maar niet qua verhaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(49,'Star Wars: Episode VI - The Return of the Jedi',1983,'44',132,'2001-08-14',3,9,9,9,8,8,'Dit slot van het zesdelige verhaal is de kers op de taart. Na een ronduit zwak begin wordt de film beter dan zijn twee voorgangers voor allerlei redenen. Het echte spektakel blijft uit, maar dat komt de spanning wel ten goede.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(50,'Book of Shadows: Blair Witch 2',2000,'45',90,'2001-08-15',3,8,7,9,7,9,'Als dit de opvolger van The Blair Witch Project moet voorstellen, is het een echte flop geworden. Het verhaal is wel leuk om volgen, maar het is geen uitzonderlijke film meer zoals zijn voorganger. Dit is eerder een groot uitgevallen X-files-aflevering. Geluid en beeld zijn wel fantastisch.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(51,'Dracula 2000',2000,'46',99,'2001-08-19',5,8,8,9,8,9,'Dit is een verbazingwekkend goede film. Het is totaal niet het typische vampierenverhaal, maar wel een nieuw verhaal dat perfect aansluit op het originele, zonder het originele aan te tasten. Beeld en geluid zijn prachtig. Jammer dat er een ontknoping moest komen. Een open einde was misschien beter geweest…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(52,'What Women Want',2000,'47',126,'2001-08-29',3,6,6,8,6,7,'Dit is een verstand-op-nul film. Af en toe wat schaarse goede, met moeite lachwekkend te noemen, momenten die afgewisseld worden met een verhaallijn die ongeveer alle clichés van Hollywood bevat. Toch is de film amusant om volgen door het originele thema. Maar met het thema dat een man de gedachten van vrouwen kan lezen, kan veel meer gedaan worden dan wat we in deze film te zien krijgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(53,'Dead Cold',1995,'48',91,'2001-09-06',4,6,6,7,5,6,'Dit is een thriller zoals er al velen zijn. De film komt enorm traag op gang. Het inleidende verhaal duurt zowat een uur. Dan begint de actie en er is één verrassende wending. Voor de rest is dit een voorspelbare film. Niet echt een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(54,'Stir of Echoes',1999,'49',99,'2001-09-09',3,8,7,9,8,9,'Dit is een film die eigenlijk een remake is van The Sixth Sense. Het gaat ongeveer over hetzelfde, maar er is iets meer actie. Hierdoor is het verhaal minder meeslepend en verrassend, maar het zit toch goed in elkaar. Zeker een genietbare film!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(55,'Planet of the Apes',2001,'50',119,'2001-09-14',5,8,7,9,7,8,'Deze film is een remake van de oudere films. Het blijft echter een klassieker en het thema is origineel. Het verhaal zit goed in elkaar. De beeldeffecten zijn goed. Maar het verhaal mist diepgang en het einde is eerder zwak. Best genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(56,'The Beach',2000,'32',119,'2001-09-23',2,7,7,9,9,8,'Dit is een meevaller. Leonardo DiCaprio is het enige minpunt aan deze film. De film schept een speciaal sfeertje. Het is heel leuk om volgen, maar de spanning ontbreekt. Leuk om te zien is de verborgen kritische kijk op het toerisme en het hedendaagse leven. De film bestaat uit prachtige beelden en geluiden. Het verhaal is ook sterk. Het slot laat het wat afweten. Toch een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(57,'Mission Impossible',1996,'51',110,'2001-10-11',8,8,7,9,8,8,'Dit is een heel geslaagde actiefilm. Het verhaal zit goed in mekaar en je moet er echt met je gedachten bij zijn om te kunnen volgen. Toch is het einde compleet onrealistisch en laat de indentificatie met de personages veel te wensen over. Hierdoor wordt je nooit echt meegesleept in het verhaal, tenzij bij de inleiding.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(58,'American Pie 2',2001,'52',104,'2001-10-18',5,9,10,8,9,9,'Dit is een ongelooflijk goede film. De sequel is nog beter dan zijn voorganger. Een absoluut prachtstuk. Er zijn wel enkele voorwaarden. Droge humor mag geen taboe zijn. Het onderwerp \"sex\" ook niet. En American Pie moet nog in je achterhoofd zitten om bepaalde oneliners te begrijpen. Prachtige muziek en beeld.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(59,'Unbreakable',2000,'53',106,'2001-11-09',8,8,9,10,7,8,'Dit is een film van de makers van The Sixth Sense. Het genre is ook vergelijkbaar. Toch blijft dit een steengoede film als je wat tijd tussen het bekijken van The Sixth Sense en Unbreakable laat. Het einde is meesterlijk. Soms mist de film wel wat tempo, maar dit versterkt andere aspecten zoals verrassing. Ook over de perspectieven werd heel goed nagedacht. Niets dan lof dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(60,'Blade Runner',1982,'54',117,'2001-11-22',4,8,9,8,6,7,'Dit is een film met een ijzersterk verhaal. De computereffecten zijn heel goed voor hun tijd. Toch komt er nooit echt spanning in het verhaal. Hoewel je niet echt meegesleept wordt met het verhaal, is deze film toch een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(61,'The Lottery',1996,'55',120,'2001-11-27',4,8,9,7,6,9,'Deze film werd als een horrorfilm aangekondigd, maar is eigenlijk meer een thriller. Het verhaal is ijzersterk, een beetje Twin Peaks-achtig. Hollywood-clichés komen niet voor. Toch wat tekort aan actie. Deze film verveelt niet. Een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(62,'Miss Congeniality',2000,'56',109,'2001-12-04',8,7,7,9,6,7,'Dit is een onverwacht leuke film. Al bij al toch matig, maar door de lage verwachtingen waarmee ik naar de film vertrok, is dit toch goed meegevallen. Niets nieuws, maar toch leuk om te volgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(63,'The Wedding Planner',2001,'57',103,'2001-12-04',8,5,5,6,6,6,'Dit is een normale slijmfilm. Helemaal niets nieuws onder de zon en voorspelbaarheid troef. Liefhebbers van het genre worden weer eens op hun wenken bediend, maar qua inhoud is dit een grote 0. Nog een geluk dat mooie Jennifer Lopez de hoofdrol speelt. Toch nog iets te zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(64,'The Cell',2000,'58',107,'2001-12-04',8,8,9,10,8,10,'Dit is een heel originele, aangrijpende thriller-horrorfilm. Kijk hier niet naar alleen in het donker. Volledig meeslepend, geen clichés, niets overdreven, en vooral superspannend en sfeerscheppend. Niet voor gevoelige zielen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(65,'Patriot Games',1992,'59',117,'2001-12-17',4,8,9,8,7,7,'Deze klassieker wordt aangekondigd als een spannende actiefilm. Het is ook zo, maar het heeft iets meer. Het is een meeslepend verhaal, dat niet onrealistisch is, maar toch soms voorspelbaar. Gewoon een aangename film om te volgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(66,'The Fifth Element',1997,'60',126,'2001-12-19',4,8,9,8,6,9,'Dit is een zeer genietbare SF-film. Af en toe is er plaats voor humor, maar het ontbreekt ook niet aan spanning, zij het slechts in enkele momenten. De visuele effecten zijn zoals het hoort en de acteerprestaties zijn best OK. Het enige negatieve is de voorspelbaarheid en eventueel de hollywoodclichés. Deze vallen echter nauwelijks op door de steengoede andere aspecten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(67,'Exit Wounds',2001,'61',101,'2001-12-20',8,6,6,8,10,8,'Dit is een keiharde actiefilm. Zo\'n echte typische overdreven film, maar toch best genietbaar. De actiescènes zijn soms onbedoeld grappig uitgedraaid. Er is ook wel plaats voor wat geplande humor. Al bij al niet slecht, maar er mogen wel niet te veel hercencellen actief zijn. Goeie soundtrack!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(68,'Once upon a time in America',1984,'62',227,'2001-12-28',4,9,9,9,8,8,'Dit is een heel lange gangsterepos. Toch gaat deze film nooit vervelen. De filmtechnieken zijn prachtig, maar soms wat opvallend. De film is totaal niet voorspelbaar. Een echte aanrader, maar met die bijna 4 uur, niet echt iets om tussendoor te bekijken. Alleen voor de liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(69,'The Name of the Rose',1986,'63',130,'2001-12-29',3,8,8,9,7,7,'Dit is een heel mysterieuze film. De Middeleeuwse sfeer wordt perfect overgebracht. Toch is deze film wat voorspelbaar en niet echt moeilijk om te volgen. Gewoon een leuke film. Door de hooggespannen verwachtingen toch wat teleurstellend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(70,'Iron Eagle II',1988,'64',105,'2002-01-14',3,8,8,7,6,7,'Dit is een steengoede, maar toch voorspelbare actiefilm. De film slaagt er wel in om je aan je scherm gekluisterd te houden, maar bevat iets te veel jaren-80 clichés. Maar het totaalbeeld is positief.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(71,'The Others',2001,'65',101,'2002-01-14',5,9,10,10,8,8,'Deze film was een aangename verrassing. Het verhaal zit heel goed in elkaar. De film is nooit verrassend of voorspelbaar. De filmtechnieken en muziek zorgt voor een ongeziene creepy sfeer. Meeslepend van begin tot einde. Een waar meesterwerk met schitterende acteerprestaties. Tijdens de film is alles wat moeilijk om te volgen, maar nadien lijkt het zo simpel…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(72,'Mulholland Drive',2001,'66',145,'2002-01-14',5,7,8,9,7,7,'Dit is een typische weird film van David Lynch. Het zit vol van de mysteries die niet verklaard worden in de film, tenzij je grillige fantasie van Lynch kan volgen. De film lijkt echter nooit te boeien. Hij komt nooit op gang. Misschien was dat te wijten aan mijn te hoge verwachtingen. Best genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(73,'Shaft',2000,'67',99,'2002-01-17',2,7,7,8,7,8,'Dit is een matige actiefilm die nooit echt boeit. Het is wel leuk om Samuel L. Jackson bezig te zien als coole politieagent, maar toch is het verhaal niet meeslepend of realistisch. Leuk om te zien, maar daarmee is ook alles gezegd. Weinig extra\'s op de DVD.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(74,'Con Air',1997,'68',115,'2002-02-09',3,7,8,9,7,9,'Dit is een flitsende actiefilm met een heel sterk verhaal. Toch is deze film in het algemeen een beetje té. Sommige toevalligheden maken het verhaal wel heel ongeloofwaardig en soms hilarisch. Toch leuk om een vervelende avond mee te vullen. Best aangenaam om te bekijken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(75,'The Big Lebowski',1998,'69',117,'2002-02-07',8,9,9,8,6,7,'Dit is een schitterende komedie. Weinig droge humor. In het begin is de film niet zo goed en eigenlijk een beetje saai. Hoe meer het verhaal echter vordert, hoe beter het lijkt in elkaar te zitten. Deze film verveelt nooit, buiten het prille begin. De film is eigenlijk nooit onrealistisch, maar wel wat onwaarschijnlijk. Een aanrader voor mensen die willen lachen zonder \"Naked Gun\"-toestanden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(76,'De Alias',2002,'70',90,'2002-02-10',5,7,7,6,8,7,'Dit is een Belgische poging tot thriller. En voor Belgische normen, is deze film heel erg goed. Toch barst deze film van de clichés uit de jaren 60. Eigenlijk is er niet zo veel speciaal aan de film, maar dat is niet noodzakelijk slecht. Was het echter een Hollywood-productie, dan zou ik de film onvoldoende gevonden hebben. Chauvinisme redt deze productie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(77,'Brotherhood of the Wolf',2001,'71',142,'2002-02-11',3,6,7,9,7,8,'Deze Franse film kon mij wel bekoren. Maar toch is de 142 minuten iets te veel van het goede. Het verhaal is nooit, maar dan ook nooit meeslepend. Het verhaal zit wel goed in elkaar, de actiescènes zijn ietwat te spectaculair. Niet echt een aanrader, maar voor de alternatievelingen zal dit een leuk tijdverdrijf zijn. Goed geluid en beeld.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(78,'Cherry Falls',2000,'72',92,'2002-02-14',3,6,6,7,7,8,'Dit is een typische tienerthriller in het genre van Scream. Het biedt ook niet echt iets nieuws. Alleen de drijfveer van de klassieke psychopaat is origineel en leidt tot komische momenten. Dit biedt wat afwisseling. Niet echt een aanrader, want zo bestaan er al tientallen films.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(79,'Ocean\'s Eleven',2001,'22',116,'2002-02-18',5,7,8,9,8,7,'Dit is een typische blockbuster zonder veel om het lijf. Een leuke film om te volgen, een collectie grote namen en een aangename sfeer. Dat is het zowat. Het verhaal is verder nogal onwaarschijnlijk. Maar het slechtste punt is het ontbreken van iets heel positiefs…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(80,'The Hunt for Red October',1990,'73',134,'2002-02-21',4,8,9,6,7,8,'Dit is een klassieker. Het verhaal zit heel erg goed in elkaar. Er wordt een goeie sfeer gecreeërd, het verveelt gewoon nooit. Toch ontbreekt een echte spectaculaire actiescène, maar misschien is dat ook wel goed omdat het verhaal minder geloofwaardig zou worden. Een minpunt zijn de verouderde special effects. Maar wel heel goed geluid. Goeie acteerprestaties.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(81,'The Green Mile',1999,'74',188,'2002-02-28',8,9,10,9,8,7,'Dit is een fantastische film. De lange duur valt echt niet op. Geen enkel onderwerp wordt uit de weg gegaan. De film werkt echt mee aan het proberen oplossen van het verhaal samen met de kijker. Soms ook compleet misleidend. Het verhaal is zonder meer 100% meeslepend in een geheel eigen sfeer. Deze film moet men gezien hebben.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(82,'Funny Bones',1995,'75',128,'2002-03-14',8,7,6,8,8,7,'Dit is een matige film. Niet echt een aanrader. Er komen weinig komische momenten in, maar toch blijft deze film min of meer boeien. Er is wel een heel eigen typisch Britse sfeer. De ouderwetse muziek draagt hiertoe bij. Een speciale film, alleen voor echte liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(83,'From Hell',2001,'76',121,'2002-03-16',5,7,8,9,7,8,'Dit is een eerder teleurstellende thriller. Een waarvan er al een dozijn gemaakt zijn. Toch zijn er sterke acteerprestaties. De film wordt nooit meeslepend of spannend. Er bestaan betere films van dit genre, maar toch best genietbaar. Deze film blinkt uit in het gebruiken van perspectieven en lichtinval.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(84,'The Craft',1996,'77',101,'2002-03-18',4,8,9,9,6,7,'Een originele thriller over de moderne hekserij. Er gebeuren veel magische zaken, maar slechts heel zelden komen die ook ongeloofwaardig over. Het verhaal zit goed in elkaar. De speelduur is zelfs iets te kort om het verhaal goed tot zijn recht te laten komen, vind ik. Hierdoor mist de film het echte meeslepende aspect. Knappe acteerprestaties, maar dat is door de goede keuze van de regisseur…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(85,'Showtime',2001,'78',95,'2002-04-22',5,7,6,8,8,8,'Een leuke komedie. De sterren uit de jaren 80 komen nog eens op het witte doek, en doen eens wat anders. Betrekkelijk aangenaam, maar ook niet enorm indrukwekkend. Beeld en geluid zijn goed en dragen zeker bij tot het komediegehalte.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(86,'Panic Room',2002,'79',112,'2002-05-03',5,8,9,9,7,9,'Dit is een boeiende thriller met een schitterende Jodie Foster. Het verhaal zit simpel in elkaar (een huis, een aantal kamers, 6 personages, …), maar toch is deze film nooit langdradig. Integendeel, meeslepend. Achteraf bekeken zijn er niet zo veel spannende momenten, maar bij het bekijken van de film valt dit echt niet op. Ook schitterend beeld en vooral geluid.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(87,'Air Force One',1997,'23',124,'2002-05-08',4,4,4,8,6,7,'Een veelbelovende cast in een echte blockbuster. Helaas is dit geen garantie op een goede film. Het onbegrijpelijk eenvoudige verhaal zit vol van de filmclichés en Amerikaans chauvenisme. Ook de geloofwaardigheid laat te wensen over. De special effects zijn ook al niet al te denderend, hoewel deze film nog maar uit 1997 dateert... Als er echt, echt niets beters is op TV, kan je dit misschien overwegen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(88,'True Lies',1994,'80',144,'2002-05-09',4,9,9,8,6,8,'Dit is iets tussen een komedie en een actiefilm. De actie in deze film is compleet, maar dan ook helemaal onmogelijk. Realisme was ook niet de bedoeling, hoop ik. Soms zijn er hilarische momenten, ook in de actiescènes. Hele leuke, uitzonderlijke film. Moeilijk in een genre te stoppen. Schwarzenegger en Jamie Lee Curtis zijn uitmuntend. Leuk tijdverdrijf!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(89,'Rain Man',1988,'31',133,'2002-05-11',3,9,9,6,7,8,'Dit meesterlijk drama over een autist is een absolute klassieker. Nooit langdradig, altijd meeslepend. Zo sterk dat het stresserende gevoel van het hoofdpersonage perfect wordt overgebracht op de kijker. Dit is een film die je niet loslaat. Toch duurt dit meesterwerk iets te lang en is de eighties-spirit soms ies te nadrukkelijk aanwezig. Onvoorstelbare Dustin Hoffman in de hoofdrol. Een klassieker, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(90,'Disturbing Behaviour',1998,'81',84,'2002-05-13',4,7,8,9,6,7,'Dit is een tienerthriller over de gebeurtenissen in een klein boerengat in Amerika. Het is best leuk om volgen en soms spannend en meeslepend. Dit maakt het niet echt een klassieke tienerthriller. Toch is het verhaal te weinig uitgewerkt, en is het allemaal betrekkelijk simpel gehouden. Aangename film, maar geen topper.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(92,'Judge Dredd',1995,'82',96,'2002-05-16',4,7,6,8,7,9,'Dit is een actiefilm zoals er al duizenden gemaakt zijn. Een leuk thema, maar er is te weinig mee gedaan. Iets te veel Disney-allures zelfs! Deze film is ongelooflijk voorspelbaar, maar toch best te genieten. Geen hersenactiviteit noodzakelijk. Leuk om Sly en partner bezig te zien. Goed geluid.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(93,'In the Company of Spies',1999,'83',104,'2002-05-22',4,8,9,7,7,8,'Dit is een verrassend goeie spionagefilm. Niet zo gekend bij het grote publiek, maar een echte kaskraker, volgens mij. Prachtige karakteruittekeningen, erg spannende film. Soms wel wat overactief camerawerk dat de kijker zeeziek doet worden. Speciale effecten laten wat te wensen over, maar dit kan de pret niet bederven. Zowat alles is genietbaar aan deze film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(94,'Jumpin\' Jack Flash',1986,'84',100,'2002-05-23',4,6,8,6,6,6,'Dit is geen opvallende film, maar toch blijkbaar een klassieker. Steengoeie acteerprestaties en het verhaal zit heel goed in elkaar. Veel details. Toch weet deze film nooit te boeien. Ook zijn er weinig of geen goeie komische momenten. Een typische komedie die amusant is als er niets anders te zien is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(95,'Mortal Kombat',1995,'85',101,'2002-05-23',4,7,7,9,9,8,'Een goeie film voor de liefhebbers van het videospel. Goede acteerprestaties en de sfeer die rond de film wordt gecreëerd is opmerkelijk. Toch is het verhaal wat magertjes en is er iets te veel tienergehalte aanwezig. Dwz geen denkvermogen nodig. Plain and simple slaan en motten. Goed voor de liefhebbers. Muziek en geluid zijn meer dan behoorlijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(96,'True Crime',1999,'28',127,'2002-05-25',4,7,8,8,7,7,'Dit is een aangename film. Het verhaal komt moeizaam op gang, maar er komt echt veel spanning op het einde. Ik vind dus dat de film wat te lang duurt. Ook het einde bevat iets te veel feel-good Disney-gehalte. Voor de rest is dit een van de betere in het genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(97,'Scorpio One',1997,'86',90,'2002-06-02',4,6,6,7,6,7,'Dit is een B-actiefilm. De speciale effecten zitten redelijk in elkaar, maar het verhaal is veel te simpel, er gebeurt te weinig en het verhaal is niet meeslepend. Het is een lang uitgerekte Star Trek aflevering met alleen mensen. Niet echt een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(98,'Go',1999,'87',103,'2002-06-03',4,9,9,8,7,8,'Dit is een onorthodoxe komedie/misdaadfilm. Je beleeft 3 keer hetzelfde verhaal, gezien vanuit verschillende personages van een kennissengroep. Heel origineel dus, en erg goed. Echt een aanrader. Het verhaal zit heel goed in elkaar en blijft mede daarom boeien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(99,'Victim of the Haunt',1996,'88',105,'2002-06-04',4,6,6,9,6,9,'Dit is een typische spookthriller over een behekst huis. Beeld en geluid zijn goed, de sfeer lijkt soms spanning op te wekken. Dit is dan ook het enige wat er echt goed aan is. Er bestaan betere films van dit genre. Ook de kerngedachte van de \"onverwoestbare liefde van de moeder voor haar kind\" past totaal niet in deze film. Toch wordt er veel te veel belang aan gehecht. Geen aangename film…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(100,'The Gingerbread Man',1998,'89',114,'2002-06-07',4,7,8,5,6,7,'Dit is een weinig meeslepende thriller. Het verhaal zit goed in mekaar. De acteerprestaties zijn ook goed. Maar dat is het dan. Er werd geprobeerd om de film duister te maken, maar het is geweldig overdreven: gewoon niet zichtbaar soms. Om hoofdpijn te krijgen. Het verhaal wordt nooit meeslepend. Het begin is te langdradig, en het einde is te snel. Er zijn betere films.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(101,'Cruel Intentions',1999,'90',95,'2002-06-08',4,8,8,8,9,7,'Deze film heeft een heel origineel verhaal. Er wordt in de eerste helft van de film ook goed gebruik van gemaakt. Een heel boeiend begin dus. Maar naar het einde toe verwatert deze film in een dozijn romantische clichés. Jammer toch. Het einde is nochtans het belangrijkste deel van een film. Goeie muziek. Net geen meesterwerk…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(102,'Silverado',1985,'91',127,'2002-06-10',4,7,8,7,6,6,'Een ouderwetse western. Een echte klassieker. De acteerprestaties zijn niet zo goed, ondanks de fantastische cast. De film zit goed in elkaar en blijft boeien. Vooral de liefhebbers van westerns zullen aan hun trekken komen. Alle clichés worden in volgorde in de film gepropt en geloofwaardigheid is soms ver te zoeken, maar dat is toch niet altijd slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(103,'Single White Female',1992,'92',107,'2002-06-10',4,8,9,6,8,8,'Dit is een semi-klassieker. Het verhaal steekt goed ineen. De film gaat niet vervelen, maar ook niet echt boeien. Goeie acteerprestaties. Toch ontbreekt er iets om een echte topper te zijn. Misschien is het de weinig inspirerende \"eighties-in-New-York\"-sfeer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(104,'Icebreaker',1999,'93',90,'2002-06-18',4,3,4,4,3,5,'Dit moet zowat het trieste dieptepunt van het actiegenre vormen. De clichés druipen eraf en zijn totaal ongeloofwaardig gebracht. Het verhaal is nooit meeslepend. De effecten zijn gewoon slecht. De actiescènes zijn totaal maar dan ook totaal ongeloofwaardig. Nooit gezien amateurwerk. En dan nog een verhaal dat op niks lijkt. Moest dit echt 90 minuten duren? Dergelijk miskunkel van een film is te lelijk om aan je hond te laten zien…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(105,'The River Wild',1994,'94',111,'2002-06-15',4,7,8,9,7,7,'Dit is een goeie actiefilm. Niet echt spectaculair, maar gewoon aangenaam. Goeie acteerprestaties, simpel maar boeiend verhaal. Een gezin gaat op vakantie en ontmoet 2 mannen. Het blijken misdadigers te zijn. Spanning genoeg, goed in beeld gebracht. Het einde vind ik persoonlijk nogal zwak.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(106,'Sliding Doors',1998,'95',99,'2002-06-19',4,7,9,8,6,7,'Dit is een romantische film met wat niveau in. Het verhaal zit heel origineel in mekaar. Twee verhalen lopen eigenlijk door elkaar. Hoe een toeval je leven kan veranderen: het ene deel geeft een soort levensverhaal na het missen van de trein. Het andere deel geeft hetzelfde verhaal, maar dan werd de trein niet gemist. De film raakt nooit echt op gang, maar dat is ook het enige slechte punt. Best genietbaar, maar niet makkelijk te volgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(107,'My Favourite Martian',1999,'56',93,'2002-06-15',4,8,8,8,8,7,'Dit is een onverwacht goede komedie. Het is een soort verbeterd disney-verhaal. Klassiek thema, maar heel erg goed gebracht. Het is ook in bepaalde mate voorspelbaar. Humorgehalte ligt hoog. Best in orde dus. Beeldeffecten zijn goed verzorgd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(108,'When Trumpets Fade',1998,'96',95,'2002-06-23',4,9,9,9,7,8,'Niet om met een volle maag naar te kijken. Een relax filmavondje kan maar best met een andere film doorgebracht worden. Dit is onverwachts meeslepend en heel erg goed gemaakt. Geen echte blockbuster, maar het getuigt van heel wat vakmanschap. Zonder meer prachtig. Geluid en beeld zijn uiterst scherp en sfeervol.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(109,'Police Academy',1984,'97',95,'2002-06-24',3,7,8,6,7,7,'Een klassieke komedie. Niet echt hoogstaand, maar wel een verhaal dat steek houdt. Het is een film met grote naam en stelt daarom wat teleur. Er zitten wel goeie momenten in, maar die wegen niet op tegen het ietwat oubollige eighties-komedie-genre. Beeld en geluid is niet perfect, maar de film is dan ook niet meer zo recent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(110,'The Rock',1996,'98',136,'2002-06-25',3,8,8,9,7,7,'Goeie actiefilm, zonder meer. Brengt weinig nieuws, maar is best wel spannend. Het is genietbaar, want de sfeer is pakkend. Het verhaal zit goed in elkaar, maar is wat voorspelbaar. De acteerprestaties zijn ook goed, maar van zo\'n cast verwachtte ik niets anders. Degelijke film dus, best genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(111,'Star Wars: Episode I - The Phantom Menace',1999,'41',133,'2002-07-02',3,8,8,6,8,8,'Het beginverhaal van de populaire sage. Beelden en effecten zijn enorm verbeterd ten opzichte van vroeger, maar inmiddels al weer sterk verouderd. Iets voor de fans. Toch gaat de magie van de eerste drie films wat verloren. Alles is iets te commercieel gemaakt. Als je van de Star Wars-reeks houdt, is deze film zeker geen teleurstelling, maar hij kan niet tippen aan de vroegere delen. Toch blijft het een topper.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(112,'Star Wars: Episode II - Attack of the Clones',2002,'41',143,'2002-07-08',5,8,9,8,9,8,'Deze episode is ijzersterk qua beeld en geluid. Het verhaal steekt ook weer goed in elkaar, en er is duidelijk geprobeerd om de magie terug te brengen die ontbrak in Episode 1. Dit is duidelijk gelukt. De commercialisering is weer duidelijk op te merken, maar de liefhebbers zullen dit niet aan hun hart laten komen. Deze film is onvolgbaar wanneer je de eerste film niet hebt gezien. Weer een fraai werk van George Lucas.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(113,'What\'s Eating Gilbert Grape',1993,'99',118,'2002-07-10',4,7,8,7,7,8,'Dit pakkende drama gaat over een autistische jongen en zijn oudere broer. Het verhaal is meeslepend en niet langdradig. Er gebeurt echter niet veel. Er ontbreekt wat spanning, maar dat zal wel eigen zijn aan dit genre. Prachtig geacteerd, speciale beeldsfeer. Best te doen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(114,'Artificial Intelligence',2001,'8',146,'2002-07-11',3,8,7,9,7,8,'Deze film is eigenlijk een sprookje over de zin van het leven en de evolutie van artificiële intelligentie. Het verhaal zit heel goed in elkaar, maar komt niet realistisch over. De film is niet meeslepend genoeg. Een speciale film die best gezien mag worden, maar alleen voor de liefhebbers. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(115,'40 Days and 40 Nights',2002,'100',96,'2002-07-11',5,7,7,8,8,7,'Een weinig origineel thema, maar meesterlijk in beeld gebracht. -16-jarigen zullen moeite hebben om alles te begrijpen. De film gaat geen enkel thema uit de weg, maar is soms wat overdreven. Degelijke boereleute die goed in beeld is gebracht. Spijtig van de voorspelbaarheid. Goeie genietbare komedie, maar er ontbreekt iets. Goeie muziek.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(116,'Spider-Man',2002,'15',121,'2002-07-29',5,6,5,8,7,8,'Een fel overschatte actiefilm. Het verhaal is er een zoals er al 17 van bestaan, met het onnodige Amerikaanse romantische droomverhaal. De film is zo voorspelbaar dat je van tevoren kan noteren wat er zal gezegd worden. Hoewel de actiescènes goed in beeld zijn gebracht en soms ook amusant zijn als het niet te onwaarschijnlijk wordt, is deze film gewoon ondermaats. De clichés druipen eraf en de film boeit zelden of nooit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(117,'Mind Games',2000,'101',95,'2002-08-12',4,8,9,7,6,8,'Degelijke thriller. Weinig of geen actie, maar toch boeit deze film tot de laatste minuut. Het verhaal zit heel goed in elkaar. Eigenlijk weinig op aan te merken. Goeie en genietbare film. Het is eens iets anders.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(118,'The Karate Kid III',1989,'102',112,'2002-08-13',3,6,7,8,6,8,'Deze actiefilm brengt niets nieuws. Gewoon een leuke karatefilm, niets meer of minder. Mensen die de eerste 2 films hebben gezien, zullen er meer van genieten hoewel alles goed te volgen is als je niks van de voorgeschiedenis afweet. Er hangt alleen een wat hatelijke eighties-sfeer. De film is supervoorspelbaar en dus totaal niet meeslepend, maar leuk om volgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(119,'Fucking Amal',1998,'103',89,'2002-08-14',5,7,8,6,8,7,'Low-budget, maar toch goed. Dit vat alles zowat samen. Het verhaal wordt nooit echt meeslepend of herkenbaar, maar de film is wel aangenaam om volgen. Het is een romantische film, maar voor de verandering eens zonder de Amerikaanse clichés. Een hele verademing. Dit is een film voor als men eens wat anders wil.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(120,'Dragonfly',2002,'104',104,'2002-09-01',5,9,9,8,8,9,'Dit is een heerlijke film à la Sixth Sense, maar nog iets mysterieuzer. De film zit ook steengoed in elkaar. Het verhaal is ook heel meeslepend. De beelden zijn ook heel goed. Het geluid is ook heel goed. Dit alles maakt ook wel duidelijk dat de film eigenlijk niets nieuws brengt, maar voor de rest is dit gewoon genieten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(121,'In Broad Daylight',1991,'105',90,'2002-09-10',4,6,7,8,6,7,'Een al bij al matige thriller. Het verhaal is aanlokkelijk, maar stelt wat teleur. Het gaat allemaal wat te traag en soms zijn de kunstgrepen om het verhaal te doen kloppen iets te veel zichtbaar. Toch kan deze film wel wat emoties loswekken. Het is een aangenaam tijdverdrijf, maar niet meer dan dat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(122,'8mm',1999,'106',123,'2002-09-17',4,8,8,9,7,8,'Een detectivefilm die op het eerste gezicht niet veel nieuws brengt. Maar hoe meer de film vordert, hoe eigenaardiger alles wordt. Dit is een film die men niet licht zal vergeten. Er wordt toch met wat clichés komaf gemaakt, wat niet zo vanzelfsprekend is in dit genre. Beeld en geluid zijn beter dan gemiddeld. Een negatief punt is dat de film zelden of nooit meeslepend is. Het mist wat feeling. Als men niet te veel nadenkt, is dit een klassefilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(123,'Tomb Raider',2001,'68',100,'2002-09-26',8,5,4,8,5,7,'Deze kinderachtige heldenfilm maakte geen indruk op mij. De stunts zijn zo fake als iets en het verhaal is totaal voorspelbaar. Het verhaal van de heldin tegen de slechterik voor de duizendste maal herhaald. Enkel op de special effects valt er weinig of niets aan te merken. Maar het brengt niets nieuws. Leuk voor kinderen jonger dan 12 jaar die graag Indiana Jones in absurde versie zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(124,'Pulp Fiction',1994,'107',154,'2002-09-26',8,9,9,7,9,7,'Een ware klassieker. Meeslepend, maar ingewikkeld. Humoristisch en dramatisch. De cast is indrukwekkend en stelt niet teleur. Enkele parallelle verhalen maken van deze film een boeiend kijkstuk. Vooral als deze verhalen op de meest onmogelijke manieren samenkomen. Een meesterwerk. Muziek en geluid zijn uitzonderlijk, mede dankzij de cast.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(125,'Saving Private Ryan',1998,'8',170,'2002-09-27',3,8,8,9,6,7,'Een soms gruwelijke, maar hierdoor meeslepende oorlogsfilm. Enkele zaken worden angstvallig voor de kijker verborgen, omdat anders het Amerikaanse Patriotisme in het gedrang komt. Als je dit even vergeet, boeit deze film van de eerste tot de laatste minuut. Het is zo\'n film die iedereen moet gezien hebben. Maar een eeuwig durend succes zal dit niet worden…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(126,'You\'ve Got Mail',1998,'108',119,'2002-10-03',3,7,8,8,6,7,'Een van de betere romantische films. Misschien geholpen door initieel sceptisisme, viel dit eigenlijk goed mee. Ik heb zelfs van deze film genoten. Soms duurt deze wel wat lang, maar dit komt het verhaal ten goede. Het is een feel-good filmpje, maar zeker niet slecht. Voor als je een rustig ontspannend avondje zonder veel gruwelijkheden wilt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(127,'Roswell',1994,'109',105,'2002-10-03',4,6,6,5,6,6,'Een magere film over aliens waarbij steeds de gedachte \"Ik heb dit al eens gezien\" bovenkomt. Typisch verhaal van een onschuldige soldaat die slachtoffer wordt van de overheid en haar doofpotpraktijken. Weinig nieuws, maar voor de alien-addicts is dit zeker niet slecht. Beeld en geluid zijn ronduit slecht te noemen. Het lijkt meer op vroege jaren-80 SFX.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(128,'Wild Things',1998,'110',108,'2002-10-09',4,8,8,8,9,7,'Wat eerst een drama lijkt te worden slaat al snel om in een thriller met enorm veel verrassende wendingen. Zoveel zelfs, dat de film er naar mijn mening iets te snel door gaat en niet echt meeslepend wordt. Het is wel boeiend omdat de voorspelbaarheid nihil is. Beeld en geluid zijn heel goed. Aangename ontspanning.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(129,'Fled',1996,'111',94,'2002-10-10',4,6,6,7,6,7,'Een actiefilm die er redelijk goed uit ziet, maar niets nieuws brengt. Nooit boeiend, zelfs af en toe gewoon saai. Voorspelbaar tot en met, alleen de acteerprestaties zijn goed. Ook het beeld is goed, vooral in de achtervolgingsscènes. Niet echt een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(130,'Minority Report',2002,'8',145,'2002-10-19',5,9,8,8,7,8,'Dit is een typische Amerikaanse Sci-fi film, maar het brengt toch wel wat nieuws op vlak van emotie. Op de SFX valt niets op te merken, ook het geluid valt bijzonder goed mee. De film is zonder meer meeslepend en het verhaal zit uitstekend in elkaar, en is ook niet te moeilijk. Een film om te onthouden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(131,'Le Fabuleux Destin d\'Amélie Poulain',2001,'112',122,'2002-10-24',8,9,10,8,9,8,'Een soms hilarisch melodrama, sterk onderschat. Geniale meeslepende film, met soms wat onrealistische toevalligheden waardoor het verhaal klopt. Dit is dan ook het enige minpunt door wat muggenziften. Heerlijke film, goede muziek, enz enz…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(132,'Signs',2002,'53',106,'2002-10-29',5,7,6,8,6,7,'Een verteerbare alien-film. Het verhaal is wat voorspelbaar. De zoveelste film van Shyamalan die inwerkt op de grootste angsten van de mensen. Alles wordt perfect opgebouwd, meeslepend en spannend, en plots een anticlimax als slot. Onbegrijpelijk hoe zo\'n film kan mislukken alleen al door het slot. Genietbaar, maar zeer spijtig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(133,'White Men Can\'t Jump',1992,'113',112,'2002-11-03',4,7,7,7,7,8,'Aangename en zonder veel moeite volgbare film. Het zwakke verhaal wordt weggewerkt door de emoties die perfect worden verfilmd. Het wordt zelfs meeslepend. Hier en daar is er ook een humoristisch moment te vinden ook. Dit is een leuke, maar geen fantastische film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(134,'Dude, Where\'s My Car?',2000,'114',83,'2002-10-27',8,7,8,8,8,8,'Absurde humor, aangenaam, maar soms wat te hectisch. Voor een droge avond is dit een leuk kijkstuk, maar zeker geen geld waard. Er kan eens gelachen worden, maar veel andere troeven bezit deze film niet. Goede muziek.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(135,'Shrek',2001,'115',90,'2002-11-05',8,7,8,7,8,9,'Een leuke animatiefilm, zowel voor kinderen als volwassenen. De engelstalige versie is wel veruit het beste met heel bekende stemmen. Een leuke feel-good animatiefilm, maar niet meer dan dat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(136,'Life of Brian',1979,'116',94,'2002-11-05',8,8,9,6,5,6,'Een typische Monty Python film. Leuk, soms hilarisch. Toch zijn er al betere Monty Python, zoals Holy Grail. Simpel beeld en geluid, weinig extras. Maar het blijft natuurlijk een klassieker in typische Monty Python stijl.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(137,'Swordfish',2001,'117',99,'2002-11-05',8,8,7,9,7,8,'Een leuke actiefilm, typisch Amerikaans. Weinig realisme, met andere woorden. Het brengt ook nooit spanning. Toch is er iets speciaals mee. Het is gewoon een leuke actiefilm, maar zeker geen meesterwerk. Goed beeld en geluid.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(138,'Red Dragon',2002,'118',124,'2002-11-07',5,9,9,8,8,8,'De derde film in de Hannibal Lecter-reeks breekt met wat basisprincipes. Het is een spannende film, zelfs als je de eerste 2 films niet gezien hebt. Iedere seconde verwacht je dat er iets zal gebeuren, op de meest onmogelijke momenten. Meeslepend en pakkend, spannend en huiveringwekkend. Precies wat een film als deze moet zijn. Indrukwekkend. Beeld en geluid zijn heel goed, en ze zorgen voor de nodige sfeer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(139,'Secret Lies',1993,'119',93,'2002-11-14',4,6,5,7,6,6,'Dit is een aangename film om volgen, maar zeker geen thriller te noemen. De film is leuk zolang het over de drie sleutelpersonages gaat. Het einde zou moeten wat spanning brengen, maar daarvoor is het veel te klassiek. Een \"zomaar-moordenaar\" die van de ene gemoedstoestand in de andere vliegt met de gebruikelijke happy-end. Jammer van het slot, anders een aangenaam drama.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(140,'Dark Angel',1996,'37',90,'2002-11-20',4,7,8,6,7,7,'Een weinig originele detective-thriller. Het is weer het typische verhaal over een psychopaat die het op een agent gemunt heeft. Toch heeft deze film wel iets. Het is dan misschien allemaal wat voorspelbaar, maar het wordt allemaal wel goed uitgewerkt. Onverwachts genietbaar, maar zeker niets speciaals.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(141,'Ice Age',2002,'120',81,'2002-11-21',8,9,9,9,8,8,'Absoluut zalige animatiefilm. Hilarisch van begin tot einde en zelfs meeslepend ook. En dat voor een animatiefilm. Dit is een absolute must voor wie eens goed wil lachen. De originele dieren en stemmen dragen bij tot iets subliems. Om toch maar een slecht punt te moeten zeggen: Alles is wat kort en weinig uitgewerkt. Maar misschien is dat juist positief.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(142,'She\'s All That',1999,'37',95,'2002-11-26',3,7,8,8,7,7,'Een tienerfilm zoals zovele. Weinig origineel, maar toch redelijk boeiend. Dit is eigenlijk wel typisch voor een Iscove-film. Hoewel de voorspelbaarheid eraf druipt, zijn er best wel aangename en humoristische momenten. Leuk tijdverdrijf.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(143,'Insomnia',2002,'121',118,'2002-11-28',5,6,6,7,8,6,'Weinig vernieuwende politiefilm. Er is voortdurend een \"dit heb ik al eens gezien\"-gevoel. De muziek is aardig, en het is zeker een van de betere films van het genre. Maar om het een goede film te noemen is het geheel net niet origineel genoeg. En wat heeft die slapeloosheid in godsnaam te maken met het verhaal. Er is helemaal geen sleutelrol voor dit thema.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(145,'Bowling for Columbine',2002,'122',120,'2002-12-03',5,9,9,7,5,7,'Dit is eigenlijk een documentaire waarin Moore op zoek gaat naar de oorzaak van de vele gewapende moorden in de VS. Eindelijk eens een Amerikaan die de waarheid durft te zeggen. Er wordt niets uit de weg gegaan. Absurd, gruwelijk of shockerend. Je bent volledig ondersteboven van deze film. Meer mensen zouden dit moeten zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(146,'Not Another Teen Movie',2001,'123',89,'2002-12-05',8,7,8,8,6,7,'Een heerlijke absurde parodie op allerlei tienerfilms met als belangrijkste \"She\'s All That\". Een grove opmerking over de belachelijkheid van sommige tienerfilms wordt niet uit de weg gegaan. Deze komedie is best wel genietbaar als je de originele films hebt doorstaan. Maar echt origineel kan je dit niet noemen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(147,'The Fast and the Furious',2001,'124',106,'2002-12-07',2,8,6,9,8,8,'Een leuke actiefilm waarbij duidelijk op geen dollar werd gekeken. Er is heel aangename en geloofwaardige actie. Voor de liefhebbers van tuning is dit een absolute must. Het verhaal zelf mist originaliteit. Een leuke, maar voorspelbare, klassieke en commercieel uitgebuite film. Geluid en muziek mogen er zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(148,'Die Another Day',2002,'24',133,'2002-12-14',5,6,5,8,9,8,'De zoveelste Bondfilm die de legende verknoeit. Het irrealisme stijgt in deze film ten top. Kosten noch moeite zijn gespaard om de special effects perfect te laten lijken, en dat is aardig gelukt. Spijtig genoeg gaat men hier duidelijk over the edge en het slappe verhaal helpt daar nog een beetje bij. Geluid en beeld zijn wel nagenoeg perfect. Na het zien van deze film, wens ik een onmiddellijke stopzetting van het belachelijk maken van het Bondgenre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(149,'My Big Fat Greek Wedding',2002,'125',96,'2002-12-22',5,8,7,6,8,7,'Een leuke komische film. Het gaat eens niet over de prille romance gedurende anderhalf uur. Alles gaat snel vooruit. De film zelf blijft boeien tot het einde. Een zuivere feel-good romantische komedie met enkele hilarische momenten. Toch is dit duidelijk een low-budget film en weinig origineel. Het uiteindelijke resultaat is wel erg goed. Vooral met betrekking tot de vertolkingen en de Griekse muziek.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(150,'One From The Heart',1982,'126',100,'2002-12-27',4,4,6,4,5,4,'Een matige romantische film waar ik meer van verwacht had. Het is een aaneenschakeling van rare feiten en ondoordringbare fantasietjes van Coppola. De karakteruittekeningen zijn heel goed en uitgebreid. Dat is dan meteen ook het enige goede aan deze film. De beelden en geluiden zijn erbarmelijk slecht. De film boeit nooit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(151,'Candyman: Day of the Dead',1999,'127',93,'2002-12-26',3,5,6,7,5,7,'Het verhaal van de Candyman is natuurlijk een klassieker. Daarom zal de eerste film ongetwijfeld heel goed zijn. Dit derde deel is alleen gedeeltelijk boeiend als men de eerste twee heeft gezien. Maar eigenlijk is dit gewoon het uitmelken van een hit van enkele jaren geleden. Kijk naar de eerste film, als je kan. Geluid en beeld zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(152,'Thir13en Ghosts',2001,'128',91,'2002-12-28',2,7,6,8,7,8,'Een remake van een klassieker. Het verhaal is best origineel en zit wel goed in elkaar. Het schitterende beeld en geluid versterkt dit nog. Deze film boeit tot het einde. Maar toch ontbreekt er iets. De personages zijn weinig uitgetekend. Het verhaal zit soms met haken en ogen in elkaar. Ik krijg er een \"goed geprobeerd\"-gevoel van. Redelijk wat extra\'s op de DVD.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(153,'Bean',1997,'129',90,'2002-12-28',4,8,8,8,6,6,'Een hilarische Bean-komedie. De typische Bean-chaos is weer helemaal afwezig. Bean praat zelfs in deze film, en dat geeft een meerwaarde. Schitterende komedie, maar enkel voor de liefhebbers van dit soort humor. Compleet erover dus, maar om over de grond te rollen van het lachen. Muziek en geluid zijn minder.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(154,'Home Alone 2: Lost in New York',1992,'130',120,'2002-12-28',4,7,6,8,6,7,'Deze bijna perfecte kopie van Home Alone is alleen genietbaar als je de eerste film niet gezien hebt. Bijna alle grappen uit de eerste worden hier nog eens herhaald zonder het minste schaamrood op de wangen. Dit is toch een aangename komedie, maar kijk naar de eerste film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(155,'The Lord of the Rings: The Two Towers',2002,'131',179,'2002-12-29',5,9,9,9,9,9,'Het vervolg op de eerste film. In dit exemplaar zit er veel meer actie. Dit is ten koste van het verhaal, maar dit hoeft niet noodzakelijk slecht te zijn. Beeld en geluid zijn zoals gewoonlijk bijna perfect. En het schept ook de nieuwsgierigheid naar de ontknoping in het derde deel. Zeker een aanrader, maar je moet zeker het eerste deel gezien hebben.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(156,'The Lord of the Rings: The Fellowship of the Ring',2001,'131',178,'2001-12-26',5,9,9,9,9,9,'Een schitterende film. Dit lijkt op een sprookje, maar er zit heel veel meer in. Beeld en geluid zijn indrukwekkend. Dit is het eerste deel van een trilogie, dus er is geen ontknoping. Dit maakt het geheel wel wat minder. Maar het is natuurlijk een uniek project. Spannend van begin tot einde, ondanks de lange duur.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(157,'Far and Away',1992,'132',140,'2002-12-30',4,8,9,6,7,6,'Een apart drama met een romantisch tintje. Eigenlijk volgde ik deze film niet graag. Het gaf een onaangenaam gevoel. Nadien bleek dit een klassieker te zijn. Wel om slechts een keer te bekijken. Beeld en geluid zijn niet echt uitmuntend. Het verhaal zit wel prachtig in elkaar. Aan meeslependheid geen gebrek!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(158,'The Mothman Prophecies',2002,'133',119,'2003-01-02',2,8,9,8,7,8,'Een angstaanjagende thriller. Deze blijft in je kleren hangen. Het verhaal bouwt perfect op naar een hoogtepunt. Maar de ontknoping laat te wensen over. Het is een typische fout. Jammer, dit kon een klassieker geworden zijn. Prachtig beeld en geluid. Goede acteurs. Prachtig verhaal. Alleen dat slot...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(159,'Kevin & Perry Go Large',2000,'134',82,'2003-01-02',3,6,7,6,8,7,'Een boertige absurde komedie om naar te kijken met een bende. Soms is het erover, maar raar genoeg is dit juist goed voor de film. Hoe vunziger, hoe liever. Over wat je in Ibiza niet allemaal kan meemaken. Het is als Bean maar wansmakelijk en tienerniveau. De muziek is pure techno.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(160,'American Beauty',1999,'135',122,'2003-01-11',3,9,9,8,8,7,'Het bewijs dat een drama ook nu en dan humoristisch kan zijn. Het is een levensles. Het verhaal is steengoed. De beelden en het geluid dragen bij tot een meeslepende en realistische plot. Dit is een absolute klassieker over hoe sullig je kan sterven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(161,'Thelma & Louise',1991,'54',129,'2003-01-19',4,8,8,6,7,6,'Deze film heeft de \"cult\"-status verworven. Het is mij wel niet meteen duidelijk waarom. Het is een aangename feministische film, dat wel. Maar er ontbreekt iets aan. De karaktertekeningen van Thelma & Louise zijn goed, de rest zo goed als onbestaande. Het verhaal, en vooral het slot, blijft aan de ribben plakken. Geluid en beeld zijn matig. Al bij al een goede film, maar niets meer dan dat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(162,'Two if by Sea',1996,'136',96,'2003-01-23',4,8,7,8,6,6,'Eigenlijk een romantische komedie. Spijtig van dat romantische gedeelte. Anders had dit wel eens een heel goeie film kunnen zijn. De film boeit en het subverhaal van de relatieproblemen is meeslepend. Maar het blijft romantiek, dus alles wordt op een simpele onzinnige reden opgelost. Soms zijn er hilarische momenten. Het totaalpakket is niet slecht, maar kon beter. Beeld en geluid zijn niet uitmuntend. De locatie is wel aangenaam om zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(163,'Erin Brockovich',2000,'22',130,'2003-01-25',4,7,8,8,7,7,'Een film met een grote naam, maar het stelt allemaal een beetje teleur. Het verhaal is goed, de verfilming is goed. De acteerprestaties zijn ook best goed. Soms is er een grappig moment. Maar dat is het dan ook. Niet zo speciaal, maar aangenaam.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(164,'Schindler\'s List',1993,'8',197,'2003-01-25',3,9,8,8,9,8,'Een absolute klassieker. Het gaat over de jodenvervolging, dus het onderwerp is niet echt mijn ding. Toch boeit deze film omdat het niet enkel probeert aan te tonen hoe verschrikkelijk het daar allemaal wel was. De unieke filmmethode doet veel aan de sfeer. Geluid en beeld zijn dus goed. Meeslepend tot een met, een klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(165,'The Haunting',1999,'137',112,'2003-01-23',4,8,7,8,8,8,'Een doordeweekse thriller. Leuk om met een bende naar te kijken. Het verhaal is weinig origineel, maar wel goed uitgewerkt. Leuk om volgen, zonder meer. Beeld en geluid zijn goed, maar het ontbreekt aan originaliteit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(166,'Behind Enemy Lines',1996,'138',89,'2003-01-30',4,6,5,7,6,7,'Een weinig originele post-Vietnamfilm, waarin het Amerikaanse patriotisme de realiteit overstijgt. Het is een film waar je echt niet moet naar uitkijken. Als je toevallig aan het kijken bent, blijf je dat doen. Maar dat is dan ook alles. Een film waarvan er al zo\'n honderd gemaakt zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(167,'Just Cause',1995,'139',102,'2003-02-01',4,8,9,8,6,7,'Een onbekende, maar des te betere thriller. Het verhaal zit steengoed in elkaar, dus het verveelt nooit. Integendeel, soms gaat het net iets te snel vooruit. Het is leuk om volgen en ook spannend. Het komt nooit onrealistisch over. Beeld en geluid zijn degelijk. Deze film heeft mij positief verbaasd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(168,'Money Train',1995,'140',103,'2003-02-02',4,7,7,7,8,7,'Een weinig originele actiekomedie. Soms is het wel leuk, maar de actiescènes zijn er wel een beetje over. Sommige momenten is deze film ook meeslepend. Kortom, er zit vanalles iets in, maar de film blinkt in niets uit. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(169,'Tango & Cash',1989,'141',98,'2003-02-24',4,6,5,7,7,7,'Weinig originele actiekomedie, maar toch leuk om volgen. Er zijn er al zo\'n 350 van deze soort gemaakt. Bekijk het dus niet als je een leuke filmavond wil hebben, maar wel als je niets anders te doen hebt. Actiescènes zijn goed voor die tijd, maar natuurlijk geweldig overdreven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(170,'Color of Night',1994,'142',121,'2003-02-28',4,8,9,9,7,8,'Meesterlijke thriller. Het verhaal zit eigenlijk redelijk simpel in elkaar. Dit is een voordeel voor de film: Het laat de ruimte om de personages goed te leren kennen. Je wordt dan meegesleurd in een spel van verdachtmakingen en smerige rotstreken. Beeld en geluid zijn heel erg goed. Gewoonweg prachtig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(171,'Drop Dead Gorgeous',1999,'143',97,'2003-03-03',4,8,8,8,7,7,'Leuke en orginele komedie. Het is een overdreven en boeiend verhaal over een stel mooie meiden die het tegen elkaar opnemen in een missverkiezing. Soms hilarisch en op andere momenten pakkend. Een niet alledaagse film die best wel meevalt. Beeld en geluid zijn goed, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(172,'The Ring',2002,'144',115,'2003-03-04',5,9,9,9,9,9,'Dit is er een die aan de ribben blijft plakken. Wat begint als een domme tienerthriller, eindigt in een ware nachtmerrie. Er wordt grondig komaf gemaakt met de meeste gebruikelijke clichés. Vooral het slot is verrassend. Zeker een aanrader, een van de beste. Beeld en geluid zijn gelukkig ook heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(173,'Catch Me If You Can',2002,'8',141,'2003-03-07',5,8,8,8,8,8,'Een echte blockbuster, en dan ook zijn geld niet waard. Het is wel een boeiend kijkstuk, maar de hele histerie is geweldig overdreven. De film zelf is leuk, soms gevat en komisch. Als je eenmaal begint te kijken, kan je niet meer stoppen. Maar uitblinken doet deze film nooit. Beeld en geluid zijn zoals het moet. Spielberg heeft zijn beste jaren gehad, denk ik.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(174,'We Were Soldiers',2002,'145',138,'2003-03-10',2,9,8,9,9,9,'Als Saving Private Ryan al pakkend was, dan is deze film verschrikkelijk. Het is naar Wallace\'s zeggen de eerste film die het Vietnam-verhaal vertelt zoals het is. En het blijft plakken, wees gerust. Als je even de Hollywood emo-opwekkers buiten beschouwing laat, is dit een van de betere oorlogsfilms, zoniet de beste. Niet voor de gevoelige zielen. Beeld en geluid zijn uitmuntend. De DVD-extra\'s zijn wat dunnetjes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(175,'Blade',1998,'146',120,'2003-03-12',3,8,7,9,8,9,'Het actiegenre is aan het doodbloeden, en deze film probeert daar wat verandering in te brengen. En met succes. Het is een heel aangename feel-good slayermovie. Wesley Snipes is meesterlijk als macho Blade. Het verhaal is afgezaagd, maar de film maakt dit alles boeiend. Om met een bende te bekijken. Beeld en geluid zijn heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(176,'Flatliners',1990,'106',115,'2003-03-21',3,8,9,7,7,7,'Een aangename thriller over bijna-dood ervaringen. Er zijn heel wat grote namen, en die lossen de verwachtingen in. Het is een film die niet echt bijster spannend is, maar het geeft wel stof om over na te denken. Het verhaal zit goed in elkaar. Je wordt er zonder veel commentaar ingegooid en eigenlijk voortijdig weer uitgehaald. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(177,'Cop Land',1997,'147',104,'2003-03-27',4,8,9,6,6,8,'Een ijzersterke misdaadfilm met Stallone. Klinkt als een paradox, maar de kwaliteit kan men niet ontkennen. Sterke cast en een super plot. Toch kan het slot de intussen smachtende kijker niet tevreden stellen. Een gemiste kans. Toch is dit zeker een film die een pluim verdient. Vooral het eighties-sfeertje valt hierbij goed mee.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(178,'The Untouchables',1987,'51',119,'2003-03-26',4,8,9,7,8,7,'Deze misdaadfilm is boeiend van begin tot einde. Het is een mafiaverhaal, zonder veel blabla. Leuk om volgen, en wekt de juiste gevoelens op de juiste momenten op. Een ware klassieker, de naam waardig. Toch kan je dit moeilijk uitmuntend noemen. Beeld en geluid zijn goed voor die tijd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(179,'Taxi Driver',1976,'3',113,'2003-04-02',8,5,6,6,5,6,'Een zogenaamde cult-film. Maar ik hield er niet van. Een verhaal die zich werkelijk vooruit sleept. Er zitten zoveel dubbele bodems in verwerkt, en de karakters zijn zo scherp uitgetekend, dat het geheel gewoon te traag gaat. Er gebeurt weinig of niets, en als er al eens iets gebeurt, lijkt het niet belangrijk. Absoluut geen aanrader, maar wat doe je met een klassieker?','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(180,'K-PAX',2001,'148',120,'2003-04-05',3,8,9,8,7,8,'Prachtig drama om alleen naar te kijken. Het verhaal begint en eindigt mysterieus, maar ook niet té. Je wordt van de ene gedachte naar de andere geslingerd. Wat een film kan doen met iemand. Daarbij komt dat beeld en geluid goed zijn. Het geheel is aangrijpend en meeslepend. Een rustige, maar heel boeiende film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(181,'Road Trip',2000,'149',93,'2003-04-15',3,7,6,7,7,7,'Leuke film, genre American Pie. Daarmee is ongeveer alles gezegd. Het is een leuke komedie, maar zeker geen meesterwerk. Er zijn er al betere gemaakt. Maar als je niets anders te doen hebt... Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(182,'Johnny English',2003,'95',88,'2003-04-15',5,5,7,7,8,7,'Typisch Atkinson, een beetje Bean-achtig. Het is niet echt een meesterwerk, hij heeft al beter gemaakt. Het verhaal boeit nooit, en is maar nu en dan eens sporadisch grappig. Huur de afleveringen van Blackadder, en je bent veel beter af. Beeld en geluid zijn goed. De stunts zijn indrukwekkend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(183,'Evolution',2001,'150',101,'2003-04-18',3,8,8,9,7,8,'Een wat vergezocht verhaal, maar heel erg leuk. De clichés druipen er soms vanaf en het verhaal is zo voorspelbaar als iets, maar de vertolkingen zijn gewoonweg fantastisch. Hierdoor is de film soms echt hilarisch. Beeld en geluid zijn prachtig. Zeker de moeite.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(184,'Mickey Blue Eyes',1999,'151',102,'2003-04-19',4,6,6,7,6,6,'Hugh Grant in een typische rol. Dit is compleet belachelijke mafia-onzin. Het is een leuke film als je van Grant houdt, maar ik vond het maar niets. Het verhaal is nooit boeiend en de komische momenten zouden beter worden aangeduid met een felle markeerstift, zodanig dat we het doorhebben dat we moeten lachen. Om positief te eindigen: Het kon slechter...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(185,'The Game',1997,'79',128,'2003-05-03',4,8,8,9,8,8,'Een klassieke puzzelthriller. Je weet nooit wat echt is en wat niet. Dit exemplaar zit wel heel goed in elkaar. Je moet er met je hoofd bij zijn, maar het is ook verstaanbaar voor iemand met weinig ervaring in het genre. Spannend kan je het niet noemen, maar boeiend des te meer. Genietbare film. Het goede beeld, geluid en muziek zijn wat je van dergelijke film mag verwachten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(186,'Midnight in the Garden of Good and Evil',1997,'28',155,'2003-05-04',4,7,7,8,7,7,'Een aangename detective-film. Heeft hij het gedaan of niet? Deze film heeft wel een speciale sfeer. Die zorgt ervoor dat het verhaal nog wat boeit. Maar dat is dan ook het enige. Ik had veel meer verwacht van dergelijke cast en regisseur. Goeie poging, maar over het algemeen net niet goed genoeg.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(187,'The Matrix',1999,'152',136,'2003-05-15',3,9,9,10,9,10,'Dit is een actiefilm die de lat legt voor de volgende jaren. Het is een meesterwerk van SFX en ook het verhaal kan mij bekoren. Als je dat verhaal gelooft, lijkt alles betrekkelijk realistisch. Dit is een absoluut uniek kijkstuk, die echter niet iedereen zal kunnen appreciëren. Geluid en beeld zijn fenomenaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(188,'The Matrix Reloaded',2003,'152',138,'2003-05-16',5,9,8,10,10,10,'Een verderzetting van het verhaal uit de eerste film. Dat verhaal is wel wat verzwakt. De menselijke kant van het gebeuren is verdwenen ten voordele van de beenharde flitsende actie. Het is een supermanverhaal geworden, met af en toe wel heel zware filosofische scènes, waarbij de leek afhaakt. Maar daarom is het bijlange nog niet slecht. De SFX zijn zo mogelijk nog beter dan in de eerste film. Jammer dat de tweede en de derde film eigenlijk een zijn, maar in twee zijn gekapt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(189,'The Jackal',1997,'153',124,'2003-05-20',4,7,7,7,9,7,'De zoveelste klopjacht op de ongenaakbare legende van een seriemoordenaar. Deze film is op geen enkel moment origineel en barst van de clichés, maar is wel een van de betere van het genre. Leuk om volgen, af en toe spannend en goed in beeld gebracht. Muziek en geluid zijn ook goed. Maar niet meer dan dat. Soms vervalt het in een gewone blockbuster...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(190,'The Witches of Eastwick',1987,'154',121,'2003-05-20',4,7,8,8,7,6,'Een heksenfilmpje. Het gaat eigenlijk over de verschillen tussen vrouwen en mannen. Maar dan met een duivels laagje erop. Weinig nieuws, niet echt boeiend. Af en toe eens spannend en soms leuk om volgen. Waarom niet eigenlijk? Beeld en geluid zijn goed voor die periode.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(191,'Y Tu Mamá También',2001,'155',105,'2003-05-17',3,6,6,7,6,7,'Een cultfilm zonder meer. Maar niet echt iets voor mij. Het is een weinig boeiend verhaal, en het werd ook weinig boeiend op film gezet. De zoektocht van enkele jongeren naar zichzelf is hier wel heel erg in detail bekeken. Als je niets anders te doen hebt, is dit wel een leuke komedie...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(192,'The Bourne Identity',2002,'87',119,'2003-05-17',3,7,8,7,7,7,'Een origineel kijkstuk. Een man heeft geheugenverlies en gaat op zoek naar zichzelf. Hij blijkt nogal wat eigenaardige mogelijkheden te hebben. Leuke plot dus. De uitwerking is iets minder. De film vervalt in een typische Bondfilm, maar dan zonder Bond. Al bij al nog zo slecht niet, maar met dit verhaal kon meer aangevangen worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(193,'U-571',2000,'156',116,'2003-05-24',8,7,8,7,8,9,'De zoveelste duikbootfilm uit de tweede wereldoorlog. Het geheel is wel spannend, goed gefilmd, goed gespeeld enzovoort. Maar wat onderscheidt het van eender welke andere duikbootfilm? Ik zou het niet weten. Het is een leuke actiefilm, zonder al te veel wreedheden. Niet echt iets speciaals. Het geluid is zoals alle duikbootfilms heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(194,'Austin Powers: International Man of Mystery',1997,'157',94,'2003-05-26',4,8,7,8,7,8,'Austin Powers in zijn gebruikelijke stijl. Absurde humor troef met de vervlogen hippy Austin Powers in een glansrol. Als je van dit genre houdt, is dit zeker een aanrader, hoewel er ongetwijfeld betere komedies bestaan. Al bij al niet slecht en leuk om je zinnen te verzetten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(195,'25th Hour',2002,'158',135,'2003-05-24',8,8,9,8,7,7,'Spike Lee toont eens te meer hoe hij op een ongeëvenaarde manier karakters kan uittekenen. Het is een wat rare film, en hierdoor enkel voor de liefhebbers. Het 24 uur volgen van een man die naar de gevangenis moet, werd meesterlijk in beeld gebracht. Beeld is goed, geluid iets minder. Niet voor het grote publiek, maar ik vind het een juweel van een film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(196,'Steal',2002,'159',83,'2003-05-31',3,6,6,7,6,7,'Dit leek een veelbelovende actiefilm waar veel goede kritiek op te horen was. Dit maakt de teleurstelling nog wat groter. De actie is totaal maar dan ook totaal onrealistisch. Het verhaal is niet meeslepend. En leuke momenten zijn ook schaars. Ik weet niet wat de critici hierin zien...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(197,'Interview With The Vampire',1994,'160',123,'2003-06-04',4,9,9,9,9,9,'Een prachtige vampierenfilm. Het werpt een nieuw licht op alles wat met de klassieke vampierenverhalen te maken heeft. Meeslepend, spannend en boeiend. Dit is een meesterwerk, maar niet bedoeld om meerdere keren te bekijken. Als je dit bekijkt zonder al te hoge verwachtingen, zal je ongetwijfeld onder de indruk zijn... en nog een tijdje blijven. Beeld, geluid en muziek zijn hoogstaand.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(198,'La Vita è Bella',1997,'161',122,'2003-06-04',4,9,10,7,8,7,'Zonder meer een schitterend verhaal over de jodenvervolging. Maar dan niet volgens het klassieke patroon. Het vertederende verhaal over de liefde van een vader voor zijn kind laat niemand onbetuigd. Deze Italiaanse film is technisch uiteraard niet hoogstaand, maar het blijft een klassieker. Neem er de tijd voor en u zal niet teleurgesteld worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(199,'Flodder',1986,'162',111,'2003-06-06',4,7,8,7,7,7,'Een heel gekende naam, en ik weet nu ook waarom. Het is een leuke, maar niet echt bijster originele film. Het sloeg in als een bom in die tijd. Maar echt fantastisch kan je het niet noemen. Ik vond het wel een aangenaam kijkstuk, maar er zijn al betere films gemaakt. Beeld en geluid zijn matig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(200,'Who Am I?',1998,'163',108,'2003-06-08',4,7,6,7,7,8,'Een typische Chan-film. Het plot trekt op niks, maar dat maakt het wel wat aangenamer. Soms is het zo belachelijk en doorzichtig dat het komisch wordt. De actiescènes zijn wel van hoog niveau, ten koste van de andere delen. Leuk voor de liefhebbers. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(201,'Wrongfully Accused',1998,'164',87,'2003-06-09',4,9,8,9,8,8,'Deze Naked Gun-achtige film zorgt voor enkele ongecontroleerde lachbuien, tenminste als je van het genre houdt. Het is een parodie op vanalles en nog wat. Het verhaal is totaal onrealistisch, maar het blijft boeien. Zelfs als je de film meerdere keren bekijkt, blijf je nieuwe verdoken grappen ontdekken. Een topfilm, trouwens ook wat beeld en geluid betreft.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(202,'Fathers\' Day',1997,'150',98,'2003-06-11',4,7,7,7,7,7,'Deze film begint als een flauwe eighties-komedie. Het flauwe verhaal draagt daar ook wat aan bij. Beeld en geluid zijn ook niet schitterend. Maar dan is er ook een zekere Robin Williams. Zijn meesterlijke prestatie zorgt ervoor dat de film aangenaam tijdverdrijf wordt in plaats van uiterst voorspelbare verveling. Zijn one man-show is al bij al aangenaam.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(203,'The Patriot',1998,'165',90,'2003-06-12',4,5,5,7,6,7,'Als je probeert een Seagal-film te bekijken, neem dan deze niet. Seagal doet inderdaad mee, maar er is weinig of geen actie van hem. Het verhaal is niet meeslepend, origineel of verrassend. Ook de uiteindelijke oplossing is niet geloofwaardig. Totaal geen aanrader, er zit helemaal niets in. Beeld en geluid zijn wel redelijk in orde.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(204,'Flodder 2',1992,'162',95,'2003-06-15',4,7,8,6,6,7,'Flodder 2 is ongeveer een replica van de eerste film, maar dan in verbeterde versie. De komische stukken zijn beter, ook de beelden en het plot zitten beter in elkaar. Maar zoals gezegd is het geheel niet origineel. Een leuke film, maar niets meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(205,'The Truman Show',1998,'166',103,'2003-06-15',4,9,9,10,9,9,'Dit is een miskende klassieker. Het originele, maar ingewikkelde verhaal klopt als een bus. Er is duidelijk over nagedacht. Ook de beelden en de acteerprestaties zijn heel erg goed. Hoewel er nogal wat clichés in zitten, is dit zeker een boeiende film. Het mocht zelfs iets langer geduurd hebben, vind ik. Beeld en geluid zijn ook heel goed. Waarom is deze film geen klassieker geworden?','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(206,'Happy Gilmore',1996,'26',92,'2003-06-19',8,4,5,7,5,7,'Slappe komedie over de klassieke held die de hele wereld op zijn kop zet. Daartegenover heb je dan de eeuwige slechterik. Kortom, er kon net zo goed een tekenfilm van gemaakt zijn. Maar er bestaan er al te veel met dergelijk verhaal. Voorspelbaarheid en onmogelijkheid troef. Bekijk dit alleen als je -12 jaar bent...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(207,'Mr. Deeds',2002,'167',96,'2003-07-15',2,7,7,8,8,7,'Een leuke komedie, zonder al te veel speciale pluspunten. Een genietbare film met af en toe een leuk moment. Om in een bende te bekijken. Beeld en geluid zijn goed. Het verhaal is verzadigd van de clichés, maar het is en blijft een doordeweekse komedie...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(208,'2 Fast 2 Furious',2003,'67',107,'2003-07-16',5,6,6,8,7,8,'Een simpele actiefilm, zoals de eerste film. Het verhaal zit iets anders in elkaar, er zijn andere auto\'s en de effecten hebben duidelijk wat meer gekost. Voor de rest is deze film compleet gelijkaardig met de vorige. Als je niet van tuning houdt, is dit geldverspilling. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(209,'The Naked Gun: From the Files of Police Squad!',1988,'168',85,'2003-07-17',3,8,7,8,8,8,'Een klassieker in het genre, zonder meer. De absurde humor gaat perfect gepaard met de fijnere kost. Dit kijkstuk is heerlijk om naar te kijken, hoewel het verhaal niet altijd blijft boeien. Kortom: Als je eens stevig wil lachen met absurditeiten, is dit je ding. Beeld en geluid zijn zeer goed voor die periode.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(210,'Overnight Delivery',1998,'169',100,'2003-07-23',4,6,5,7,6,7,'Dit is een film zoals Road Trip. Maar dan echt compleet hetzelfde, tot en met het verhaal toe. Het is dus razend voorspelbaar, en weinig origineel. De zoveelste komedie over tienerromantiek. Enkel de acteerprestaties waren heel erg goed. Te goed voor deze slappe film. Spijtig...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(211,'The Naked Gun 2 1/2: The Smell of Fear',1991,'168',85,'2003-07-30',2,9,8,7,7,7,'In dit genre is het makkelijker dan in andere om een vervolgfilm nog beter te maken dan de eerste. Hier is men daarin geslaagd. Het is een hilarische komedie geworden die net lang genoeg duurt om niet té te worden. Men heeft geleerd uit de fouten van de eerste film om hiervan een echte kaskraker te maken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(212,'The Terminator',1984,'80',108,'2003-08-13',3,7,8,6,8,8,'Dit is een klassieker in het Sci-fi genre, maar ook niet meer dan dat. Als de de andere films zonder problemen wilt volgen, moet je deze gezien hebben. Het was in die tijd een geweldige film, maar nu heel wat minder. De SFX zijn gewoon niet goed genoeg meer. Het verhaal zit wel heel goed in elkaar. Leuke, maar verouderde actiefilm. Muziek en geluid zitten goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(213,'Terminator 2: Judgement Day',1991,'80',137,'2003-08-20',3,8,9,8,8,8,'Het vervolg op de eerste film. De SFX zijn veel beter dan zijn voorganger. Ook het verhaal zijt soms meesterlijk in elkaar. Toch sluipen er hier en daar al wat te veel clichés in het geheel. Al bij al een verrijking van zijn voorganger, en een zeer genietbaar kijkstuk. Muziek en geluid zijn ook beter.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(214,'Terminator 3: Rise of the Machines',2003,'156',108,'2003-08-23',5,7,7,9,7,8,'Al bij al is deze film een aangename actiefilm, zonder al te ongeloofwaardig te zijn. Maar eigenlijk hadden ze beter niet verdergewerkt aan het verhaal van Cameron. Het degradeert het meesterwerk tot een klein onbenullig actiefilmpje, waar echter vele dollars zijn tegen aangegooid. Genietbaar, maar het waarom is onbegrijpelijk...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(215,'Reservoir Dogs',1992,'107',99,'2003-08-25',4,9,9,7,7,8,'Een typische Tarantino-film. Het is dus niet voor iedereen weggelegd. Maar voor wie houdt van een film zonder clichés, recht voor de raap en zonder scrupules, zit goed met deze film. De karaktertekeningen zijn ongeëvenaard. De film boeit ook van begin tot einde. En het controversiële einde zet aan tot denken. Deze op het eerste gezicht simpel gemaakte film, is een absoluut onderschatte klassieker door acteerprestaties en plot.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(216,'Vertical Limit',2000,'29',124,'2003-09-04',8,7,7,9,8,9,'Weinig verrassende actiefilm, maar wel leuk voor klimmers. Het verhaal zit wat slapjes in elkaar en is nooit boeiend. Ook de actiescènes zijn niet echt adembenemend, maar wel goed gemaakt. Deze film verwatert na een veelbelovend begin. Spijtig. Beeld en geluid zijn ok, maar achteraf bekeken is het maar een gewoon filmpje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(217,'Shallow Hal',2001,'170',113,'2003-09-04',8,6,6,8,8,7,'Als je echt niets anders te doen hebt, is deze film een aangenaam tijdverdrijf. Maar daarmee is ook alles gezegd. Op de enkele grappige momenten na, is dit een saaie en voorspelbare komedie. Volgens mij kon meer met dit idee gedaan worden, want het verhaal is toch wel origineel. Spijtige misser.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(218,'Coyote Ugly',2000,'171',100,'2003-09-11',8,5,4,8,7,8,'Een film met veel schone meisjes, en veel schone jongens, maar daarmee is alles ook gezegd. Het voorspelbare druipt er werkelijk vanaf, en het verhaal is ook op geen enkel moment boeiend of geloofwaardig. Alles loopt te makkelijk. Dit is een goeie blockbuster, maar een flauw kijkstuk. Beeld en geluid zijn goed, maar het verhaal is niets waard.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(219,'Identity',2003,'147',90,'2003-09-14',5,9,8,9,7,9,'Een meesterlijke psychologische thriller. Het is een geslaagde mix van diepe karaktertekeningen en klassieke schrikmomenten. Deze laatste zijn eerder voorspelbaar, maar de sfeer is zo goed gemaakt, dat dit niet noodzakelijk slecht is. Een van de betere films van de laatste tijd, sterk ondergewaardeerd. Beeld en geluid zijn heel erg goed. Deze film is ideaal om eens een avondje te schrikken en te huiveren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(220,'Speed 2: Cruise Control',1997,'137',121,'2003-09-18',4,5,4,8,7,8,'Dit is dan wat je noemt: het uitmelken van een goed concept. Speed was het voorbeeld van hoe een goeie no nonsens actiefilm moest zijn, maar deze breekt duidelijk met deze traditie. Deze weinig spannende vertoning moet het hebben van de dure spectaculaire SFX, maar heeft anders weinig of niets om het lijf. Beeld en geluid zijn zoals gezegd het enige goede.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(221,'Meet The Parents',2000,'157',108,'2003-09-19',4,8,8,7,7,7,'Niet echt mijn ding, maar zeker en vast een geslaagde komedie. Het brengt niet echt iets nieuws onder de zon, maar het geheel is heel goed uitgewerkt en geacteerd. Dit is een onderhoudende komedie, waar veel films nog iets van kunnen leren. Beeld en geluid zijn ook degelijk. Maar zoals gezegd is het niet echt mijn ding...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(222,'Speed',1994,'137',116,'2003-09-11',4,8,8,6,8,7,'Een actiefilm zoals het moet zijn. Het verhaal boeit, de actie is goed in beeld gebracht, maar net iets te (hoe kan het ook anders in dit genre) ongeloofwaardig voor mij. No nonsense meesterwerk in het genre. Muziek is goed, beeld is eerder matig, want van sommige stunts zie je de trucage.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(223,'Grease',1978,'172',110,'2003-09-20',4,7,6,6,9,8,'Deze klassieker uit 1978 is ongetwijfeld een musical die iedereen moet gezien hebben. Maar ik vind dat deze film niet echt iets nieuws bevat. Het bevat geen originaliteit, laat staan een moraal. Het verhaal zit eerder zwak in elkaar, en de vertolkingen zijn niet echt denderend. Dit laatste heb je wel meer in de jaren 70. Niet echt iets voor mij, maar een klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(224,'Enemy of the State',1998,'173',131,'2003-09-22',4,8,9,8,9,8,'Een geslaagde mix tussen een actiefilm en een misdaadfilm. Het misdaadverhaal zit goed in elkaar, en wordt goed aangevuld door actiescènes, die geloofwaardig zijn. De acteerprestaties zorgen ervoor dat je meegesleept wordt, en niet meer kan stoppen met kijken. Beeld en geluid zijn heel goed. Aangename film, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(225,'Crimson Tide',1995,'173',116,'2003-10-26',4,7,6,8,7,8,'Een typische duikbootfilm, met de gebruikelijke spannende momenten. Dit is een goede film in het genre. Maar het verhaal komt volgens mij nooit echt van de grond. Het slot is ook nogal simpel. En dat is toch vooral waat het om draait in een film. Hier kon meer van gemaakt worden, maar het is zeker genietbaar. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(226,'American Pie: The Wedding',2003,'174',97,'2003-09-27',5,8,8,7,7,7,'Het vervolg op deze goeie reeks tienerkomedies stelt niet teleur. Er zijn weer wat leuke momenten, en ook het typische ethische gebrabbel ertussen. Als je de eerste films gezien hebt, is dit zeker een aanrader. Maar anders stop je beter je tijd in iets anders. Een van de betere komedies van de laatste tijd. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(227,'Dr. T & the Women',2000,'89',121,'2003-10-03',NULL,4,5,5,6,5,'Het plot ziet er geweldig uit, maar de film is een echte ramp. Er komen weinig of geen komische momenten in, en het slot gaat al helemaal uit de bocht. Dit is didactisch materiaal in de filmschool: hoe een prachtig script verknoeien. Af en toe is er een schuchtere poging om het verhaal min of meer aandoenlijk te maken. Maar met dergelijke namen mag je veel meer verwachten. Beeld en geluid zijn ook niet al te best. Een teleurstelling!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(228,'Forrest Gump',1994,'16',142,'2003-10-14',4,8,9,7,7,8,'Deze film is zijn grote naam waardig. Het is een boeiend kijkstuk over het leven van een laagbegaafde man. Het is meeslepend, en soms lachwekkend. De film is soms ongeloofwaardig, maar dat is net de bedoeling. En dat loont, want pakkend is deze film zeker. Beeld en geluid zijn goed. Vooral de muziek draagt bij tot de sfeer. De acteerprestaties zijn fenomenaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(229,'Gattaca',1997,'175',101,'2003-10-16',4,8,8,8,7,7,'Dit is een onderhoudende en originele toekomstvisie van Niccol. Het verhaal zit goed in elkaar en blijft daarom boeien. Maar echte spanning ontbreekt wel. Dit hoeft echter niet slecht te zijn. Al bij al een sterk onderschatte film, maar ook geen meesterwerk. Beeld en geluid zitten goed in elkaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(230,'The Core',2003,'176',135,'2003-10-23',2,6,6,8,8,8,'Een sci-fi actiefilm met weinig nieuws om het lijf. Het is duidelijk een film met een hoog budget, maar de filosofie achter het verhaal is ietwat kinderachtig. De actiescènes zijn hoed gemaakt, en ook de effecten mogen er zijn. Het verhaal is echter compleet ongeloofwaardig en doet deze film de das om. Kortom een goeie no-brains actiefilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(231,'Kill Bill: Vol. 1',2003,'107',111,'2003-10-31',5,9,9,9,10,9,'Dit is spetterende Tarantino-actie. Het verhaal is ongelooflijk meeslepend door het goede beeld en geluid. De gebruikelijke Tarantino-stijl is duidelijk te zijn. Daarbij komt dan nog eens de spetterende (soms letterlijk) martial arts. Een juweeltje van een actiefilm, zowel voor de kenners als voor de leken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(232,'The Matrix Revolutions',2003,'152',129,'2003-11-07',5,8,7,10,10,9,'Dit is de derde film in de trilogie. Het is duidelijk dat de makers al hun kruit hebben verschoten in de eerste film. De tweede film was al een verzwakking van het verhaal met betere SFX, en het derde exemplaar is nog erger. Zelfs de addicts van het eerste uur zijn niet bijster positief. Het is en blijft een schitterende actiefilm, maar ze hadden er beter afgebleven. Geluid en beeld zijn fenomenaal, maar het verhaal is eerder zwak.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(233,'Taxi',1998,'159',86,'2003-11-09',8,7,7,8,7,8,'Dit is zo een van die wereldberoemde films onder jongeren. Het is dan ook een best leuke film, maar het verhaal is ronduit zwak. Bij momenten heel amusant, maar echt boeiend is deze film niet. De magistrale showbeelden zijn wel van wereldklasse, samen met het geluid van de ronkende motoren. Aangenaam, maar niet meer dan dat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(234,'The Four Feathers',2002,'177',131,'2003-11-10',3,8,8,8,7,8,'Deze film is valselijk gecatalogeerd als romantisch oorlogsdrama. Eigenlijk is dit een onderhoudende avonturenfilm in de tijd van de Engelse kolonies. Het is een leuke film, waar wel alles geweldig snel vooruit gaat, maar dat komt de boeiendheidsgraad wel ten goede. Beeld en geluid zijn degelijk. Zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(235,'Requiem For A Dream',2000,'178',102,'2003-11-25',8,8,9,8,7,7,'Dit is heel zware kost voor de doorsnee filmliefhebber. Bekijk dit niet als je een ontspannend filmpje wilt bekijken. Zoek je echter achter een steengoede pakkende film, dan ben je bij het juiste adres. De hardheid van het verhaal is enorm pakkend. Ook de karaktertekeningen zijn heel goed, samen met de goede beelden. Maar daarmee is alles gezegd. Als je niet in de juiste stemming bent, is dit een veel te zwaar kijkstuk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(236,'Baise Moi',2000,'179',77,'2003-12-01',8,7,8,6,6,7,'Een harde alternatieve film over twee vrouwen die wraak nemen op alles wat mannelijk is. Er wordt niets gemijd en het verhaal zit anders dan anders in elkaar. Beeld en geluid zijn deftig. Alleen jammer van het voorspelbare einde. Deze Franse klassieker is enkel voor de liefhebbers en mensen met stevige magen...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(237,'Bruce Almighty',2003,'180',101,'2003-12-07',8,6,7,7,7,6,'Een matige komedie waarin Jim Carrey zoals gewoonlijk weer veel bekken trekt, maar weinig nieuws brengt. De film heeft zijn leuke momenten en zijn origineel verhaal, maar daarmee stopt het ook. Het wordt totaal niet uitgewerkt en zomaar een moraal in geramd. Iets te veel blockbuster naar mijn hart... Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(238,'Finding Nemo',2003,'181',100,'2003-12-12',5,9,9,9,9,9,'Dit is een prachtige animatiefilm, een uitblinker in het genre. Het is een feel-good film met alles erop en eraan, en niet enkel voor kinderen. Dit is duidelijk de betere animatiefilm van de laatste tijd. Soms hilarische momenten, en prachtige typetjes. Beeld en geluid zijn uitmuntend. Deze film is af.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(239,'Confidence',2003,'182',97,'2003-12-13',3,8,9,7,8,7,'Een klassieke misdaadfilm met alles waar een fan van houdt. Het verhaal is niet te moeilijk, maar zit toch goed in mekaar. Het is geen originele film, maar zeker geen slechte, integendeel. Alle trucs van het genre worden toegepast. Voor als iemand eens iets anders wil dan ontploffingen, razende SFX en dergelijke. Beeld en geluid zijn heel degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(240,'Monsters Inc.',2001,'183',92,'2003-12-17',3,8,7,8,9,8,'Wat begint als een slechte poging tot moderne kinderfilm, eindingt in een leuk verhaal met de nodige actie, effecten en emotie. Beeld en geluid zijn van gebruikelijke Disney3D-kwaliteit, dus heel degelijk. Zeker een aangename film in het genre, maar een film als Finding Nemo is toch nog een graadje sterker...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(241,'It Could Happen To You',1994,'184',101,'2003-12-21',4,7,7,8,8,8,'Een aangename film, zonder meer. Het is zo voorspelbaar als iets, maar dat heb je nu eenmaal met dit genre. Het boeiende verhaal wordt optimaal uitgebuit. Beeld en geluid zijn ook goed. Het is dus een leuk kijkstuk, maar originaliteit is er zeker niet bij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(242,'Home Alone 3',1997,'185',102,'2003-12-25',3,6,7,8,7,7,'Het uitgemelkte concept van de Home Alone films, heeft blijkbaar toch nog wat druppeltjes over. Deze derde film is de beste van de drie, maar altijd heb je het gevoel dat je dit al eens eerder hebt gezien. Bekijk dit dus alleen als je de eerste films niet recent bekeken hebt. De ideale kerstfilm om met heel de familie te kijken is het wel. Uitgemelkt is het echter ook. Beeld en geluid zijn deftig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(243,'Ready to Rumble',2000,'186',107,'2003-12-26',4,7,7,8,8,7,'Een leuke film voor mensen die houden van WCW. Voor de rest is het een platte, simpele en voorspelbare komedie die zijn goede momenten kent, maar ook zijn hopeloze passages. Het is een film die je wel wilt uitkijken, maar een aanrader is het allerminst. Beeld en geluid zijn wel erg goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(244,'Meet Joe Black',1998,'187',178,'2003-12-20',4,8,7,9,8,9,'Deze romantische thriller is een leuke film voor als je eens veel tijd hebt. De lange speelduur valt nooit op, hoewel sommige verklaringen om het verhaal geloofwaardig te maken, serieus de mist in gaan. Het is namelijk nogal een origineel script. Er zijn sterke acteerprestaties en heel goed beeld en geluid. Maar al bij al is dit toch maar de zoveelste romantische film, hoewel het een goede poging is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(245,'The Lord of the Rings: The Return of the King',2003,'131',201,'2003-12-28',5,9,9,10,9,9,'Een waardig slot voor het indrukkwekkende verhaal. Het is een meeslepende mengeling van de eerste en de tweede film. Hoewel deze film iets te traag op gang komt, boeit hij tot het einde, net zoals de twee voorgangers. Beeld en geluid zijn zoals steeds fenomenaal. Zo ook de muziek. Schitterend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(246,'The Shadowshank Redemption',1994,'74',142,'2004-01-03',2,9,9,8,8,9,'Een van de beste gevangenisdrama\'s die er zijn. Het verhaal is boeiend en spannend, maar vooral zonder al te veel clichés. Beeld en geluid zijn prachtig om nog iets meer op de gevoelens van de kijker in te werken. Acteerprestaties zijn heel goed. Een goed drama, maar ook geen legendarische superfilm. Weinig extra\'s op de DVD.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(247,'Hard Rain',1998,'188',97,'2004-01-05',4,6,7,6,8,7,'Een gewone actiefilm over een overstroming. Daarmee is ook alles gezegd. Een grote naam als Morgen Freeman trekt natuurlijk aan, en hij stelt ook niet teleur. Maar de film zelf is eerder zwak en voorspelbaar, vol van de hollywood-clichés en eigenlijk totaal niet boeiend. Weinig origineel en soms zijn de SFX wel heel slordig. Geen aanrader, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(248,'Dumb and Dumberer: When Harry Met Lloyd',2003,'189',85,'2004-01-07',8,5,5,7,6,7,'Dit is humor van het allerdroogste kaliber. Weinigen zijn erin geslaagd om nog absurder te gaan in een min of meer normale film. Toch is dit af en toe een leuke film, met goede effecten en geluiden. Maar die momenten wegen niet op tegen het saaie karakter van deze film. Geen aanrader dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(249,'Silent Fall',1994,'190',101,'2004-01-15',4,7,8,7,7,7,'Een aangename film over autisme. Het boeit wel, maar echte spanning komt er nooit in. Interessant is het wel, maar om er echt tijd voor uit te trekken, is ook wat overdreven. De acteerprestaties zijn wel goed. Beeld en geluid zijn degelijk voor het genre. Aangenaam tijdverdrijf, maar dat is het dan ook.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(250,'The Opposite of Sex',1998,'191',105,'2004-01-21',4,8,7,9,8,8,'Deze film breekt met alle hollywoodclichés, of toch bijna. Dit alleen maakt het al amusant en vooral boeiend. Het verhaal zelf is minder van kwaliteit, maar de arrogantie van de acteurs maakt veel goed. Beeld en geluid zijn heel goed en origineel. Voor de liefhebbers van de iets alternatievere film zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(251,'Edtv',1999,'132',122,'2004-01-22',4,6,7,8,8,8,'Een komedie met een origineel verhaal op het eerste zicht. Dat is ook het enige wat er goed aan is. Het originele verhaal boeit, maar niet zoals het zou moeten. Verder staat de film bol van de voorspelbare clichés. Best genietbaar, maar zeker niet meer dan dat. Beeld en geluid zijn wel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(252,'The Last Samurai',2003,'192',154,'2004-01-29',5,9,9,10,8,9,'Het meeslepende verhaal van het verdwijnen van de Samurai. Het hollywoodgehalte mag helaas niet ontbreken, maar men heeft echt geprobeerd om dit zoveel mogelijk te weren. Een meeslepend en indrukwekkend verhaal met schitterend beeld en geluid. Acteerprestaties zijn van het hoogste niveau. Een indrukwekkende film...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(253,'Kiss the Girls',1997,'193',111,'2004-02-28',4,7,6,7,7,7,'Dit kan je het best samenvatten als het B-kantje van Se7en. Het verhaal mist wel dat tikje dat het een klassieker maakt. Rustig kabbelend, kan je het samenvatten. Als er een probleem is, wordt dit altijd wonderwel opgelost. Nooit boeiend, laat staan spannend. Dit is hoe Se7en kon zijn indien het slecht gemaakt was. Niet echt aan te raden maar leuk voor de liefhebbers. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(254,'Cobra',1986,'194',87,'2004-02-04',4,4,5,6,4,4,'Best te omschrijven als \"Junk food for the mind\". Deze actiefilm is degelijk qua SFX, maar het is absoluut no-brains niveau. Heel wat onrealischisch geschiet en met veel ontploffingen, maar dat is het dan ook. In die tijd waarschijnlijk wel redelijk indrukwekkend qua beelden en geluiden, maar nu iets voor -12 jarigen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(255,'Me, Myself and Irene',2000,'170',116,'2004-02-04',4,7,6,8,7,8,'Een aangename komedie over een schizofrene man. Dit wil echter niet zeggen dat het medisch correct is, verre van. Jim Carrey zelf is subliem in dergelijke rol. Zeer aangenaam om te volgen, al duurt het naar mijn idee nogal lang. Zeker een aanrader als je niets beters te doen hebt. Beeld en geluid zijn heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(256,'The Godfather',1972,'195',175,'2004-01-30',4,9,9,7,8,7,'Een absolute klassieker. Zoals dit worden er geen films meer gemaakt, denk ik. Een boeiend en spannend mafiaverhaal. Het houdt je aan het scherm gekluisterd van begin tot einde, ondanks de lange duur. Beeld en geluid zijn goed voor die tijd en de acteerprestaties zijn heerlijk. Een klassieker voor de meerwaardezoeker en natuurlijk voor wie van misdaadfilms houdt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(257,'The Mask of Zorro',1998,'29',136,'2004-02-09',4,8,7,9,7,8,'Een film die beter uitdraaide dan ik verwachtte. Ik dacht dat het een verkrachting van het Zorro-verhaal ging zijn, maar dat is het absoluut niet. Het is natuurlijk een \"verhollywoodsing\" van het verhaal, maar het boeit wel en is zeer leuk om volgen. Beeld is heel goed, geluid is degelijk. Antonio Banderas en Catherine Zeta-Jones maken dit verhaal een aangenaam kijkstuk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(258,'Virus',1999,'196',99,'2004-02-10',4,3,3,7,6,7,'Een absoluut stuk afval van een film. Dit is een flop van het zuiverste soort. Het boeit nooit, laat staan dat het ooit spannend is. Onrealistisch tot en met. Beeld en geluid zijn degelijk, maar aangezien de film op niets trekt... Waarom heb ik dit afschuwelijk kijkstuk moeten aanschouwen?','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(259,'Analyze This',1999,'197',103,'2004-02-11',4,8,8,7,7,7,'Een heel degelijke parodie op The Godfather. Meer is er niet over te zeggen. Er zijn wat dode momenten, maar ook wat hilarische passages. Het boeit en is grappig, zonder bijzonder te zijn. Zo zouden er meer komedies moeten zijn. Degelijk en aangenaam, net zoals het geluid en beeld.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(260,'Beowulf',1999,'198',95,'2004-02-12',4,5,5,6,6,7,'Een eigenaardige verfilming van een bekend verhaal, waar men best was afgebleven. Christopher Lambert schittert natuurlijk in zo\'n vechtersrol, maar de film geeft een continue B-film indruk. Zelfs de muziek klinkt zo. Je kan het een kans geven als je niets beters te doen hebt, maar een aanrader kan je het niet noemen. Beeld is ook soms iets te goedkoop gemaakt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(261,'Ronin',1998,'199',121,'2004-02-25',4,8,9,7,8,7,'Een heel degelijke actiefilm, zoals die moet zijn. Deze keer een film met realistische achtervolgingen, goede SFX en een goed verhaal. De acteerprestaties zijn ook goed. Alles zit dus goed, maar voor een of andere onduistere reden zit er een wel heel amateuristische scène in verwerkt. Waarschijnlijk later met Photoshop bijgewerkt. Maar al bij al een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(262,'The Rainmaker',1997,'195',135,'2004-02-24',4,7,7,8,8,7,'Een leuke advocatenfilm. Een goed verhaal, maar niet echt meeslepend. Het acteren verloopt wel vlot. Beeld en geluid zijn ok. Al bij al een redelijk tijdverdrijf, maar een echte topper wordt het nooit. Het is net iets te langdradig en komt nooit echt los van de intro.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(263,'The Godfather: Part 2',1974,'195',200,'2004-02-28',8,9,8,7,8,8,'Uiteraard is dit een ware klassieker, maar het mist wel wat power dat wel te vinden is in de eerste film. Het gaat net allemaal een beetje te traag. Je kan dan zeggen dat dit het verhaal verbetert, maar echt veel nieuws is er niet. Al bij al toch een klassieker, maar als je de eerste gezien hebt, heb je deze ook gezien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(264,'The Godfather: Part 3',1990,'195',162,'2004-02-28',8,8,8,8,7,7,'Ik vreesde voor een mislukte sequel om wat geld te verdienen. Maar het valt al bij al nog wel mee. Het slot is eerder raar te noemen, omdat de rest van de film eerder traag vooruit gaat. Ook het begin is niet echt van een hoog niveau te noemen. Toch zeker een klassieker, hoewel er opnieuw niet veel nieuws aan is...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(265,'Mona Lisa Smile',2003,'10',117,'2004-02-22',5,6,7,7,8,7,'Leuk tijdverdrijf, maar niet echt een aanrader. Het is een gewoon verhaal van een vrouw in een conservatieve mannenwereld. Het feminismegehalte is net op niveau, zonder echt storend te worden. Zeker geen slechte film, maar waarom zou je hiervoor geld geven? Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(266,'Deuce Bigalow: Male Gigolo',1999,'200',88,'2004-02-23',4,8,8,9,8,8,'Een leukere komedie dan ik had verwacht. Deze film kent zijn hilarische momenten, zonder ooit maar eventjes wat dieper te graven. Een degelijke no-brains film voor als je eens goed wil lachen. Zeker te genieten! Beeld en geluid zijn zeer goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(267,'Mission Impossible 2',2000,'201',123,'2004-02-26',3,7,7,9,8,9,'Een van de betere actiefilms van de laatste jaren. Het hele verhaal is natuurlijk redelijk onrealistisch, maar het is wel best spannend. Beeld is fenomenaal en ook het geluid mag er wezen. Echt meeslepend wordt het nooit, maar deze film heeft dat zeker niet nodig. Leuk als je eens een hele reeks explosies in een avond wil zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(268,'Felicia\'s Journey',1999,'202',116,'2004-03-03',4,9,9,8,7,8,'Een heel meeslepend drama/thriller over een wel heel lief meisje die het slachtoffer wordt van haar eigen naïviteit. Het begint wat traag, maar dit is nodig om tot het krachtige slot te komen. Dit is een heel erg goede film, voor de meerwaardezoeker. Beeld en geluid zijn degelijk. Acteerprestaties zijn fenomenaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(269,'Girl with a Pearl Earring',2003,'203',95,'2004-03-08',5,7,7,8,7,7,'Een aangename film over Johannes Vermeer en zijn Delft. Beeld en geluid zijn degelijk. Ook de acteerprestaties zijn goed. Alleen het verhaal blijft wat achter, al kan dit wat met persoonlijke smaak te maken hebben. Niet echt iets uitgesproken goeds of slechts over te zeggen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(270,'Pay It Forward',2000,'204',123,'2004-03-13',4,8,8,8,8,8,'Dit is een drama die mij direct aansprak en mij bleef boeien tot het einde. Dat alleen verdient al een pluim. Beeld en geluid zijn goed. De acteerprestaties zijn uitmuntend. Het verhaal zit goed in elkaar, op wat kleine clichés na dan. Zeker een aanrader als je een pakkend verhaal wil zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(271,'The General\'s Daughter',1999,'68',116,'2004-03-14',4,7,7,8,7,8,'Eveneens een deftige vertoning. Het verhaal neemt je mee naar de interne keuken van het leger. Het moddert wat aan in het begin, maar boeit des te meer op het einde. Ook zijn er soms wat leuke passages, maar ook niet echt veel. Het enige echt spijtige aan deze film is dat het slot erg voorspelbaar is. Een leuke film, maar geen echte hoogvlieger.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(272,'The Devil\'s Own',1997,'205',111,'2004-03-15',4,7,6,8,7,8,'Een redelijk magere film over het IRA. Er wordt gepoogd om het verhaal van de IRA in te kaderen in een Hollywoodfilm, maar dat mislukt hopeloos. De acteurs blinken ook niet echt uit. Echt veel spannende momenten zijn er niet te vinden. Toch heeft deze film wel iets dat blijft boeien tot het einde. Niet slecht dus, zeker niet qua beeld en geluid, maar ik had er meer van verwacht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(273,'Big Fish',2003,'50',125,'2004-03-20',5,9,9,9,8,8,'Wat begint als een flauwe Forrest Gump rip-off, eindigt als pakkend kijkstuk. Dit is een film die moeilijk in een genre thuis te brengen valt. Het blijft wel boeien en heeft een schitterend slot. Zeker een aanrader dus. Beeld en geluid zijn meesterlijk. De acteerprestaties mogen er ook zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(274,'Chicken Run',2000,'206',84,'2004-04-07',8,7,6,8,7,8,'Een animatiefilm zoals er niet veel zijn. Het is onderhoudend, en net niet te lang. Ook zijn er soms grappige momenten, maar de film mist iets. Het verhaal boeit nooit, al is dat ook niet de bedoeling. toch zal dat het zijn wat deze film de das om doet. Leuk om te zien, maar niet meer dan dat. Misschien is de Nederlandstalige versie beter.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(275,'Kill Bill: Vol. 2',2004,'107',136,'2004-04-30',5,9,8,10,9,9,'Het vervolg op de eerste film. Het is dan ook volstrekt onmogelijk om te volgen als je die niet gezien hebt. Beter of slechter kan je deze film niet echt noemen. Ik zou aanraden om de twee films na elkaar te bekijken. Het blijft natuurlijk een aparte film, en het is echt de moeite om te zien. Beeld en geluid zijn zonder meer subliem.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(276,'Pearl Harbor',2001,'98',183,'2004-04-19',4,5,4,7,6,7,'Een zogenaamde oorlogsfilm, met hier en daar wat fancy SFX, maar zeker niets meer dan dat. Het is totaal niet waarheidsgetrouw en het romantische verhaaltje getuigt helemaal van wansmaak. Dit gedeelte neemt zelf de aandacht weg van de gebeurtenissen, die dan nog eens verkeerd geschetst worden ook. Zeker geen aanrader, hoewel het geen slechte film is. Ik heb me er een beetje te veel aan geërgerd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(278,'Battle Royale',2000,'207',114,'2004-05-23',8,7,9,6,6,6,'Een stevige Japanse actiefilm met de nodige liters bloed die daarbij horen. Mocht dit een film zijn met Hollywood-budget, dan was het een meesterwerk. Nu is het een volledig geflipt verhaal, zonder de ondersteunende beeld en geluidskwaliteit. Spijtig, maar toch een aparte film voor de liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(279,'Prince of Darkness',1987,'208',102,'2004-05-11',4,5,5,7,5,6,'Waar je normaal gezien een goede horrorfilm van een man als Carpenter kan verwachten, gaat deze nooit verder dan een groot uitgevallen B-film. Beeld en geluid zijn redelijk goed voor de tijd, maar het is en blijft low-budget. Geen aanrader dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(281,'Deep Rising',1998,'209',106,'2004-05-19',4,7,6,8,8,8,'Een typische actiefilm over een groot zeemonster die alles en iedereen vermoordt. Hoewel je alles kan voorspellen en het verhaal totaal niet origineel is, blijft het wel spannend van begin tot einde. Het verhaal zelf is zo zwak als maar kan, maar het is op een of andere manier toch aanstekelijk gebracht. Beeld en geluid zijn goed. Al bij al niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(282,'Broken Arrow',1996,'201',108,'2004-05-20',8,7,7,8,7,8,'Een leuke no-brains actieprent met de nodige ontploffingen en speciale effecten. De film is redelijk boeiend, hoewel het eigenlijk niets nieuws brengt. Niet slecht, maar ook niets speciaals. Beeld en geluid zijn goed tot zeer goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(283,'Mercury Rising',1998,'210',108,'2004-05-25',4,6,6,7,6,7,'Dit is een misdaadthriller die al zo\'n duizend keer eerder werd gemaakt. Het is best genietbaar, maar er zijn betere films in het genre. Hoewel het goed begint, komt de film nooit echt los van het begin. Geen echte aanrader dus. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(284,'Cruel Intentions 2',2000,'90',87,'2004-05-22',4,5,5,7,6,7,'Ongeveer exact dezelfde film als de eerste. Toch is er een belangrijk verschil, maar meer vertel ik niet. Soms zijn er wel goeie momenten, maar het overstijgt de eerste film nooit. Niet echt een aanrader, het lijkt meer een low-budget vervolg zonder inspiratie. Het is wel leuk als je de eerste film niet hebt gezien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(285,'Troy',2004,'23',163,'2004-05-29',5,7,6,9,8,9,'Een actiefilm die zich afspeelt in de tijd van de Grieken. Het is een jaarlijks terugkomend fenomeen van de verziekende blockbusters die dit soort films uitbraakt. Het brengt niets nieuws en is met moeite meeslepend. Het is gebaseerd op het boek van Homer, maar volgt het aan geen kanten. Mooie beeldjes, veel franjes, maar weinig inhoud.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(286,'Out of Sight',1998,'22',123,'2004-06-02',NULL,8,8,7,7,7,'Thriller die ook best als komedie kan gerangschikt worden. Een heel aangename film om volgen met af en toe passende humor en serieuze momenten. Een film voor tussendoor, maar daarom zeker niet slecht. Beeld en geluid zijn best ok. Er wordt gezegd dat de acteerprestaties niet te best zijn, maar ik heb daar weinig van gemerkt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(287,'The Virgin Suicides',1999,'211',97,'2004-06-10',4,7,7,7,7,7,'Een pakkend verhaal over een aantal meisjes en een aantal jongens. De film weet dus te boeien, maar niet meer dan dat. Waarschijnlijk ligt dat aan mijn persoonlijke voorkeur. Dit is voor mij een matige film. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(288,'The Taking of Pelham 123',1998,'212',100,'2004-06-12',4,7,8,7,6,7,'Een thriller of een gijzeling. Het heeft een beetje een B-film gehalte, maar verdient een pluim omdat het een aantal overbekende clichés vermijdt. Dat maakt het een boeiende film. Beeld en geluid zijn matig, maar zorgen toch voor de juiste sfeer. De acteerprestaties zijn goed, hoewel het bijna allemaal onbekenden zijn. Niet verkeerd...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(289,'Scent of a Woman',1992,'187',157,'2004-06-15',4,8,7,8,8,8,'Een goed uitgetekend drama met veel gevoel voor emotie. Toch zijn er net wat te veel clichés gebruikt om het te doen opbrengen. Voor de rest zeker een genietbare en boeiende film, maar niet echt geschikt voor een luchtige avond. Beeld en geluid zijn heel degelijk, acteerprestaties zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(290,'Pitch Black',2000,'213',110,'2004-06-16',4,8,8,9,7,8,'Het is de zoveelste film over vijandige monsters, zou je zeggen. In eerste instantie is dat ook waar, maar naarmate de film vordert, blijkt er toch heel wat in te zitten. Beeld en geluid zijn goed tot zeer goed. De film zelf wordt alsmaar boeiender. Jammer van het aantal clichés, maar voor de rest zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(291,'Gangs of New York',2002,'3',166,'2004-06-20',2,6,6,7,8,7,'Een historische misdaadfilm. Dit alleen maakt het al een geval apart. De originaliteit is het enige speciale aan deze film. Hoewel het allemaal wel goed in mekaar zit, is het wat flets en niet zo boeiend. Beeld en geluid zijn redelijk goed. Niet echt een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(292,'Shrek 2',2004,'115',92,'2004-06-28',5,8,7,8,8,7,'Een waardige opvolger van de eerste film. Sterker nog, deze sequal is een sterke verbetering. Boeiend en amusant van begin tot einde. Spannend is het natuurlijk niet, maar dat is ook de bedoeling niet van deze film. Gegarandeerd lachen! Beeld en geluid zijn heel goed. Aanrader, hoewel dit niet kan tippen aan Finding Nemo.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(293,'The Mexican',2001,'144',123,'2004-06-29',4,7,7,8,8,7,'Onderhoudend en soms komisch, maar al bij al brengt deze film te weinig. Beeld en geluid zijn goed en de film zelf ook wel. Moeilijk te zeggen wat ontbreekt. Een klassieker is het dus zeker niet, maar deze film hoeft zeker niet ontweken te worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(294,'I Know What You Did Last Summer',1997,'214',100,'2004-07-10',4,4,5,4,6,6,'Een zoveelste tienerthriller waarvan de parodieën beter zijn dan het origineel. Dit verhaal is supervoorspelbaar en verrast nooit. De krampachtige pogingen om iemand te doen schrikken en om spanning op te bouwen zijn te belachelijk voor woorden. Een absolute flop. Alleen het geluid trekt nog op iets.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(295,'The English Patient',1996,'215',160,'2004-07-13',2,9,8,9,8,8,'Een echte romantische klassieker. Het verhaal begint wat slapjes. Het eerste anderhalf uur zijn slechts opbouw. Maar plots verandert het verhaal in een pakkend epos. Het laat in eerste instantie een naar gevoel na, maar het is zonder meer een schitterende film met meesterlijk beeld en geluid.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(296,'The Punisher',2004,'216',124,'2004-08-01',5,8,7,8,7,8,'Een dermate overdreven actiefilm, dat het weer goed wordt. Deze zeer onderhoudende film is recht uit een stripverhaal getrokken en op beeld gezet. Schitterend, pakkend en spannend. Beeld en geluid zijn veel te spectaculair, maar dat hoeft niet negatief te zijn. Zeker een aanrader, ook voor wie niet zo voor actie te vinden is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(297,'King Arthur',2004,'217',126,'2004-08-08',5,8,7,8,7,9,'Een alternatief verhaal over King Arthur and his knights. Ga niet naar deze film kijken voor een verfilming van de boeken, maar wel om een goed ridderverhaal te zien met bekende figuren. Waar de film nooit echt memorabel is, is het zeker ook niet slecht. Voor de fans van ridderverhalen is dit ongetwijfeld een hoogtepunt. Beeld en geluid zijn heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(298,'Johnny Mnemonic',1995,'218',103,'2004-08-10',4,3,2,6,6,7,'Deze film werd aangekondigd als de grootste Canadese blockbuster ooit. Voor die jaren zitten wel wat peperdure SFX inbegrepen, maar de plot is helemaal niets waard. Het is niet meeslepend noch spannend. Na een uur begon de verveling toe te slaan. Kelderniveau...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(299,'Martha, Meet Frank, Daniel and Laurence',1998,'219',88,'2004-08-12',4,8,7,8,7,7,'Een van de betere romantische films van de laatste jaren. Het verhaal boeit echt. Soms zijn er ook echt hilarische momenten. Pas in de laatste 10 minuten vervalt het verhaal in een klassieke romantische huilplot. Dat doet wat af van het over het algemeen voortreffelijke oordeel. Beeld en geluid vallen niet echt op in positieve of negatieve manier.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(300,'The Tragedy of Othello: The Moor of Venice',1952,'220',90,'2004-08-13',3,7,8,4,4,4,'Een heel oude, maar heel goede film. Het verhaal is de klassieker van Shakespeare. Helaas wordt in deze jaren heel anders omgegaan met een film. Daarom is het soms wat moeilijk te vatten waar het verhaal naartoe wil. Tenminste, als je het verhaal nog niet kent. Beeld en geluid zijn uiteraard niet goed in die jaren. De acteerprestaties zijn wel goed. Misschien toch een iets recentere versie bekijken volgende keer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(301,'Arlington Road',1999,'133',117,'2004-08-13',4,7,8,8,7,7,'Nog voor de aanslagen van 9/11 was terrorisme al een heet thema blijkbaar. Hoewel het een beetje simplistisch wordt voorgesteld, is deze film zeker onderhoudend en spannend. Ook heeft de film verbazingwekkend weinig last van clichés en voorspelbaarheden. Beeld en geluid zijn heel goed. Over het algemeen een goeie film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(302,'Fahrenheit 9/11',2004,'122',122,'2004-08-15',5,9,9,8,7,7,'De volgende docu van Moore. Deze keer gaat het over de absurditeiten van Bush en de oorlog in Irak. Opnieuw is het pakkend en shockerend, hoewel de meeste Europeanen die de actualiteit volgen, het meeste al wel zullen weten. Toch is de opeenvolging van schandalige praktijken leuk om te zien. Zeker een aanrader en iets wat de meeste Amerikanen zouden moeten te zien krijgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(303,'I Still Know What You Did Last Summer',1998,'82',100,'2004-08-18',4,3,2,6,4,5,'Deze film is zo mogelijk nog slechter dan de vorige. Het is hetzelfde liedje van een onmogelijke plot en een krampachtige poging om spanning op te wekken. Maar nu komt er nog bij dat het verhaal niet meer klopt met dat van de eerste film. Zo wordt het echt wel hilarisch en onvergeeflijk. Wat een mislukking...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(304,'Top Gun',1986,'173',110,'2004-08-25',3,8,7,8,9,8,'Een van de gekendere oorlogs-actiefilms. Het is een soort Iron Eagle met een romantische en populistische saus. Het verhaal is boeiend, de beelden zijn top voor die tijd en de acteerprestaties mogen er ook zijn. Dit is een klassieker en alleen daarom al geslaagd. Hoewel het Amerikaanse heldenverhaal een gevoel geeft van 13 in een dozijn. Soundtrack en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(305,'The Village',2004,'53',108,'2004-10-13',5,9,9,9,8,9,'Een van de betere films van het jaar. Deze spannende thriller is zeker niet wat je verwacht, maar net daarom blijft het boeiend. Het is een typische Shyamalan-prent, maar die stapt eindelijk af van het Sixth Sense-principe. Zeer verrassend. Beeld en geluid zijn meesterlijk. Zeker een aanrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(306,'From Dusk Till Dawn',1996,'221',108,'2004-08-25',4,6,6,8,6,7,'Wat begint als een slimme roadmovie met aangename dialogen, eindigt in een verschrikkelijke B-horrorfilm. Wat kon dit een goei film geweest zijn, maar van de ene seconde in de andere wordt alles om zeep geholpen. Spijtig, maar deze film is enkel in het eerste deel mijn ding. Acteerprestaties zijn wel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(307,'Jakob the Liar',1999,'222',120,'2004-09-01',4,8,8,7,6,7,'Deze film over de werkkampen in WOII is een van de betere. Het verhaal gaat over hoop, moed en durf. Deze eerder onbekende film blijft aan je ribben plakken en is eerder ongeschikt voor ontspanning. Toch een positieve indruk in het algemeen. Beeld en geluid zijn zuinig maar goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(308,'Twelve Monkeys',1995,'223',129,'2004-09-10',4,8,9,8,8,8,'Eindelijk een film over tijdreizen met wat niveau en een origineel verhaal. Deze actiedrama is boeiend vanaf de eerste minuut en blijft dat tot het einde. Je moet wel aandachtig zijn om de soms bizarre verhaallijn te volgen. Als dat lukt is het slot wel wat voorspelbaar, maar al bij al is dit zeker een aanrader. Beeld en geluid zijn heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(309,'Fight Club',1999,'79',139,'2004-10-05',4,8,8,7,7,8,'Laat het vooroordeel dat dit een domme actiefilm is met wat grote namen voor het geld maar vlug varen. Dit is een film met een statement, die niet altijd even realistisch is, maar de dialogen en karaktertekeningen zijn meesterlijk. Heel onderhoudend en soms ook wat ingewikkeld. Deze film blijft plakken en is minder geschikt voor liefhebbers van blockbusters.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(310,'Dodgeball',2004,'224',92,'2004-10-09',5,8,7,8,8,8,'Non-brains slapstick van de betere kwaliteit. Ik vreesde een absolute flop, maar deze prent is best wel hilarisch op sommige momenten. Als er een film is die ik zou aanraden om eens goed te ontspannen, is het deze wel. Beeld en geluid werken goed samen met de film. Ook de muziek is best OK. Een blockbuster die er een mag zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(311,'Thirteen Days',2000,'225',145,'2004-10-13',4,8,9,7,6,8,'Dit verhaal is een politieke prent die toont hoe de Kennedy\'s met de Cubaanse raketcrisis omgingen. Het is eerder een soort documentaire over allerlei politieke intriges. Het verhaal is zeker onderhoudend en spannend omwille van het feit dat je maar een kant te horen krijgt, en de vijand niet. Een aanrader voor wie zich voor politieke intriges interesseert. Een moeilijk te volgen en trage film voor anderen. Ik vond het de moeite waard. Hoewel je het einde van het verhaal al kent van voor het begin van de film, blijft dit spannend tot het einde. Grote klasse, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(312,'Jackie Brown',1997,'107',151,'2004-10-12',3,8,8,7,8,7,'Jackie Brown is precies wat je van een Tarantino-film kan verwachten. Verrassende plot en goeie personages. Al lijkt hij nog altijd wat te teren op het succes van Pulp Fiction. Toch is deze film zeker onderhoudend en niet echt moeilijk om volgen. Zeker een aanrader. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(313,'Natural Born Killers',1994,'34',118,'2004-10-19',8,7,7,9,8,8,'Een ribbenklever. De film zit nogal eigenaardig in elkaar geflanst, maar al bij al is het goed te volgen. De voorspelbaarheid is eigenlijk het enige echte grote nadeel. Bekijk dit dus met niet al te hoge verwachtingen, om teleurstellingen te vermijden. Niet slecht, maar in deze plot zat meer. Beeld en geluid zijn heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(314,'Final Descent',1997,'226',100,'2004-11-22',4,7,7,7,7,7,'Dit is een remake van een seventies-film over een reddingsoperatie met een vliegtuig. Het is natuurlijk een B-film en origineel is het allerminst. Toch heeft deze film wel iets. Hoewel alles zéér voorspelbaar is, blijft het geheel toch boeien. Misschien ligt het aan het oerdegelijke beeld en geluid. Gezellig vertier met een vliegramp...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(315,'Primary Colors',1998,'227',143,'2004-10-27',4,7,6,7,7,8,'Een aangename film over de primary-verkiezingen in de USA. Hoewel men durf toont door enkele wantoestanden aan te kaarten, vervalt deze film toch al te vaak in het verkondigen van \"het goede gedrag\". Ergens geloof ik er dus niks meer van. Leuk voor fans van politieke films, maar er zijn beter films in het genre dan dit...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(316,'Ghost Ship',2002,'128',91,'2004-11-12',8,4,3,7,6,7,'Een onmetelijk zwakke horrorfilm. Het start allemaal veelbelovend, maar het hele verhaal verwatert nadien. Het kon me nooit boeien en het is zo voorspelbaar als iets. Dit is geen aanrader, op uitzondering van liefhebbers van de goeie oude schrikfilms. Leuk voor een avondje onder de vrienden, zal ik maar zeggen... Geluid en beeld zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(317,'Storm',1999,'228',104,'2004-11-25',4,3,2,4,6,5,'Een walgelijke film over een verschrikkelijk geheime operatie van de ongelooflijk slechtaardige overheid. Het is niets meer dan een klucht, waar zelfs de actiescènes sneller kunnen leiden tot een schaterlag, dan tot enige opwinding. Loop in een grote boog rond deze film...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(318,'Rush Hour',1998,'118',97,'2004-11-15',4,7,6,7,8,8,'Een soort late eighties-komedie die heel aardig uit de hoek komt. Het gaat over de vreemdeling die kennis maakt met het eigenaardige Amerika. Hoewel het thema al tot vervelens toe is verfilmd, blijft deze film boeien. Ook de gevechtsscènes zijn best geloofwaardig. Leuke no-brains ontspanning.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(319,'Rush Hour 2',2001,'118',94,'2004-11-16',4,7,6,8,8,8,'Een vervolg op de eerste film. Voor de meeste films is dat een brug te ver, maar dit exemplaar slaagt er in om beter te worden. Hoewel het geen meesterwerk is, blijft deze film ontspannen en boeien tegelijk. Een aangename komedie, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(320,'The Incredibles',2004,'229',121,'2004-12-10',5,8,8,8,9,8,'Een animatiefilm van de makers van Finding Nemo lokt aan. Deze film stelt niet teleur, ware het niet dat dit niet kan tippen aan zijn voorganger. Het verhaal is wel erg origineel. Een echt Bondverhaal in animatiestijl. Zeker een aanrader, maar uitmuntend is deze film niet. Een schaterlach hier en daar is onvermijdelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(321,'A Beautiful Mind',2001,'132',135,'2004-12-11',2,8,9,8,9,9,'Een heel aangrijpend drama die de realiteit van een psychische ziekte aantoont. Beeld en muziek zijn heel passend bij de verhaalwendingen. Het verhaal kleeft werkelijk aan de ribben. Een aanrader voor wie van de iets minder ontspannende films houdt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(322,'Snatch',2000,'230',104,'2004-12-14',8,9,9,8,8,8,'Een misdaadfilm die een kluwen van verhalen doet passen in elkaar. Dit maakt het geen gemakkelijke film om alle personages te volgen, maar het zorgt wel dat je van begin tot einde geboeid blijft. Af en toe een vleugje humor zorgt voor de perfecte afwisseling. Deze film heeft van alles iets en staat garant voor een leuke avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(323,'The 6th Day',2000,'231',123,'2004-12-15',4,6,5,8,7,7,'Een sci-fi actiefilm met Schwarzenegger zoals hij er al enkele heeft gemaakt. Hoewel het verhaal eigenlijk niet slecht is, wordt er te weinig uitgehaald in de film. Deze film is een teleurstelling, en geen echte aanrader. Beeld en geluid maken veel goed. Er zijn er ergere, maar goed kan je dit niet noemen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(324,'I\'ll Be Home for Christmas',1998,'232',86,'2004-12-19',4,6,5,8,7,7,'Dit is een typische Amerikaanse kerstfilm voor de hele familie. Soms kan die wel bekoren, maar meestal vervalt deze film in een opsomming van de Amerikaanse moraal. Misschien leuk om met de kinderen naar te kijken, maar niet meer dan dat. Hoewel beeld en geluid goed zijn, en het zeker de gezellige kerstsfeer ademt, brengt deze prent te weinig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(325,'The American President',1995,'233',114,'2004-12-20',4,7,6,7,7,7,'Deze prent wordt aangekondigd als een politieke komedie, maar in werkelijkheid is dit niets meer dan een romantische film. Maar wel een zoals het hoort. De clichés worden binnen de perken gehouden en dringen pas op het einde te ver door. Tot dan onderhoudt deze film best. Ook hete politieke thema\'s worden met een stevig statement aangepakt. Zeker een aanrader voor wie van het meer romantische genre houdt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(326,'Secrets and Lies',1996,'234',142,'2004-12-26',3,7,8,6,6,7,'Dit is een film over de beslommeringen van een doorsnee-Britse familie. Het gaat over de familierelaties van alledag met de verschillende moeilijkheden daarbij. Hoewel er nooit actie in voorkomt, weet de film de nieuwsgierigheid levend te houden door af en toe wat mysterieuze informatie los te laten. Een nadenk-film voor als je iets meer wil dan alleen maar ontspannen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(327,'Liar Liar',1997,'104',86,'2004-12-26',4,7,7,7,7,7,'Een typische Jim Carrey-overacting-prent. Als je houdt van de humor van Carrey, zal je dit beslist een goeie prent vinden. Ook als je eens lekker onderuitgezakt wil lachen, bekoort deze film zeker. Meer omvat de prent echter niet. Daarom geen bijster hoge score. Alles is zoals het hoort. Niets meer, niets minder.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(328,'Coming to America',1988,'235',117,'2004-12-27',4,8,8,7,6,6,'Het is goed dat er nog zekerheden in het leven bestaan. In dit geval: Een film met Eddie Murphy kan altijd bekoren. Deze no-brains komedie kan iedereen doen ontspannen en hoeft niet naar te droge humor te grijpen om humoristisch te blijven. Zeker geen slechte prent. Ook dat typische eighties-sfeertje doet er veel aan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(329,'Liberty Stands Still',2002,'236',92,'2005-01-02',4,8,9,7,6,7,'Dit werd aangekondigd als een actiefilm, maar er is bitter weinig actie te bespeuren. Het verhaal bestaat hoofdzakelijk uit een intelligente dialoog tussen twee personen. Het blijft voortdurend boeien en dat alleen is al bewonderendswaardig. Een aangename kijkfilm, zonder veel extra\'s.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(330,'Michael',1996,'108',105,'2005-01-12',NULL,8,8,8,8,8,'Dit is een soort sprookje over een engel die naar de Aarde gestuurd is om een opdracht te vervullen. Het verhaal is boeiend en soms ontroerend. Dit is dé ideale ontspannings- en feel-good film. Beeld en geluid doen aardig mee. Een leuke prent, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(331,'Monster\'s Ball',2001,'237',111,'2005-01-18',4,8,8,7,7,7,'Een rauw drama over hoe een leven volledig in de soep kan draaien. Bekijk deze film niet als je een blij verhaal wil, of iets dergelijks. Dit is een absolute rauwe tekening van hoe hard het leven kan zijn. Meeslepend is het zeker wel. Kwaliteit gegarandeerd, maar enkel voor de liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(332,'Black Hawk Down',2001,'54',144,'2005-01-21',4,7,6,8,7,8,'Door de fenomenale reclamecampagne rond deze film, verwachtte ik een \"Pearl Harbor\"-achtig misbaksel van een oorlogsdrama. Ik werd aangenaam verrast. Dit is een degelijke oorlogsfilm, maar de Amerikaanse propaganda is nooit veraf. Een boodschap ontbreekt ook, het is gewoon een verhaal verteld uit het Amerikaanse standpunt. Beeld en geluid maakt veel goed, al is de muziek niet uitmuntend. Al bij al geen aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(333,'Closer',2004,'227',104,'2005-02-04',5,8,8,9,8,8,'Voor een keer een intelligente romantische film uit Hollywood. Het gaat allemaal wel wat snel, maar meeslepend is het zeker. Voor klassieke feel-good romantiek ben je aan het verkeerde adres. Zeker een aanrader! De hele sterke cast doet daar enorm veel aan. Beeld en geluid zijn heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(334,'Spy Game',2001,'173',126,'2005-02-07',4,7,7,7,8,8,'Een wat klassieke film over terrorisme en de CIA. Het is best een genietbare film, maar het brengt weinig nieuws onder de zon. Al bij al niet slecht, maar echt boeiend kan je dit niet noemen. Beeld en geluid zijn sterk, maar dat mag je verwachten van dergelijke blockbuster.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(335,'Hot Shots',1991,'238',84,'2005-02-11',3,6,7,5,7,7,'Een legendarische absurde film. Deze parodie op Top Gun en nog wat andere gevechtspilootverhalen, is er soms wat over. Af en toe is deze film echt hilarisch, maar die momenten kan je wel op een hand tellen. Een aanrader voor de liefhebbers, maar er zijn al betere gemaakt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(336,'Serendipity',2001,'75',103,'2005-02-15',4,8,8,7,8,7,'Een feel-good romantische prent dat wel op een of andere manier geweldig blijft boeien. Van begin tot einde een glimlach op je gezicht, en zo hoort dat te zijn bij dit soort film. Een prachtfilm in het genre. Beeld en geluid zijn ook best ok.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(337,'Der Untergang',2004,'239',156,'2005-02-16',5,8,8,7,7,7,'De beste omschrijving: Een belangrijke film. Het geeft het einde van de oorlog weer vanuit het standpunt van de Duitse oppermacht. Dat is heel moedig en zeker interessant. Beklijvend is deze film helaas niet, maar het stemt wel tot nadenken. Zeker een aanrader voor de liefhebbers van de \"betere film\".','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(338,'Timon & Pumbaa: De Wereld Rond',2003,'240',80,'2005-02-26',4,7,7,8,7,7,'Een tekenfilm met de avonturen van Timon & Pumbaa. Schitterend voor de kleintjes en zeker te genieten voor de iets groteren. Soms hilarisch, soms kinderachtig. Als je eens lekker kinderachtig naar een hilarische tekenfilm wil kijken, is dit zeker je ding.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(339,'Gothika',2003,'241',98,'2005-03-02',8,6,6,8,8,8,'Een typische blockbuster die weinig nieuws brengt. Het is het zoveelste spookverhaal met gillende meisjes en te verwachten schrikmomenten. Als goeie oude angstfilm komt deze prent goed uit de verf, maar daarmee is ook alles gezegd. Beeld en geluid maken de spanning en zijn dus goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(340,'Cats & Dogs',2001,'242',87,'2005-03-20',3,6,6,7,7,6,'Een kinderkomedie over het eeuwig durende duel tussen katten en honden. Wie een zwak heeft voor dieren, zal dit een goeie film vinden. Anderen zal men minder kunnen bekoren. Af en toe een schaars komisch moment houdt deze prent recht. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(341,'Shark Tale',2004,'243',90,'2005-03-21',2,7,7,8,8,8,'Alweer een goeie animatiefilm in de reeks volgend op Shrek. Nieuw is dit niet, maar het weet wel te boeien. Het is gewoon weer een degelijke parodie, maar dan in animatievorm. Het beeld en geluid is heel degelijk, maar echt vernieuwend is deze prent niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(342,'De Indringer',2005,'244',120,'2005-03-27',5,6,7,7,6,7,'Een Belgische film, opgenomen in de Ardennen. Het is alweer een poging om een goeie thriller op poten te zetten. Deze prent komt echter nooit verder dan aangename zondagavondtelevisie. Spannend is deze film nooit, hoewel het verhaal er heel wat kans toe geeft. Met zo\'n plot kon meer worden gedaan. Aangenaam, maar toch ontgoochelend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(343,'The Chronicles of Riddick',2004,'213',119,'2005-03-28',8,7,6,8,7,8,'Een zogenaamd vervolg op Pitch Black. Het viel te verwachten dat de film in geen eeuwen meer op Pitch Black zou lijken, maar zou verwateren in een droge actiefilm. Precies, special effects ten top, hevige actie, maar weinig inhoud. Qua actie is dit een topper, maar de inhoud ontbreekt het ene moment, en het andere is het onbegrijpbaar. Spijtig...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(344,'Zoolander',2001,'245',89,'2005-04-02',4,8,7,8,8,8,'Een lekker vettige komedie zonder inhoud. Het steekt enorm de draak met de modewereld, en bezorgt je voor de rest gegarandeerd een goed humeur. Een simpele goeie komedie, meer moet dat niet zijn. Ben Stiller acteert zeer sterk. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(345,'Thirteen',2003,'246',100,'2005-04-04',8,6,6,8,6,7,'Een drama over hoe enkele tienermeisjes verzeild geraken in de criminaliteit en drugs. Het is een soort goedkoop afkooksel van Requiem For A Dream. Boeiend is dit nooit, maar het is al bij al toch een redelijk sterke film. Al is het maar voor de kritische toon op de stoerdoenerij van pubers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(346,'Million Dollar Baby',2004,'28',132,'2005-04-08',5,8,8,8,7,8,'Dit drama is een absolute topper. Weinig films weten zo ongemerkt over te schakelen van actie naar drama. De acteerprestaties maken het geheel meeslepend en sterk. Een ribbenplakker is dit niet, maar pakkend zeker en vast. Beeld en geluid zijn ook heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(347,'Never Say Never Again',1983,'43',134,'2005-04-29',4,6,7,6,8,8,'Een doodgewone bondfilm. Zinloos, maar leuk. Het dateert van de periode dat een Bondfilm nog inhoud had. Het verhaal is goed, maar de beeldkwaliteit is eerder zwakjes voor de jaren 80. Al bij al genietbaar, maar er zijn betere Bondfilms.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(348,'Cypher',2002,'247',95,'2005-06-02',8,8,8,9,9,8,'Een sci-fi spionage film die boeit van begin tot einde. Soms is dit verhaal wat voorspelbaar, maar de verwikkelingen volgen elkaar snel genoeg op om verrassend te blijven. Beeld en geluid zijn heel goed. De muziek is heel sterk. Zeker een aanrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(349,'Basic',2003,'73',98,'2005-06-03',4,8,8,8,6,7,'De film heeft heel wat grote namen op de castlijst, en die stellen zeker niet teleur. Hoewel de film soms iets te makkelijke wendingen neemt en het hierdoor af en toe wat ongeloofwaardig is, is dit zeker een sterke prent. Je moet wel wakker zijn. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(350,'Eyes Wide Shut',1999,'248',159,'2005-06-07',4,7,7,8,7,8,'Een film die begint met een verhaal over een koppel dat wat huwelijksproblemen kent. Serieuze intriges volgen snel. Hoewel dit een heel aparte film is, komt dit nooit echt uit de startblokken. Niet goed, niet slecht. Beeld en geluid zijn wel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(351,'Medusa\'s Child',1997,'88',170,'2005-06-09',4,6,6,7,6,7,'Een veel te langgerekte actiefilm over een vliegtuig in een storm met een of ander uiterst dodelijk wapen aan boord. Niets nieuws en uiterst voorspelbaar. Maar voor een of andere reden blijf je wel kijken. Laat maar zo...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(352,'Diamonds Are Forever',1971,'30',120,'2005-06-10',4,7,7,6,7,7,'Een van de betere Bondfilms. Sean Connery is nog altijd de beste Bond, vind ik. De plot is sterk qua Bondnormen en de effecten mogen er zeker zijn voor die tijd. Leuke Bondprent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(355,'Mindhunters',2004,'249',106,'2005-06-14',8,8,8,8,7,8,'Een bende profilers op een geschifte stage. Dat kan niet mislopen. Dit is en blijft spannend, maar je hebt gedurende de hele film een \"Dit heb ik al eens gezien\"-gevoel. Weinig nieuws onder de zon, maar best spannend en leuk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(356,'Pi',1998,'178',84,'2005-06-17',8,7,7,5,6,6,'Een heel alternatieve film, enkel voor de liefhebbers. Alleen al omdat de hele film in zwart-wit is. Een geniale wiskundige op zoek naar het antwoord op alles. Interessant om volgen, maar soms wat over de top. Wel boeiend, maar dus enkel voor wie een alternatieve prent wil zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(357,'The Glass House',2001,'55',106,'2005-06-19',4,5,5,7,6,7,'Een heel onopvallende thriller. Deze eenvoudige film is wel aangenaam om naar te kijken, maar boeit eigenlijk niet. Spannend is deze prent ook al niet. Met wat twijfel raad ik deze film af. Beeld en geluid zijn wel ok.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(358,'Driven',2001,'249',116,'2005-06-26',3,5,4,6,7,6,'Het zoveelste heldenverhaal in de autosport. Het geeft een volstrekt onrealistisch beeld van de CART-competitie. De film is al evenmin boeiend. Het is een soort \'The Fast & The Furious\', maar dan met echte racemachines. Als de ondertitels dan nog eens \'Front wing\' vertalen in \'Spatborden\', is het helemaal naar de haaien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(359,'Madagascar',2005,'250',86,'2005-06-28',5,8,8,8,9,8,'Een typische Dreamworks-prent met de bijbehorende onweerstaanbare personages. Dit is een niet echt overdonderende, maar zeker een boeiende animatiefilm. Het mocht zelfs best iets langer duren, naar mijn idee. Beeld en geluid zijn zoals steeds sterk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(360,'Overboard',1987,'251',106,'2005-07-03',3,7,7,7,6,7,'Een typische 80s-komedie met weinig om het lijf. Toch kan deze film best boeien en is dit een van de betere in het genre. Eenvoudig en voorspelbaar, maar het geeft toch een goed gevoel. Waarom eigenlijk niet. De typische 80s-style geeft amusant beeld en geluid.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(361,'The Girl in the Café',2005,'252',94,'2005-07-05',3,9,8,8,6,8,'Een film die aangekondigd wordt als een documentaire over de G8-top in 2005. Wat een misvatting! Dit is een romantische film van de bovenste plank, met wat indringende politieke achtergrond. Het sterke slot en meeslepende verhaal, maken van deze prent een echte topper.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(362,'I, Robot',2004,'253',115,'2005-07-09',8,8,8,9,8,8,'Enorm gehyped en daarom enorm gevreesd. Ik ben met de nodige argwaan beginnen kijken, maar werd heel aangenaam verrast. Hoewel dit een geliefkoosde film is voor de anti-scifi critici, is dit onmiskenbaar een sterke film. SFX zijn dik in orde, verhaal is wat voorspelbaar, maar boeiend. Goed, voor een vettige actiefilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(363,'The Terminal',2004,'8',128,'2005-07-09',8,8,8,8,7,8,'Een pakkende film over een gestrande reiziger op de JFK-luchthaven. Boeiend van begin tot einde, met een aardig tempo. Sterke acteerprestaties. Toch ontbreekt er iets aan deze film. Moeilijk te zeggen, maar een echte ribbenplakker is het niet. Beeld en geluid zijn wel ok.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(364,'Life',1999,'254',108,'2005-07-10',4,7,7,7,6,7,'Dit is eigenlijk niets meer dan een komisch afkooksel van \'The Green Mile\'. Door Eddie Murphy is deze film nog leuk. Door de verteller-stijl is deze film nog boeiend. Toch overvalt een \'Ach ja\'-gevoel mij na het bekijken van deze film. Het sterke slot maakt veel goed. Als je niets beters te doen hebt...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(365,'Crouching Tiger, Hidden Dragon',2000,'255',120,'2005-07-22',3,6,6,9,8,8,'Een oosterse gevechtsfilm, maar met een knipoog naar de westerse gewoontes. Voor de liefhebbers is dit een prachtfilm, en voor de leek is dit een goeie starter in het genre. Mij kon het echter niet altijd boeien. Beeld en geluid zijn nagenoeg perfect. Iets aparts, dat wel...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(366,'RoboCop',1987,'21',102,'2005-07-26',4,7,6,7,8,8,'Over deze klassieker valt niet zoveel te vertellen. Voor die tijd is dit een absolute topper. Tegenwoordig zijn de SFX wel wat achterhaald. Ook hun visie op de toekomst is wat bizar, maar kom... De film is wel boeiend en is perfect voor de no-brains-actie-liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(367,'1492: Conquest of Paradise',1992,'54',154,'2005-07-29',8,7,7,8,9,7,'Het verhaal van de ontdekking van Amerika, met een serieus blockbuster-sausje overgoten. Beeld en geluid zijn dan ook heel goed. De muziek is prachtig. Hier en daar is er een historische uitschuiver te merken, maar al bij al boeit dit grote avontuur wel. Na de film bleef ik met een leeg gevoel achter. Ik bleef wat op mijn honger zitten. Een beetje overschat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(368,'Herbie: Fully Loaded',2005,'256',101,'2005-08-07',5,8,7,8,8,8,'Een klassieke Herbie-prent. Totaal onrealistisch en plakkerig van het slijm, maar best genietbaar. Sterker nog, je gemoed wordt hiervan zeker en vast opgekrikt. Spijtig genoeg is de film wat van de vroegere magie kwijt, maar toch bespeur ik het nodige respect voor de oude films. Beeld en geluid zijn best OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(369,'Basic Instinct',1992,'21',123,'2005-08-12',8,8,9,7,7,7,'Een absolute klassieker in het genre. Deze intelligente thriller boeit van begin tot einde. Het pikante verhaal doet daar ook wel iets aan. Beeld en geluid zijn goed, maar de acteerprestaties zijn buiten categorie. Schitterend dus, maar iets te langdradig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(370,'Ordinary Decent Criminal',2000,'257',93,'2005-08-21',3,8,8,7,6,7,'Het verhaal van een misdadiger die het doet om de flikken op stang te jagen. Heel leuke film, zonder meer. Het ontbreekt wat aan uitzonderlijkheden om het echt te laten hangen bij de kijkers. Toch is dit zonder meer een aanrader voor iedereen. Beeld en geluid zijn best ok.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(371,'Alexander',2004,'34',175,'2005-08-19',8,8,8,9,7,9,'Het historische epos van Alexander de Grote is voor het eerst sinds lang nog eens een degelijke historische film na de misbaksels Troy en King Arthur. Hoewel die films wel onderhielden, kon deze film ook nog boeien en blijven plakken. Er is hier dan ook duidelijker gemikt op het vertellen van een juist verhaal in plaats van op de opbrengst. Beeld en geluid zijn van uitzonderlijke kwaliteit. Prachtig epos, maar alleen als je in de stemming bent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(372,'The Island',2005,'98',136,'2005-09-02',5,8,7,8,8,8,'Een leuke sci-fi film met een blockbuster-randje. Echt onrealistisch is het niet. Het geheel is voorspelbaar, maar weet erg te boeien door de acteerprestaties. Beeld en geluid zijn goed, zoals het hoort. Niet echt een topklassieker, maar zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(373,'Mr. & Mrs. Smith',2005,'87',120,'2005-09-17',2,7,7,8,7,7,'Dé blockbuster van het jaar. Met een absolute topcast lokt deze film het meeste bezoekers, maar dit is niet helemaal terecht. Een leuk kijkstuk, dat wel, maar een slot om van te kokhalzen. Nochtans is het slot hetgeen wat het meest blijft hangen. Beeld en geluid zijn goed, zonder meer. Dit is zeker een gemiste kans en ongetwijfeld wel een avondje leuke cinema.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(374,'Any Way The Wind Blows',2003,'258',127,'2005-09-27',4,7,6,8,9,7,'Een speciale Belgische film. Het is een samenvoegsel van het verhaal van 30 personen op een doordeweekse dag. Van een begin en einde is geen sprake. Je wordt er in gegooid en er even onverwacht weer uit getrokken. Dit kon me niet de volle twee uur boeien. De muziek is ijzersterk. Mijn chauvinisme gebiedt mij hier toch een goeie score aan te geven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(375,'Mr. Nice Guy',1997,'259',94,'2005-10-01',2,6,5,7,6,5,'Een typische Jackie Chan-prent met de indrukwekkende vechtscènes. Dit is de perfecte film voor een avondje no-brains entertainment. De plot is wel heel erg goedkoop, maar liefhebbers van Jackie Chan zullen daar niet om malen. Beeld en geluid zijn eerder matig. Al bij al een niet zo geslaagde vechtfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(376,'Double Jeopardy',1999,'190',105,'2005-10-04',4,5,5,6,6,7,'Geen aanrader. Nochtans is er een sterke cast en een aanlokkelijk thema. Het verhaal is echter niet uitgewerkt en je ziet het slot van mijlenver aankomen. Beeld en geluid zijn dan ook nog eens niets bijzonder en je komt uit bij een afrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(377,'Beethoven\'s 4th',2001,'260',93,'2005-10-11',2,3,4,5,7,5,'Bekijk deze film enkel bij gebrek aan beter. Het uitgemolken verhaal van de grote hond kon mij op geen enkel moment boeien. De grappen en avonturen zijn rechtstreeks afkomstig uit een B-kinderfilm. De visuele effecten zijn abominabel slecht. Enkel de muziek is op niveau. Absoluut vermijden, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(378,'AVP: Alien vs. Predator',2004,'261',101,'2005-10-14',8,8,7,9,8,8,'De verfilming van het legendarische videospel. De SFX, geluiden en muziek zijn heel goed. Deze prent weet te boeien van begin tot einde. Het is duidelijk ook niet bedoeld voor de zwakke magen. Let wel: Dit is enkel goed voor de liefhebbers van Sci-fi horror. Het verhaal kon ook best wat beter uitgewerkt worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(379,'Meet John Doe',1941,'262',122,'2005-10-15',4,8,8,5,5,5,'Dit moet zowat de oudste film zijn die ik ooit heb gezien. Het is zeker en vast de slechtste niet. Het verhaal blijft boeien en zit vol met ethische boodschappen waar je even bij stil blijft staan. De gemiddelde kijker zal het plot uiteraard te traag vinden, maar de echte filmliefhebber kan deze prent zeker appreciëren. Beeld en geluid zijn uiteraard niet goed, maar dat kan ook moeilijk anders in 1941.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(380,'The Sum of All Fears',2002,'263',124,'2005-10-20',4,6,6,8,7,8,'Deze film past goed in het angstaanjagende beeld dat de USA wil ophangen over massavernietigingswapens. De zoveelste simpele CIA-film over een verdwenen bom. De sterke cast kan deze film niet redden. Je kan het hoogstens onder \"aangename ontspanning\" catalogeren. Beeld en geluid zijn wel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(381,'Sneakers',1992,'263',126,'2005-10-30',4,6,6,7,6,7,'Een film over hackers van begin jaren 90. De nodige brainless hackingmethodes zijn natuurlijk aanwezig, maar wat moet je anders met zo\'n algemeen publiek. Gewoon verstand op nul en eens goed lachen met de geavanceerde computertechnologie uit 1992. De film zelf is weinig nieuws onder de zon.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(382,'The Saint',1997,'59',116,'2005-11-01',4,7,6,8,7,8,'Een typische nineties-actieprent over een superheld en een genie-meisje. Alles is wel leuk, maar het mist dat tikkeltje uniekheid. Het verhaal weet te boeien, beeld en geluid zijn goed, maar er zijn beter films in dit genre. Het is een soort zwak afkooksel van Bond. Toch al bij al een meevaller.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(383,'Devil\'s Pond',2003,'264',92,'2005-11-06',4,6,6,7,6,7,'Dit is een zwakke typisch Amerikaanse tienerthriller over een veel te eenvoudig uitgetekende psychopaat en een veel te paniekerig meisje. Veel gil en schrikwerk in het donkere bos, maar meer is er echt niet aan. Het plot is te eenvoudig en voorspelbaar voor woorden. Toch evolueert dit verhaal zodanig dat je nieuwsgierig wordt naar het slot. En dat is dan geen teleurstelling. Al bij al ondermaats.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(384,'X-Men',2000,'265',104,'2005-11-08',2,8,8,9,8,9,'Een comic-film over de overbekende X-Men. Net als DareDevil is deze prent een aangename verrassing. Hoewel het verhaal natuurlijk een echt stripverhaal is, blijkt deze film op en top boeiend. Voor een ontspannende filmavond is dit zeker een aanrader. Beeld en geluid zijn opperbest.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(385,'X-Men 2',2003,'265',133,'2005-11-11',2,8,8,9,7,8,'De sequal is voor een keer niet een verslechtering. Het verhaal wordt niet uitgemolken, maar wel nog versterkt. Het is zeker een aanrader als je de eerste film gezien hebt. Beeld en geluid zijn zoals steeds heel goed. Schitterende film voor een ontspannende filmavond, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(386,'Flightplan',2005,'266',98,'2005-11-26',5,8,9,7,7,7,'Een leuke en spannende thriller over een verdwenen meisje in een vliegtuig. De verrassende wendingen slepen je helemaal mee in een claustrofobisch verhaal. Jodie Foster is zoals gewoonlijk weer ijzersterk, hoewel de rest van de cast zeker niet moet onderdoen. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(387,'Bulletproof Monk',2003,'267',104,'2005-11-29',3,6,6,8,9,8,'Wat de titel (en de tagline: \'Don\'t mess with this monk\') al suggereert is de absolute waarheid. Dit is een absoluut hilarische B-martial arts prent. Beeld en geluid zijn toch heel goed (een eervolle vermelding voor de muziek), maar het verhaal is echt niks waard. Om eens goed te lachen is dit een ideale prent. Anders kan ik geen excuus bedenken om naar dit gedrocht te kijken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(388,'The Straight Story',1999,'66',112,'2005-12-03',2,9,9,9,8,8,'Een sterk onderschatte film. Hoewel deze prent internationaal zwaar in de prijzen viel, is het weinig bekend. De prijzen waren allemaal terecht. Dit absolute meesterwerk is een van de \'normaalste\' verhalen van de hand van Lynch. Meeslepend van begin tot einde en geen clichés. Zware kost, maar een aanrader eerste klas!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(389,'Trapped',2002,'268',106,'2005-12-11',3,8,8,7,6,7,'Onbekend en onderschat. Deze thriller gaat over het ideale Amerikaanse gezin met de juiste waarden, maar dat stoort enkel in het begin. Het verhaal boeit en sleept je van het ene gevoel in het andere. Een sterke Kevin Bacon zit daar voor veel tussen. Zeker een aanrader voor een goeie thriller. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(390,'Gladiator',2000,'54',155,'2005-12-23',4,9,9,9,7,8,'Een must-have-seen historisch drama. Waar films als Troy en King Arthur het genre meer slecht dan goed deden, herinnert deze prent ons aan de sfeer die dergelijke film kan opwekken. Een schitterende film waarin beeld en geluid meedoen met het plot (lees: heel goed zijn).','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(391,'Steve + Sky',2004,'269',100,'2005-12-24',2,6,6,6,8,6,'Een Belgische film dat wat in het genre van \'Any Way the Wind Blows\' valt. Deze laatste film is merkelijk interessanter. Enkel voor de liefhebbers van alternatieve romantische films is dit een aanrader. Ik vond het allemaal wat teleurstellend, inclusief beeld en geluid. De muziek bleef wel hangen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(392,'Stuart Little',1999,'270',84,'2005-12-24',4,7,6,8,6,6,'Een leuke kerstavond-komedie, ook voor de kinderen. Het is al bij al natuurlijk een kinderfilm, maar de schattigheid van Stuart Little maakt veel goed. Kijk hier natuurlijk niet naar als je een geloofwaardige film wilt. Niet opvallend, maar zeker niet mis.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(393,'Miracle on 34th Street',1994,'271',114,'2005-12-24',4,8,7,8,6,6,'Dit is een van de beste kerstfilms die ik al heb durven aanschouwen. Ik kan er zelfs positief over zijn. Het is een mooi verhaal. De vertolkingen zijn pakkend. Een feel-good movie voor de kerstdagen. Zeker niet af te raden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(394,'There\'s Something About Mary',1998,'170',119,'2006-01-03',4,9,9,7,8,7,'Een komedie waar ik met het nodige behoud aan begon, maar die een absolute verrassing was. Dit is nog eens echt een hilarische komedie waarvan er veel te weinig worden gemaakt. Boeiend en interessant van begin tot einde. Een absoluut meesterwerk. Beeld en geluid zijn weinig opvallend, maar toch goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(395,'2001: A Space Travesty',2000,'272',99,'2006-01-07',4,6,5,6,5,6,'Dat Leslie Nielsen het voordeel van de twijfel geniet na zijn Naked Gun-films, verbaast niemand. Deze film is het echter niet waard om in één adem met \'Naked Gun\' vermeld te worden. De goeie momenten zijn op één hand te tellen. Al de rest is zo zwaar overdreven dat je er zowaar medelijden mee krijgt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(396,'Saw',2004,'273',102,'2006-01-13',2,9,9,9,7,8,'Vlijmscherpe, spannende horror van begin tot einde. Deze ribbenplakker raakt iedereen. De verassende plot en de claustrofobische sfeer maken van deze film een echte topper. Hoewel het zeker niet voor de zwakke magen is, zou ik dit toch aan iedereen aanraden. Beeld en geluid zijn verder ook schitterend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(397,'Saw 2',2005,'274',93,'2006-01-20',5,9,9,8,8,9,'Een sterke verbetering ten opzichte van de eerste film. Het is een nog veel sterkere ribbenklever en het verhaal zit echt veel verrassender in mekaar. Het kan natuurlijk ook zijn dat de bioscoopomgeving het geheel wat verbeterd. Een aanrader voor kijkers met een sterke maag.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(398,'How to Lose a Guy in 10 Days',2003,'56',116,'2006-01-27',4,8,8,7,7,8,'Zowat hetzelfde verhaal als \"There\'s something about Mary\". Er werd een belachelijke romantische zakdoekprent verwacht, maar deze film bewijst het tegendeel. Het verhaal is wel wat slapjes, maar soms hilarisch. Voor een ontspannen avond is dit een echte aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(399,'Bad Company',2002,'106',125,'2006-02-01',NULL,6,6,8,7,7,'Met grote namen probeert deze film kijkers te lokken. Helaas is dat ook de enige troef van deze film. De actiescènes zijn best OK, maar over de rest valt weinig te vertellen. Al bij al te mager.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(400,'Lilo & Stitch',2002,'275',85,'2006-02-10',2,8,8,8,6,7,'Een ietwat aparte animatiefilm van Disney. Het feel-good verhaal is er wat uit, maar dat is dan ook het enige minpunt. Deze film brengt een boeiend kijkstuk door de tekenstijl en de humor. Helaas is de typische zagerige Disney-muziek er wel bij. Zeker een film om te bekijken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(401,'Men in Black',1997,'276',98,'2006-02-13',4,8,7,8,7,8,'Een klassieker in het Sci-fi/komedie-genre. Will Smith is natuurlijk outstanding en dat is ook noodzakelijk voor deze film. Het verhaal is weinig waard, het zijn de acteerprestaties die het hem doen. Zeker het bekijken waard, al was het maar omdat het jonge klassieker is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(402,'Lethal Weapon 2',1998,'277',114,'2006-02-16',4,7,7,8,7,7,'Een typische eighties-actieprent. Het verhaal windt er weinig doekjes om. Het is een rechtdoorzee actiekomedie met weinig technische hoogstandjes. Gewoon \"good old brute force\", en met success. Deze prent wordt verder vooral gedragen door de situatiehumor. Voor als er eens niets anders te zien is...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(403,'Super Troopers',2001,'278',100,'2006-02-03',4,9,9,8,8,8,'Een no-brains komedie over enkele highway patrol-agenten. De karikaturen en clichés druipen ervan af, maar dat maakt de film net hilarisch. Een onbekende film, maar een absolute topper in het ietwat absurde genre. Voor een ontspannen avond onder vrienden is dit een fantastische prent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(404,'The Score',2001,'279',124,'2006-02-20',4,9,9,9,8,8,'Wat mij het meest is bijgebleven zijn de 2 hoofdrollen die schitterend vertolkt worden. Dit maakt het verhaal geloofwaardig en meeslepend. De wendingen hebben de allures van een echte spionageprent. Een schitterend kijkstuk dat boeit van begin tot einde.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(405,'First Blood',1982,'280',97,'2006-02-26',4,8,8,7,7,6,'Deze film is beter gekend onder de naam \"Rambo\". Een klassieker tot en met. En bij het bekijken ervan weet je meteen waarom. Als je wat seventies-rariteiten eruit filtert, is dit een schitterend dramatisch verhaal over een vietnamveteraan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(406,'Two Weeks Notice',2002,'281',101,'2006-03-02',4,6,5,7,6,7,'Hugh Grant in een van zijn ontelbare zogezegde romantische komedies. Leuk voor de pubermeisjes, maar weinig boeiend voor de rest van de wereldbevolking. Niets nieuws te zien en het verhaal is al helemaal niet komisch. Er zijn veel betere films in het genre dan dit...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(407,'Antitrust',2001,'95',108,'2006-03-03',4,7,7,8,7,7,'Een film over computermisdrijven. Hoewel het verhaal natuurlijk volstrekt onmogelijk is in realiteit, bewijst deze film toch een van de meest realistische te zijn in zijn genre. Het verhaal zelf is niet slecht, maar ook niet uitzonderlijk. Aardige film, maar beter verdient dit niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(408,'The Interpreter',2005,'282',128,'2006-03-05',2,7,8,7,6,7,'Een misdaadfilm over een tolk in de VN. Het verhaal begint ontstellend zwak, maar naarmate de film vordert, verbetert dit wel. Het slot is dan uiteindelijk het beste van de film. Eigenlijk is dit absoluut niet slecht, maar indrukwekkend als term gebruiken is overdreven. Wel een sterke Nicole Kidman.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(409,'Good Night, and Good Luck',2005,'283',93,'2006-03-08',5,8,9,7,6,7,'Een controversiële film die subtiel een apart beeld werpt over de mediamaatschappij waarin we leven. Het zwart-wit maken de fifties-sfeer compleet. Boeiend van begin tot einde door de uitzonderlijk sterke cast. Je moet er wel wakker voor zijn, want deze film moet het vooral hebben van de dialogen...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(410,'The Art of War',2000,'284',117,'2006-03-10',8,4,4,6,5,6,'Wesley Snipes staat vaak synoniem voor vette actie. Dit keer draaide dit echter anders uit. De wel aanwezige zeldzame actie was wel goed. Men probeerde hier een \"intelligente Snipes-film\" uit de grond te stampen, maar dat voornemen heeft de film een dikke onvoldoende bezorgd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(411,'Tomb Raider 2: The Cradle of Life',2003,'137',117,'2006-03-17',4,6,5,8,7,7,'Een sequal die eindelijk eens wat beter is dan de eerste film. Maar dat was natuurlijk ook niet zo moeilijk. Deze film moet het vooral hebben van de spetterende actiescènes. Maar het blijft hoe dan ook redelijk kinderachtig. Enkel voor de liefhebbers van no-brains actiefilms, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(412,'Elektra',2005,'285',97,'2006-04-02',2,7,6,8,9,8,'Een soort half vervolgverhaal op DareDevil doet de stripfanaten watertanden. Toch is dit een heel ander type film. Het is een poging om een oosters-getinte strip te verfilmen, maar het vervalt in al te veel clichés. Beeld en geluid zijn wel goed. Al bij al een teleurstelling, maar leuk voor de stripfanaten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(413,'The Inner Circle',2003,'286',88,'2006-04-10',3,6,7,6,5,6,'Dit is een typische film om op VijfTV getoond te worden. Alles bij mekaar is dit wel een leuke verfilming van een uit de hand gelopen etentje. Toch is dit niet echt mijn genre en is het ook een B-film. Dat zie je vooral aan sommige acteerprestaties. Als je niets beters te doen hebt...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(414,'Ice Age 2: The Meltdown',2006,'120',91,'2006-04-22',5,8,7,8,7,8,'Dit is nagenoeg helemaal dezelfde film als de eerste. Dezelfde humor en dezelfde personages. Maar op een of andere manier blijft deze film een prachtig kijkstuk en is het bij momenten hilarisch. Een avond onder vrienden, borrelhapjes en deze film: Succes gegarandeerd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(415,'Tomcats',2001,'287',95,'2006-04-22',3,6,5,6,7,7,'De zoveelste sexkomedie. Hoewel er heel sporadisch eens een goed stuk in komt, blinkt deze film vooral uit in het ergeren van de kijker. Dit is een ideale film om eens een domme absurde avond mee te vullen. Er zijn betere films in het genre. Toch besluipt mij een \"waarom niet?\"-gevoel...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(416,'Any Given Sunday',1999,'34',150,'2006-04-29',4,8,8,8,7,7,'Een sportdrama over American Football die toch boeit, hoewel het geen populaire sport is in onze streken. Het verhaal over de nieuwe ster en de gestresseerde coach boeit van begin tot einde. Vooral de sterke Al Pacino blinkt uit. Zeker een aanrader, maar dit is zeker geen ontspannende film...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(417,'The Machinist',2004,'288',102,'2006-05-05',2,9,9,10,7,8,'Een man die al in een jaar niet meer geslapen heeft, begint te twijfelen aan zijn eigen geestelijke gezondheid. Schitterend en pakkend drama die op sommige momenten de spanning ten top drijft met eenvoudige situaties. De filmtechniek en de acteerprestaties maken dit een topper. Zeker een aanrader, maar eentje die zwaar op de maag ligt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(418,'Bicentennial Man',1999,'130',132,'2006-05-09',4,8,9,7,7,7,'Een heel aparte film, een beetje in het genre van AI. Toch speelt deze film veel meer in op emotie dan op speciale effecten. Het begint als een leuk verhaal, maar blijft hoe langer hoe meer plakken. Beeld en geluid zijn niet zo denderend, maar dit is zeker een aanrader voor wie eens wat anders wil.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(419,'The Hound of the Baskervilles',1983,'289',101,'2006-05-13',2,4,4,3,6,6,'Een low-budget B-verfilming van een Sherlock Holmes verhaal. Weinig interessant. Het moet wel gezegd dat de film er uitzonderlijk goed in slaagt om de sfeer van het oude Engeland over te brengen. Helaas is dat ook het enige positieve punt... Soms is het beter een boek niet te verfilmen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(420,'Earth Girls Are Easy',1988,'290',100,'2006-05-13',2,3,3,4,5,5,'Een komedie waarmee de carriëre van menig superster begon. Daarmee weet je ook meteen dat het een low-budget film is. Het blijkt ook aan de plot en... eigenlijk aan alles. Een absolute saaie prent. Je vraagt je af wie ooit dergelijke onzin heeft durven schrijven...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(421,'The Da Vinci Code',2006,'132',149,'2006-05-18',5,9,9,8,8,9,'Een enorme blockbuster die op het toppunt van het seizoen in de zalen komt. Maar eerlijkheid gebiedt mij te zeggen dat dit echt wel een klassefilm is. Het plot is fantastisch, de verfilming geniaal. Spanning van begin tot einde. Critici hekelen wel het gebrek aan detail in de film, die wel in het boek voorkomt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(422,'The Boondock Saints',1999,'291',110,'2006-05-20',2,8,9,8,9,9,'Dit is een soort kruising tussen Reservoir Dogs en Pulp Fiction. Maar dan wel een geslaagde. Het verhaal boeit en straalt een speciale sfeer uit. Niet al te ontspannend, maar zeker een aanrader. Hilarisch, meeslepend en spannend, Door zo\'n films herinnert men zich weer waarom films leuk zijn…','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(423,'Circus',2000,'292',95,'2006-05-27',2,7,8,7,7,7,'Dit is een poging om The Godfather in een hedendaags kleedje te stoppen. Het resultaat mag er best zijn, maar het blinkt nooit echt uit. Voor iemand die zin heeft in een \"zomaar\"-misdaadfilm, is dit een aanrader. Maar echte klasse moet je nooit in deze film zoeken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(424,'Donnie Darko',2001,'293',118,'2006-06-03',2,7,8,9,8,8,'Dit is een film die voor heel veel interpretatie vatbaar is. Dat vind ik ook meteen het grootste nadeel. Het is een rare film, die heel wat zaken suggereert, maar ze nooit echt feitelijk toont. De plot is heel goed, maar wordt nooit afgewerkt. Een ribbenplakker is het zeker, maar waarom zoveel mysterie?','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(425,'Memento',2000,'121',113,'2006-06-06',4,9,9,9,7,8,'Dit is de eerst film die ik ken die achterwaarts loopt. Het verhaal begint bij het einde en stilaan wordt het begin duidelijk. Deze eigenaardige volgorde vereist wel heel veel aandacht van de kijker. Die wordt beloond door de film als geheel. Boeiend, pakkend en interessant tegelijk. Zeker bekijken als je de kans hebt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(426,'The Break-Up',2006,'294',105,'2006-06-12',5,6,5,7,6,7,'De grote namen kunnen de magere verhaallijn niet verdoezelen. Het is soms wel eens leuk, maar al bij al is dit geen aanrader. Er bestaan veel beter films in het genre. Je kan niet echt zeggen dat deze film boeit, maar de liefhebbers zullen hier zeker van genieten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(427,'Suicide Kings',1997,'295',106,'2006-06-15',4,9,9,7,8,8,'Enkele kerels gaan eventjes een maffioso kidnappen. Dat alleen zegt al genoeg. De vertolkingen zijn op zijn minst gevat te noemen. Alles wat een goeie misdaadfilm moet hebben: humor, spanning en een sterk plot. Heel eigenaardig dat dit geen bekendere film is geworden...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(428,'Over the Hedge',2006,'296',83,'2006-07-07',5,9,9,8,8,8,'Alweer een typische animatiekomedie in de stijl van Shrek en Ice Age. Maar deze is wel heel erg geslaagd. De typetjes zijn heel goed gekozen. Het verhaal laat je lachen van begin tot einde en kent, in tegenstelling tot al te veel genregenoten, geen dode momenten naar het einde toe. Top...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(429,'Manneken Pis',1995,'297',89,'2006-07-14',4,7,8,7,7,6,'Een Belgische film met een klinkende naam. Dit verhaal is heel pakkend en straalt een heel aparte sfeer uit. Het is geen film om eens lekker te ontspannen, maar boeiend is het zeker. Toch slaagt men er niet in om het beeld van de typische B-film weg te werken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(430,'Head of State',2003,'298',95,'2006-07-19',4,5,4,7,6,7,'Het enige lichtpuntje in deze veel te vervelende komedie is hoofdrolspeler en regisseur Chris Rock. Hij is de enige die blijft boeien in deze overdreven prent over het presidentschap in de USA. Zeker geen aanrader, enkel als er echt niets anders te zien valt...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(431,'Pirates of the Caribbean: The Curse of the Black Pearl',2003,'144',143,'2006-08-11',4,8,7,9,7,7,'Hoewel ik eerst de tweede film heb gezien, blijft deze film wel boeien. Johnny Depp houdt de film grotendeels recht. Samen met het hele grote Blockbuster-gehalte van deze film, is dit zeker geen flop. Licht-verteerbaar vermaak...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(432,'Pirates of the Caribbean: Dead Man\'s Chest',2006,'144',150,'2006-07-30',5,7,7,9,7,8,'Bij dit soort films kan je er niet van uit dat ze net dat tikkeltje minder zijn dan de eerste film. Samen met het feit dat deze film eigenlijk in twee delen gekapt is, met het volgende deel dat maar volgend jaar uitkomt, ben ik tot de conclusie gekomen dat je best naar alle drie de films na elkaar kijkt. Maar ontspanned is het zeker...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(433,'What Dreams May Come',1998,'299',113,'2006-08-09',4,7,7,9,7,7,'Een heel aparte film over een gedurfd onderwerp, nl. de dood. Het romantische aspect verdoezeld de grote gaten in het plot wel wat. Maar door de heel aparte sfeer gaat deze prent allerminst de mist in. Voor de liefhebbers van dat tikkeltje anders is dit een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(434,'Big Momma\'s House',2000,'185',98,'2006-08-13',4,7,6,7,7,6,'Dit is een typische Martin Lawrence-film. Er zijn best leuke momenten, maar het commerciële gehalte ligt net wat te hoog. Een komedie mag wat voorspelbaar zijn, maar te veel is te veel... Zeker genietbaar als er niets anders te zien is. Een echte topper kan je het in geen geval noemen, maar toch goed geprobeerd en leuk voor onder vrienden...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(435,'The Musketeer',2001,'300',104,'2006-08-18',4,7,6,8,6,7,'Een actiefilm over de musketeers die de koninklijke familie moeten beschermen. Het typische historische kantje aan dit soort film is vervangen door een reeks overdreven hippe futuristische Matrix-actiescènes. Het is alweer een \"net-niet\" verhaal...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(436,'Dumb & Dumber',1994,'301',107,'2006-08-19',4,9,8,8,7,8,'Een van de zeldzame echt goeie absurde komedies. Deze film dateert van in het toptijdperk van Jim Carrey en dat is per definitie dan goed. Hilarisch met momenten. Daar heeft de topcast zeker bij geholpen. Een absolute aanrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(437,'Memoirs of an Invisible Man',1992,'208',99,'2006-08-20',4,5,6,7,5,7,'Het verhaal van een onzichtbare man is altijd een sterk begin om tot een goed plot te komen. In deze film wordt er echter te weinig mee gedaan. De schaarse boeiende momenten vallen te ver uit elkaar waardoor een gevoel van tijdverspilling mij overviel tijdens het bekijken van deze film. Spendeer uw tijd beter aan andere zaken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(438,'Heist',2001,'302',109,'2006-08-28',4,8,8,9,7,8,'Een enorme blockbuster, maar deze mag er zijn. Het is een misdaadplot, dus altijd garant voor spanning. Voorspelbaar is het helaas ook, maar dat wordt goedgemaakt door de algemene sfeer die deze prent uitstraalt. Zeker boeiend, maar net onvoldoende voor een absolute topper.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(439,'The Flight That Fought Back',2005,'303',90,'2006-09-10',4,6,6,7,5,6,'Dit is eigenlijk bedoeld als documentaire over vlucht 93 van American Airlines tijdens de aanvallen van 9/11. Toch is de hele prent sterk gedramatiseerd en passen de feiten wel heel erg goed in mekaar. Zeker niet een documentaire om meer te leren over 9/11, maar wel als eerbetoon voor de passagiers van die bewuste vlucht. Niet echt een aanrader, dus...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(440,'Cliffhanger',1993,'249',113,'2006-09-19',4,7,8,7,7,8,'Stallone op zijn retour. Het is niet meer wat het ooit geweest is, maar een goeie actiefilm is het zeker. Inhoud moet je niet zoeken, maar al bij al is dit zeker genietbaar. Beeldkwaliteit is typisch begin jaren 90, dus nog niet perfect. Hierdoor moet de pure filmkwaliteit beter zijn. En dat is precies wat de recentere actiefilms missen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(441,'Dangerous Liaisons',1988,'304',119,'2006-09-20',4,9,9,8,7,7,'Intelligent drama over verleiding, romantiek en passie. Het is absoluut geen film om als ontspanning te bekijken. Inhoudelijke supersterk, de cast ook, en boeiend van begin tot einde. Een aanrader voor iedereen die van een inhoudelijk sterke film houdt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(442,'A Knight\'s Tale',2001,'305',132,'2006-09-29',4,8,7,9,7,8,'Een soort sprookje over een arme jongen die het tot ridder wil schoppen. Alle ingrediënten zijn aanwezig: Actie, romantiek en humor. Het is een film zonder veel inhoud, maar liefhebbers kunnen dit zeker appreciëren. Topontspanning.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(443,'Lost in Translation',2003,'211',102,'2006-10-04',4,7,8,7,7,7,'Een verrassend sterke romantische prent. Het is nooit echt meeslepend, maar wel onderhoudend. Het slot is ijzersterk en dat draagt zeker bij tot de algemene indruk. De vertolkingen zijn heel sterk. Soms grappig zelfs... Dit is zeker een aanrader voor de liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(444,'Virtual Sexuality',1999,'306',92,'2006-10-06',4,5,5,7,6,7,'Je hoeft niet veel achter deze film te zoeken. Het is een romanische tienerkomedie en daarmee is ook alles gezegd. Grappig is het weinig, clichés alom. Als er echt niets anders is, kan je deze film wel eens een kans geven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(445,'Full Metal Jacket',1987,'248',116,'2006-03-10',2,9,9,10,8,9,'Een absolute cultfilm, een meesterwerk van Kubrick. Het is een gat in de cultuur van iedere filmliefhebber die deze prent niet heeft kunnen aanschouwen. Het is iets heel aparts en doet zelfs een beetje seventies aan. Meeslepend, keihard en soms gruwelijk. Muziek, geluid en beeld zijn ijzersterk. Een absolute topper','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(446,'The Whole Nine Yards',2000,'307',98,'2006-10-17',4,8,7,8,7,7,'Een leuke misdaadkomedie met een sterke cast. Het verhaal is heel voorspelbaar. Toch is deze film bij momenten hilarisch en zonder meer boeiend. Er is een constant feel-good gevoel over deze film, dus het is ideaal om met vrienden ontspannen te bekijken. Zeker een aanrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(447,'Glimmer Man',1996,'308',92,'2006-10-24',4,6,5,7,6,6,'Een Steven Seagal-film zonder veel inhoud. De plot is flinterdun en de cast is al niet veel indrukwekkender. De vechtscènes zijn het enige leuke, maar die zijn minder aanwezig dan in zijn andere films. Laat deze film dus maar achterwege.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(448,'Dogville',2003,'309',178,'2006-11-03',8,9,8,9,8,7,'Dit is eigenlijk meer een verfilmd toneelstuk. Alles speelt zich af in een abstract dorp op één locatie. De plot en de vertolkingen zijn ijzersterk. Je kleeft echt aan je scherm bij het bekijken van deze film. Het begint wat traag, maar naarmate de film vordert, wordt het des te meeslepender. Deze film blinkt uit in originaliteit en breken met clichés.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(449,'All Of Me',1984,'310',93,'2006-11-05',4,6,7,6,5,6,'Steve Martin op het hoogtepunt van zijn loopbaan. Een typische eighties-komedie met een ijzersterke hoofdrol. Dit genre van komedie is voorbijgestreefd, maar kan de echte liefhebbers zeker nog boeien. Eerder passé, maar niet verdorven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(450,'Secret Window',2004,'49',96,'2006-11-08',8,8,7,9,7,8,'Een ietwat rare, voorspelbare Johnny Depp-thriller met een heel aparte sfeer errond. De acteerprestaties zijn heel sterk en zorgen voor die sfeer. Geluid en beeld zijn heel goed. Jammer genoeg heb je na een uur wel door waarover het gaat. Zeker een aanrader, het was een sterke poging.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(451,'Big Trouble',2002,'276',85,'2006-11-22',4,8,8,8,7,8,'Een laat overblijfsel van een typische eighties-komedie. Een absoluut pareltje in het genre met veel situatiehumor en minder absurditeit dan verwacht. Hilariteit gegarandeerd, maar er moet niet te veel bij nagedacht worden. Zeker de moeite!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(452,'Bad Boys 2',2003,'98',147,'2006-12-08',4,7,7,8,8,8,'Inhoud: nul, realisme en herkenbaarheid: nul, amusement: tien! Je hoeft er totaal niet bij na te denken, maar het duo Will Smith en Martin Lawrence kan van iedere B-film een aangenaam kijkstuk maken. Een spectaculaire no-brains actiefilm met een stevige komische saus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(453,'K-19: The Widowmaker',2002,'311',138,'2006-12-15',4,7,7,7,6,7,'Deze film begint als een doordeweekse koude oorlog-prent. De duikbootoorlog op zijn piek. Toch begint het verhaal na verloop van tijd zo te boeien, dat de kijker aan het scherm gekluisterd blijft. Wees er maar zeker van dat bepaalde scènes van deze film dagen in je hoofd zullen spoken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(454,'Combien tu m\'aimes?',2005,'312',95,'2006-12-27',4,6,7,7,6,7,'Het is eens iets anders. Een Franse romantische film pakt een romatisch verhaal toch heel anders aan. Deze film boeit meer en meer naar het einde toe, maar slaagt er nooit in om het B-film-gevoel te verdoezelen. Het slot is niet om over naar huis te schrijven. Een gemiste kans!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(455,'Diary of a Hitman',1991,'313',92,'2007-01-03',4,6,8,6,7,7,'Een intelligent verhaal over een huurmoordenaar samen met sterke acteerprestaties kan nooit fout gaan. Deze film eindigt echter met een sisser en dat is zeker een gemiste kans. Voor de filmliefhebber is dit zeker de moeite, maar ontspannend kan je deze prent moeilijk noemen. Toch een pluim voor de durf van de scenaristen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(456,'Sin City',2005,'314',124,'2007-01-05',4,9,9,8,9,8,'Deze film gaat over een handvol stripverhalen die los door elkaar lopen en mekaar soms kruisen. Pakkend en heel apart, alleen al omdat deze film quasi volledig in zwart-wit is. Toch is deze film niet weggelegd voor iedereen, wat het weinige success in de bioscoop verklaart. De kijker moet wel houden van het comic-gehalte. Topper!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(457,'War of the Worlds',2005,'8',116,'2007-01-09',4,8,8,9,9,9,'Een gigantische blockbuster met een serieus Spielberg-laagje. Een meer serieuze \"Independence Day\" met een teleurstellend slot. Net zoals bij \"AI\" is de film afgekapt, alsof het geld plots op was. Jammer, want dit kon een meesterwerk geworden zijn. Beeld en geluid zijn heel goed, wat je mag verwachten van dit soort film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(458,'The Butterfly Effect',2004,'315',113,'2007-01-10',4,9,9,8,7,7,'Onbekend, maar een absoluut meesterwerk. Het begint als een doordeweekse thriller, maar hoe verder het verhaal gaat, hoe meeslepender het wordt. Een van de weinige films die mij van mijn stoel kreeg. Het slot verknalt het niet. Dat alleen verdient al een pluim. Beeld en geluid zijn degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(459,'The Italian Job',2003,'316',111,'2007-01-19',4,7,7,9,8,8,'Indrukwekkende cast voor deze actiefilm. Het brengt op zich niets nieuws, maar het is altijd eens leuk om een ontspannende actiefilm te zien. Een van de betere films in het genre met alle ingrediënten van actie-blockbuster. Maar er ontbreekt toch iets om een topfilm te zijn. Beeld en geluid zijn goed, met af en toe verrassende camerastandpunten bij de actiescènes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(460,'Independence Day',1996,'317',145,'2007-01-26',4,8,8,9,8,8,'De zoveelste film over het gevecht tussen de mensheid en aliens. Toch brengt Will Smith net dat tikkeltje meer wat deze film eigenlijk wel goed maakt. Niet al te veel vragen stellen, dus. Toch is dit zeker aangenaam om naar te kijken, al was het maar voor de verbluffende special effects. En misschien ook een beetje omdat het een klassieker is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(461,'Black Knight',2001,'318',95,'2007-02-06',4,7,8,7,7,7,'Net wat je zou verwachten van een film met Martin Lawrence. Anderhalf uur pure onzin, maar met af en toe een hilarische scène. Dommer kan een scenario moeilijk worden, maar de acteurs houden het nog boeiend. Voor een ontspannende klassieke komedie kan dit wel tellen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(462,'The Red Colored Gray Truck',2004,'319',95,'2007-02-09',4,7,9,7,7,8,'Een romantisch verhaal midden in de burgeroorlog in Ex-Joegoeslavië. Het klinkt zoals het is: best wel bizar. De originaliteit houdt deze film recht. Toch maken de uiterst scherpe kantjes dit zeker een heel realistisch verhaal. Een aanrader voor de meerwaardezoeker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(464,'Meatballs',1979,'150',99,'2007-02-09',4,6,7,5,6,6,'Ooit zal dit wel een pionier in het genre geweest zijn, maar deze prent is echt wel verouderd. Af en toe eens een leuke uitschieter, maar het \"nerd op zomerkamp\"-gegeven werd al te vaak uitgemolken. Niets nieuws, enkel nog bewaard omdat het dat ooit wel was.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(465,'The Devil\'s Advocate',1997,'320',144,'2007-02-13',4,9,10,9,8,9,'Een van de beste thrillers die ik ken. Er hangt een heel donkere sfeer rond deze film. Een verbluffende Al Pacino geeft een extra dimensie aan het verhaal. Boeiend en meeslepend van begin tot einde. Een ijzersterk slot maakt dit meesterwerk af. Absolute top!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(467,'The Postman',1997,'321',177,'2007-02-16',4,8,8,7,7,7,'Hoewel het hele \"USA is the best\"-sfeertje nogal storend werkt, kan deze film best boeien. Het verhaal begint wat traag, maar ondanks de lange duur zijn er voldoende snelle plotwendingen. Deze emo-film weet de kijker wel bij de keel te grijpen. Het slot stelt wat teleur, maar dat mag het overwegend positieve oordeel niet beïnvloeden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(468,'Hackers',1995,'148',107,'2007-02-19',4,7,8,5,7,6,'Een van de betere films voor IT\'ers. Er is uiteraard weer de typische overload aan special effects, maar het verhaal lijkt toch voor de eerste keer een beetje realistisch. Al is het maar een beetje... De cast maakt veel goed en het verhaal is niet al te dun. Het nadeel is dat dit soort films na tien jaar hopeloos verouderd is. Niet slecht, maar zeker ook niet goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(469,'Night at the Museum',2006,'322',108,'2007-02-24',5,8,8,7,6,7,'Een typische Ben Stiller-film en dat is positief bedoeld. Een eenvoudige, onderhoudende komedie. Stel je niet al te veel vragen bij het verhaal, want dat valt echt wel mager uit. Toch is de situatiehumor zeker te pruimen. Dat is sterk in deze tijd van absurditeiten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(470,'Underworld',2003,'323',121,'2007-02-27',4,8,9,9,8,8,'Een film over vampieren en weerwolven, dus ben ik er met het nodige voorbehoud aan begonnen. Je wordt ook echt midden in een verhaal gegooid. Van een intro is geen sprake. Toch versterkt deze prent hoe langer hoe meer. Het verhaal wordt beklijvender en spannender. Beeld en geluid dragen hiertoe bij. Heel sterk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(471,'The Aviator',2004,'3',170,'2007-03-20',4,7,8,9,7,8,'De halve biografie van Howard Hughes kon mij nooit echt boeien. Deze hollywood-blockbuster is dan ook één lange reclamespot en vereenvoudiging van een complex leven. Omwille van de positieve kritieken kan je deze film toch een kans geven. Beeld en geluid zijn uiteraard goed, met zo\'n budget... Er ontbreekt iets...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(472,'Scarface',1983,'51',170,'2007-03-27',4,8,9,6,5,6,'Een gangsterepos in de nasleep van de Godfather-reeks. Opnieuw met Al Pacino, dus de vergelijking is niet te vermijden. Dit verhaal gaat echter meer over de menselijke kanten, dan over de maffiacultuur. Boeiend van begin tot einde. De beeldtechniek komt recht uit de seventies en de absoluut foute muziek is begin eighties. Dat buiten beschouwing gelaten, is dit een ijzersterk misdaaddrama.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(473,'Shooter',2007,'217',124,'2007-04-21',5,7,7,7,7,7,'Niet echt iets speciaals, maar zeker een genietbare actiethriller over een zogenaamde \"sniper\". Beeld en geluid zijn goed, zonder meer. Er is eigenlijk niet zo veel meer over te vertellen. Een voorspelbare, maar leuke film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(474,'The Count of Monte Cristo',2002,'324',131,'2007-05-04',4,8,9,7,7,7,'Een ijzersterk Middeleeuws verhaal. De verfilming van het boek zal ongetwijfeld veel details achterwege laten. Het gaat soms wel snel, maar boeiend is het zeker. Deze film is niet echt voorspelbaar en dat zorgt ervoor dat de kijker perfect bespeeld wordt. Beeld en geluid zijn goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(475,'Doom',2005,'61',100,'2007-05-11',4,7,6,9,8,7,'Het verfilmen van een video-game heeft tot nu toe nog geen meesterwerken voortgebracht. Deze film is geen uitzondering. In het actie-genre scoort deze film goed, maar de verhaallijn is flinterdun. Hierdoor is de spanning ver te zoeken. Een goede poging, maar meer niet. Beeld en geluid zijn wel best OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(476,'The Ring 2',2005,'325',110,'2007-05-12',4,7,6,9,8,9,'De eerste film was een ribbenplakker en legde de lat hoog voor de sequal. Deze film lost de verwachtingen niet in. Het is eigenlijk gewoon het uitmelken van het originele verhaal. Best genietbaar, als men de eerste film niet heeft gezien. Maar dan begrijpt de kijker wel de helft van de verwijzingen naar die eerste film niet, natuurlijk. Beeld en geluid zijn de sterkte van deze film, want het verhaal stelt niet veel voor.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(477,'Walking Tall',2004,'326',87,'2007-05-19',4,7,7,7,7,8,'Een B-actiefilm waar ik aan begon zonder al te hoge verwachtingen. Het valt al bij al best mee. Het verhaal is voorspelbaar, maar ergens boeit het wel. De acteurs stellen ook niet teleur. Alleen is en blijft het een B-prent, waardoor het niet opvalt in de massa.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(478,'John Carpenter\'s Vampires',1998,'208',108,'2007-05-22',4,5,4,5,7,7,'Dit is iets om op BIFFF te tonen. Het verhaal lijkt nergens op en de special effects zijn niet om over naar huis te schrijven. Liefhebbers van vampierenverhalen zullen dit wel kunnen appreciëren, maar al de rest zal deze film met moeite uitkijken. Enkel James Woods kan deze film nog voor een stuk dragen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(479,'Shattered Glass',2003,'327',94,'2007-05-29',4,8,9,6,7,8,'Een ijzersterk drama, voor de meerwaardezoeker. Spectaculaire beelden of actiescènes moet je niet verwachten, maar het verhaal zit heel goed in elkaar. Het is niet voorspelbaar en goed in beeld gebracht. De acteurs dragen dit verhaal volledig. Een aanrader voor wie van een intelligente film houdt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(480,'Hellboy',2004,'328',121,'2007-06-01',4,8,7,8,8,8,'De zoveelste verfilming van een comic. Het is niet meteen beter of slechter dan de andere, maar is zeker aan te raden voor de liefhebbers. De sfeer van deze film is donkerder dan bv. bij X-Men, en dat doet deze prent opvallen. De special effects zijn, zoals men mag verwachten van dit soort films, heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(481,'Matchstick Men',2003,'54',116,'2007-06-08',4,8,9,8,8,8,'Een misdaadfilm met Nicolas Cage lijkt een foute combinatie. Toch blijft deze film boeien van begin tot einde. De cast presteert indrukwekkend. Een film waar je duidelijk de hand van Ridley Scott in ziet. Absoluut een aanrader, maar pure ontspanning is het zeker niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(482,'Death Proof',2007,'107',113,'2007-06-16',5,9,7,8,9,8,'Een film van Tarantino is eigenlijk een genre op zich. Na deze film vraag je je wel af wat je nu eigenlijk net gezien hebt, maar voor de rest is dit een must-see film. Inhoudelijk zeker niet sterk, maar alleen de manier van het in beeld brengen, is al de moeite waard. Geluid en muziek zijn ook indrukwekkend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(483,'Black River',2001,'329',100,'2007-06-20',4,7,6,7,6,6,'Deze film zal zeker niet iedereen aanspreken, wegens de hoge ongeloofwaardigheid. Toch heeft die film iets boeiends, de kijker wil weten hoe het nu eigenlijk afloopt. En dat slot is best verrassend. Beeld en geluid zijn degelijk, maar het blijft een B-film. Leuk, als je niet te kritisch bent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(484,'Black Snake Moan',2006,'330',116,'2007-06-24',5,7,7,9,8,8,'Deze uitzonderlijke film, met een even uitzonderlijke cast, is enkel voor de meerwaardezoeker. Het verhaal blijft plakken, maar gaat niet echt goed vooruit. Het is geen ontspannende film, vandaar enkel voor de liefhebbers. Beeld en geluid zijn wel uitzonderlijk goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(485,'Hope Springs',2003,'331',92,'2007-07-14',4,7,6,8,6,6,'Een goede ouderwetse ontspannende slijmfilm. Het is echt ook niets meer dan dat. Het verhaal is zo oud als de straat, maar het boeit wel. De plot wordt dus goed vertolkt. Voor een gezellige avond is dit dus ideaal, maar voor de meerwaardezoeker is dit een absolute rioolfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(486,'The School of Rock',2003,'332',108,'2007-07-27',4,8,6,8,7,7,'De affiche is niet echt aantrekkelijk: Een film over een absolute nietsnut die in een school moet gaan werken. Er zijn er al een dozijn van gemaakt, maar deze is soms wel echt hilarisch. Dit heeft de film allemaal te danken aan een uitmuntende Jack Black. Daarmee is alles gezegd, want de plot is wel heel erg ongeloofwaardig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(487,'Starsky & Hutch',2004,'149',101,'2007-08-01',2,8,7,9,8,9,'Een remake van een ooit succesvolle serie. Er zijn er al heel wat de revue gepasseerd, maar dit lijkt echt wel een geslaagde poging. Een actiekomedie van de bovenste plank. Beeld en geluid zijn heel goed, wat je van zo\'n blockbuster wel kan verwachten. Een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(488,'Resident Evil',2002,'261',100,'2007-08-07',4,6,5,8,7,9,'De zoveelste film over een opgesloten team met overal moordlustige hindernissen onderweg naar buiten. Beeld en geluid zijn heel erg goed en dat houdt het niveau nog ietwat aanvaardbaar. De plot is echter ondermaats. Een blockbuster, zonder veel inhoud.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(489,'The Human Stain',2003,'333',106,'2007-08-31',4,9,9,7,7,7,'Onbekend, maar inhoudelijk ijzersterk. Anthony Hopkins en Nicole Kidman maken het plaatje compleet, samen met de rest van de cast. Een plakkend en intelligent verhaal boeit van begin tot einde. Beeld en geluid zijn goed. De titel vat het allemaal samen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(490,'Reach The Rock',1998,'334',100,'2007-08-31',4,7,8,6,7,6,'Het ziet er wat B-film uit, maar de plot en de vertolkingen zitten wel goed. Beeld en geluid zijn niet echt denderend, omdat de hele film zich op een handvol stilstaande locaties afspeelt. Geef de film wat krediet en je krijgt een degelijke karakterfilm terug.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(491,'The Mosquito Coast',1986,'166',117,'2007-09-05',4,6,6,7,7,6,'Een wat oudere film over een gezin die in de jungle gaat wonen. Het zet af en toe eens aan tot denken, maar echt boeien doet dit verhaal niet. Er is eigenlijk niet echt iets negatiefs van te zeggen, maar misschien is dit gewoon mijn type film niet. Voor de fans van Harrison Ford...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(492,'Ransom',1996,'132',121,'2007-09-09',4,8,9,7,7,8,'Deze film begint als een van de zovele kidnapfilms, zonder veel nieuws. Toch neemt het verhaal wel heel wat onconventionele wendingen. Hoe meer naar het einde, hoe spannender. Het slot is hierdoor echter een anticlimax, maar het geheel blijft wel goed. Zeker een aanrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(493,'Taking Lives',2004,'335',103,'2007-09-11',4,6,6,8,7,8,'De indrukwekkende cast zorgt voor hoge verwachtingen, maar de film zelf stelt erg teleur. Het is verre van slecht, maar het is niets nieuws. De zoveelste superagente die op zoek gaat naar een seriemoordenaar. Als er niets anders te zien is, dan misschien...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(494,'Batman Returns',1992,'50',126,'2007-09-12',4,7,5,9,7,8,'De tweede film uit de Batman-reeks blijft zijn roots trouw. Er hangt een unieke donkere sfeer die je enkel bij deze films krijgt. Toch is het verhaal wat dunnetjes. Dit boeiend noemen is overdreven. Beeld en geluid zijn verbazingwekkend goed voor die periode. Toch een pluim waard, vind ik.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(495,'Charlie\'s Angels: Full Throttle',2003,'336',106,'2007-10-19',4,3,2,6,6,7,'Een echte blockbuster die echt alle verwachtingen overtreft. Maar dan in negatieve zin. Acteerprestaties zijn ongelooflijk slecht, het verhaal is gewoon belachelijk en de special effects zien er wat low-budget uit. Dit is zelfs het overwegen niet waard.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(496,'Notting Hill',1999,'337',124,'2007-10-19',4,6,7,6,7,6,'Een ontspannend romantisch verhaal, typisch met Hugh Grant. Het brengt absoluut niets nieuws en is al helemaal niet beter dan de rest. Toch is dit genietbaar als je even niets anders te doen hebt. Een blockbuster met een dure cast zou toch iets meer mogen bieden. Maar ach, waarom niet...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(497,'The Departed',2006,'3',151,'2007-10-27',8,7,7,8,8,7,'Met Scorsese als regisseur verwacht je wel wat. Het is dan ook een ijzersterk misdaadverhaal met dat typische laagje uitzonderlijkheid. Het einde is echter wel wat van het goede te veel. Soms denk je dan dat de scenaristen plots het hele verhaal in 5 minuten moesten pompen. Spijtig, maar dat is een niet te negeren punt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(498,'Constantine',2005,'338',121,'2007-10-29',8,8,7,9,8,8,'Een verfilming van een comic, maar dan een die iets donkerder is dan de rest. Het verhaal zit goed in mekaar, de acteerprestaties volgen. Sta open voor de typische comic-fantasy en deze film staat garant voor een leuke avond. Beeld en geluid zijn, zoals altijd bij dit soort films, heel erg goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(499,'Goya\'s Ghosts',2006,'339',114,'2007-11-03',2,8,9,7,8,7,'Een film met een eerder onbekende cast, maar met heel goede kritieken. Terecht, zo blijkt, want dit verhaal zit heel goed in elkaar en heeft weinig Hollywood-clichés. Alleen dat loont al de moeite. De cast doet het goed, in tegenstelling tot wat ik verwachtte. Een miskend pareltje, al is het niet echt een ontspannende film, maar een echt drama.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(500,'Lucky Number Slevin',2006,'340',109,'2007-11-03',2,9,9,8,7,8,'Een typische avondvullende ingewikkelde misdaadprent. Het is een heel erg boeiend, maar ook redelijk ingewikkeld verhaal. De plotwendingen en verrassende elementen maken van deze film een echt pareltje. Zonder meer een echte aanrader. Ook beeld en geluid blijven niet achter.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(501,'The Recruit',2003,'225',115,'2007-12-02',4,8,7,8,7,8,'Bij een film over de CIA zijn de verwachtingen altijd hooggespannen. Het begin van deze film stelt niet teleur. Er wordt echt opgebouwd naar een climax... Maar die blijkt er dan niet te zijn. Het verhaal verwatert in Hollywood-clichés die de geloofwaardigheid niet ten goede komen. Al is het einde toch wel verrassend. Toch, om niet al te kritisch te zijn, is dit een van de betere misdaadfilms van de laatste jaren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(502,'Transformers',2007,'98',144,'2007-12-15',2,8,7,9,9,9,'Een actiefilm gebaseerd op de tekenfilms van vroeger. Na een indrukwekkende start verwatert deze film toch wel wat. De special effects zijn zowat perfect, maar de plot valt wat magertjes uit. Actie, humor en spanning wisselen elkaar goed af, precies wat je van dit soort films kan verwachten. Zeker de moeite waard, vooral voor wie vroeger de tekenfilms nog heeft gezien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(503,'Garden State',2004,'341',102,'2007-12-18',2,7,8,7,8,7,'Een intelligent romantisch verhaal. Dat op zich is al heel wat, het verwatert niet in een zeemzoete feel-good film. Het is zo\'n film waarvan je vermoedt dat het niet even goed zou geweest zijn met een andere cast. Beeld en geluid zijn goed, maar het is natuurlijk geen blockbuster. Al bij al niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(504,'Austin Powers: Goldmember',2002,'157',94,'2007-12-24',4,8,8,7,8,7,'Dit is niet de eerste, maar ook niet de minste Austin Powers-film. De typische absurde humor kan zeker bekoren. Beeld en geluid zorgen voor dat beetje extra. Een no-nonsense absurde komedie voor een ontspannen avondje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(505,'Eternal Sunshine of the Spotless Mind',2004,'342',108,'2007-12-27',4,8,9,8,7,7,'Een zwaar onderschatte film. In tegenstelling tot mijn verwachtingen, kan deze film echt wel boeien. Beeld en geluid ondersteunen goed. Laat u dus niet misleiden door het genre, deze film heeft echt wel iets. Sterker nog, het is een sterk en geloofwaardig verhaal. Een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(506,'Hitman',2007,'343',100,'2007-12-29',5,7,6,8,8,8,'Een verfilming van een game bekijk ik altijd met de nodige argwaan. Het aandeel van de game in deze film is echter beperkt tot enkele elementen. Deze elementen worden helaas niet samengehouden door een goeie plot. Het verhaal valt wat dunnetjes uit. Beeld en geluid maken veel goed, er is een aparte sfeer. Hierdoor valt deze film zeker mee, maar de plot mocht wel wat dikker zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(507,'Heat',1995,'344',171,'2008-01-02',4,9,9,7,8,9,'Met zo\'n cast een misdaadfilm maken, dat kan niet fout lopen. Al wekken de taglines wel enige argwaan. Toch stelt deze film absoluut niet teleur, integendeel. Deze misdaadfilm heeft alles wat je kan verwachten: Actie, spanning, scherpe dialogen en een goeie plot. Een echte ouderwetse misdaadfilm van heel erg hoog niveau.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(508,'Cast Away',2000,'16',143,'2008-01-04',4,8,9,8,7,7,'Een avonturenfilm à la Robinson Crusoe. Deze film wordt voor 90% gedragen door Tom Hanks en dat is voor een film een groot risico. Dit doet hij echter met verve. Een boeiende en geloofwaardige film, al valt het slot wat dunnetjes uit. Bekijk deze film niet voor de special effects en actiescènes. Als dat niet uw doel is, dan is deze film echt een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(509,'Bend It Like Beckham',2002,'345',112,'2008-01-08',4,6,5,6,6,6,'Deze Britse romantische film gaat, in tegenstelling tot wat de titel insinueert, niet over voetbal. Althans, dat is niet het hoofdthema. Het is daarentegen wel een zeemzoet romantisch verhaal waarin alle clichés verwerkt zijn. Ook de voetbalscènes zelf zijn heel erg slecht in beeld gebracht. Het is een film van dertien in een dozijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(510,'While You Were Sleeping',1995,'346',103,'2008-01-09',4,6,7,7,7,7,'Een romantische komedie zoals er in de jaren 90 honderden gemaakt zijn. Het is een leuk VijfTV-verhaaltje doorspekt met Hollywoodclichés. Toch kan Sandra Bullock het niveau een beetje de goeie kant uit duwen. Alleen als er echt niets beters te zien is, verdient deze film uw aandacht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(511,'AVPR: Aliens vs. Predator - Requiem',2007,'347',86,'2008-02-02',5,2,1,7,6,6,'Een sequal op een goeie actiefilm waarbij de plot volledig uitgemolken is in de vorige film, dient met argwaan bekeken te worden. Het draait dan ook uit op een complete flop. Het verhaal is zo dun, dat de term \"verhaal\" eigenlijk overdreven is. Het brengt niets bij aan de originele film. Het slot is al helemaal belachelijk. Een echte schande dat dit in cinema\'s mag getoond worden!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(512,'30 Days of Night',2007,'348',113,'2008-02-10',2,7,6,9,9,9,'Het was een tijdje geleden, maar hier is nog eens een lekker ouderwetse vampireslasher. Beeld en geluid zijn fenomenaal, het is zelfs de kracht van deze film. Het heeft alle ingrediënten van een goeie slasher, de plot is zelfs nog redelijk. Maar bekijk dit niet voor de grote inhoud. Het is en blijft horror.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(513,'Ratatouille',2007,'229',106,'2008-02-11',2,7,7,8,7,7,'Van een Pixar-animatiefilm mag je wel wat verwachten. En het komt er ook uit. Het is een typische Pixar geworden: Geen al te dik plot, veel humor en schattige personages. Niets negatiefs dus, alleen dit: Het brengt niets nieuws. Voor de liefhebbers...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(514,'Crazy/Beautiful',2001,'349',99,'2008-02-12',4,5,4,7,6,6,'Dit is een feel-good romantische film, zonder meer. De cast bestaat uit wat mooie mensen en er is ook het nodige, maar discrete, naakt vlees aanwezig. Dat is dan ook wat het meeste de moeite waard is aan deze film. De plot is zo voorspelbaar als wat. Slecht is het niet, maar dit een aanrader noemen, is overdreven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(515,'Juno',2007,'350',96,'2008-02-13',5,7,8,7,7,7,'Een film over een ongewenste tienerzwangerschap lijkt niet echt aanlokkelijk. Toch vervalt deze film niet in overdreven sentiment, maar gaat het echt over het bizarre meisje Juno. Aangenaam en iets aparts, maar meer ook niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(516,'Armageddon',1998,'98',150,'2008-01-19',4,7,6,8,8,8,'Blockbusters zijn meestal geen garantie voor kwaliteit. Toch kan deze film echt wel boeien. Het is zeker niet geloofwaardig en het typische Amerikaanse patriotisme druipt er van af, maar al bij al valt dit wel mee. Voor een no-brain actieprent ben je bij deze film aan het goede adres. Beeld en geluid dragen hier ook toe bij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(517,'The Wedding Date',2005,'351',90,'2008-03-04',4,6,6,7,7,6,'Een romantische komedie zoals er al honderd gemaakt zijn. Zeker niet slecht in zijn genre, maar daar blijft het ook bij. Af en toe grappig, maar altijd voorspelbaar en nooit meeslepend. Het is absoluut niets speciaals. Enkel sommige elementen in het scenario kunnen af en toe de interesse wekken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(518,'Assault on Precinct 13',2005,'352',109,'2008-03-02',4,6,5,7,7,7,'Het is zo\'n typische actiefilm met veel grote namen en een sterk begin, maar waarbij het heel snel verwatert. De plot is veelbelovend, maar er wordt veel te weinig mee gedaan. Je kan het slechts met momenten meeslepend noemen, al is dat woord zelfs wat overdreven. Beeld en geluid zijn goed, hoewel dit niet zo spectaculair is. Niet echt een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(519,'1408',2007,'353',104,'2008-03-07',2,7,6,8,7,8,'Dit is een echte old-style horrorthriller. Het bevat alle goeie angst- en schrikclichés die je van zo\'n film kan verwachten. Beeld en geluid zijn ook OK. Alleen is het einde ontstellend zwak, zelfs een anti-climax. Spijtig, hier zat veel meer in. De opbouw is perfect, maar leidt tot niets. Het geld was waarschijnlijk op...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(520,'10,000 B.C.',2008,'317',109,'2008-03-22',5,7,7,8,8,8,'De zoveelste avonturenfilm uit de oudheid. Als je je niet te veel vragen stelt, is dit wel te verteren. Een lichte, maar historisch erg incorrecte heldenepos. Beeld en geluid zijn heel erg goed, maar toch ontbreekt dat tikkeltje extra dat deze film er zou doen uitspringen. Niets speciaals, dus...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(521,'Training Day',2001,'217',120,'2008-03-23',4,8,7,8,7,7,'Ik verwachtte bij deze film het ergste. Alweer een film over de CIA, FBI of iets dergelijks. Het verhaal lost die verwachtingen ook in. Het brengt weinig nieuws en is ook niet echt meeslepend. Toch maakt de cast heel wat goed. Al bij al zeker te genieten, maar ook geen meesterwerk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(522,'De Hel van Tanger',2006,'244',105,'2008-03-25',4,7,7,7,6,6,'Een Belgische film die een award in de wacht sleept, dat verdient een kans. Dit is, naar mijn mening, ook een van de betere Belgische drama\'s. Het oogt wat TV-film achtig en lijkt op een B-film. Van de spetterende actie en spanning moet deze film het ook niet hebben. Wel zijn de karaktertekeningen goed. Als je de film actief meebeleeft, laat deze zeker een indruk na.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(523,'Invasion',2007,'239',99,'2008-05-16',2,7,7,8,8,7,'Al bij al een redelijk aangename film. De cast doet daar veel aan, want het verhaal is eerder mager en voorspelbaar. Beeld en geluid zijn degelijk. Deze film springt er niet uit, maar het valt zeker mee.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(524,'Last Action Hero',1993,'73',130,'2008-05-23',4,9,9,7,7,7,'Schwarzenegger in een komedie, het is altijd gevaarlijk. Maar deze film heeft echt wel iets, hoewel het echt wel heel erg ongeloofwaardig is. Het zit allemaal wat simpel in elkaar, maar het vaak gewoon hilarische situatiehumor. Dit is zeker een van de betere, niet-absurde komedies van de laatste decennia.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(525,'Indiana Jones and the Kingdom of the Crystal Skull',2008,'8',124,'2008-05-25',5,7,7,8,8,8,'Een vierde verhaal voor de Indiana Jones-trilogie. Het klinkt verschrikkelijk overbodig en het is ook wel een beetje zo. Het is gewoon één van de vier, niets meer of minder. Ga niet voor het geloofwaardige verhaal, maar wel om te genieten van een no-brains avonturenfilm. Net zoals in de goede oude tijd...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(526,'Chocolat',2000,'99',121,'2008-05-27',2,8,9,8,7,7,'Het ziet er allemaal geweldig melig uit, maar deze film verrast positief. Het zit niet vol van de clichés, zoals de meeste films in dit genre vooral uit bestaan. Het verhaal heeft zelfs iets opgewekts, ondanks dat het eigenlijk vooral over negatieve thema\'s gaat. Zeker en vast een aanrader voor de meerwaardezoekers onder ons.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(527,'Stardust',2007,'354',127,'2008-06-10',4,8,8,9,8,9,'Dit sprookjesachtig avontuur zit goed in elkaar, tegen alle verwachtingen in. Het zit vol van de clichés, maar eigenlijk valt dit niet zo heel erg op. Dat komt vooral door de magische sfeer in het verhaal. Af en toe komisch en pakkend, zoals het hoort. Dit is een leuk sprookje om te volgen, maar het biedt helaas niet echt iets nieuws. Toch een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(528,'Derailed',2005,'353',108,'2008-06-01',2,9,9,9,8,8,'De cast en de trailer doet het beste verhopen en deze film stelt niet echt teleur. Het is een misdaadfilm die ergens wel realistisch en geloofwaardig is. Mede hierdoor is het wel een erg voorspelbare film. Buiten enkele belangrijke elementen dan... Zeker een aanrader als je een stevige thriller wil zien!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(529,'Van Helsing',2004,'209',132,'2008-06-03',4,6,5,9,8,9,'Een mix van verschillende oude verhalen is meestal een onsamenhangend geheel. Hier is dit ook het geval. De plot is maar dunnetjes en weinig meeslepend, laat staan geloofwaardig. De stunts zijn soms gewoon lachwekkend. Enkel in de bioscoop of op een gigantische home-cinema is deze film de moeite waard, door de aparte sfeer en beeldtechniek.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(530,'The Happening',2008,'53',91,'2008-06-16',5,6,5,8,9,8,'Shyamalan is al altijd een garantie geweest op een film dat net dat tikkeltje meer biedt. Helaas glijdt hij sinds \"The Sixth Sense\" meer en meer af naar verhalen waar hij naar het einde toe geen oplossing meer voor weet. De film bouwt schitterend op en heeft iets heel aparts. Het slot verbrodt de prent echter helemaal. Het is zelfs frustrerend. Alweer een mislukking, net zoals Signs. Jammer, hier zat echt veel meer in.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(531,'The Incredible Hulk',2008,'355',114,'2008-06-29',5,7,7,9,8,8,'Enkele jaren na het gedrocht van een eerste film, is hier al de remake. Met gefronste wenkbrauwen ging ik hier naar toe, maar het viel echt wel goed mee. Een aangename verfilming van deze comic, al mis ik een begin en einde. Het is als een episode in een reeks. Toch al bij al een leuke prent, waarbij vooral de goeie special effects opvallen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(532,'Get Shorty',1995,'276',105,'2008-07-07',4,8,8,7,7,7,'Alweer een misdaadfilm met John Travolta en een reeks andere grote namen. Wat kan dit mogelijks nog bijbrengen aan het genre? Antwoord: helemaal niets. Het is zeker geen slechte film en af en toe heel geslaagd. Toch is het niets nieuws.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(533,'I Am Legend',2007,'338',101,'2008-08-20',2,8,7,9,8,8,'Een heel erg boeiende actiefilm. Het plot heeft een enorm potentieel, maar het komt er eigenlijk niet echt uit. Het is zo\'n film die eindigt net als je verwacht dat het gaat beginnen. Heel erg jammer, want het is echt heel leuk gevonden. Beeld en geluid dragen hiertoe bij. Heel leuk, maar net niet...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(534,'WALL-E',2008,'181',98,'2008-08-04',5,8,7,8,8,9,'Een groots aangekondigde animatiefilm van Pixar, die maar af en toe de verwachtingen in lost. Het is allemaal heel leuk in het begin, maar het wordt wat té langdradig naar het einde toe. Het is dus zeker een aangename film om te zien, maar tegelijk ook wat overroepen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(535,'The Mist',2007,'74',126,'2008-08-09',2,9,9,9,8,9,'Een absoluut ijzersterke film! Als je niet weet waarover het gaat voordat je begint te kijken, komt deze film echt tot zijn recht. Het begint eigenlijk als een doordeweekse thriller, maar het boeit tot de laatste seconde. Het is een film die ongetwijfeld lang aan de ribben blijft plakken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(536,'The Reaping',2007,'356',99,'2008-08-12',2,6,6,7,7,8,'Je vraagt je af wat een thriller over religie nog aan het genre kan toevoegen. Het werd gemaakt tijdens de grote Da Vinci Code hype, dus dat zegt genoeg. Het verhaal is magertjes en boeit nooit echt. Het is een grijze muis in zijn genre. Niet echt een aanrader...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(537,'Shrek the Third',2007,'357',93,'2008-08-13',2,7,7,8,8,7,'Deze derde film is niet van dezelfde regisseur als de eerste twee. Dat zie je eigenlijk wel. Het is leuk voor de kleintjes en ook af en toe voor volwassenen. Toch begint het Shrek-verhaal op zijn laatste benen te lopen. Leuk als je de eerste twee films hebt gezien, ter volledigheid. Tijd voor iets anders...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(538,'Sneeuwwitje: De Sequel',2007,'358',82,'2008-08-13',2,8,8,7,8,7,'Walt Disney draait zich ongetwijfeld om in zijn graf. Deze super... euh... pikante tekenfilm is niet voor de jonge kijkers. Het is zonder meer een hilarische film, maar lang niet iedereen zal deze platte humor goed vinden. Leuk als experiment, want origineel is het zeker. De Vlaamse stemmen zijn de kers op de taart.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(539,'The Dark Knight',2008,'121',152,'2008-08-25',5,9,9,8,8,9,'Een remake van een recente Batman-film. Bovendien leek de vorige versie onaantastbaar met een schitterende Jack Nicholson. Toch is het uiteindelijke resultaat heel verrassend. Het is totaal niet wat de trailer lijkt te voorspellen. Beeld en geluid zijn absoluut magistraal en ondersteunen het geheel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(540,'Get Smart',2008,'359',110,'2008-09-05',5,7,7,8,7,7,'Alweer een typische Steve Carell film. Een degelijke komedie. Zodanig absurd dat het weer goed wordt. Het is niet echt topklasse, maar zeker te genieten. Deze film slaagt er in om het blockbusterjuk goed te dragen, zonder dat het echt opvalt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(541,'Be Cool',2005,'316',118,'2008-09-07',4,6,6,7,7,7,'De titel verraadt het niet, maar dit is de sequal van \"Get Shorty\". Helaas kan het zijn voorganger op geen enkel moment evenaren. Er zitten wel wat goeie ideeën in de plot, maar het wordt nooit echt goed gebracht. Al bij al te mager. Enkel als je de eerste film gezien hebt, loont dit de moeite.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(542,'Duplex',2003,'360',89,'2008-09-10',4,6,6,8,8,7,'Een wel heel erg irritante komedie. Het is een absurd verhaal, typisch een eighties film eigenlijk. Alleen is dit niet echt grappig, maar wel echt om gek van te worden. Kortom, niets voor mij, maar voor degenen die van het genre houden, be my guest...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(543,'The Eye',2008,'361',98,'2008-09-21',2,7,7,8,8,7,'Hoewel deze film niet fantastisch origineel is, is het toch een leuke prent om wat tijd te verdrijven. Hoewel je meestal moet vechten om de clichés te negeren, blijf je voor de een of andere reden toch kijken. Zeker niet slecht, zeker beeld en geluid niet. Maar het is echt niets nieuws.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(544,'Cold Mountain',2003,'215',154,'2008-09-23',4,8,8,8,6,7,'Een romantisch avonturenverhaal als dit heeft als grote uitdaging het vermijden van het al te dramatische plot. Helaas valt deze film ook ten prooi hiervan. Het is een heel sterk verhaal en het boeit van begin tot einde. Maar deze film blijft iets te sterk aan de ribben plakken, naar mijn mening. Goed om één keer te bekijken, maar niet meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(545,'The Covenant',2006,'249',97,'2008-09-27',4,4,4,7,6,7,'Dit kan hoogstens een goede \"Buffy\"-aflevering genoemd worden. Waar de producenten het geld hebben gevonden om dergelijk flauw afkooksel te maken, ik zal het nooit weten. Het verhaal is totaal geen film waard, misschien een episode van een of andere serie. Een absolute afrader, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(546,'V For Vendetta',2005,'362',132,'2008-10-13',2,9,9,9,8,8,'Het filmlandschap wordt gelukkig af en toe eens opgeschrikt door een staaltje innovatief werk. Net toen we dreigden te verdrinken in een gigantische bak met gelijkaardige films, komt Hollywood met dit op de proppen. Een ijzersterke film. Actie, humor en af en toe iets om eens lang over na te denken. Beeld en geluid zijn passend en zelfs vernieuwend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(547,'300',2006,'363',117,'2008-10-05',2,8,7,9,8,8,'Deze film wordt vaak afgebroken door de vele computeranimaties die gebruikt werden. Ik vind echter dat dit een meerwaarde geeft. Men kan zo bepaalde gebeurtenissen veel krachtiger weergeven. Het is zeker en vast vernieuwend, hoewel het achteraf gezien toch wel wat teleur stelt. Misschien was het budget voor een origineel plot op na alle special effects? Al bij al zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(548,'Iron Man',2008,'364',126,'2008-10-08',2,8,8,8,8,8,'De zoveelste verfilmde comic van Marvell kan eigenlijk niet zoveel meer bijbrengen. En dat doet het ook niet. Toch blijft dit voor mij een heel leuk genre. Beeld en geluid zijn zoals het hoort. Hoewel het dus niets nieuws is, is dit zeker een aanrader voor wie van het genre houdt. Maar het is geen vernieuwend meesterwerk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(549,'The Hills Have Eyes',2006,'365',107,'2008-10-31',4,8,7,9,7,8,'Op Halloween moet een film zoals deze best kunnen. Bloederig en gewelddadig tot en met, maar het is een echt pareltje in zijn genre. Spannend en meeslepend, maar vooral af en toe lachwekkend. Het is er zo over, dat het weer leuk wordt. Zeker een aanrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(550,'Twisted',2004,'366',97,'2008-10-31',2,7,6,7,7,7,'Een indrukwekkende cast geeft niet altijd een garantie op een hoogstaande film. Ook hier is dit het geval. Het is allemaal wel aangenaam om te zien, maar de verhaallijn is toch echt iets te simpel. Het is eigenlijk een degelijke aflevering van een politieserie, maar dan met een erg goeie cast.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(551,'The Karate Kid, Part 2',1986,'102',113,'2008-11-01',4,4,4,5,5,6,'Wat ooit een echte blockbuster was, is nu echt niet meer om aan te zien. Het feit dat iedereen in Japan Engels spreekt, samen met de wel heel erg foute kledij, maken deze film echt wel irritant. Daarbij komt dat de plot flinterdun is. Zeker niet de moeite, maar het moet toch ooit wel eens iemand aangesproken hebben...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(552,'High Fidelity',2000,'304',113,'2008-11-01',3,8,8,7,8,7,'Deze film kan volgens mij het best omschreven worden als een \"romantisch drama waar over nagedacht is\". Het komt helemaal niet zo slijmerig over als andere films uit dit genre. Net daardoor werd deze film blijkbaar geen succes. Voor mij is dit echter een echt pluspunt. De cast levert een indrukwekkende prestatie. Niet echt lichte kost, maar zeker de moeite!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(553,'Little Miss Sunshine',2006,'367',101,'2008-11-05',2,9,9,7,9,8,'Wat deze film apart maakt is niet zo heel erg duidelijk, maar dat het zo is, staat wel echt vast. Het plot is buitengewoon absurd, maar tegelijk heel herkenbaar. Of hoe je van iets heel erg tragisch, toch een schitterende komedie kunt maken. Ook van de muziek was ik onder de indruk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(554,'Harry Potter and the Sorcerer\'s Stone',2001,'130',152,'2008-11-08',2,6,6,7,6,7,'Volgens de kenners is dit de meest kinderachtige van de Harry Potter films. En zo blijkt... Het is eigenlijk een verijdelde kinderfilm, maar een noodzakelijk kwaad om de volgende films te kunnen volgen. Die volgende films zouden dus beter zijn. Laat ons hopen... Ik geef deze film toch nog een aardige score omdat het verhaal wel goed in mekaar lijkt te zitten. Dat mag ook wel voor een verfilmd boek.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(555,'Harry Potter and the Chamber of Secrets',2002,'130',161,'2008-11-08',2,7,7,8,7,7,'Deze film is een hele verademing na het zien van de eerste film. Er zijn natuurlijk nog sporen van het \"sprookjesachtige\", maar het stoort eigenlijk niet meer. Het is al bij al wel leuk, maar laat ons duidelijk zijn, ik zal er mijn slaap niet voor laten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(556,'The Pacifier',2005,'57',95,'2008-11-18',4,4,3,6,6,6,'Vin Diesel als nanny, dat is kort samengevat wat deze film inhoudt. Er is weinig of niets anders van te zeggen. Op een handvol leuke momenten na, is dit geen aanrader. Vin Diesel probeert het nog een beetje de moeite waard te maken, maar tevergeefs.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(557,'Twilight',2008,'246',122,'2008-11-30',5,7,6,9,7,8,'Dit is vooral filmtechnisch een heel erg sterke film. Aparte sfeeropwekkende camerawerk en geluid, maakt van deze film een leuk kijkstuk. Het verhaal zelf valt echter wat tegen. Het is een tienerfilm qua inhoud, maar kan door de hele omkadering toch wel interesse wekken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(558,'Match Point',2005,'368',124,'2008-12-16',4,7,7,8,8,8,'Dit is zonder twijfel de film die het traagst op gang komt ooit. Het is zonder meer een uur saai, maar dan wordt het wel beter. Deze onvoorspelbaarheid maakt al veel goed. De cast tilt deze film naar een hoger niveau. Zeker een aanrader, maar je moet door het eerste uur geraken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(559,'Kung Fu Panda',2008,'369',92,'2008-12-21',1,5,5,8,8,8,'Over het algemeen is men heel positief over deze animatiefilm. Maar ik vind persoonlijk dat dit niet aan de verwachtingen voldoet. Het verhaal is heel erg dunnetjes. Misschien is de technische vooruitgang er wel ten opzichte van zijn voorgangers, maar enkel wat mooie beelden maken geen film goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(560,'Bad Santa',2003,'370',91,'2008-12-22',4,7,8,7,6,6,'Een op zijn minst aparte kerstfilm te noemen. Het steekt de draak met heel wat heilige huisjes en is ook zonder meer brainless amusement. Een redelijk aangename komedie, om tijdens de eindejaarsfeesten te bekijken. Niet al te opvallend, maar zeker niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(561,'The Mummy: Tomb of the Dragon Emperor',2008,'124',112,'2008-12-23',1,4,4,7,7,6,'Typisch een film om een geslaagd concept uit te melken. Dit hadden ze beter niet gemaakt. Supervoorspelbaar en helemaal niets nieuws. En echt spectaculair qua effecten is deze film ook niet. Om in een boogje rond te lopen en straal te negeren...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(562,'Horton Hears a Who!',2008,'371',86,'2009-01-06',2,8,9,7,7,7,'Na een hele reeks gemiddelde animatiekomedies springt deze er eindelijk nog eens uit. Spannend en meeslepend is het natuurlijk niet, maar wel heel erg entertaining. Beeld en geluid zijn zoals gewoonlijk. Een van de betere animatiefilms van de laatste jaren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(563,'The Day the Earth Stood Still',2008,'372',104,'2009-01-10',NULL,8,7,10,8,9,'Een eersteklas blockbuster. Het is zeker geen film die een breed publiek zal bekoren, al doet de hype anders vermoeden. Het is echter heel goed geprobeerd. Het verhaal is boeiend. Beeld en geluid zijn van uitzonderlijk niveau. Iets aparts, maar daarom niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(564,'Legally Blonde',2001,'373',96,'2009-01-16',NULL,8,8,7,8,7,'Een film waarin de rijkeluisjeugd ferm op de korrel wordt genomen. Het is eigenlijk een romantische komedie, maar toch is het niet bepaald melig. Het element komedie overheerst duidelijk. Beeld en geluid ondersteunen de situatiehumor goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(565,'Black Sheep',2006,'374',87,'2009-01-17',2,6,6,7,6,6,'De titel zegt alles, dit is een B horrorfilm van de beste soort. Het is zo gigantisch overdreven dat het weer komisch wordt. Dit kan gewoon niet als serieus verhaal opgenomen worden, daarvoor is het te lachwekkend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(566,'Click',2006,'375',107,'2009-01-20',2,8,9,9,7,8,'Een voor mij volledig onbekende titel, maar ook volledig onterecht. Dit is een komedie met Adam Sandler. Dat staat meestal voor een flinterdun verhaal. Maar dat is hier niet het geval. Boeiend is het wel, al moet je je niet te hard ergeren aan de moraal die deze film probeert over te brengen. Heel onderhoudend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(567,'You Don\'t Mess with the Zohan',2008,'26',113,'2009-01-30',2,8,8,7,7,7,'Voor wie van absurde komedies houdt, is dit zeker een aanrader. Adam Sandler op zijn best, ondersteund door een sterke cast. Het verhaal bevat niet veel, maar dat heeft dit genre eigenlijk niet nodig. Wie een diep verhaal wil, is hier duidelijk aan het verkeerde adres. Hilarisch is het echter wel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(568,'Hooligans',2005,'376',109,'2009-02-08',2,8,8,7,7,8,'Het voetbalthema zal heel wat mensen afschrikken, maar het is belangrijk te melden dat het voetbal zelf niet echt aan bod komt. Het is een verhaal over groepsdruk, respect, eer en traditie. Zeker niet slecht, maar een voor een feel good movie ben je aan het verkeerde adres.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(569,'The Curious Case of Benjamin Button',2008,'79',166,'2009-02-09',5,9,9,8,8,8,'Je zou verwachten dat dit een zeemzoet liefdesdrama is, maar niets is minder waar. Het is een epos van een wel heel apart persoon. Pakkend, zoals er al een hele tijd geen zo\'n pakkende films geweest zijn. Voor de cinefiel is dit een niet te missen film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(570,'Wanted',2008,'377',110,'2009-03-22',NULL,6,6,7,7,7,'Een cast om u tegen te zeggen, kan de verwachtingen helaas niet inlossen. Het begint allemaal veelbelovend, maar de plot verliest zich volledig in flitsende actie. Hierdoor heb je de indruk dat je naar een wekelijkse actieserie hebt zitten kijken, en niet naar een blockbuster movie. Al bij al wel leuk, maar niet meer dan dat. Zeker niet uitzonderlijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(571,'Anger Management',2003,'359',106,'2009-03-18',4,7,8,7,7,7,'Alweer een komedie die goed is door de cast. Een schitterende Nicholson en Sandler dragen deze film perfect. Het verhaal is niet speciaal goed, maar door de situatiehumor wordt veel goedgemaakt. Een klassieke komedie met een doel, zoals er tegenwoordig te weinig gemaakt worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(572,'Dinosaur',2000,'378',82,'2009-04-04',4,7,6,8,7,7,'Een tekenfilm van de nieuwe generatie. Volledig in 3D, dus geen platte tekeningen meer. Het is eigenlijk een kinderfilm, maar ook niet al té kinderachtig. Mooi gedaan, zeker qua beeld, al is de plot wel wat simpel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(573,'Robin Hood: Men in Tights',1993,'379',104,'2009-04-10',4,8,9,7,8,8,'Deze typische Mel Brooks rariteit kwam uit op het moment dat de absurde komedie hoogtij vierde. Het resultaat is een echte klassieker vol verfijnde, en iets minder verfijnde humor. Deze moet je gezien hebben als liefhebber van het genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(574,'Spider-Man 2',2004,'15',127,'2009-04-17',4,5,5,9,8,8,'Meer van hetzelfde. Dit is een eerder melige versie van een comicverfilming. Enige vorm voor realiteit is verdwenen en de plot zelf is ook maar heel erg dunnetjes uitgevallen. Beeld en geluid zijn wel heel goed, maar dat maakt hier geen goede film van.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(575,'Hot Shots: Part Deux',1993,'238',86,'2009-04-18',4,8,8,7,7,7,'Deze film brengt perfect wat je verwacht: Een hilarische parodie op tal van andere films. Als je deze film voor de tweede keer ziet, merk je pas dat je de vorige keer de helft gemist hebt. Het is een echte klassieker, maar kan toch net niet aan de eerste film tippen. Zeker een aanrader voor wie van absurde humor houdt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(576,'America\'s Sweethearts',2001,'380',102,'2009-04-22',4,6,6,7,7,7,'Een melige romantische komedie over een hollywoodkoppeltje. Hoewel dit zeker geen slechte film is, brengt het ook echt niets nieuws. Het is een film van dertien in een dozijn. De sterke cast kan hier niets aan veranderen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(577,'Knowing',2009,'253',121,'2009-04-25',5,8,8,9,8,8,'Waar films als \"The Happening\" sterk beginnen, maar dan volledig in mekaar zakken, blijft deze film wel stand houden. Deze meeslepende blockbuster boeit van begin tot einde en is ook superspannend. Vooral de SFX zijn indrukwekkend. Geen lichte kost, maar zeker de moeite waard.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(578,'Candyman',1992,'381',99,'2009-05-02',2,7,8,6,8,8,'De eerste film in de trilogie van Candyman. Hoewel het een enorme hit was in zijn tijd, is deze film echt wel oud. Althans, zo lijkt het. Het is een fancy B-horrorfilm. Maar een echte filmliefhebber zal deze film zeker niet links laten liggen. Vooral de muziek zorgt voor een unieke sfeer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(579,'Bram Stoker\'s Dracula',1992,'195',128,'2009-05-15',4,7,8,7,8,8,'De oerversie van de Draculafilms. Een echte klassieker met een ijzersterke cast. Hoewel de effecten en de beeldkwaliteit vaak te wensen over laten, geeft deze film toch een heel unieke sfeer. Een echt pareltje voor cinefielen en voor mensen die gewoon eens wat anders willen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(580,'X-Men Origins: Wolverine',2009,'382',107,'2009-05-20',5,7,6,9,8,8,'Deze film gaat eigenlijk voor op de X-Men trilogie. Het beantwoordt heel wat vragen en valt bovendien ook nog eens goed mee. Het verhaal is voorspelbaar en de structuur is absoluut niet origineel. Maar voor een avondje ontspanning is dit een ideale kandidaat. Beeld en geluid zijn, zoals gewoonlijk bij dit soort films, heel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(581,'Wicker Park',2004,'340',114,'2009-05-21',2,7,7,7,8,7,'Hoewel de plot vrij goed in elkaar zit en naar het einde toe ook wel kan boeien, is deze film toch in zijn geheel te traag. Het is allemaal best OK, maar soms betrap je jezelf als je bijna aan het indommelen bent. Het is zo\'n film die je maar achteraf kan appreciëren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(582,'Crocodile Dundee',1986,'383',93,'2009-05-22',4,7,8,5,6,6,'Een klassieke komedie, volledig volgens de regels van de kunst van midden de jaren tachtig. Echt boeiend en meeslepend kan je dit dus niet noemen. Origineel is het echter wel. Zeker een aangename afwisseling in deze tijden van flitsende special effects.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(583,'Days of Thunder',1990,'173',107,'2009-05-23',2,8,8,7,7,7,'Een van de weinige degelijke films over autosport. Waar de andere films onvermijdelijk terugvallen op onrealistische stripverhaalavonturen, probeert deze film echt het NASCAR-gevoel over te brengen, ook naar minder geïnteresseerde kijkers. Voor NASCAR-fans is dit een verplicht kijkstuk. De rest zal dit maar niks vinden...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(584,'Big Momma\'s House 2',2006,'384',99,'2009-05-23',4,7,6,7,7,7,'De sequal is in dit geval wel wat beter dan het origineel. Maar je weet wat je kan verwachten met zo\'n Martin Lawrence film. Ontspannend, dat wel, maar veel meer heeft deze film niet om het lijf.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(585,'Hitch',2005,'385',118,'2009-05-29',4,7,7,6,6,7,'Omdat ik altijd met enig argwaan aan een romantische komedie begin, verdient deze film zeker extra punten. Het is geen hilarisch meesterwerk, maar het onderhoudt wel. Voor mij persoonlijk is dat al een hele prestatie. Beeld en geluid zijn degelijk, maar vallen niet echt op in dit soort films.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(586,'Crocodile Dundee 2',1988,'386',108,'2009-05-29',4,6,5,5,6,6,'De sequal op de eerste degelijke komedie. Deze film brengt echter niets bij aan de eerste. Dat lijkt wel de ziekte van alle sequels in de eighties. Beeld en geluid zijn typisch voor die tijd. Geen hoogvlieger, maar enkel nuttig als er echt niets anders te zien valt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(587,'Zack and Miri Make a Porno',2008,'387',101,'2009-06-05',4,8,9,8,8,8,'Af en toe komt er nog eens een film uit die echt verrassend is. Dit is een van die films die in dat selecte lijstje thuis hoort. De verhaallijn is op zijn minst apart te noemen. Daarbij vervalt dit niet in het enkel gericht zijn naar cinefielen. Topklasse, maar niet echt voor kinderen...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(588,'Meet the Spartans',2008,'388',84,'2009-06-14',2,6,6,8,8,7,'Deze af en toe hilarische parodie op 300 kon mij niet echt bekoren. Het is er soms zó over, dat het echt degoutant wordt. Als je 300 gezien hebt, valt deze film te overwegen, maar neem er dan je misselijkheid bij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(589,'Ripley\'s Game',2002,'389',110,'2009-07-15',4,8,8,9,8,9,'Deze film creeërt een heel aparte sfeer. Mede daarom kan John Malkovich schitteren in deze koude misdaadfilm. Boeiend en meeslepend van begin tot einde. Maar toch licht verteerbaar. Dit is een zwaar onderschatte film en had veel beter verdiend in de zalen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(590,'My Best Friend\'s Wedding',1997,'390',105,'2009-07-16',4,6,6,6,6,6,'Deze romantische komedie heeft niet erg veel om het lijf. Maar het is toch niet iets gewaagder en etisch fout, dan de gemiddelde film in dit genre. De acteurs doen hun uiterste best om deze film te laten uitblinken, maar slagen er niet echt in. Niet al te slecht, niet al te goed...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(591,'Harry Potter and the Order of the Phoenix',2007,'252',138,'2009-07-19',2,7,7,8,7,8,'De vijfde film over Harry Potter bouwt verder op de vorige vier. Het is nog iets donkerder en volwassener dan de vorige, maar daarmee is het belangrijkste verschil ook vermeld. Meer van hetzelfde, dus. Al begint het stilaan echt geen kinderfilm meer te zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(592,'Shanghai Knights',2003,'391',114,'2009-07-31',4,7,7,8,7,7,'Jackie Chan en Owen Wilson is een gewaagde, maar heel erg geslaagde combinatie. De vechtscènes zijn, zoals gewoonlijk, fenomenaal. Maar dat is het zowat. De rest is maar lauw. Een goede poging, maar niet meer dan dat. Ik geef deze film het voordeel van de twijfel...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(593,'Category 6: Day of Destruction',2004,'392',174,'2009-08-05',4,6,4,3,5,6,'Goddank dat deze film nooit in de zalen is geraakt. De effecten zijn echt wel ondermaats. Ze komen zo uit een actiespel uit het jaar 1995. Toch zit het plot niet zo slecht in elkaar. Het weet wel te boeien, al moet je de technische en soms eerstejaarsfouten er wel bij verdragen. Vermijden als je kan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(594,'Watchmen',2009,'363',162,'2009-08-08',4,8,7,9,8,9,'Een enorme blockbuster die niet teleurstelt. De effecten en actiescènes zijn om te snoepen. Ook het verhaal is boeiend, omdat het heel wat anders is dan wat je zou verwachten van een superhero-movie. Maar stellen dat deze film me jaren zal bijblijven, is ook overdreven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(595,'Stealing Harvard',2002,'393',85,'2009-08-15',4,6,7,6,6,6,'Een vrij aangename komedie, maar echt veel inhoud is er niet. Het doet net iets te veel aan de 90s denken. Beeld en geluid zijn eerder matig. Ach, waarom niet?','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(596,'Sunshine',2007,'32',107,'2009-08-15',4,8,8,9,8,8,'Een, op zijn zachtst gezegt, vrij eigenaardige film. Het is ongetwijfeld een pareltje in de Scifi wereld. Maar voor wie geen fan is van het genre, zal dit geen leuke filmavond garanderen. Hoewel het einde duidelijk aan originaliteit mist, is dit net het aspect waar de rest van deze film in uitblinkt. Boeiend, alleen al omdat het uniek is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(597,'The Illusionist',2006,'394',110,'2009-08-18',2,7,8,7,7,8,'Deze film moet het vooral hebben van de sfeer die er rond hangt. De cast tilt het niveau omhoog. Boeiend is het van begin tot einde. Alleen is dit niet echt een ontspannende plot. Met een beetje moeite is dit zeker de moeite waard.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(598,'Casino Royale',2006,'29',144,'2009-08-21',1,8,9,9,8,8,'Dit is een heel aparte Bondfilm. Het is niet het typische superheld actieverhaal. Het is de eerste Bondfilm die echt aan de ribben blijft plakken. Als je dus een no-brain actiefilm verwacht, ben je er aan voor de moeite. De film op zich is echter ijzersterk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(599,'Yes Man',2008,'294',104,'2009-08-29',2,7,7,7,7,7,'Dit is een klassieke komedie, met Jim Carrey als drager ervan. Het biedt absoluut niets nieuws en al zeker geen origineel plot. Maar het blijft wel een degelijke komedie. Geen meesterwerk en niets speciaals. Gewoon een degelijke komedie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(600,'Superman Returns',2006,'265',154,'2009-08-30',2,5,4,8,7,7,'Een remake maken van het alom bekende Superman verhaal, is vragen om problemen. Niets aan deze film maakt het de moeite waard. Voor de comic-fans is dit zeker een must, maar alle anderen mogen deze film gerust links laten liggen. Beeld en geluid zijn dan wel goed, maar de plot is quasi onbestaande.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(601,'Tropic Thunder',2008,'245',107,'2009-09-05',4,9,8,9,9,8,'De cast van deze Ben Stiller komedie doet het beste vermoeden. En dat maken ze ook waar. Hoewel de film eigenlijk niet al te goed is, wordt dit een fantastische komedie door de cast. Een aanrader voor een hilarische avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(602,'Loft',2008,'395',118,'2009-09-08',2,9,8,9,8,8,'Na \"De Zaak Alzheimer\" waren de verwachtingen hoog gespannen. Deze film stelt echt niet teleur. Het ziet er heel onbelgisch uit. Het verhaal zit goed in mekaar. Van de actiescènes moet deze film het niet hebben, maar wel van de dialogen en sfeer. Verrassend goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(603,'Meet Dave',2008,'186',90,'2009-09-14',2,9,9,7,7,8,'Lang geleden dat ik nog zo gelachen heb met een komedie. En dat is verrassend, want een film die volledig rond Eddie Murphy draait, is sinds eind de jaren 80 geen garantie meer op succes, laat staan niveau. Het verhaal klinkt enorm dwaas, maar het is het hoofdingrediënt van een hilarische superkomedie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(604,'The Golden Compass',2007,'396',113,'2009-09-25',4,6,5,8,8,7,'In tijden waar fantasy-avonturenfilms een echte hype lijken te zijn, ontstaan ook dit soort films. Het zijn volstrekt overbodige samenvoegsels van al eerder gemaakte filmelementen. Het is een soort slecht gemaakte \"Lord of the Rings\"-kloon, maar dan met heel erg weinig om het lijf. Afrader!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(605,'Quantum of Solace',2008,'237',106,'2009-09-26',1,8,7,9,8,8,'Casino Royale was verrassend goed. Deze film kan echter geen goed gevolg geven. Het is een heel goeie actiefilm, maar mist dat meeslepende van de vorige film. Zeker een must voor Bondliefhebbers, maar in tegenstelling tot zijn voorganger, is dit geen pareltje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(607,'Beowulf',2007,'16',115,'2009-10-02',4,8,7,7,8,8,'Een supercast, maar dan volledig als animatiefiguren. Het komt een beetje bizar over en begint als echte horror, maar dit is eigenlijk lang niet slecht. Beeld en geluid zijn eerder uitzonderlijk, maar zeker niet slecht. Zeker veel beter dan de andere verfilming die ik al heb gezien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(608,'Surrogates',2009,'156',88,'2009-10-24',5,6,5,8,6,7,'Zoals zovele Sci-fi films heeft ook deze een veelbelovend thema. Iets waar je als scenarioschrijver echt je ding mee kan doen. Maar eveneens als evenveel van zijn voorgangers in zijn genre, wordt er bitter weinig mee gedaan. Voorspelbaar en niet meeslepend. Je blijft de hele film op je honger zitten. Niet slecht, maar heel erg gewoontjes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(609,'Coneheads',1993,'397',88,'2009-11-02',2,7,7,6,7,7,'In die jaren was deze film echt baanbrekend. De absurditeit druipt er af en is, het moet gezegd, toch af en toe er zwaar over. Maar toch is dit zeker geen slechte komedie. Ideaal voor een ontspannen avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(610,'Superhero Movie',2008,'398',75,'2009-11-10',4,8,7,8,7,8,'Een komedie met Leslie Nielsen stelt zelden teleur. Deze ook niet, hoewel zijn rol eerder beperkt is in deze film. Zonder al te veel over de schreef te gaan, is deze film goed geslaagd, als je het eigenlijke doel in acht neemt. Verwacht geen diepgaand verhaal, natuurlijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(611,'The Bank Job',2008,'225',111,'2009-11-17',4,8,7,8,8,8,'Een ouderwets type actiethriller over een bankoverval, zoals de titel al aangeeft. Het is niet moeilijk en ook eigenlijk niet echt origineel. Maar wel goed gedaan, zonder meer. Leuke actiefilm, maar geen die ik me jaren zal herinneren. Beeld en geluid zijn best wel OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(612,'The Twilight Saga: New Moon',2009,'396',130,'2009-11-22',5,7,6,8,8,8,'De tweede film uit de immens populaire Twilight saga. Het typische tienerverhaal over de onmogelijke liefde. Net zoals Romeo en Juliet, maar dan in een hedendaags kleedje. Het is wel goed gedaan, maar de plot is nogal simpel. Ideale teen chick movie, vrees ik.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(613,'No Country for Old Men',2007,'399',122,'2009-11-24',4,9,9,8,9,8,'Een western van de nieuwe stijl. Deze film is bekroond met een berg prijzen, en helemaal terecht. Een bloedstollende western met een heel aparte sfeer. Clichés zijn er niet in te vinden, alsook geen muziek. Die originaliteit verdient het om hoog aangeprezen te worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(614,'Awake',2007,'400',84,'2009-12-02',2,7,8,7,7,7,'Een nogal leuke thriller, vrij boeiend, maar ook niets speciaals. Zeker onderhoudend, maar meer niet. Ach, waarom niet...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(615,'Transformers: Revenge of the Fallen',2009,'98',150,'2009-12-09',2,7,6,9,7,8,'Leuk voor de Transformers fans en zonder meer een heel spectaculaire actiefilm. Van de superintelligente plot moet deze film het echter niet hebben. Dertien-in-een-dozijn-film. Al is het zeker geen slechte actieprent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(616,'Bee Movie',2007,'401',91,'2009-12-16',4,7,7,6,7,7,'Alweer een Dreamworks animatiefilm. Dus alweer degelijk, maar alweer dezelfde feel-good sfeer en animatie. Het is dus een leuke film voor een ontspannen avond, maar de zinloosheid van deze film trof mij nog het meest. Sinds Toy Story is er blijkbaar nog maar weinig veranderd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(617,'Mirrors',2008,'365',112,'2010-12-20',2,6,5,8,9,7,'Alweer een blame-it-on-the-demon horrorprent. Waarschijnlijk weer een verkrachting van de originele Japanse versie. Hoewel deze film erg goede kritieken krijgt, zie ik niet in wat er nu precies zo speciaal aan is. Een gevoel van \"been there, done that\" overvalt me spontaan. Maar kom, de muziek is in ieder geval goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(618,'Bangkok Dangerous',2008,'402',99,'2009-12-22',4,8,8,9,7,8,'Een actie-misdaadfilm over een huurmoordenaar stelt in mijn ogen zelden teleur. Zo ook deze. Het is allemaal niet zo bijster origineel, maar het is wel goed gedaan. Een in mijn ogen erg onderschatte actiefilm met Nicolas Cage.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(619,'House of Flying Daggers',2004,'403',119,'2009-12-28',4,9,8,10,8,8,'De actiescènes in deze film hebben vaak wenkbrauwgefrons tot gevolg gehad. Maar eigenlijk zijn sommige shots prachtige kunstwerken op zich. Het verhaal is voor een keer niet doorspekt met Amerikaanse clichés, aangezien het een Japanse film is. Een pareltje voor wie er voor open staat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(620,'Avatar',2009,'80',162,'2010-01-02',5,9,8,9,8,8,'Twaalf jaar na Titanic komt James Cameron nog eens met een blockbuster op de proppen. En het is een pareltje geworden. Wat mij betreft, is dit de eerste film waarbij animatiebeelden onopvallend overvloeien in gewoon camerawerk. Zelfs voor wie niet van sci-fi houdt, zal dit toch aangenaam blijken te zijn. Dit wordt zeker een klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(621,'Trading Places',1983,'235',118,'2010-01-02',4,7,7,6,6,6,'Een film uit de hoogdagen van Eddy Murphy en Dan Aykroyd. Duidelijk een klassieke eighties komedie, dus. Meer is het niet, maar het is zeker genietbaar voor de liefhebbers. Een ontspannende no-brains komedie voor het hele gezin.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(622,'Eagle Eye',2008,'335',118,'2010-01-04',4,8,7,9,8,8,'Soms heb je van die films waar je nog nooit van gehoord hebt en bijgevolg met enig argwaan aan begint. En dan blijken die enorm goed te zijn. Wel, dit is er zo eentje. Spectaculaire actiescènes en spanning. Hoewel de geloofwaardigheid hier soms wel wat onder te lijden heeft, blijft dit een hele goede actieprent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(623,'Up',2009,'404',96,'2010-01-09',2,9,9,8,7,8,'Net op het moment waarop het de Pixar animatiefilms aan originaliteit begon te ontbreken, kwam Up op de markt. Totaal niet wat je er van verwacht. Bijgevolg dus goed. Zeker een van de betere animatiefilms van de laatste jaren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(624,'Bolt',2008,'405',96,'2010-01-10',2,6,6,NULL,7,8,'Na het zien van Up, valt deze Bolt echt wel tegen. Het is zeker geen slechte film, maar er is echt niets speciaals aan. Soms grappig, soms niet. En al helemaal niet origineel. Door het bestaan van betere films in dit genre, krijgt deze film een onvoldoende.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(625,'Diary of the Dead',2007,'406',95,'2010-01-22',4,8,8,9,7,7,'Een typische moderne zombiefilm. Het is een deel van een reeks van een tiental films. De plot is natuurlijk niet te complex, maar liefhebbers van het genre zullen dit zeker kunnen appreciëren. Het wordt namelijk gefilmd door een van de personages. Het is een vorm van klasse, al moet je er wel voor open staan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(626,'Drag Me To Hell',2009,'15',99,'2010-01-22',4,8,8,9,7,8,'Een horrorfilm die bulkt van de clichés en klassieke technieken, is niet altijd slecht. Het resultaat is in dit geval een echte cult-horrorprent met alles erop en eraan. Een echte ribbenplakker, al is het wel wat voorspelbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(627,'88 minutes',2007,'407',108,'2010-01-23',1,7,6,7,7,7,'Al Pacino is al langer geen garantie meer op een goeie film. Maar hij kreeg bij deze nog het voordeel van de twijfel. Nadien bleek dat hij vooral de film moet dragen. Origineel en meeslepend is het niet, maar zijn acteerkunde maakt veel goed. Niet fantastisch, want alleen Pacino maakt het de moeite waard.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(628,'9',2009,'408',79,'2010-01-31',2,7,6,9,8,8,'Dit is een typische plastic animatiefilm geworden met alweer een heel aparte sfeer. Maar het verhaal is echter nogal dunnetjes. Ik vrees dat deze film te snel af moest zijn. Hier was meer mee te doen. Beeld en geluid zijn typisch, maar degelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(629,'Noise',2007,'409',92,'2010-02-07',4,7,7,8,7,9,'De plotsamenvatting doet het beste verhopen. Alleszins heel origineel en het schept hoge verwachtingen. Helaas wordt er niet zoveel mee gedaan. HEt is een leuke en originele film geworden, maar de kijker blijft wel wat op zijn honger zitten. Degelijk, maar teleurstellend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(630,'Coraline',2009,'410',96,'2010-02-03',2,8,7,9,8,9,'Dit soort griezelige animatiefilm lijkt de hype van het jaar te worden. De heel aparte sfeer, maakt hier een pareltje van. Echt ontspannend is het niet, mede door de aparte stijl. Zeker niet slecht, qua beeld en geluid. Al mocht het verhaal iets minder eenvoudig zijn geweest.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(631,'Sherlock Holmes',2009,'230',128,'2010-02-09',8,7,6,8,7,8,'Guy Ritchie staat meestal garant voor een goede film. Dit valt echter een beetje tegen. Zijn eerste echte mainstream film, heeft last van de pijnen van de andere films in het genre: Weinig meeslepend en niet vernieuwend. Aangenaam, maar zeker niet uitmuntend. Beeld en muziek zijn wel OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(632,'Short Circuit 2',1988,'411',110,'2010-02-10',4,6,5,7,6,7,'Een eighties klassieker zoals er een heel pak zijn. Dit type komedie\'s is alleen nog de moeite uit nostalgie of voor de echte liefhebbers. Eigenlijk vrij saai, maar het is voor die tijd wel vrij goed gedaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(633,'Hot Babes',2009,'412',85,'2010-02-13',8,7,6,8,7,8,'Een tienerkomedie die kan doorgaan voor een remake van de Porky-films uit de eighties. Af en toe best leuk, maar soms ook vrij plat. Voor een ontspannende avond is dit zeker niet slecht, maar verwacht geen meesterwerk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(634,'Indiana Jones and the Temple of Doom',1984,'8',118,'2010-02-22',4,8,8,6,8,7,'Een van de drie klassieke Indiana Jones films. Vrij eighties en daardoor wat ouderwets, maar in ieder geval veel beter dan de recentere Indiana Jones film. Behoeft weinig uitleg...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(635,'The Pink Panther',1963,'413',115,'2010-03-08',4,7,8,5,6,6,'De echte cinefielen kennen deze komedie nagenoeg uit het hoofd. Het is eigenlijk een erg goede film voor die tijd, maar natuurlijk hopeloos ouderwets. In die tijd waarschijnlijk enorm trendsettend. Enkel voor de echte liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(636,'Who Framed Roger Rabbit',1988,'16',104,'2010-03-08',4,7,6,7,8,7,'Op het einde van de eighties waren deze semi-animatiefilms een echte rage. Dit is een van de betere in die serie. Als je de wat amateuristische look er wil bij nemen, is dit eigenlijk een redelijke film. Zeker als je Looney Tunes fan bent. De rest zou deze film beter vermijden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(637,'Push',2009,'340',111,'2010-03-10',8,5,5,9,8,8,'In deze tijd van superhero movies, past deze prent in het rijtje van niet-vernieuwende wastes of money. Dit is een goedkope Heroes rip-off. Beeld en geluid zijn zeker OK, maar het verhaal mist inhoud. En ook een degelijk slot. Gemiste kans, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(638,'Evan Almighty',2007,'104',96,'2010-03-19',4,8,8,8,7,7,'Het is alweer een tijdje geleden dat ik nog eens een sequel heb gezien die beter was dan het origineel. Bij deze film is dit zeker het geval. Alleen daarvoor verdient deze film een pluim. Een van de betere komedies van het jaar. Maar erg veel inhoud moet je er nu ook weer niet van verwachten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(639,'City of Ember',2008,'414',90,'2010-03-28',4,6,6,8,7,7,'Een speciale avonturenfilm, maar eerder iets voor de jeugd. Het verhaal is niet echt boeiend, maar het is wel eens iets anders. De schaarse pogingen om grappige momenten in de film te krijgen, lijken wel wat amateuristisch. Niet zo denderend, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(640,'The Taking of Pelham 1 2 3',2009,'173',106,'2010-03-30',4,8,8,8,7,8,'Een lekker ouderwetse actiethriller over een gijzeling. Hoewel het verhaal dus niet echt origineel is, zorgt de cast er wel voor dat je dit al snel vergeet. Boeiend, spannend en onderhoudend. Alles wat je van dit soort film verwacht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(641,'Alice in Wonderland',2010,'50',108,'2010-04-03',8,7,7,9,8,8,'Zowat dé blockbuster van het jaar, maar geweldig ge-overhyped. Knappe verfilming van het gekende sprookje, maar ook niet meer dan dat. Ik ben beter gewoon van Tim Burton. Hij heeft zich duidelijk laten verleiden door het mainstream publiek. Een gemiste kans, maar niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(642,'11:11',2004,'415',95,'2010-04-16',4,3,3,5,6,5,'Een zoveelste film met ongeveer hetzelfde verhaal. Dertien in een dozijn, of zelfs veertien. Absoluut niets nieuws, en dan ook nog eens niet goed gedaan. Om nog maar te zwijgen van het slot. Volstrekte verspilling van geld en tijd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(643,'Chaos Theory',2007,'416',87,'2010-05-01',2,7,7,8,7,7,'Als je de korte inhoud leest, verwacht je best veel van deze film. Maar het is totaal niet wat je er van verwacht. Een komedie kan je het al helemaal niet noemen. En voor één keer is dat niet positief. Het is een aangename film, maar zeker niet een die blijft hangen. Al bij al teleurstellend, maar toch zeker genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(644,'How to Train Your Dragon',2010,'417',98,'2010-05-23',2,7,7,8,7,8,'Een degelijke animatiekomedie, zoals er wel meerdere gekend zijn in het genre. Maar ook weer zo een waarvan je de trailer niet mag zien, of je weet al 90% van de inhoud. Zeker de moeite waard, als je er nog nooit van gehoord hebt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(645,'Ghost Rider',2007,'418',123,'2010-05-24',2,8,7,8,8,8,'Een comic verfilming waar verdacht weinig lawaai rond werd gemaakt in 2007. Wat mij betreft, onterecht. Een van de betere verfilmingen, al moet je dit wel met een korreltje zout nemen. Leuke film, goed gedaan, zeker qua beeld en geluid, maar zeker niet uniek. Ontspannend is het natuurlijk wel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(646,'Duplicity',2009,'419',118,'2010-05-24',4,7,7,8,7,6,'Een misdaadfilm met zo\'n cast vraagt om sterke dialogen. En dat heeft deze film genoeg. Alleen vind ik het verhaal wel wat aan de magere kant. Zeker het slot is een beetje te gemakkelijk opgelost. Voor wie van dit soort films houdt, is dit zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(647,'Traitor',2008,'420',114,'2010-06-05',4,8,8,7,6,7,'Een film over terrorisme door Amerikanen die het proberen te bekijken vanuit het standpunt van de terroristen. Eigenlijk is dit vragen om problemen. Toch zitten hier en daar wel scènes om eens bij stil te staan. Helaas vervalt deze film naar het einde toe in het typische patriotisme. Niet realistisch, maar toch een goeie poging om eens iets anders te maken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(648,'G-Force',2009,'421',88,'2010-06-06',4,4,3,6,6,7,'Een eerder onbekende animatiefilm, en al snel blijkt waarom. Het gaat over schattige cavia\'s, maar daar stopt de originaliteit. Een flinterdun verhaal met helemaal niets nieuws. Absoluut een kinderfilm die bij mij gecatalogeerd staat als tijdverlies.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(649,'The Tournament',2009,'422',95,'2010-06-20',8,7,7,9,7,7,'Na het wereldwijde succes van Battle Royale, moest Hollywood met zijn eigen versie komen. Dit is al bij al een leuke actiefilm geworden, maar eigenlijk niets speciaals. Niet realistisch, maar wel spectaculair.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(650,'The Twilight Saga: Eclipse',2010,'348',124,'2010-07-03',5,7,6,8,8,8,'De derde film in de vierdelige Twilight saga. Helemaal niets nieuws, maar als je de eerste twee gezien hebt, kan je bijna niet anders dan deze ook te verteren. Het blijft hetzelfde verhaal: absoluut een vrouwenfilm, maar ook niet slecht gedaan. Een van de betere films in dit genre, maar mijn genre is dit zeker niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(651,'Terminator Salvation',2009,'336',115,'2010-07-04',8,5,5,8,6,8,'Eigenlijk was het Terminator verhaal al uitgemolken na de tweede film. Deze gaat nog een stapje verder. Een degelijke actiefilm met af en toe een verplichte verwijzing naar de vorige films, althans zo lijkt het toch. Enkel voor de fans, maar zelfs die zullen zeggen dat ze dit beter niet hadden gedaan. Volstrekt overbodig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(652,'Step Brothers',2008,'423',98,'2010-07-05',8,8,8,7,8,7,'Lang geleden dat er nog eens een absurde satire doorbrak naar het grote publiek. Bij deze film is dit dus het geval. En daarom alleen al verdient deze een pluim. Verfrissend in een poel van films van 13 in een dozijn. Let wel, absurde humor is enkel voor de liefhebbers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(653,'Paul Blart: Mall Cop',2009,'424',91,'2010-07-12',8,7,8,7,7,8,'Een ouderwetse komedie, recht uit de eighties, zo lijkt het wel. Puur gedragen door het hoofdpersonage, aangezien de plot wel heel erg dun is. Eigenlijk is dit een parodie op Die Hard, maar dan wel heel erg veel te laat. Al bij al wel leuk voor een ontspannende avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(654,'Star Trek',2009,'425',127,'2010-07-26',8,8,8,9,7,9,'Een remake van de originele Star Trek film uit de sixties. Absoluut geslaagd, zonder meer. Het is, in tegenstelling tot de algemene verwachting, een pareltje geworden. Je krijgt onmiddellijk weer zin om naar de serie te beginnen kijken. Beeld en geluid zijn heel erg goed, want dat is noodzakelijk voor dit genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(655,'Largo Winch',2008,'426',108,'2010-07-27',8,9,9,9,8,9,'Een rauwe misdaadfilm van Belgisch/Franse makelij. Je moet wel mee zijn, want na een tijdje wordt het wel complex. Maar genietbaar is het zeker. Een van de betere misdaad thrillers van het laatste jaar. Beeld en geluid zijn daarbij heel goed. De cast maakt het helemaal af.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(656,'Slumdog Millionaire',2008,'32',120,'2010-08-06',8,8,8,7,8,7,'Een leuk feel-good verhaal, perfect voor een ontspannende avond. Origineel, maar ook wel wat overroepen. Zeker genietbaar, al weet je eigenlijk al wat je kan verwachten van de korte inhoud. Al zal het niveau van realisme wel heel erg klein zijn. Alles wordt immers bekeken vanuit een westerse bril.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(657,'War Inc.',2008,'427',107,'2010-08-08',8,6,6,7,7,8,'Een politieke oorlogssatire is enkel genietbaar als je van dit genre houdt. Maar zelfs dan zal je moeten bekennen dat er betere films in het genre zijn. Het lijkt allemaal een beetje los zand waar men een film van probeert te maken. Niet denderend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(658,'Die Hard: With a Vengeance',1995,'73',131,'2010-08-29',4,8,8,7,7,8,'De derde Die Hard film, en eigenlijk ook de beste. Het is natuurlijk niets nieuws. De held redt zichzelf een een hele hoop anderen uit onmogelijke situaties op enorm spectaculaire manieren. De indrukwekkende cast tilt deze film nog naar een hoger niveau. Originaliteit nul, maar anders best OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(659,'Gamer',2009,'428',95,'2010-08-20',8,7,6,9,8,8,'Een ietwat aparte actiefilm over hoe de gaming industrie een steeds prominentere rol speelt in de maatschappij in een zeer nabije toekomst. Schitterende actiescènes, maar weinig inhoud. Ook het slot stelt wat teleur, vind ik. Een absolute no-brain actiefilm, maar wel een van de betere.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(660,'Grown Ups',2010,'26',102,'2010-08-21',8,8,9,8,7,8,'Een komedie van de oude stempel, die het vooral moet hebben van situatie- en herkenningshumor. Dus echt toegankelijk voor iedereen. Een sterke cast en een ontspannende plot zorgen voor een heel aangenaam kijkstuk. Wel is de film doorspekt met de Amerikaanse moraal, en dat werkt wel wat storend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(661,'The Bounty Hunter',2010,'385',110,'2010-08-25',8,6,7,7,6,7,'Alweer een romantische komedie waarvan de korte inhoud veelbelovend is, maar de film zelf is heel wat minder. Er zitten, zoals altijd, wel wat goeie stukken in, maar eigenlijk veel te weinig. Middelmatig, van begin tot einde.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(662,'Year One',2009,'197',97,'2010-08-27',8,6,7,6,6,6,'Een film met Jack Black moet het meestal enkel van zijn personage hebben. En dat is ook zo in deze film. Een typische \"all the funny parts are in the trailer\" film. Maar wel een acceptabele parodie op enkele bijbelverhalen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(663,'Once Upon a Time in Mexico',2003,'221',102,'2010-09-01',4,8,8,9,7,7,'Een megacast doet het beste verhopen. Het is een heel aangename actie/misdaad film, maar er zijn wel heel erg veel clichés. Eigenlijk weet je dit als je naar dit soort films kijkt, dus deze film krijgt het voordeel van de twijfel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(664,'The Simpsons Movie',2007,'429',87,'2010-09-04',4,7,7,8,7,7,'Zeker niet slecht, maar het blijft een lang uitgerokken aflevering van The Simpsons serie. Daarom zelfs vrij teleurstellend, want het is niet echt speciaal. Een aanrader is het dus niet, maar slecht kan je het natuurlijk ook niet noemen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(665,'Salt',2010,'59',100,'2010-09-19',8,7,6,8,7,8,'Een teleurstellende blockbuster. Gewoon omdat er weinig nieuws aan was. Typisch zo\'n film waarvan er al een dozijn eerder van zijn gemaakt. Wanneer komen ze eens met iets nieuws? Maar in zijn genre is het al bij al niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(666,'100 Feet',2008,'430',96,'2010-10-03',8,4,4,8,6,7,'Als je ooit een film nodig hebt waarbij alle clichés van een horror/schrik film op een rijtje hebt, dan is dit zeker iets waar je wat kan mee doen. Ik heb al zodanig veel van dit soort films gezien, dat ik van minuut tien tot het einde alles kon voorspellen. Een volstrekt onnodig misbaksel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(667,'Dossier K.',2009,'70',120,'2010-10-10',8,7,7,7,8,8,'Het recycleren van rollen uit De Zaak Alzheimer lijkt een garantie op succes, maar dat bleek niet het geval te zijn. De film is al bij al niet slecht, maar in vergelijking met zijn voorganger is dit toch een stuk minder. Net omdat ze een deel cast opnieuw gebruiken, waren de verwachtingen van het publiek heel hoog. Deze film heeft deze niet ingelost.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(668,'Where the Wild Things Are',2009,'431',101,'2010-10-15',8,8,8,8,8,8,'Een heel bijzonder verhaal over de fantasiewereld van een jongentje. Het is niet wat je er van verwacht, als je de trailer ziet. Om eens goed te lachen, ben je niet echt aan het goede adres. Het is gewoon een mooi verhaal, een modern sprookje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(669,'Timeline',2003,'277',116,'2010-10-23',4,5,4,7,7,7,'Je hebt zo van die filmgenres die meestal schitterende films afleveren en die slechts heel af en toe eens een miskleun opleveren. Deze film behoort tot zo\'n genre, maar helaas ook tot de miskleuncategorie. Voorspelbaar, niet boeiend of spannend. Dit kon ook in een twintigtal minuten en had waarschijnlijk een veel beter resultaat opgeleverd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(670,'The Lovely Bones',2009,'131',136,'2010-10-30',2,7,7,9,9,9,'Zo\'n film die begint bij het einde en de dagen ervoor beschrijft. Een beproefd recept, en het zorgt hier ook voor succes. Maar de enorme hype die rond deze film ontstond, doet toch wat af aan de verrassing. Je verwacht er gewoon te veel van. Gewoon op je laten afkomen dus. Een pareltje qua beeld en geluid.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(671,'Imagine That',2009,'432',107,'2010-10-31',4,6,4,6,7,6,'Het probleem met films met Eddie Murphy is meestal het feit dat zijn naam volgens de producenten genoeg is om er een succes van te maken. De film zelf is dan eerder aan de magere kant. Deze film is daarop geen uitzondering. Zwakke film, maar nog een geluk dat Eddie Murphy het nog enigzins goed maakt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(672,'Zombieland',2009,'433',88,'2010-11-12',4,8,8,8,7,7,'De hoeveelheid zombiefilms neemt de laatste tijd toe. Dat vraagt gewoon naar een over-the-top parodie voor het genre. Deze film vult die rol perfect in. Met momenten hilarisch, maar nooit platvloers. Fijne prent, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(673,'The Boondock Saints II: All Saints Day',2009,'291',118,'2010-11-17',2,7,7,7,8,7,'Er zijn van die films die onverwachts een gigantisch succes zijn. Helaas springt de industrie er dan op en proberen het nog wat uit te melken door overbodige sequels te maken. De eerste film was een pareltje, dit is een afkooksel ervan. Volstrekt overbodig, maar ook niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(674,'Harry Potter and the Deathly Hallows: Part 1',2010,'252',146,'2010-11-21',5,6,6,8,7,7,'Om de Harry Potter serie nog wat langer te rekken dan de boekenreeks, werd de laatste film uit de reeks gesplitst in tweeën. Het is intussen echt geen kinderfilm meer, want het begint meer van een horrorprent weg te hebben. Alleen zorgt de opsplitsing voor ongelooflijk saaie passages. Het is gewoon te veel gerokken. Men doet ook de moeite niet om een en ander te verklaren tijdens de film. Je blijft dus beter bij de boeken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(675,'The A-Team',2010,'434',117,'2010-12-05',1,8,7,9,8,8,'Met enige argwaan begon ik aan deze film, maar ik werd niet teleurgesteld. Hoewel er nog weinig overschiet van de originele serie, werd ik toch aan het beeld gekluisterd gedurende de volle duurtijd. Een spetterende actiefilm zoals het hoort, maar naar mijn gevoel te weinig respect voor de roots van The A-Team.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(676,'Perfume: The Story of a Murderer',2006,'435',147,'2010-12-05',2,8,8,7,8,7,'Een middeleeuws drama dat het verhaal vertelt over een \"aparte jongeman\" en zijn unieke geurzin. Wat deze film uniek maakt, is de opbouw. Het begint wat gewoontjes, maar eindigt sterk. Dit principe laat altijd een goede indruk na. Een van de positieve verrassingen van dit jaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(677,'Death Race',2008,'261',111,'2010-12-10',1,8,7,9,8,8,'Een actiefilm met zo\'n titel zorgt altijd voor enige argwaan. Het is echter een van de meest onderschatte actiefilms van de laatste jaren. Weinig taboes blijven heel, de actie spettert er af. Geloofwaardig is het nooit, maar het is heel aangename ontspanning.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(678,'Ginger Snaps',2000,'436',108,'2010-12-15',8,6,5,7,7,7,'Een tienerfilm over enkele meisjes in hun puberteit die te maken krijgen met een weerwolf. Origineel of spannend is het niet. Maar het is waarschijnlijk voor pubermeisjes wel eens leuk. Geen aanrader, zeker omdat je de sequal ook moet zien om er een degelijk slot aan te krijgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(679,'District 9',2009,'437',112,'2011-02-04',8,9,8,9,8,9,'Deze film wordt in het algemeen hoog aangeschreven, en aanzien als een positieve reactie. Dus ik heb deze Zuid-Afrikaanse film een kans gegeven. Ik heb het me niet beklaagd. Een leuke sci-fi actiefilm, die eens niet uit Hollywood komt. Absoluut een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(680,'The Emperor\'s New Groove',2000,'438',78,'2011-02-06',2,7,7,6,7,7,'Een komische old-style Disney tekenfilm, is meestal niet iets waar ik snel naar zal beginnen kijken. Toch ben ik bij deze film gesukkeld. En het valt eigenlijk al bij al mee. Het is niets nieuws, maar af en toe wel leuk. Verwacht geen meesterwerk, maar ook geen flop.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(681,'The Men Who Stare at Goats',2009,'439',94,'2011-02-06',8,7,6,7,8,7,'Op de originaliteit van de titel kan je weinig aanmerken. Ook de cast is indrukwekkend. Het verhaal is wel origineel, een soort zwarte komedie over Irak. Al is dat misschien wat kort door de bocht. Toch kan de film de sterke lijn niet aanhouden tot het einde. Leuk, maar te weinig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(682,'Cloudy with a Chance of Meatballs',2009,'440',90,'2011-02-16',8,7,7,7,6,7,'De zoveelste animatiefilm in de stijl van Pixar, maar dan van Sony. Het bleef onder de radar en is eigenlijk niet echt bekend. Het is echter wel een positieve verrassing. Alweer niets nieuws, maar ook niet slecht. Vooral net even iets anders dan de Pixar films.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(683,'Star Wars: Episode III - Revenge of the Sith',2005,'41',140,'2011-02-13',4,8,9,8,8,8,'Omdat ik al van tevoren de inhoud van deze film kende, heb ik het jaren uitgesteld om te kijken. Het is er dan uiteindelijk toch van gekomen omdat ik de films 1 tot 6 in volgorde aan het bekijken was. De drie nieuwe films worden meestal met de grond gelijk gemaakt door de critici. Af en toe ook met reden. Maar deze film is toch wel de interessantste van de drie, omdat er meest links in zitten met de volgende films. De transformatie van Anakin Skywalker is sterk, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(684,'Pandorum',2009,'441',108,'2011-02-20',8,6,6,7,5,6,'Een claustrofobische horror sci-fi schrikfilm, zoals er al vele bestaan. Het is wel degelijk, maar heeft eigenlijk vrij weinig om er iets aantrekkelijks van te maken. Vooral het slot is inspiratieloos. Het is geen slechte poging, maar het is niet origineel en ook niet goed genoeg uitgevoerd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(685,'Inglorious Bastards',2009,'107',153,'2011-02-27',8,8,8,8,9,9,'Tarantino stapt af van de slashers en probeert het eens op een andere manier. Zijn hand is echter duidelijk te zien. Typische kenmerken van een Tarantino film zijn nooit ver weg. De muziek en dialogen zijn hierbij sterk. Als je iets tegen Tarantino films hebt, blijf hier dan van weg. Het is een typische film, maar wel heel beklijvend. Zeker een aanrader voor wie eens iets anders wil.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(686,'Ice Age: Dawn of the Dinosaurs',2009,'120',94,'2011-03-13',8,6,6,7,7,7,'De volgende film in de Ice Age reeks. Het biedt absoluut niets nieuws, maar het blijft een goede animatiefilm. Het loopt over van de clichés en van de makkelijke humor. Maar dat is net wat deze reeks groot heeft gemaakt. Als je van de eerste Ice Age films houdt, dan is dit zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(687,'Legend of the Guardians: The Owls of Ga\'Hoole',2010,'363',97,'2011-03-13',8,8,8,8,8,8,'Het is eens iets anders: een animatiefilm met een iets serieuzere invalshoek. Het blijft toegankelijk voor de jongsten, maar er zit toch wel wat meer in dan de gemiddelde Pixar prent. Zowel qua plot als qua karakters. Dit vind ik een van de betere films in het animatiegenre, omdat het net dat tikkeltje donkerder is dan de concurrenten met hun vrolijke kleurboeken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(688,'The Book Of Eli',2010,'76',118,'2011-04-01',4,8,8,9,8,9,'Als je bij deze film door het Amerikaanse perspectief kan kijken, dan is dit eigenlijk een pareltje. Beeld en geluid verhogen het niveau van een voor de rest weinig inspirerend plot. Het is geen absolute klassieker, maar het was toch een goeie poging.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(689,'Dorian Gray',2009,'442',112,'2011-04-05',4,7,6,8,7,7,'In deze tijd van superhero films en andere sci-fi verhalen, mag Dorian Gray zeker niet vergeten worden. Het is een iets donkerdere variant in het genre, maar daarom niet beter. De hele film blijft wat aan de oppervlakte en laat je wat op je honger zitten. Maar slecht is het nu ook weer niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(690,'Afterwards',2008,'443',107,'2011-04-10',4,6,6,7,7,7,'Terwijl de cast het beste doet verhopen, en het eerste half uur indrukwekkend verloopt, verwatert deze film naarmate het vordert. Het al te voorspelbare slot, zorgt voor een al bij al negatieve beoordeling. Hier was er zeker meer mee te doen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(691,'Bitch Slap',2009,'444',109,'2011-04-15',4,6,6,7,6,6,'Dit is eigenlijk meer een komedie, een parodie meerbepaald. De clichés van de femmes fatales en de daarbij horende domme slechteriken, is het basisbeginsel van deze film. De actiescènes zijn al bij al wel goed gedaan, maar de inhoud is flinterdun en voorspelbaar. Het gaat eigenlijk meer om de absurditeit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(692,'Southland Tales',2006,'293',145,'2011-04-19',4,5,5,8,7,8,'Had ik geweten dat de makers van deze film ook de makers zijn van Donnie Darko, dan had ik deze film zeker links laten liggen. Plotwendingen waarbij enkel de regisseur nog kan volgen, vind ik al te makkelijk. Heel bizar en daardoor best aanlokkelijk, maar enkel voor de cinefiel. Verwacht ook geen veelzeggend verhaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(693,'Resident Evil: Afterlife',2010,'261',97,'2011-04-22',4,5,4,8,7,7,'De zoveelste film in het uitmelkgebeuren genaamd Resident Evil. Alweer ongeveer dezelfde actiefilm, waarbij je eigenlijk weer niets wijzer wordt, wat betreft het onderliggende verhaal. Zo kan je blijven films maken, als je telkens weer bij hetzelfde startpunt eindigt. Enkel voor een no-brain actiefilm, scoort dit aardig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(694,'From Paris with Love',2010,'445',92,'2011-04-24',4,6,6,7,7,7,'Deze film is in niets een uitblinker, maar ook niet aan de negatieve kant. Het is een aardige actiefilm, maar zeker niet origineel. De cast maakt van deze film zeker een aangenaam kijkstuk, want van de plot moet je het niet hebben.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(695,'Iron Man 2',2010,'364',124,'2011-05-22',4,8,7,9,9,8,'De zoveelste film over een superhero, zou je denken. En eigenlijk is dat juist. Alleen heeft deze film net iets mee zelfkritiek. Het is een denderende actiefilm geworden, en dus zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(696,'De helaasheid der dingen',2009,'269',108,'2011-05-24',4,7,8,7,8,7,'Ik heb deze film bekeken omdat iedereen er over bezig was. Dan weet je eigenlijk al bij voorbaat dat je verwachtingen te hoog zijn. Zo ook hier. Het is een degelijke film, maar helaas overhyped. Misschien zal deze film beter zijn als ik het herbekijk over een tiental jaar, of zo.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(697,'Tekken',2010,'446',92,'2011-06-08',4,6,5,8,7,7,'Een verfilming van een game is in slechts een handvol gevallen een succes gebleken. Deze film doet een aardige poging, maar vervalt uiteindelijk toch in alle clichés. Het is een aangename film, vooral voor de fans van de franchise. Maar meer stelt dit niet voor.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(698,'Legion',2009,'447',100,'2011-06-20',4,7,8,7,6,7,'Wat de originaliteit betreft, scheert deze film zeker hoge toppen. De uitwerking is echter nogal B-film kwaliteit. Het is alweer een heel goed idee dat door gebrek aan tijd en/of middelen niet is wat het kon geworden zijn. Zeker leuk, maar tegelijk ook een gemiste kans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(699,'Wolf',1994,'227',125,'2011-06-30',4,8,8,6,7,7,'Deze klassieker is inmiddels verheven tot de cult-status. Door het ietwat verouderde karakter van de film, is dit toch een verademing tussen de clichéfilms door. De cast draagt deze film zowat volledig. Verwacht geen flitsende actie met bijbehorende supereffecten, maar wel een pakkend ouderwetse thriller.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(700,'The Invention of Lying',2009,'448',100,'2011-07-01',4,9,9,7,7,7,'Hoe vaak is een schitterend, eenvoudig idee voor een plot niet vernietigd door een slechte uitwerking? Deze film hoort in ieder geval niet in het rijtje thuis. Een ijzersterk begin verdoezelt het verwateren van het verhaal wel wat. Het is echter een van de ontdekkingen van het jaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(701,'Splice',2009,'247',104,'2011-07-04',4,8,8,8,7,8,'Het is meestal een speciaal publiek die kan genieten van een sci-fi/horror verhaal. In een poging om het genre wat meer mainstream te maken, ontstond Splice. En met succes. Deze film straalt een speciale sfeer uit, en komt op de een of andere manier erg realistisch over. Weinig ontspannend, maar wel een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(702,'The Karate Kid',2010,'449',140,'2011-07-10',4,7,7,8,8,7,'Een remake van een 26 jaar oude klassieker in een hedendaags jasje. En niet zonder succes. Bij dit soort films is er altijd enige argwaan, maar dit is zonder meer goed gedaan. Voor het realisme moet je het niet doen, maar wat de film ambieert, wordt ook waargemaakt. Puur plagiaat, maar het komt er mee weg.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(703,'Get Him to the Greek',2010,'450',109,'2011-08-07',4,7,7,8,8,6,'Een komedie volledig in nineties stijl. Het is zeker niet slecht, maar soms wat over-the-top. Al bij al een ontspannende en degelijke komedie, zeker bedoeld voor een heel breed publiek.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(704,'Cop Out',2010,'387',107,'2011-08-07',8,7,7,8,7,7,'Het is altijd een beetje je hart vasthouden als je een Bruce Willis actiekomedie op je scherm krijgt. Meestal loopt dat soort eighties revivals slecht af. Maar deze film is al bij al niet slecht. Tenminste, als je niet verwacht dat er een constant hoog niveau gehaald wordt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(706,'Talladega Nights: The Ballad of Ricky Bobby',2006,'423',108,'2011-09-11',2,7,8,7,7,7,'Een, in de States, inmiddels legendarische parodie op de NASCAR sport. Je weet ook wat je moet verwachten van een komedie met Will Ferrell, natuurlijk. Af en toe hilarisch, maar het kan de lijn niet helemaal tot het einde doortrekken. Het typische verwateren van zo\'n films is hier ook aanwezig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(707,'Senna',2010,'451',168,'2011-09-27',2,9,9,7,7,9,'Hoewel het altijd lastig is om naar een documentaire te kijken waarvan je het slot al kent, is dit bij deze prent helemaal niet het geval. Een prachtig verhaal over het leven van Ayrton Senna, zonder verteller, enkel gemaakt met archiefbeelden en wat interviews. Deze docu grijpt je bij de keel. Een van de films van het jaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(708,'The Twilight Saga: Breaking Dawn - Part 1',2011,'452',117,'2011-11-18',5,6,5,7,8,7,'Aangezien de eerste films een succes bleken, hebben ze de laatste film maar in tweeën verdeeld. Volstrekt nutteloos langerekt, maar al bij al ook weer zo slecht niet. Het is wat het is, een echte teen blockbuster, maar niet meer dan dat. En het zal ook nooit iets anders worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(709,'Red',2010,'266',111,'2011-11-19',4,5,6,8,7,7,'Een ongelooflijk sterke cast is het uitgangbord van deze film. Alle eighties en nineties actiesterren nog eens bij mekaar. Alleen is het verhaal voorspelbaar en flinterdun. Enkel ter ontspanning, maar geen onverdeeld succes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(710,'Wall Street: Money Never Sleeps',2010,'34',133,'2011-11-19',4,6,6,7,7,7,'Op het einde van de rage van het herwerken van seventies films, komt deze ondergewaardeerde prent nog eens aan bod. Het is al bij al een degelijke film, maar speciaal is het niet. Het is een poging om iets speciaals neer te zetten, maar faalt hierin. Niet slecht, maar het blijft me zeker niet bij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(711,'Season of the Witch',2011,'117',95,'2011-11-27',4,7,7,8,7,8,'Voor de liefhebbers van ridderverhalen is dit zeker een aanlokkelijke titel. Het maakt zijn beloftes waar, maar opnieuw is er niet veel nieuws aan. Het is leuk gedaan, maar niet bepaald memorabel. De cast maakt veel goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(712,'Brokedown Palace',1999,'453',100,'2011-12-04',4,5,6,6,7,7,'Deze film lijkt wat op De Hel van Tanger, maar dan doorspekt met Amerikaanse clichés. Het is niet echt een meeslepend verhaal, je hebt het allemaal al eens eerder gezien. Maar op een of andere manier kan je toch niet stoppen met kijken. Achteraf gezien, over de hele lijn, een teleurstelling.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(713,'A Christmas Carol',2009,'16',96,'2012-01-08',4,7,7,8,8,7,'Het overbekende kerstverhaal, dat ik nota bene niet kende, is herwerkt in een animatiefilm. Laat dat je niet misleiden, want deze film is niet geschikt voor kinderen. Het is een beetje van alles wat. Te kinderachtig en feel-good voor volwassenen en te griezelig voor kinderen. Niet slecht voor een kerstfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(714,'Platoon of Death',2011,'454',100,'2012-01-16',4,4,4,4,6,7,'Een oorlogsfilm over een dorp in Vietnam. Laat me duidelijk zijn: Het is een B-film. Dat zie je aan alles. Het verhaal is pakkend, maar er gebeurt al bij al weinig. En als je bij het einde komt, is het ronduit teleurstellend. Zeker niet ontspannend, en ook geen hoogvlieger.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(715,'Drive Angry',2011,'46',104,'2012-01-17',4,7,6,8,7,8,'Een lekker ouderwetse, over-the-top actiefilm. Deze film pretendeert niet te zijn wat het niet is, namelijk een pakkend verhaal. Het is niets meer of minder dan ontspannende actie, die er met momenten echt wel over is. Zeker een aanrader als ontspanning, maar verwacht niet te veel inhoud.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(716,'Rundskop',2011,'455',124,'2012-01-25',4,8,8,7,8,7,'Een Belgische blockbuster, genomineerd voor een Oscar en internationaal geprezen. Dat schept hoge verwachtingen. En toegegeven, het is qua Belgische normen een ijzersterke film. Maar echt voor de filmliefhebber, want ontspannend is het niet. Het heeft ook niet de structuur van een typische Hollywoodprent. Zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(717,'In Bruges',2008,'456',107,'2012-03-02',4,8,8,8,7,7,'Een Amerikaanse film die in Brugge werd gefilmd, zorgde voor een vrij grote hype in België. Tot men inzag dat dit feitelijk niet zo\'n positieve rol speelde in de film. Als je daar echter doorheen kijkt, blijft er een sterke film over, zonder clichés, en een meeslepend verhaal. Zeker een voltreffer, wat mij betreft.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(718,'The Passion of the Christ',2004,'457',127,'2012-04-01',8,6,7,8,6,6,'Het is altijd gevaarlijk om het passieverhaal te verfilmen. Deze film is een keiharde versie. Ontspannend of aangenaam is deze film zeker niet. Het is een vrij grof verhaal, zonder veel nuance. Bekijk deze film, omdat het een klassieker is. Andere redenen kan ik niet vinden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(719,'Cars',2006,'458',117,'2012-04-04',1,8,8,7,7,7,'Wat kan je nog verwachten van de zoveelste Pixar animatiefilm? Je weet ongeveer wel wat je zal krijgen. Maar toch is deze film zeker een van de betere. Het is, zoals zovele films, een geslaagde mix van humor voor kinderen en voor volwassenen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(720,'Cars 2',2011,'458',106,'2012-04-20',1,6,6,7,6,6,'Als iets aanslaat, moet je het uitmelken. Dat is althans duidelijk de visie van Pixar. En zo geschiedde. Het is geen slechte film, maar komt niet meer in de buurt van de eerste. Maar laten we deze film niet met de grond gelijk maken, enkel omdat zijn voorganger veel beter was.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(721,'God Bless America',2011,'459',104,'2012-04-28',NULL,8,7,7,7,8,'De titel verraadt het niet, maar deze film is een aanklacht tegen bepaalde aspecten van de Amerikaanse samenleving. Het is verrassend, maar soms heb ik de indruk dat deze film zichzelf te serieus neemt. Denk er niet te veel over na, en laat je meeslepen in de ergernissen van de personages.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(722,'Mortal Kombat 2: Annihilation',1997,'460',95,'2012-05-05',4,2,2,2,6,6,'Waar de eerste Mortal Kombat film al wat B-filmachtig aanvoelde, is het hek hier helemaal van de dam. Verhaallijnen die niet kloppen, effecten die er niet uit zien,... Je zou verwachten dat een sequel meestal wat meer budget krijgt. Dit is pure tijdverspilling. Het begint zelfs lachwekkend te worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(723,'Green Lantern',2011,'29',114,'2012-05-17',8,8,8,9,7,8,'DC is altijd al wat donkerder geweest dan Marvel, en dat komt er in deze film goed uit. Het is natuurlijk de zoveelste comicverfilming, maar het heeft toch net dat ietsje meer. Vooral visueel dan, en qua sfeer. Het lijkt mij ook niet echt geschikt voor kinderen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(724,'Captain America: The First Avenger',2011,'461',124,'2012-05-19',1,6,6,7,6,7,'In een periode waarin ik veel comic verfilmingen bekijk, valt het des te meer op als er een film helemaal niets uitzonderlijks heeft. Dat is bij deze het geval. Het is al bij al geen slechte film, maar het is er zeker geen die zal blijven hangen. Allemaal te gewoontjes, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(725,'Thor',2011,'462',115,'2012-06-01',1,8,7,9,8,9,'Eindelijk eens een Marvel personage met wat uitstraling. De sfeer vond ik verrassend donker, en bijgevolg ook interessant. Voor het eerst sinds lang, heb ik me niet geërgerd aan de comic clichés. Er zijn er wel, maar het is net niet storend. Beeld en geluid zijn indrukwekkend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(726,'Chronicle',2012,'463',89,'2012-06-03',1,9,9,8,7,8,'Deze film wordt overal omschreven als B-film. Ik zie het er echter niet aan, integendeel. Misschien qua budget en special effects wel. Het is volgens mij zo\'n pareltje, dat je maar eens om het jaar tegenkomt. Een onverwachtse meevaller. En dan nog eens aangrijpend ook.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(727,'Prometheus',2012,'54',124,'2012-06-19',5,7,7,8,6,8,'De rage van de laatste jaren lijkt wel het rebooten van oude successreeksen. En dan nog meestal met een prequel, omdat het originele verhaal afgelopen was. Zo ook deze film. Het is een leuke blockbuster, maar niet meer dan dat. Leuk voor de fans van vroeger, maar als standalone film is dit maar gewoontjes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(729,'X-Men: First Class',2011,'354',132,'2012-07-10',1,8,7,8,7,7,'Opnieuw een film in de prequel rage van de laatste maanden. Maar deze is echter wel goed uitgewerkt. Het feit dat de verhalen, zowel van voor als van na de films, uitgebreid uitgeschreven zijn, helpt natuurlijk enorm. Een van de betere comic book verfilmingen, en voor de verandering een prequel die kan wedijveren met de originele films.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(730,'Rio',2011,'120',96,'2012-06-13',4,7,6,8,7,6,'De zoveelste animatiefilm met schattige beestjes in de hoofdrol. Leuk gedaan, soms wel grappig, kortom een eenvoudige ontspannende film. Niet speciaal goed of slecht. De vraag over het nut van deze film wordt niet gesteld. Het is gewoon OK, er zijn er slechtere in het genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(731,'Braveheart',1995,'457',177,'2012-08-05',4,8,9,7,7,7,'Dit is een van die roemruchte marathonblockbusters van Mel Gibson. Het is zeker boeiend van begin tot einde, pakkend af en toe. Het is een ribbenplakker, en is als ontspanning misschien niet zo aangewezen. Een historisch accuraat verhaal romantiseren, is meestal een schot in de roos. Zo ook bij deze film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(732,'The Dark Knight Rises',2012,'121',164,'2012-07-29',5,9,8,9,9,9,'De laatste film in de nieuwe Batman trilogie, kon in feite niets anders doen dan teleurstellen. Na zo\'n uitzonderlijk succes als \"The Dark Knight\". In feite is dit ook wel zo, maar als je de vorige film niet meerekent, blijft dit wel een ijzersterke prent. Een van de films van het jaar zelfs. Voor een keer een trilogie waarvan het spijtig is dat het afgelopen is...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(733,'Arthur',2011,'464',110,'2012-07-30',4,7,5,6,7,6,'Het lijkt redelijk goedkoop om alweer een romantische komedie te maken over een onbenul die zwemt in het geld en de grote boze wereld moet trotseren. Feitelijk is het zelfs een remake van een film uit 1981. Het is allemaal wel leuk en aardig, maar origineel is het allerminst. Een no-nonsense romantische komedie, zonder meer. Maar wel een keertje aangenaam, vooral door de vrij onbekende cast, die het uitzonderlijk goed doet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(734,'Super 8',2011,'425',112,'2012-08-01',4,7,7,9,7,8,'Een mysterieuze start van dit sci-fi verhaal doet het beste verhopen. De blik vanaf de hoofdrolspelers doet je zelfs de clichés grotendeels vergeten. Maar dan komt de ontknoping, wat altijd een kritiek punt is bij dit genre van films. Deze film slaat de bal niet volledig mis, maar het blijft achteraf bekeken een teleurstelling. Zeker een aanrader, maar er zat veel meer potentieel in.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(735,'John Carter',2012,'181',132,'2012-08-03',1,8,7,9,8,8,'Deze film is wat onder de radar gebleven, ondanks het enorme budget. Onterecht, zo blijkt, want het is wel origineel en goed uitgewerkt. Alleen de dialogen lijken wel wat simplistisch. Dit was duidelijk materiaal voor een 3u durende film. Door het proppen in 132 minuten, is het op cruciale momenten fout gegaan. Vergeet de dialogen en het is een pareltje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(736,'The Divide',2011,'343',112,'2012-08-05',1,6,7,8,6,7,'Deze film trok me aan door zijn origineel uitgangspunt. Het is een absolute ribbenplakker, geen ontspannend verhaaltje. In zijn genre is het ongetwijfeld een pareltje, maar je moet weten waar je aan begint. De goede cast, beeld en geluid dragen hieraan bij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(737,'Indie Game: The Movie',2012,'465',94,'2012-08-05',8,8,8,7,6,6,'Dit is een documentaire over indie game developers. Heel interessant voor mij dus, maar blijkbaar niet alleen voor gamefanaten. Ook mensen die minder voeling met de industrie hebben, kunnen het originele oogpunt zeker appreciëren. De verscheidenheid van karakters in de personages, draagt bij tot de boeiendheid van de film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(738,'Melancholia',2011,'309',136,'2012-08-15',4,7,8,8,8,7,'Bij een film van Lars von Trier weet je feitelijk nooit waar je aan begint. Het thema en de cast overhaalden me om dit te kijken. Het is ook geen lichtverteerbaar verhaaltje. Het komt ook wat traag op gang. Maar dat draagt uiteindelijk allemaal bij tot een ijzersterk slot.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(739,'The Hunger Games',2012,'466',142,'2012-08-21',8,7,7,8,7,8,'Origineel is het scenario niet. Dit hebben we eigenlijk allemaal al eens gezien. Maar het is wel vrij goed uitgewerkt. Het sci-fi futuristisch kader is wel nieuw. En dat is een van de kenmerken die deze film de moeite waard maakt. Verwacht geen uitzonderlijk pareltje, en je bent vertrokken voor een ontspannende avonturenfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(740,'True Romance',1993,'173',120,'2012-08-29',8,7,7,7,9,7,'In de jaren negentig leek het wel een rage. Een eighties misdaadfilm, maar met een twist. Een indrukwekkende cast luidde het begin van deze rage in. En eerlijk, het is een goede uitvoering. Zeker voor die tijd was dit vrij nieuw. Een klassieker, zeker genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(741,'The Avengers',2012,'467',143,'2012-09-11',8,8,7,9,8,8,'Een groots opgezette blockbuster waarin alle Marvell superheroes samen in een film komen. Het is een riskant gegeven, maar het zit wel redelijk OK in elkaar. De actiescènes zetten een nieuwe standaard, maar je weet wel waar je aan begint. Een psychologische thriller hoef je natuurlijk niet te verwachten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(742,'Dark Shadows',2012,'50',113,'2012-09-12',8,6,6,8,7,8,'Een film van Tim Burton is eigenlijk al 15 jaar hetzelfde. Het verhaal wordt gedragen door een schitterende visuele stijl. Enkel als dit verhaal een sterke fundering vormt, leidt dit tot echte pareltjes. In deze film is dat echter niet het geval. Het is allemaal wel leuk en aardig, maar niet meer. Sterker nog, het tweede deel van de film verwatert echt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(743,'Men in Black 3',2012,'276',106,'2012-09-14',8,8,7,8,7,8,'Het derde deel van de MIB reeks leek in eerste instantie volstrekt overbodig. Dat is het toch meestal, als je jaren nadien nog een vervolg aan een afgesloten reeks breidt. Maar deze film valt best mee. Ik vond het in vele opzichten zelfs beter dan de originele films. Bij momenten grappig, soms spannend. Alles wat een ontspannende blockbuster hoort te hebben.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(744,'Immortals',2011,'58',110,'2012-09-16',8,7,7,8,6,7,'De makers van 300 doen hun kunstje nog eens over met een verhaal over griekse goden en volkeren. Het is in heel wat een kopie van wat 300 zo origineel maakte. Met andere woorden, dit was een onnodige film. Het was wel eens leuk, omdat 300 al een tijd geleden was. Maar meer niet...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(745,'Starship Troopers',1997,'21',129,'2012-09-20',8,7,8,6,6,6,'Een cult-hit uit de jaren negentig. De special effects zijn wat limiet, zeker omdat het al eind jaren negentig was. Voor 1997 mag je wel wat meer verwachten. En dat drukt echt de filmervaring. De film zelf is wel vrij OK. Clichés worden afgewisseld met originele plotwendingen. Een must-see voor sci-fi liefhebbers. Twijfelachtig voor anderen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(746,'The Help',2011,'468',146,'2012-09-23',4,8,8,7,7,7,'Een drama over de onderdrukking van de zwarten halfweg vorige eeuw lijkt niet echt een film die ik zou bekijken. Maar af en toe zit er toch een pareltje tussen. Toevallig zag ik dit en het is absoluut een aanrader. Een pakkend verhaal. Het is geen film die je keer op keer terug wilt zien, maar dat is wat eigen aan het genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(747,'Skyfall',2012,'135',143,'2012-11-02',5,8,8,9,9,8,'De derde film in de \"nieuwe generatie\" Bondfilms. Het is in ieder geval geen teleurstelling, want het heeft alle ingrediënten wat een Bondfilm hoort te hebben. Men gaat verder op de ingeslagen weg, door het persoonlijker maken van het verhaal. De puristen gaan het hier moeilijk mee hebben, maar het blijft een ijzersterke actiethriller.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(748,'Dr. No',1962,'469',110,'2012-10-20',8,7,6,6,8,6,'In een poging om gemiste klassiekers alsnog te bekijken, moest Dr. No zeker in de lijst voorkomen. De allereerste Bondfilm legt de fundamenten voor wat later een legendarisch format zou worden. Het valt al bij al best mee voor een film uit de vroege jaren zestig. Voor de cinefielen is dit een mijlpaal, voor de anderen een leuke, maar hopeloos verouderde actiefilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(750,'The Twilight Saga: Breaking Dawn - Part 2',2012,'452',115,'2012-11-16',5,7,7,8,6,7,'Het tweede deel van een film die er eigenlijk maar één mocht zijn. De uitgerokken scènes uit het eerste deel komen hier niet meer voor. Er is actie genoeg en het blijft vrij interessant. Het is zeker de beste film in de hele \'saga\'. Spijtig van de drie films tussen de eerste en de laatste...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(751,'From Russia with Love',1963,'469',115,'2012-11-28',8,7,7,6,7,6,'In het kader van het bekijken van alle Bondfilms, is dit de tweede in het rijtje. Een aanzienlijk is duidelijk te merken. De filmindustrie maakte in die tijd reuzesprongen. Deze film is echt het begin van de Bond historie. Een aanrader voor de cinefiel, maar als actiefilm natuurlijk hopeloos verouderd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(752,'Ghosts of Girlfriends Past',2009,'470',100,'2012-12-02',4,7,7,7,6,7,'Het komt zelden voor, maar soms komt er eens een interessante romatische komedie langs. En toeval wil dat dit er zo eentje is. Als je door de Amerikaanse clichémoraal kan kijken, dan is dit zeker te doen. Als ontspanning dan, niet voor de fantastische filmervaring...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(753,'Ted',2012,'471',112,'2012-12-23',8,6,7,6,7,7,'Een eerder donkere komedie, met een origineel onderwerp. Maar het is als zoveel films in dit genre: Het kan een sterke start niet volhouden tot het einde. Hierdoor kan ik dit niet als superfilm beoordelen. Echt memorabel is het niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(754,'ParaNorman',2012,'472',92,'2013-01-04',8,8,8,9,8,9,'Een heel sterk verhaal in een stop-motion animatiefilm, is meestal goed nieuws. Zo ook hier. Dit is zeker de animatiefilm van het jaar, wat mij betreft. De sfeer en het thema zijn boeiend. De uitwerking mag er ook zijn. Misschien minder geschikt voor de kids.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(755,'Looper',2012,'473',119,'2013-01-05',8,9,9,8,8,8,'Onbekende pareltjes zijn er weinig te vinden in het actie genre. Door het sci-fi element kreeg deze film niet de erkenning die het verdient. Het zit echt goed in elkaar, met mysterie en verklaring op de juiste momenten. Het pakkende verhaal draagt de actie en spanning naar een hoger niveau.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(757,'Starship Troopers 2: Hero of the Federation',2004,'474',92,'2013-01-21',8,3,3,4,5,5,'Omdat de eerste film een echte cultstatus verwierf eind de jaren negentig, kwam er een vervolg. Het is echter een volledig andere film geworden. Het is veel kleinschaliger en de focus ligt niet meer op wat de eerste film interessant maakte. Een rasechte flop dus. Een sequal zoals er geen zouden mogen bestaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(758,'I Now Pronounce You Chuck & Larry',2007,'26',115,'2013-02-12',4,7,7,7,7,6,'Een film met komediekanonnen Adam Sandler en Kevin James, krijgt heel wat aandacht. Er is altijd de vrees dat er te veel aandacht aan de cast is gegeven, en te weinig aan de inhoud van de film. Maar in dit geval is het wel degelijk. De film kan onderhouden en ontspannen. Maar verwacht geen pareltje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(759,'The Social Network',2010,'79',120,'2013-02-14',8,7,7,6,7,7,'Wat eigenlijk een documentaire moest zijn over het ontstaan van Facebook, is een soort docu-film geworden met een vrij eenzijdige kijk op de ontstaanshistorie. Het is heel interessant, zeker voor mij als ITer, maar moet zeker met een korrel zout genomen worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(760,'Abraham Lincoln: Vampire Hunter',2012,'377',105,'2013-03-03',8,6,6,8,7,7,'Met zo\'n titel verwacht je echt een heel foute actiefilm. En het maakt zeker die belofte waar. Fout in de goede zin van het woord. Het is eigenlijk een sterke actiefilm met heel erg foute personages. Leuk als ontspanning, en dat was zeker ook de bedoeling van de makers. Maar ook niet meer dan dat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(761,'Wreck-It Ralph',2012,'475',108,'2013-04-02',8,7,6,7,7,7,'Vooral het thema van de film, en de verwijzingen naar oude videogames spreken me aan. Alleen is de film zelf niet erg opvallend. Het is wel leuk, maar daarmee is alles gezegd. Helemaal niet vernieuwend, maar zeker ontspannend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(762,'Being John Malkovich',1999,'431',112,'2013-04-21',4,6,7,6,6,7,'Een komedie kan je deze bizarre trip moeilijk noemen, maar bij gebrek aan een beter genre, koos ik dan toch maar dit. Spike Jonze heeft al eerder dit soort bizarre en kunstige trucs uitgehaald, en deze hoort zeker thuis in die reeks. Vernieuwend voor de cinefielen, veel te bizar voor de anderen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(763,'Hugo',2011,'3',126,'2013-05-10',8,7,7,7,7,7,'Deze film wordt internationaal heel hoog aangeschreven. En het is ook wel duidelijk waarom. Het is vooral technisch erg goed. Alleen ontbreekt dat ene iets, wat de ervaring echt goed maakt. Wat rest is een film die alles perfect volgens het boekje doet, maar eigenlijk niet boeit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(764,'Total Recall',2012,'323',118,'2013-05-11',8,8,7,9,7,7,'Remakes van oude klassiekers zijn niet altijd een onverdeeld succes. Maar deze sci-fi actiefilm is dat zeker wel. Het is een film die past in het rijtje moderne eighties actiefilms. Af en toe over-the-top, maar door de SFX echter superspectaculair. Zelfs de plot kan boeien, en dat is in dit genre niet vanzelfsprekend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(765,'The Dictator',2012,'476',83,'2013-05-19',4,7,6,7,8,7,'Het truucje van Sasha Baron Cohen wordt stilaan wat verouderd. Na Borat was dat eigenlijk al het geval. Maar dat neemt niet weg dat dit een aangename komedie is, met de te verwachten hilariteit. Zeker niet de beste film in de reeks, maar toch een ontspannende lachsessie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(766,'The Watch',2012,'477',102,'2013-05-21',2,3,2,6,6,6,'Een komedie met zo\'n kast, kan enkel maar goed zijn, zou je denken. Maar niets is minder waar. Deze film kan je, naar mijn mening, moeilijk een komedie noemen. De trage en aangekondigde grappen, zorgen er voor dat je zit af te tellen, tot de ergernis eindelijk voorbij is. Het feit dat we een gecensureerde vliegtuigversie hebben gezien, zal ook niet geholpen hebben.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(767,'Hotel Transylvania',2012,'478',91,'2013-06-15',4,8,8,8,7,7,'Deze animatiefilm is redelijk onder de radar gebleven. Althans voor mij. Het was dan ook een aangename verrassing. Een grappige film, met een aardig verhaal. Meer niet, maar zeker ook niet minder. Vooral de animaties dragen bij tot de ervaring. Een onverwacht succes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(768,'Silver Linings Playbook',2012,'479',122,'2013-06-25',4,5,5,6,7,6,'Als ik al naar een chick flick kijk, dan moet het een zijn die al heel wat goede (mannelijke) commentaren heeft gekregen. Dit is er zo een van. Alleen bewijst het niet meer te zijn dan een simpele chick flick. De cast van up-and-coming namen doet het beste verhopen, waarop een teleurstelling volgt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(769,'Oz the Great and Powerful',2013,'15',130,'2013-06-26',8,7,6,9,8,8,'Een groots opgezette avonturenfilm met deze cast en Raimi als regisseur, schept grote verwachtingen. En in zekere zin stelt deze film ook niet teleur. Er zijn zeker momenten die bij blijven. Maar de algemene indruk is toch eerder teleurstellend. Het is een modern sprookje, maar niets speciaals.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(770,'Despicable Me',2010,'480',95,'2013-07-01',8,8,8,8,8,8,'De laatste tijd heb ik, met wisselend succes, heel wat animatiefilms bekeken. Het is dan ook verrassend dat deze er zo ver kan bovenuit steken. Deze film doet weinig nieuws, maar doet wel alles heel erg goed. Een voltreffer die, volgens mij, te weinig aandacht gekregen heeft.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(771,'Die Hard',1988,'73',131,'2013-07-02',8,8,8,5,6,6,'Deze film heeft het eighties-actie genre mee gedefinieerd. Het is een ware klassieker. En het is ook een van de betere in het genre. Waar de franchise later helemaal over-the-top gaat, blijft deze film trouw aan een zekere vorm van realisme. Een must-see.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(772,'Die Hard 2',1990,'249',124,'2013-07-02',8,7,7,7,7,7,'Deze sequal doet waarvoor het gemaakt is: Spectaculaire actie, althans voor die tijd. Het was in die zin zijn tijd ver vooruit. Alleen breekt het met wat de originele film, in mijn ogen, zo goed maakte. Namelijk het claustrofobische van de ene locatie. Dat is nu veel minder het geval. Een goede sequal, maar minder pakkend dan het origineel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(774,'Die Hard 4.0: Live Free or Die Hard',2007,'323',128,'2013-09-17',8,6,5,6,7,7,'Een reboot van een oude legendarische filmreeks, is een gevaarlijke onderneming. Zelfs voor een topregisseur als Len Wiseman. Dat wordt bewezen in deze film. Het is een \"dertien-in-een-dozijn\" actiefilm geworden, zonder enige vorm van vernieuwing. Deze film houdt halstarrig vast aan oude principes, en voelt dan ook vrij verouderd aan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(775,'A Good Day to Die Hard',2013,'481',98,'2013-07-03',8,5,5,8,7,6,'De (voorlopig) laatste Die Hard film uit de reeks, begint nu echt op uitmelken van de franchise te lijken. Het is een aardige spectaculaire actiefilm, maar er zijn zeker betere te vinden. Er wordt nog wat geteerd op de Die Hard franchise, maar dat is ten onrechte. Er zijn, buiten Bruce Willis, geen raakvlakken met de originele films. Sla deze maar over.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(776,'Django Unchained',2012,'107',165,'2013-07-05',8,9,8,9,9,8,'Op een of andere manier zijn de films van Tarantino altijd uitzonderlijk. Het is echter wel een typische Tarantino film, met ijzersterke dialogen, sfeervolle muziek en constante spanning. Het is een lange, maar zeker memorabele film. Je hoeft zelfs niet van westerns te houden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(777,'Seven Psychopaths',2012,'456',110,'2013-07-08',8,7,7,7,7,7,'Een bizarre misdaadfilm, vol met komische knipogen naar het eigen genre. Ik kan hier feitelijk wenig over zeggen, zonder spoilers. Neem gewoon aan dat het een absurde trip door de levens van enkele nog absurdere karakters is. Leuk, maar je moet weten waar je aan begint.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(778,'Warm Bodies',2013,'482',98,'2013-08-11',8,5,5,6,6,7,'Een originele romantische films, in deze tijd waar zombiefilms op de terugweg lijken. Het is soms grappig, soms vertederend, wat een goede romantische film hoort te zijn. Alleen is het zó origineel, dat de schrijver vast leek te zitten in de eigen plot. Het verwatert dan ook snel in een veel te simplistisch en volstrekt onrealistisch verhaal (voor zover je dat met dit thema kan zeggen). Een frustrerend gemiste kans. Maar wel een extra punt voor originaliteit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(779,'Elysium',2013,'437',109,'2013-08-16',5,8,7,9,8,8,'Het lijkt de remake van District 9 te zijn, maar dan met een groot budget, en in IMAX op groot scherm. Het lijkt de droom van elke sci-fi fanaat. En het is ook wel goed, maar minder diepgaand en minder pakkend dan District 9. Je ziet zoveel raakvlakken, en je kan niet anders dan de twee vergelijken. Dan komt er echter een duidelijke winnaar uit, en het is helaas niet deze film. Dit is gewoon té mainstream en te cliché.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(780,'Inside Job',2010,'483',105,'2013-09-08',4,8,9,7,6,7,'Deze docu gaat over de bankencrisis. Het werpt een licht over de voorgeschiedenis, de crisis zelf, en hoe het verder moet. Zoals het hoort, dus. Het is superinteressant, vooral voor wie niet vertrouwd is met de materie. Dat is misschien ook een kritiekpunt: Het is misschien iets té toegankelijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(781,'Spring Breakers',2012,'484',94,'2013-09-10',4,6,6,8,8,8,'Deze film lijkt wat goedkoop mee te liften met de Spring break rage. Maar als je dat buiten beschouwing laat, dan blijft er best een goede misdaadfilm over. Het lijkt eerst wat simplistisch te zijn, maar dit verbetert naar het einde toe. Het is een eigenaardige film, waarbij beeld en geluid een sterk geheel vormen. Wel een bizarre plot.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(782,'The House I Live In',2012,'485',108,'2013-09-16',8,7,8,7,7,7,'Een documentaire over de Amerikaanse \"War on Drugs\", en de gevolgen er van. Het is een diepere kijk in de factoren die spelen bij het bestrijden van drugs in de USA. Een punt van kritiek is het feit dat het enkel tegenstanders van dit gebeuren aan het woord laat, en daaruit waarschijnlijk wat ongenuanceerd is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(783,'The Queen of Versailles',2012,'486',100,'2013-06-17',4,6,6,7,6,7,'Een documentaire die initieel zou gaan over het leven van een steenrijke Amerikaanse vastgoedmagnaat. Door het instorten van de vastgoedmarkt in de USA, blijkt dit echter een kijk te geven op de val van de familie, en de perikelen daarrond. Only in America...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(784,'Oldeuboi',2003,'487',120,'2013-09-21',8,9,9,9,9,7,'Een Koreaanse film kijken is niet vanzelfsprekend. Deze blijft echter absoluut aan de ribben plakken. Niet voor een ontspannend avondje, maar de echte filmliefhebber zal deze film enorm kunnen appreciëren. Ik kijk uit naar de Amerikaanse remake, maar toch ook wat ongerust.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(785,'Just Like Heaven',2005,'470',95,'2013-09-24',4,6,7,6,6,6,'Sommige romantische films hebben een origineel uitgangspunt, waar ze in het beste geval ook iets goeds van maken. Zo ook deze film. Het is goed gedaan, zonder meer. Wat sommige van deze films dan wel hebben, is dat het einde zeemzoet moet zijn, en bijgevolg ook volledig niet passend bij de rest van de film. En dat is hier helaas ook het geval...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(786,'The League of Extraordinary Gentlemen',2003,'146',110,'2013-09-26',4,3,4,4,6,7,'Toen de special effects echt mogelijkheden begonnen te creëren, in de vroege jaren 2000, begonnen de fantasy films ook te floreren. Maar sommige namen gewoon te veel hooi op hun vork, zo ook deze. Vol van de clichés, totaal niet aangrijpend, en slechte doorzichtige special effects. Een afrader van formaat!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(787,'World War Z',2013,'237',116,'2013-09-29',1,7,7,7,6,7,'Een blockbuster van formaat uit 2013. En alles wijst er op dat dit een klassieker zou kunnen worden uit het zombiegenre. Alleen is deze film totaal niet blijven hangen. Het was niet slecht, maar na enkele maanden kon ik hem nog met moeite herinneren. Niet slecht, maar een gemiste kans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(788,'John Dies at the End',2012,'488',99,'2013-10-13',8,7,6,7,6,7,'Een absurde horrorkomedie is niet voor iedereen, dus ook deze film niet. Maar als je open staat voor wat onzin, die af en toe hilarisch wordt, dan kan ik deze film zeker aanraden. De plot twists zijn gewoon bizar, maar dat maakt het ook wel interessant.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(789,'Opération Lune',2002,'489',52,'2013-07-22',4,8,8,6,6,6,'Dit is een documentaire over de maanlanding. Een interview met alle betrokken individuen van die tijd. Ik kan niet zeggen wat er dit zo uniek maakt, zonder al te veel te spoilen. Maar als je van een goede documentaire houdt, bekijk dit dan zeker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(790,'The Boat That Rocked',2009,'490',135,'2013-10-18',4,8,8,7,9,8,'Een Britse komedie over de piraten radiostations in de jaren 60, met een indrukwekkende cast. Het is dan ook schitterend uitgewerkt. Het feit dat dit geen hollywoodcliché bom is, draagt alleen maar bij tot de hoge score.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(791,'The Expendables',2010,'491',103,'2013-10-20',1,8,7,8,7,8,'De revival van de eighties action movies is al een tijdje aan de gang. Dit kwam in 2010 tot een hoogtepunt met deze film. De cast bestaat uit alle vroegere actiehelden, in een totaal over-the-top actiefilm. Het is vrij fout, maar het is absoluut genieten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(792,'Larry Crowne',2011,'492',98,'2013-11-01',4,7,8,6,7,6,'Dit is een film waarvan het plot mij niet echt aantrekt. Het is een film waar ik per ongeluk aan begonnen ben. En ik moet zeggen dat het wel meevalt, voor een romantische komedie. De uitwerking is minder clichématig en de cast is heel sterk. Al bij al zeker niet slecht. Maar het blijft een Amerikaanse romantische komedie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(793,'Man of Steel',2013,'363',143,'2013-11-17',1,8,7,9,8,9,'Het is altijd bang afwachten als er een remake gemaakt wordt van een klassieke superhero movie. Deze film hoort gelukkig bij de reeks die goed zijn, door het feit dat ze het over een totaal andere boeg gooien dan het origineel. Het is verrassend, niet wat je er van verwacht. En ook visueel verbluffend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(794,'White House Down',2013,'317',131,'2013-11-21',1,5,4,7,6,7,'Er was in 2013 een kortstondige rage van White House rampenfilms. Je kan je afvragen hoe dit gekomen is, maar daar gaat het even niet om. Feit is dat je wel al deze films gaat vergelijken. Terwijl dit een vrij degelijke actiefilm is, is dit zeker de slechtste uit de reeks. Totaal ongeloofwaardig, vol van de clichés en niet meeslepend. Er zijn betere films in het genre, zelfs met een gelijkaardig plot.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(795,'The World\'s End',2013,'493',109,'2013-12-01',1,7,8,7,7,7,'Een Britse komedie met Simon Pegg en Nick Frost kan nooit mis gaan. Hoewel er een ongelooflijk onverwachte plot twist is, waardoor alles totaal absurd wordt, weet deze film toch te boeien tot het einde. Niet voor iedereen, maar eentje voor de filmliefhebber.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(796,'Pacific Rim',2013,'328',131,'2013-12-08',1,7,5,9,8,9,'Als Guillermo del Toro zijn naam verbindt aan een sci-fi film, doet dat het beste verhopen. Het uiteindelijke resultaat is een flinterdun verhaal, maar met super visuals. Een stoere actiefilm, met veel toeters en bellen, en staat aan het begin van de giant monsters revival. Altijd leuk voor een avondje ontspannen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(797,'Olympus Has Fallen',2013,'217',119,'2013-12-22',1,7,7,7,6,7,'Alweer een film in de White House rampenreeks. Dit is van het niveau waar ook White House Down moest toe behoord hebben. Het is echter een rasechte actiefilm, dus geloofwaardig is het niet. Maar als je je kan over het Amerikaanse patriotisme kan zetten, is dit zeker genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(798,'Source Code',2011,'494',93,'2013-12-25',1,9,9,8,8,9,'Dit is de meest underrated film van 2013. Een mysterieus verhaal dat zich beetje bij beetje ontrafeld, en tot een knap slot leidt. Alles wat je in een goede film wil, zou je kunnen stellen. Verrassend goed, en meeslepend van begin tot einde. Beeld en geluid dragen bij tot de hoge score.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(799,'Anchorman: The Legend of Ron Burgundy',2004,'423',94,'2014-12-30',4,8,8,8,8,7,'Een komedie met Will Ferrell en Steve Carell zal altijd aanlokkelijk ogen. En deze film stelt zeker niet teleur. Het steekt de draak met de typische nieuwsankers uit de jaren 70. Dat kan misschien niet zo herkenbaar zijn voor Europeanen, maar het is zo goed gedaan, dat het weer leuk wordt. Een heel degelijke absurde komedie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(800,'Despicable Me 2',2013,'480',98,'2014-01-12',8,8,8,8,9,8,'Een sequal van een animatiefilm is zelden een succes. Deze film is daar echter een uitzondering op. Het is natuurlijk meer van hetzelfde, maar het is wel onderhoudend. Uitmelkerij die niet opvalt, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(801,'Star Trek: Into Darkness',2013,'425',132,'2014-01-16',8,7,7,9,8,8,'De reboot van de Star Trek serie van enkele jaren geleden, viel goed mee. De puristen zullen er niet al te blij mee geweest zijn, maar het bleek een aangename film. Dit vervolg gaat echter meer de actietoer op, en legt de focus minder op de aspecten die van Star Trek een succes maakten, zoals politieke relaties of wetenschappelijke onderbouw. Een aangename actiefilm, maar die vooral aandacht krijgt, omdat het mee lift op de Star Trek naam.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(802,'Crank',2006,'428',88,'2014-01-28',4,6,6,6,7,8,'Een ouderwetse actiefilm. Volledig over-the-top, en met een plot waarvan enkel de insteek origineel is. Men probeerde ook wat té hip over te komen, en dat voelt dus nu al snel verouderd aan. Ondanks dat deze film pas 8 jaar oud is. Deze film heeft de tand des tijds niet doorstaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(803,'The Duchess',2008,'495',110,'2014-01-31',4,7,7,7,6,7,'Een kostuumdrama is een genre waar ik weinig naar kijk, en deze film bekeek ik ook per toeval. Dit genre staat of valt met de acteerprestaties en de cast, en dat zit hier wel goed. Zeker niet voor iedereen, en ik zou dit ook niet zelf kiezen. Maar al bij al niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(804,'Layer Cake',2004,'354',105,'2014-02-01',8,7,8,7,7,7,'Een misdaadfilm uit de periode waarin dit genre heel populair was. Hierdoor is het ondergesneeuwd, hoewel het zeker en vast aangenaam is. Het mist echter iets, waardoor het niet uitsteekt boven de massa. Leuk, maar niet memorabel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(805,'Memoirs of a Geisha',2005,'496',145,'2014-02-14',4,9,9,8,9,8,'Een voor westerlingen vrij onbekend fenomeen, geisha\'s, zorgt er voor dat deze film interessant is. Het is een voor de rest een romantisch drama. Maar deze originele insteek en setting zorgt voor een heel boeiend kijkstuk. Het houdt het midden tussen een documentaire en een romantisch drama.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(806,'Rush',2013,'132',123,'2014-03-05',8,8,8,8,7,8,'Een documentaire over het F1 seizoen van 1976, maar dan in Hollywood filmvorm. Het zorgt voor enig argwaan. Als je echter zonder vooroordelen naar deze film kijkt, is het echter wel heel goed gedaan. Het heeft respect voor de F1, en boeit ook voor wie er weinig mee heeft. De actiescènes zelf zijn té Hollywood, naar mijn mening.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(807,'This is the End',2013,'497',107,'2014-03-14',8,7,7,6,7,7,'Een uit de hand gelopen grap van een stel Hollywood comedy acteurs. Zo kan je deze film feitelijk samenvatten. Het pretendeert ook niet meer te zijn dan dat. En dat maakt het verschil. Verwacht geen meesterwerk, maar wel ontspannende zelfspot. En dan zit je goed voor een leuke avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(808,'The Little Foxes',1941,'498',116,'2014-03-23',4,6,7,6,5,5,'Ja, je leest het jaartal goed. Dit klassieke kostuumdrama houdt zich perfect staande, tijdens dit tijdperk van superhero CGI films. Het is natuurlijk traag en oud, maar tegelijk ook veel subtieler en uitgewerkter dan hedendaagse films. Een positieve verrassing, maar je moet er voor zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(809,'E.T. the Extra-Terrestrial',1982,'8',115,'2014-03-23',4,8,8,8,7,7,'Een absolute klassieker, die ik eigenlijk nooit volledig bekeken heb. Dat is bij deze goed gemaakt. Ondanks dat deze film al meer dan 30 jaar oud is, zijn de SFX niet echt verouderd. Het ziet er beter uit dan sommige CGI films van 10 jaar geleden. Een must-see voor elke filmliefhebber.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(810,'Conan the Barbarian',2011,'499',113,'2014-03-24',4,6,6,7,6,6,'In het lijstje van laffe reboots, in plaats van het maken van een nieuwe IP, past deze film perfect. Er zijn echter zo veel reboots, dat deze volledig onder de radar gebleven is. Het is ook helemaal niet speciaal, in deze tijd. Het is een leuk tijdverdrijf, maar er zijn betere reboots, met minder clichés.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(811,'Gravity',2013,'155',91,'2014-04-04',8,9,8,10,8,9,'Om de zoveel jaar komt er echt een showcase van filmtechnologie uit. En dat is de meest recente. Films in de ruimte behoren tot de technisch meest uitdagende, en dit is de eerste film die dit echt indrukwekkend weergeeft, zonder concessies. Boeiend en audiovisueel fantastisch, hoewel alles CGI is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(812,'Don Jon',2013,'500',90,'2014-04-13',8,7,7,7,7,6,'Een romantische film, maar niet echt een film om naar de bioscoop voor te gaan, op een eerste date. Een controversieel thema, waar alleen een beginnende regisseur zich aan waagt. Niet voor kleinzerige mensen. De insteek is interessant, maar kan niet boeien tot het einde. Het slot is zelfs teleurstellend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(813,'Zero Dark Thirty',2012,'311',157,'2014-04-18',8,7,7,8,6,7,'Een film over de vangst van Osama Bin Laden, vanuit Amerikaans standpunt. Duidelijk dat dit een vrij eenzijdig verhaal zal zijn. Maar buiten dat feit is het eigenlijk wel een goed oorlogsdrama. Het zal de tand des tijds moeilijk doorstaan, maar leuk om het in deze tijd eens te zien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(814,'The Wolf of Wall Street',2013,'3',180,'2014-04-19',8,8,8,8,7,7,'Een Scorsese drama vraagt wel wat aandacht, en stelt meestal niet teleur. Alsook deze film. Het is een verheerlijking van een Wall Street misdadiger, op een decadente manier in beeld gebracht. Maar dat maakt het als filmliefhebber niet minder interessant. Het zal geen klassieker worden, en het is vrij controversieel. Maar zeker niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(815,'The Hobbit: The Desolation of Smaug',2013,'131',161,'2014-04-21',8,6,6,7,8,8,'De tweede film in de \"Hobbit\" trilogie stelt zonder meer teleur. Inhoudelijk, maar vooral visueel. De CGI is soms abominabel, zeker in vergelijking met de Lord of the Rings trilogie. Een film met dit budget moet beter doen. Het verhaal is eveneens maar dunnetjes en heeft niet die epische schaal, zoals in de Lord of the Rings films. Erg teleurstellend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(816,'xXx',2002,'124',124,'2014-04-26',4,4,3,4,6,7,'Ik herinner me de tijd toen deze film dé blockbuster was. Ik verwachtte toen al een teleurstelling, en niet zonder reden, zo blijkt. De overdreven en ongeloofwaardige actie worden niet ondersteund door een cliché plot. Amper 12 jaar na datum voelt deze film al heel gedateerd aan. Afrader van formaat!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(817,'Only God Forgives',2013,'501',90,'2014-05-01',8,8,7,10,8,9,'Verschillende critici zijn eerder negatief over deze film, maar verwachten toch dat dit een echte culthit wordt in de toekomst. Visueel verbluffend, en zonder CGI. Ook het verhaal is krachtig. De kritiek is dat deze film zich aan geen enkele afspraak houdt, waardoor het onmogelijk is om deze film te snappen, zonder extra uitleg te lezen nadien. Niet voor iedereen, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(818,'American Hustle',2013,'479',138,'2014-05-02',8,8,8,8,9,7,'Het was lang geleden dat een fraude- en misdaadverhaal nog eens echt op grote schaal werd verfilmd. Hoewel dit niet echt een uitzonderlijke film is in het genre, is het sowieso een verademing tussen alle superhero-geweld. Goed, toegankelijk, maar niet exceptioneel. Vooral de cast draagt bij tot een positieve beoordeling. De opvallende muziek helpt ook.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(819,'Big Trouble in Little China',1986,'208',99,'2014-05-05',8,6,4,5,6,6,'Het label van cultklassieker krijg je niet zomaar. Maar bij deze film moet je toch echt weten waar je aan begint. Het is een B-film, die zichzelf niet al te serieus neemt. Hou dat in het achterhoofd, en het is best leuk. Anders zal het sowieso leiden tot wat wenkbrauwgefrons.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(820,'Nymphomaniac: Vol. I',2013,'309',118,'2014-05-13',1,7,7,8,6,7,'De titel en de regisseur wekken ongetwijfeld heel wat interesse. Zoals je kan verwachten, is dig geen feel-good verhaal, en het themal is ook niet voor iedereen. Controversieel, maar zeker boeiend. De titel duidt aan dat het verhaal uit 2 films bestaat, dus hou daar rekening mee.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(821,'Nymphomaniac: Vol. II',2013,'309',123,'2014-05-14',1,7,7,8,6,7,'Hoewel deze film een duidelijk andere ondertoon heeft, is het het directe vervolg op het eerste deel. Er valt dus ook niet veel meer over te vertellen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(822,'Now You See Me',2013,'355',115,'2014-05-16',1,8,8,9,7,8,'Misdaadfilms zonder blackboxes vormen zonder meer mijn favoriete genre. Het uitleggen van de illusies vormt dan ook een belangrijke troef van deze film. De film bleef een hele tijd in mijn hoofd hangen. Dat is altijd een goed teken. Een leuke, maar niet al te ingewikkelde misdaadprent.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(823,'Stoker',2013,'487',99,'2014-05-21',1,7,6,7,8,7,'Nicole Kidman lijkt een patent te hebben op films met mysterieuze plots, die volledig onder de radar blijven, en bijgevolg positief verrassen. Stoker is zo\'n voorbeeld. Hoewel in deze film duidelijk geen tijd zit in het uitdiepen van de karakters, blijft het een goed recept. Al is het niet echt origineel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(824,'Her',2013,'431',126,'2014-05-22',1,8,7,10,8,8,'Een knap verhaal over artificiële intelligentie en de gevolgen voor de gebruikers. Het zet aan tot nadenken. Daartoe draagt de visuele stijl enorm bij, want deze film schittert in zijn details. Interieur, design en mode maken het geheel af. Alleen kan het verhaal moeilijk blijven boeien tot het einde.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(825,'Back to the Future',1985,'16',116,'2014-05-23',4,7,6,7,7,7,'Het is eigenlijk een schande dat ik deze klassieker niet eerder heb gezien, maar het is er dan toch eens van gekomen. De film heeft de tand des tijds vrij goed doorstaan, al is de verhaallijn vrij doorzichtig. Ik kan inzien waarom het destijds zo\'n impact had, maar daar schiet nu niet al te veel meer van over. Enkel nog wat nostalgie voor de fans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(826,'The Other Guys',2010,'423',107,'2014-05-23',4,6,6,6,7,7,'De Will Ferrell hype is in volle gang, en deze film is daar een onderdeel van. Het is feitelijk ook exact wat je er van verwacht: Een vrij hersenloze komedie. Tegelijk zijn er betere Ferrell-films te vinden, maar leuk is dit zeker. Het is mij in ieder geval niet bijgebleven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(827,'The Haunted Mansion',2003,'270',99,'2014-05-24',4,6,6,7,6,6,'Eddie Murphy was vooral in de 80s en 90s erg populair. Zijn carrière is duidelijk al in dalende lijn. Dit is eerder een kinderfilm, waarbij hij natuurlijk wel nog scoort. Ik zou deze film omschrijven als \"vrij onbelangrijk\".','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(828,'Turbo',2013,'502',96,'2014-05-29',1,7,6,7,8,6,'Het concept van een goeie animatiefilm is simpel: Neem een schattig beestje met een originele twist. Gooi er een slechterik bij en maak een anderhalf uur durende film. Het gevolg is erg zichtbaar in deze film. Het eerste half uur is leuk en kan nog boeien. Maar als de intro voorbij is, is het over.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(829,'Snowpiercer',2013,'503',126,'2014-06-01',1,7,7,6,6,7,'Een film die gebaseerd is op een Aziatisch verhaal, bevat altijd minder Amerikaanse clichés. Hierdoor zijn er soms verrassende plottwists. Het interessante uitgangspunt helpt ook. Alleen kent deze film te weinig diepgang, waardoor het al snel vergeten zal worden. Hier zat meer in, misschien ontbrak er wat budget.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(830,'Dallas Buyers Club',2013,'504',117,'2014-06-04',1,8,8,7,7,7,'Deze film brengt een heel triest verhaal, maar doet dat zonder al te dramatisch te zijn. Het geeft een beeld van hoe het was om in de 80s Aids te hebben in Dallas. Vrolijk wordt je er niet van, maar het is een schitterende biografie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(831,'I, Frankenstein',2014,'505',92,'2014-06-14',1,3,3,6,7,6,'Soms wordt een film geschoten, waarbij je tijdens het bekijken de indruk krijgt dat de acteurs zelf al wisten wat een baggerfilm het zou worden. Dit is er zo eentje. Mislukt op alle gebied. Slechte CGI, niet boeiend en helemaal niet origineel. Eentje om snel te vergeten, of om te bekijken op een Nacht van de Foute Film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(832,'The Lego Movie',2014,'440',100,'2014-06-15',1,9,9,9,8,8,'Als je verwacht een kinderfilm te zien met schattige lego-figuurtjes, zal je bedrogen uit komen. Het verhaal is feitelijk vrij sterk, want het zit vol met \"volwassen\" humor. De fans van lego hebben hier ook een feest van herkenning mee. Een onverwachte meevaller, zelfs een van de toppers van het jaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(833,'Edge of Tomorrow',2014,'87',113,'2014-06-18',5,7,7,8,7,7,'Ik heb altijd een zwak voor films over tijdreizen, à la Groundhog Day. Dit is dan ook een soort remastered versie, met wat fancy CGI. Meer is het echter niet, want het doet niet echt iets nieuws. Ook het verhaal zelf is niet echt origineel. Niet echt positief dus, maar ik heb er toch een zwak voor.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(834,'The Secret Life of Walter Mitty',2013,'245',114,'2014-06-19',1,9,9,8,7,8,'Een episch avontuur kan er eens om de zoveel tijd wel bij. Dit is een film die niet zo start, maar die wel escaleert. Hoe verder de film vordert, hoe boeiender hij wordt. En dat is heel zeldzaam. Het wordt soms onder \"komedie\" gerankschikt, maar ik vind het meer een avonturenfilm. Het wordt nooit plat en houdt een goeie balans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(835,'Dom Hemingway',2013,'506',93,'2014-06-23',1,7,6,8,8,8,'Uit de UK kan je vaak knappe misdaadfilms verwachten. Denk maar aan Snatch. Deze film probeert iets gelijkaardigs neer te zetten, maar het is toch net wat minder. Het verhaal komt nooit echt los. Het is alsof je in de intro blijft steken. Maar wel een leuke intro.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(836,'Fear and Loathing in Las Vegas',1998,'223',118,'2014-07-26',4,8,8,9,7,7,'Een roadtrip movie die helemaal over niets lijkt te gaan. En dat is feitelijk ook zo. Maar toch boeit het van begin tot einde. De cast draagt hiertoe zeker bij, want het is de belangrijkste troef. Twee uur onzin, dus je moet er voor zijn. Het is dan ook compleet geflopt. Ik zal het in ieder geval niet snel vergeten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(837,'My Super Ex-Girlfriend',2006,'150',95,'2014-08-15',4,7,7,7,6,6,'Net voor de echter superhero hype van start ging, kwam deze parodie op de markt. Het resultaat is een aangename feel-good movie. Het zal niet lang blijven hangen, maar voor een doordeweekse avond, is dit best OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(838,'The Big Year',2011,'507',100,'2014-08-17',4,5,4,6,7,7,'Een komedie met zo\'n cast, daar verwacht je wel een en ander van. Maar net zoals in de nineties kan dit ook erg teleurstellend zijn. Deze film behoort daar helaas toe. Zonder de sterrencast, schiet er echt helemaal niets van over. Tijdverspilling.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(839,'12 Years a Slave',2013,'508',134,'2014-09-07',4,8,8,7,8,7,'Wat films over de slavernij gemeen hebben, is dat ze allerminst licht verteerbaar zijn. Door het gewichtige onderwerp, worden deze films vaak echt serieus aangepakt, en dat leidt vaak tot echte pareltjes. Een topfilm, maar je wordt er niet echt vrolijk van.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(840,'[Rec]',2007,'509',78,'2014-09-21',8,8,8,8,6,6,'Door de heuse cultstatus van deze film, heb ik deze toch eens bekeken. En het stelt absoluut niet teleur. De manier van cameravoeren, en het ontbreken van Amerikaanse clichés, dragen bij tot dit vrij schokkende meesterwerk. Low-budget, maar het maakt zijn status waar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(841,'Veronica Mars',2014,'510',107,'2014-09-23',1,7,7,8,7,7,'De manier waarop deze film is ontstaan, is feitelijk interessanter dan de film zelf. Het is puur nostalgie voor de fans van vroeger, maar meer ook niet. Een matige plot, maar wel met zowat alle originele acteurs. Een hele prestatie. Leuk voor wie de serie kent, maar matig voor alle andere.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(842,'Capitalism: A Love Story',2009,'511',127,'2014-09-26',8,7,8,6,6,7,'De zoveelste documentaire van Michael Moore. Je weet dus wat je mag verwachten. Het is eenzijdig, en nooit objectief, maar zeker amusant om te kijken. En het doet je in ieder geval nadenken. Het is niet zijn grootste meesterwerk, maar het blijft een van de beste documentairemakers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(843,'We Are What We Are',2013,'512',105,'2014-10-31',1,8,7,8,7,8,'Dit is een thriller waarvan je best geen trailers ziet, en geen verhaal kent, voor dat je gaat kijken. Want het mysterie is wat deze film boeiend maakt. Het is allemaal wat traag en low-budget, maar dat draagt net bij tot de sfeer van de film. Voor de cinefiel een must.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(844,'Godzilla',2014,'513',123,'2014-11-08',1,7,7,8,7,8,'Na het debacle van 1998, is deze remake een schot in de roos. Het is een goede sci-fi actiefilm, zonder meer. Het is goed dat er weer de juiste sfeer heerst, want de vorige versie leek meer op een komedie. Goede actiefilm, en geen teleurstelling. Maar een klassieker is het zeker niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(845,'Guardians of the Galaxy',2014,'514',121,'2014-11-24',8,8,8,8,8,8,'De inspiratie van de superhero bedrijven lijkt wat op te zijn. Vandaar deze riskante keuze, want de superheroes liggen niet voor de hand. Het blijkt echter een onverwachte meevaller te zijn. Vrij voorspelbaar, zoals alle films in dit genre. Maar zeker onderhoudend. Ik heb af en toe goed gelachen, ook. Wat wil je nog meer van een superhero movie?','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(846,'The Adventures of Baron Munchausen',1988,'223',126,'2014-11-29',2,4,4,4,6,6,'Een cultklassieker van jewelste. Helaas ook hopeloos verouderd. Het zal waarschijnlijk fantastisch geweest zijn als je deze film als kind zag, maar nu is het toch echt niet meer van deze tijd. Soms is het zelfs ronduit frustrerend om naar te kijken. Laat deze film nostalgie blijven en rusten in het verleden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(847,'Flight',2012,'16',138,'2014-11-30',1,7,7,7,8,8,'In tegenstelling tot wat je zou verwachten, gaat deze film niet echt over een vliegramp, maar meer over alcoholmisbruik. Dat was verrassend voor mij, en draagt bij tot mijn positieve verrassing. Denzel Washington draagt deze film quasi volledig zelf. Het zal geen klassieker worden, maar wel een goede film. Degelijk, zoals het moet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(848,'True Grit',2010,'399',110,'2014-12-05',1,8,8,8,7,7,'Remakes van oude westerns zijn niet altijd een succes. De opbouw van deze film respecteert echter de regels van de oude westerns. En dat maakt het net speciaal. Een onverwachte meevaller, boeiend van begin tot einde. Vrij onbekend, maar ten onrechte. Een van de betere hedendaagse westerns.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(849,'Lucy',2014,'60',89,'2014-12-07',1,7,7,8,8,8,'Luc Besson waagt zich nog eens aan een Amerikaanse blockbuster. Zijn aanpak komt fris over, in vergelijking met zijn Amerikaanse collega\'s. Het resultaat is een boeiende, maar weinig geloofwaardige actiethriller. De poging om wetenschappelijk correct over te komen, is er echter te veel aan. Denk er niet te veel bij na, en je hebt een topfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(850,'Predestination',2014,'515',97,'2014-12-08',1,8,8,8,7,8,'Ik hou van sci-fi films over tijdreizen. Dat kan ik niet helpen. Hierdoor oordeel ik altijd positiever dan de film verdient. De film boeide van begin tot einde, en was ook vrij goed te volgen. Er zijn wel wat plotgaten, maar over het algemeen vind ik deze film een voltreffer. Spijtig dat alles in slechts 97 minuten voorbij was.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(851,'Blue Ruin',2013,'516',90,'2014-12-12',1,7,8,7,7,8,'Een originele kijk op een dramatische situatie, en wat de gevolgen daarvan zijn. Het komt op de een of andere manier heel erg realistisch over. Net dat maakt deze film uniek. Kijk niet naar deze film voor ontspannende snelle actie, maar voor wat er in een mens omgaat als hij een misdaad pleegt. Heel sterk, maar niet voor iedereen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(853,'Autómata',2014,'517',109,'2014-02-17',8,7,7,8,7,7,'Sci-fi films over AI zijn de laatste tijd echt wel weer in. Deze film was veelbelovend, en schiep hoge verwachtingen. Het resultaat is spijtig genoeg vrij middelmatig. Het is onderhoudend, en niet slecht. Maar het zal niet lang in mijn herinneringen blijven. Te gewoon, te weinig meeslepend, niet verrassend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(854,'A Million Ways to Die in the West',2014,'471',116,'2014-12-19',8,7,8,7,6,6,'Je verwacht bij een Western van Seth MacFarlane, dat het Family Guy wordt, in een western kleedje. Feitelijk is dat exact wat dit is. Het is dus niet verrassend, maar daarom niet slecht. Een aangename komedie, en tegelijk parodie op het Western genre. Alleen begint het Musical-gehalte na een tijdje wel op de zenuwen te werken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(855,'John Tucker Must Die',2006,'518',89,'2014-12-21',4,5,5,6,6,6,'Het was nog eens tijd voor een teen romance comedy. Deze film past perfect in dat genre. Het doet niets meer of minder. Je weet dan ook waar je aan begint. Vrij inhoudsloos, een echte VijfTV film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(856,'Teenage Mutant Ninja Turtles',2014,'519',101,'2014-12-26',8,6,6,7,7,6,'Het onnodig remaken van nineties films bereikt ongekende hoogtes, dezer dagen. Deze past ook in dat rijtje. Het is allemaal wel leuk, met de hedendaagse CGI, maar kan niet de indruk nalaten, zoals de originele films. Voor mij een overbodige superhero movie, maar al bij al wel leuk gedaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(857,'Inside Man',2006,'158',129,'2014-12-26',4,8,8,8,7,8,'Een Heist movie van Spike Lee, met zo\'n cast, daar mag je wel wat van verwachten. Een teleurstelling is dit allerminst, integendeel. Deze film boeit van begin tot einde, en voelt geloofwaardig aan. Het maakt dit een van de beste Heist movies die er zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(858,'The Double',2013,'520',93,'2015-01-05',8,8,8,9,8,7,'Een vrij bizarre komedie over een man die zijn perfect fysiek evenbeeld ontmoet. De sfeer en beeldtechnieken dragen bij tot een heel eigen sfeer. Deze onthoud je wel even, door die sfeer. Als het eens iets anders mag zijn, is dit zeker en vast een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(860,'The Grand Budapest Hotel',2014,'521',100,'2015-01-10',8,8,8,9,8,8,'Om de zoveel tijd, vooral rond het Oscarseizoen, verschijnt er een zogenaamde art-house film. Vooral geliefd onder professionelen, en meestal ook niet echt mainstream. Deze film behoort bij die groep, maar wordt echter positiever onthaald. En niet onterecht. Boeiend van begin tot einde, eigen technieken, sterke cast,... Alles wat je wil voor een klassieke filmavond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(861,'Homefront',2013,'193',100,'2015-01-12',8,7,7,8,7,7,'Een film met Jason Statham staat meestal garant voor knallende actie. Hoewel dit genre de laatste tijd meer en meer naar parodieën neigt, neemt deze film zich iets serieuzer. En niet zonder succes. Ben je op zoek naar een degelijke, niet al te overdreven actiefilm? Dan is dit je ding.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(862,'The Hobbit: The Battle of the Five Armies',2014,'131',144,'2015-01-16',8,6,6,7,8,8,'Dit is de laatste film in de Hobbit trilogie. Je ziet duidelijk dat er een tekort aan bronmateriaal was. Inhoudelijk is het gewoon één grote battle, en wat geforceerde referenties naar de Lord of the Rings films. Teleurstellend. Al zijn er mensen die nooit genoeg kunnen krijgen van Middle-Earth.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(864,'The Hunger Games: Catching Fire',2013,'338',146,'2015-01-22',8,7,7,8,7,8,'De tweede film in de Hunger Games reeks, en het nieuwe is er een beetje af. Wat de eerste film uniek maakte, doen ze hier nog eens over. Origineel is het dus weer niet, en het voelt ook wat oppervlakkig aan. Een van de betere reeksen in het teen action genre. Ach ja, geef het het voordeel van de twijfel, maar verwacht niet al te veel inhoud.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(865,'Trance',2013,'32',101,'2015-02-01',8,6,7,7,7,7,'Van een Danny Boyle misdaadfilm verwacht je wel een en ander. Daarom is dit ook eerder een teleurstelling. Het is wel best OK, niet te cliché, en ook onderhoudend. Toch is dit al bij al te licht, en zal het me helaas niet te lang bijblijven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(866,'The Interview',2014,'522',112,'2015-02-08',8,6,6,7,7,7,'Door het Noord-Korea thema en de bijbehorende hetse, was ik wel benieuwd. Het is echter een doordeweekse, maar niet al te slechte, komedie. Als je niet al te hoge verwachtingen hebt, dan is dit best amusant. De absurditeit is de beste troef van deze film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(867,'Fifty Shades Of Gray',2015,'523',125,'2015-02-15',5,4,4,6,6,7,'Deze film werd onthaald als de tweede geboorte van Jezus. Het moest gemaakt worden om mee te liften op de hype van de boekenreeks. En dat is er aan te zien. Het is een Amerikaanse film, dus al veel te braaf. Hierdoor komt het verhaal totaal niet over en lijkt het een nieuwe Twilight. Het boek is niet alleen beter, maar in dit geval ook anders.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(868,'The Imitation Game',2014,'524',114,'2015-03-14',8,8,8,7,8,8,'Een film over een historische wetenschapper uit Hollywood, is meestal een zeemzoete dumbed-down versie van de realiteit. Deze film valt daarin best mee. Het is een pakkend verhaal over een briljante geest, met respect voor de realiteit, terwijl er toch een verplicht romantisch tintje bij moet. Best goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(869,'Atari: Game Over',2014,'525',66,'2015-03-22',8,6,6,6,6,6,'Dit is zeker niet de beste documentaire ooit, maar het licht dicht bij mijn interesseveld. Vandaar dat ik sowieso OK ging vinden. Het gaat niet echt in op de echte controversiële onderwerpen, maar het probeert toch een breder onderwerp aan te kaarten. Net als bij alle documentaires: enkel voor de geïnteresseerden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(870,'Video Games: The Movie',2014,'526',101,'2015-03-22',8,NULL,NULL,NULL,NULL,NULL,'In 2014 leek het een echte rage om documentaires over de gamesindustrie te maken. Deze springt er eigenlijk niet echt uit. Het geeft een high-level overzicht van de geschiedenis, maar slaat de bal ook mis. Het is een heel erg Amerikaanse visie. Zoals altijd: Leuk voor de geïnteresseerden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(871,'Nebraska',2013,'527',115,'2015-03-27',8,NULL,NULL,NULL,NULL,NULL,'Een klassiek drama over een bejaarde man die op avontuur gaat en intussen terug kijkt naar zijn eigen leven. Het concept werd al eerder uitgewerkt, maar het is wel gemaakt vanuit een origineel uitgangspunt. Het is hierdoor minder toegankelijk, maar het is wel een prachtig verhaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(872,'What We Do in the Shadows',2014,'528',86,'2015-04-02',8,8,7,8,7,7,'Komedie en horror zijn twee genres die zodanig ver uit mekaar liggen, dat ze iets helemaal unieks geven als je ze samenvoegt. Deze film is een fictieve documentaire over het leven als vampier. Alleen dat onderwerp, maakt hier een geslaagde film van. Alleen zakt het in het midden wat in mekaar, als de eerste absurditeit verwerkt is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(873,'Interstellar',2014,'121',169,'2015-04-06',8,9,8,9,8,9,'Een blockbuster sci-fi film moet uitblinken in ofwel visueel spektakel, ofwel wetenschappelijke onderbouwdheid. Deze film probeert beide te doen. Alleen wordt het naar het einde toe heel erg controversieel. Het gaat van wetenschap meer naar religie. Dat stoot veel mensen af. Ik vond het wel een topfilm. Boeiend van begin tot einde, ondanks de duur. Neem het echter niet te serieus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(874,'Big Hero 6',2014,'529',102,'2015-04-16',8,7,7,7,7,8,'De reeks van Disney animatiefilms gaat door met Big Hero 6. Helaas valt deze film ook in de val van heel wat van zijn voorgangers: De plot is origineel en wekt interesse, maar de uitwerking loopt leeg als een ballon. Het is niet speciaal en blinkt nergens uit. Maar slecht is het nu ook weer niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(875,'Original Sin',2001,'530',116,'2015-04-27',4,7,8,8,7,7,'Een romantisch misdaaddrama in een Western setting. Dat moest wel iets origineel zijn. En dat is het eigenlijk ook. Uiteindelijk wordt het wat langdradig en melig. Vooral dat het einde. Het is eens iets anders...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(876,'RoboCop',2014,'531',117,'2015-05-14',8,5,5,7,7,7,'De zoveelste overbodige remake van een klassieker. Je zou verwachten dat met de hedendaagse technologie, de film nog meer indruk zou maken dan de eerste. Integendeel, de eerste film is nog steeds beter. Alles wat het origineel goed maakt, is in deze film niet aanwezig. Niet verrassend, noch meeslepend. Een gemiste kans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(877,'Mad Max: Fury Road',2015,'154',120,'2015-05-15',5,7,6,9,8,8,'Remakes zijn veelal problematisch, de laatste tijd. Deze remake is vooral eye-candy. De special effects zijn indrukwekkend, maar de film zelf heeft weinig inhoud. Het Mad Max-universum houdt het wel best interessant. Een visueel pareltje en een genietbare spektakelfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(878,'Penguins of Madagascar',2014,'250',92,'2015-05-28',8,7,8,7,8,7,'Dit is feitelijk een spin-off van de Madagascar animatiefilm reeks. Enkele populaire personages krijgen nu een eigen film. Het gevolg laat zich al raden: Weinig inhoud. Maar tegelijk best wel grappig. Het is niet bepaald de komedie van het jaar, maar hij mag er best zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(879,'Revenge of the Green Dragons',2014,'532',94,'2015-05-28',8,8,9,7,7,8,'Een Aziatische misdaad film is meestal niet echt toegankelijk. De westerse invloed is echter vrij groot. En dat maakt deze film net sterker. Het bevat geen clichés, en voelt toch niet al te vreemd aan. Zeker aan te raden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(880,'Horns',2013,'365',120,'2015-06-01',8,8,8,8,8,8,'Deze film past niet echt bij mijn smaak. Ik wilde deze toch kijken door het heel bizarre uitgangspunt. Dit uitgangspunt wordt heel sterk uitgewerkt en deze film is bijgevolg dan ook boeiend van begin tot einde. Alleen stelt dat einde best teleur. Spijtig, dit kon een klassieker geweest zijn. Onverwacht goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(881,'Horrible Bosses',2011,'533',98,'2015-06-02',4,7,7,8,7,7,'Er zijn elk jaar wel een handvol klassieke komedies die echt goed zijn. Want meestal zitten alle goeie momenten al in de trailer. Hier echter niet. Hoewel deze film zeker en vast ook in de klassieke val trapt, door totaal geen humor in het laatste stuk van de film te stoppen, blijft het wel een van de komedies van het jaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(882,'Jurassic World',2015,'534',124,'2015-06-19',5,8,7,9,8,9,'Met enig argwaan ging ik deze film kijken. En niet onterecht. Het is geen klassieker, zoals de eerste Jurassic Park film. Maar daarom is dit geen slechte film. Het laat niet dezelfde indruk als weleer, maar het is wel een indrukwekkende actiefilm. Als je deze film bekijkt met de juist instelling, dan is dit best OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(883,'Chappie',2015,'437',120,'2015-06-22',8,8,8,9,9,8,'Neill Blomkamp wordt achtervolgd door het succes van District 9. De kijkers zijn teleurgesteld over Chappie, omdat dit geen nieuwe District 9 is. Dat is echter niet de juiste instelling om deze film te kijken. Zie het als een alleenstaande sci-fi film, en je zal niet teleurgesteld worden. Je hebt een film met weinig Amerikaanse clichés, maar wel knappe actiescènes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(884,'Hysteria',2011,'535',100,'2015-06-23',4,6,7,7,6,7,'Dit is een vrij interessante romantische komedie, maar meer ook niet. Het uitgangspunt is nogal spraakmakend, maar dat komt in de film nogal weinig aan bod. Het verwatert in een dertien-in-een-dozijn rom-com, en dat is jammer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(886,'Ex Machina',2015,'536',108,'2015-06-28',8,9,9,9,8,8,'2015 is duidelijk het jaar van de artificial intelligence sci-fi films. Dit exemplaar is een van de meest opvallende, en waar de fans het meeste van verwachtten. De meningen zijn achteraf echter verdeeld. Ik vind het persoonlijk een sterke film, maar ik kan tegelijk de kritiek begrijpen. Het positieve blijft echter over in mijn herinnering.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(887,'Nightcrawler',2014,'537',117,'2015-07-04',8,9,9,8,8,7,'Ik had nog nooit van deze film gehoord, maar het blijkt een echte cult-hit te zijn. Een unieke misdaadfilm over de misdaadpers in de Verenigde Staten. Het is meeslepend en onvoorspelbaar. De cast draagt hier zeker aan bij. Een onverwacht pareltje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(888,'2001: A Space Odyssey',1968,'248',160,'2015-07-12',8,8,8,7,6,9,'Als filmliefhebber moest ik de film, waarvan velen zeggen dat het de beste film ooit is, toch gezien hebben. Het is een flinke brok, en zeker niet toegankelijk. Maar je kan wel zien welke impact deze film in die tijd kan gemaakt hebben. Zoiets zou zeker in deze tijd niet meer gemaakt kunnen worden. Alleen al daarom moet je dit kijken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(889,'Let the Right One In',2008,'538',115,'2015-07-21',8,8,8,8,8,8,'Een Zweedse film die een hit is in de Verenigde Staten, is een unicum. En daar moest natuurlijk een American Remake van gemaakt worden. Dit origineel is echter heel sterk. Verwacht geen splatter horror, maar wel mysterie en spanning. De sfeer die deze film creëert, maakt het geheel af.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(890,'Forgetting Sarah Marshall',2008,'450',111,'2015-07-21',4,8,8,7,7,7,'Een rom-com die 7 jaar na datum nog steeds bekend is, moet wel goed zijn. Het is zeker een van de beste rom-coms van de laatste jaren. Het is niet te melig, en net gepeperd genoeg. De cast verraadt de humorstijl al, en die valt bij mij zeker in de smaak.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(891,'Get Hard',2015,'539',100,'2015-09-13',8,6,6,7,8,8,'Will Ferrell is Will Ferrell. En dat zal hij altijd blijven, eender welke rol hij speelt. Deze komedie is weer vrij OK, maar het is een typische Ferrell film. Het is ook al niet zijn beste. Niet slecht, maar een aanrader zou ik dit niet noemen. De film blijft niet de volle 100 minuten boeiend of goed. Het zou een goede kortfilm geweest zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(892,'White Chicks',2004,'42',109,'2015-10-30',4,6,6,6,7,7,'Een legendarische komedie, die eigenlijk wel thuishoort in de nineties. De humor is heel Amerikaans en daar moet je je over zetten. Daarentegen is het een prettige film voor op een weekdag. Niets speciaals, gewoon een degelijke en eenvoudige komedie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(893,'Pay the Ghost',2015,'540',94,'2015-10-31',8,6,6,7,7,7,'Horrorfilms mogen clichés bevatten, maar dan mogen ze zichzelf niet te serieus nemen. Dat is meteen het probleem van deze film. Het is een supervoorspelbare halloweenfilm, maar doet zich high-end voor. Hierdoor is het een dertien-in-een-dozijn film en was volstrekt onnodig. Slecht is het niet, maar helemaal niet memorabel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(894,'Evil Dead',2013,'541',96,'2015-10-31',8,8,8,8,7,7,'Weinig remakes zijn het gegeven om beter te zijn dan het origineel. Meestal is het barslechte uitmelkerij. Dit is een uitzondering op die regel. Het is een horrorfilm zoals het hoort, met respect voor het genre en het origineel, maar heel goed uitgewerkt. Een meevaller. Want toegegeven, mijn verwachting lag niet al te hoog.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(895,'Moon',2009,'494',97,'2015-11-24',8,7,8,7,6,7,'Deze culthit van enkele jaren terug greep mijn aandacht, omdat dit de regisseur van Source Code is. Een sci-fi drama die dieper in gaat op ethische thema\'s ligt niet echt in die lijn. Het blijkt een meevaller te zijn. Hoewel de film soms de nadelen van het lage budget niet kan verstoppen, boeit het van begin tot einde. De serieuze ondertoon en laag tempo zorge er echter voor dat dit niet iedereen zal bekoren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(896,'Hotel Transylvania 2',2015,'478',89,'2016-01-09',8,6,6,6,7,7,'De eerste film was een onverwachte meevaller. Het was voor mij een van de beste animatiekomedies van de laatste jaren. Dat schept hoge verwachtingen voor deze opvolger. Verwachtingen die niet helemaal waargemaakt worden. Het is wel leuk, maar is eigenlijk meer van hetzelfde. Er is niets anders of origineels. Dat vind ik niet voldoende.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(897,'American Ultra',2015,'542',99,'2016-01-17',8,8,8,8,9,8,'Een ietwat ondergesneeuwde actie/misdaadfilm die van een weinig origineel uitgangspunt vertrekt: De held die niet weet dat hij dit is. Toch is de uitwerking wel origineel en is de film hierdoor niet echt voorspelbaar. De cast draagt bij tot het feit dat toch wel eens iets anders is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(898,'About Time',2013,'490',123,'2016-01-23',8,6,6,7,7,7,'Het wordt stilaan moeilijk om in dit genre nog origineel uit de hoek te komen. Dit is het dan ook niet echt geworden. Het verhaal heeft een originele insteek, maar dat wordt alweer niet voldoende uitgewerkt. Want het blijft een eenvoudige romantische film. De acteerprestaties proberen dat wat te verdoezelen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(899,'The Man from U.N.C.L.E.',2015,'230',116,'2016-01-30',8,7,7,6,8,8,'Een film die gebaseerd is op een seventies misdaadserie, is soms al eens erg geslaagd. Dit is er echter niet zo een. Het is een degelijke actie/misdaadfilm, maar ik heb me na enkele weken al moeten inspannen om me er nog iets van te herinneren. Wat ik mij er wel van herinner, is het feit dat de CGI soms te wensen over laat. Allerminst memorabel, maar een leuke zondagnamiddagfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(900,'Andrew Bergman',1996,'184',115,'2016-02-09',4,6,6,7,9,8,'Dit is een typische nineties komedie met Demi Moore en Burt Reynolds als trekpleister. Net als andere films in dit genre, is het wat dunnetjes. Maar het heeft net voldoende om net te blijven boeien. Ik vermoed toch dat deze film wat ondergewaardeerd wordt. Echt speciaal kan je het natuurlijk niet noemen. Vooral de muziek bleef me bij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(901,'Spectre',2015,'135',148,'2016-03-13',8,7,7,9,8,8,'De vierde Bondfilm met Craig borduurt verder op de nieuwe stijl van de vorige drie. Waar de vorige films echter meer over het menselijke aspect van Bond gingen, gaat deze film vooral opnieuw de actieheld Bond-kant uit. Maar die actiescènes zijn dan wel echt speciaal. Het is qua inhoud de dunste, al zou het qua thema wel de belangrijkste moeten zijn. Teleurstellend, zeker niet een van de beste Bondfilms.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(902,'The Good Dinosaur',2015,'543',93,'2016-03-27',8,8,8,8,7,7,'Waar de voorbije reeks Pixar animatiefilms vooral de humorkaart trekken, is dit meer een klassiek Disneyverhaal. Er zitten grappige fragmenten in, maar het is vooral een hartverwarmend verhaal. Het deed me heel erg nostalgisch denken aan Platvoet. Alle clichés worden aangehaald, maar het blijft goed uitgevoerd. Grafisch is er wel degelijk een stap gezet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(903,'John Wick',2014,'544',101,'2016-03-29',8,8,7,9,8,8,'Dit is een klassieke misdaad actiefilm, met erg veel spectaculaire hand-to-hand combat. Clichés worden lustig aangevoerd, maar dat draagt wel bij tot de hele sfeer van de film. Het is gewoon goed uitgevoerd, zonder uit te blinken. Een steengoede actiefilm, voor wat brainless kijkgenot.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(904,'Labyrinth',1986,'545',101,'2016-03-31',8,6,7,6,7,6,'Een klassieker onder de kinderfilms, maar helaas ook hopeloos verouderd. Het is voornamelijk uit nostalgie, als je deze film nog wil herbekijken. Het was in die tijd ongetwijfeld spectaculair, maar die tijd is vervlogen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(905,'The Adjustment Bureau',2011,'546',106,'2016-04-02',8,7,8,8,7,7,'De titel klinkt als een rom-com, maar het blijkt een sci-fi misdaadthriller te zijn. Die verrassing alleen al, maakt deze film al beter. Het is dan ook nog eens klassiek opgebouwd, met de nodige plotwendingen, en filosofische vraagstukken. Het neemt zichzelf soms iets te serieus, maar in het genre zeker dik OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(906,'My Neighbor Totoro',1988,'547',86,'2016-04-05',8,8,7,7,7,8,'Een voor mij ongewone keuze: een Japanse animatiefilm. Het is echter wel meteen een klassieker. Omdat de hollywoodclichés en de daarbij horende voorspelbaarheid ontbreken, boeit deze film wel van begin tot einde. Je moet er wel voor open staan, natuurlijk. Ik noem het een \"schattige film\".','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(907,'Victor Frankenstein',2015,'340',110,'2016-04-09',8,5,4,8,7,7,'De laatste jaren zijn remakes van klassieke verhalen meestal goed meegevallen. Deze film hoort echter meer thuis in de \"ik was die al vergeten\" categorie. Het is zo\'n film waarvan je een indrukwekkende trailer kan maken, maar waar alle inhoud dan ook in die trailer zit. Niet origineel of meeslepend. Een tegenvaller.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(908,'Hitman: Agent 47',2015,'548',96,'2016-04-09',8,7,7,8,7,8,'De Hitman film van enkele jaren geleden was een vrij ok-ish actiefilm. Deze reboot is wat rauwer, en staat er volledig los van. Het is opnieuw een leuke actiefilm, met een vleugje sci-fi. Vrij overbodig, maar het thema maakt het blijkbaar gemakkelijk om een aangename actieprent te maken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(909,'Youth',2015,'549',124,'2016-04-11',8,8,9,7,8,8,'Deze film snijdt een vrij gewichtig thema aan, namelijk ouder worden. Het gaat de daarmee gepaarde moeilijkheden niet uit de weg, en brengt het op een heel respectvolle manier. Typisch een film die niet voor iedereen is, want het vraagt wat inlevingsvermogen, en begrip van situaties die niet letterlijk worden benoemd. Het is ook af en toe wat kunstig qua beeldvoering. Een verrassing, en het is eens iets anders.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(910,'How to Lose Friends & Alienate People',2008,'550',110,'2016-04-15',8,7,7,8,8,7,'Dit is een poging om Britse humor over te brengen in een typisch Amerikaanse rom-com. En het resultaat is wel vrij OK. Alleen lijkt niemand anders dit te vinden. Ik vond het een rom-com met een scherp kantje, en dat kan ik wel appreciëren. Maar het lijkt er op dat ik daar alleen in sta. Alleen verwatert de film in een \"gewone\" rom-com op het einde. Jammer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(911,'Avengers: Age of Ultron',2015,'467',141,'2016-04-17',8,7,5,9,7,8,'Terwijl de superhero stoomtrein als een gek voorbij dendert, verzwakt mijn interesse zienderogen. De samenkomst van een dozijn superheroes in bijna twee en een half uur aansluitende actiescènes, is er wat te veel aan. Het is allemaal wel spectaculair en indrukwekkend, maar er is geen enkele vorm van interessant verhaal. Hoogmoed komt voor de val.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(912,'Crimson Peak',2015,'328',119,'2016-04-22',8,9,8,9,9,9,'Bij del Toro is het meestal hit-or-miss. En dit is een absolute hit. De sfeer en techniek maakt deze film erg boeiend. Het is eigenlijk een romantisch verhaal, maar door het del Toro-sausje wordt het zoveel meer. En vooral donkerder. Sfeervol en smaakvol.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(913,'Maggie',2015,'551',95,'2016-04-24',8,7,8,8,7,7,'Een drama met Schwarzenegger lijkt verdacht. En een zombiefilm die niet onder horror valt, al helemaal. Maar toch is het zo. Het is een drama, waarin Arnold laat zien dat hij ook een goede acteur is. Het is wat traag, en soms wat voorspelbaar. Tegelijk ook donker en meeslepend. Een meevaller, maar geen klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(914,'Turbo Kid',2015,'552',93,'2016-04-24',8,7,6,8,7,8,'Throw-back naar de eighties sci-fi films, maar dan met iets hedendaagser technologie. Als je uit die tijd stamt, dan kijk je deze film met een nostalgische glimlach op je gezicht. Die wordt echter niet de hele film lang vastgehouden. Een fantastische plot kan je dit niet noemen. En jongeren zullen een WTF gevoel over houden, vrees ik. Ik heb in ieder geval goed gelachen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(915,'Deadpool',2016,'553',108,'2016-05-10',8,7,7,8,8,8,'Enkele jaren geleden afgeschoten, en nu dan toch gemaakt. Men heeft dat feit goed gebruikt om de hype te starten. Het is absoluut de moeite geweest om te maken, zo slecht is het nu ook weer niet. Maar het is ook geen meesterwerk, zoals de hype ons wil laten geloven. Een komische superhero movie. Iets minder braaf dan de andere films in het genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(916,'Hail, Caesar!',2016,'399',106,'2016-05-31',8,8,8,7,8,8,'Een film van de Coen brothers, daar kijk ik altijd naar uit. Het lijkt echter wel als het uitwerken van hun frustratie op de filmindustrie. Het is een parodie, die soms hilarisch is, maar soms ook de pijnlijke kanten van de industrie bloot legt. Het is een kunststukje die geapprecieerd zal worden door filmliefhebbers. De doorsneel kijker zal dit echter iets te bizar vinden, vrees ik.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(917,'The Peanuts Movie',2015,'554',88,'2016-06-23',4,5,5,7,7,7,'Het was nog eens tijd voor een leuke schattige animatiefilm. Helaas is deze film echt wel iets té kinderachtig hiervoor. Het is echt een animatiefilm voor vroege tieners, en heeft weinig om het lijf voor volwassenen. Geen aanrader, maar waarschijnlijk wel leuk voor de kids.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(918,'The Martian',2015,'54',144,'2016-06-23',8,8,8,9,7,8,'Een van de blockbusters van het jaar. Het lijkt wel een periode van sci-fi avonturenfilms. Dit is echter wel een van de betere. Je ziet aan alles dat dit gebaseerd is op een uitgebreid boek. Dat geeft wel het gevoel dat we misschien beter het boek hadden gelezen. Maar absoluut onderhoudend en visueel indrukwekkend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(919,'Zootopia',2016,'405',108,'2016-06-25',8,6,6,6,6,6,'Soms verschijnt er een animatiefilm van Disney, en daar verwacht je dan heel veel van. Maar soms is het ook te gewoon. Deze film valt in die categorie. Het is allemaal wel leuk en onderhoudend. Er ontbreekt echter een blijvende indruk. Goed voor een zondagnamiddag bij regenweer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(920,'The 5th Wave',2016,'555',112,'2016-06-28',8,2,2,3,4,5,'Zelden ben ik meedogenloos voor een film, maar in dit geval wel. Ook al omdat het mijn verjaardag was. Dit stuk tijdverlies is een verzameling van slechte CGI, en voorspelbare tienerfantasie. Er zijn al tientallen films gemaakt in dit genre die honderden keren beter zijn dan dit stuk nonsens. Soms is een film zo slecht dat het weer lachwekkend wordt, maar die fase is deze film al lang voorbij,','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(921,'Ghostbusters',1984,'150',105,'2016-07-12',4,6,6,6,8,7,'Naar aanleiding van de remake die dit jaar uitkomt, constateerde ik dat ik deze klassieker nog niet eerder gezien had. Daar moest verandering in komen. Al bij al doorstaat deze film de tand des tijds vrij goed. Al kan je het moeilijk een meesterwerk noemen, volgens de standaarden van vandaag. Ik begrijp waarom het een klassieker is, maar het is ook een beetje vergane glorie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(922,'10 Cloverfield Lane',2016,'556',104,'2016-07-16',8,8,8,9,8,8,'De naam doet een sequel vermoeden van de originele Cloverfield film. Dat is het echter niet. Het is een verhaal dat tegelijk plaats vindt, tijdens het verhaal van de originele film. Het heeft er in feite weinig mee te maken. Wat het wel is, is een claustrofobische thriller met horrorelementen. Goed acteerwerk en geluid dragen bij tot een onverwachte meevaller.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(923,'Room',2015,'557',118,'2016-07-19',8,9,9,8,8,9,'Normaal is een psychologisch drama niet echt het genre waar ik dikwijls naar grijp. De uitmuntende commentaren hebben mij echter overtuigd. Ik werd niet teleurgesteld. Boeiend, meeslepend en soms spannend, maar wel relatief zware kost. Dit is hoe je een psychologisch drama moet maken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(924,'An Inconventient Truth',2006,'558',96,'2016-07-21',8,8,8,6,6,7,'Deze inmiddels legendarische documentaire is steeds door de mazen van het net geglipt. Er bestaat echter geen documentaire die de gevolgen en gevaren van global warming beter kan uitleggen. Knappe voordracht, en het doet een mens nadenken. Het vormt de bron voor menig milieubeleid en als startpunt voor andere goede documentaires,','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(925,'Gods of Egypt',2016,'253',126,'2016-07-23',8,4,3,6,7,8,'Na enkele jaren voel je al aan je ellebogen of een blockbuster een ramp gaat worden. Dat gevoel had ik met deze film, en klaarblijkelijk niet zonder reden. Het is een met CGI overladen godenavontuur, maar dan een van de mindere soort. Niet goed opgebouwd, veel te snel en ook vrij voorspelbaar. Af te raden. Een gemiste kans, want in bijvoorbeeld de gamesindustrie is dit thema meer dan eens goed uitgewerkt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(926,'Ghostbusters II',1989,'150',108,'2016-08-13',8,6,6,7,8,7,'Vijf jaar na de eerste film, kwam het vervolg. Het doet weinig nieuws, maar doet het ook niet slechter. In veel opzichten is deze film beter uitgevoerd dan het origineel. Dat is vrij zeldzaam voor vervolgfilms. Ook een klassieker, maar eveneens vergane glorie. Aangenaam, maar niet meer dan dat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(927,'Spotlight',2015,'559',128,'2016-09-14',8,7,8,7,7,7,'Als en film algemeen geroemd wordt, ben ik steeds wat argwanend. Deze drama/docu verdient de roem wel. Je ziet aan alles dat dit degelijk en serieus is. Alleen spreekt het mij niet echt aan. De plot maakt op mij geen indruk. Hoewel het natuurlijk een uitstekende film is, is het ook zeker niet voor iedereen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(928,'The Secret Life of Pets',2016,'560',87,'2016-09-17',NULL,4,4,8,7,6,'Dit moet zowat de grootste teleurstelling van de laatste jaren zijn. Ik heb alweer de fout gemaakt van naar een trailer te kijken. Die trailer was heel goed, en schiep hoge verwachtingen. De uiteindelijke film bleek dan ook niets meer te zijn dan die trailer. De rest is totaal niet grappig, en zelfs kinderachting. Verloren tijd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(929,'Black Mass',2015,'561',123,'2016-09-23',8,8,8,7,7,8,'Het aantal blockbuster misdaadfilms is de laatste jaren sterk verminderd. Ik keek dan ook uit naar Black Mass. Het stelt niet teleur, maar is ook geen klassieker. Het is een moderne interpretatie van het misdaadgenre. Goed, in ieder geval, maar er blijft weinig van hangen. De film wordt vooral gedragen door de cast.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(930,'Prisoners',2013,'562',153,'2016-09-25',8,9,9,9,8,9,'Lees de plot van deze film niet, voordat je de film ziet. Want dat verhaal trekt mij echt niet aan. Toch is de uitwerking dermate meeslepend, dat ik deze film tot een van de hits van het jaar benoem. Heel sterk verhaal, sterke vertolkingen, indrukwekkende sfeer. In tegenstelling tot wat je zou verwachten als je de beschrijving leest, is dit allerminst een trieste tearjerker. Onverwacht sterk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(931,'Independence Day: Resurgence',2016,'317',120,'2016-10-04',8,3,3,7,6,7,'Hoewel het dezelfde regisseur betreft, is hem duidelijk ontgaan wat de eerste Independence Day film leuk maakte. Deze overbodige sequel deed mij helemaal niets. Ik begon me zelfs te ergeren over de gemiste kansen. Op geen enkel moment grappig of meeslepend. Of hoe een sequel een serie kan vernietigen...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(932,'Oldboy',2013,'158',104,'2016-10-08',8,8,8,8,7,8,'Een Amerikaanse remake van deze Koreaanse klassieker, maakte me nieuwsgierig, maar ook ongerust. Zeker omdat het meer een actiefilm is, dan het origineel. Spike Lee slaagt er echter in om deze conceptuele veranderingen goed weg te werken in een meeslepende actiethriller. Jammer dat de muziek niet zo\'n rol speelt als in het origineel. Het maakte niet dezelfde indruk als het origineel, maar het zal voor de meeste casual filmfans heel wat toegankelijker blijken te zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(933,'The Jungle Book',2016,'364',106,'2016-10-16',8,8,8,8,7,7,'We zijn aanbeland bij de volgende iteratie van Disney remakes, opnieuw startend met Jungle Book. Nu is niet alles 3D, maar is het real-life en CGI samen. De uitwerking is echter heel goed, tenminste als je verwachtingen niet al te hoog liggen. De film probeert je min of meer succesvol de overdaad aan CGI te doen vergeten. En er zijn net genoeg herkenningspunten om de nostalgie ook te doen opborrelen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(934,'Argo',2012,'563',120,'2016-10-29',8,8,8,8,8,8,'Een film over spionage en politiek lijkt in eerste instantie niet aanlokkelijk, maar deze biografie zet het wel goed neer. Het geeft een andere kijk op de samenwerking tussen Hollywood en CIA. Erg meeslepend, en vooral eens iets anders. Het toont natuurlijk het verhaal vanuit het USA standpunt, maar dat wordt niet echt storend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(935,'Tale of Tales',2015,'564',133,'2016-10-31',4,9,9,8,9,9,'Af en toe duikt er een pareltje op, dat volledig onterecht onder de radar gebleven is. Dit is er zo eentje. Het is een verfilming van minder bekende sprookjesverhalen, die dan ook nog eens dicht bij het origineel aanleunen. Het is geen feel-good film, maar heel erg indrukwekkend. Deze film verdient meer lof dan dat het gekregen heeft.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(936,'The Nice Guys',2016,'565',116,'2016-11-05',8,8,8,8,8,8,'Een ouderwetse seventies actiekomedie is tegenwoordig echt niet meer populair. Ook deze film was geen succes. Het is echter wel een aparte komedie, soms perodiërend, maar heel boeiend. Het doet niets nieuws, maar wat het doet, doet het wel goed. Voor een ontspannen zondagnamiddag is dit ideaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(937,'Finding Dory',2016,'181',97,'2016-11-07',8,7,7,7,6,7,'Ook Pixar is al begonnen met het rebooten van hun successen. Dit is de opvolger van Finding Nemo, die in zijn tijd wel een klassieker werd. Deze film doet bijna exact hetzelfde. Dat betekent dat het ook niets nieuws doet. Het is een typische Pixar film, die zal verdwijnen in de massa. Het is heel degelijk, maar daarmee is ook alles gezegd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(938,'The Legend of Tarzan',2016,'252',110,'2016-11-12',8,5,5,8,7,6,'Door een gebrek aan inspiratie, is men nog eens begonnen aan de zoveelste Tarzan film. En ja, het ziet er wat beter uit dan vroeger. Daar is alles mee gezegd. Het is weinig boeiend, doet niets origineels, en zal dus niet lang in mijn herinneringen blijven bestaan. Een volstrekt overbodige film, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(939,'Sausage Party',2016,'566',89,'2016-11-26',8,NULL,NULL,NULL,NULL,NULL,'Een animatiefilm die meer naar volwassenen gericht is, zo zijn er niet zoveel van. Je verwacht wel wat van  absurde komedies waar Seth Rogen bij betrokken is. Deze film is meer satire en een aanklacht tegen heel wat maatschappelijke omstandigheden. Af en toe grappig, maar helaas niet echt memorabel. Het is weer zo\'n film waarbij de trailer alle goede momenten al verklapt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(940,'The Theory of Everything',2014,'567',123,'2016-11-29',8,7,8,7,8,8,'De biografie van Stephen Hawking zou moeten interessant zijn voor iedereen die ook maar iets met wetenschap heeft. Deze film gaat echter niet in op de wetenschappelijke verwezenlijkingen, maar is een echte biografie. Het gaat dus vooral over zijn relaties en ziekte. Het blijft een goede meeslepende film, maar gar er met de juiste verwachtingen naartoe.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(941,'Fantastic Beasts and Where to Find Them',2016,'252',133,'2017-12-04',5,8,8,9,8,8,'Deze film is geschreven door J.K. Rowling, en wordt ook zo gemarket. Maar als je verwacht een volgende Harry Potter te zien, kom je bedrogen uit. Bekijk je het echter als een losse fantasy avonturenfilm, dan is het best wel goed. Hier en daar zijn er herkenningspunten voor Harry Potter fans, maar voorkennis is geen noodzaak. Een meevaller, maar wel het begin van een lange reeks vervolgen, vrees ik.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(942,'Alice Through the Looking Glass',2016,'568',113,'2016-12-21',8,5,4,9,7,8,'De sequel doet niets nieuws. Het verhaal is flinterdun, en deze film wordt vooral gedragen door de visuele stijl. Daar valt niets op aan te merken, integendeel. Het is een showcase van wat vandaag de dag kan. De cast en personages zijn ook heel interessant. Alleen valt het verhaal zo heel erg tegen, dat ik deze film alleen maar overbodig en nutteloos kan vinden. Een gemiste kans van de bovenste plank.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(943,'Frozen',2013,'569',102,'2016-12-30',8,8,8,8,9,8,'Het is moeilijk om me voor te stellen dat er nieuwe franchises van Disney even grote klassiekers kunnen worden als de bestaande. Toch blijkt Frozen een verrassing te zijn. Daarom vond ik het ook nodig om deze film te kijken, en alle lof is echt niet onterecht. Het doet weinig nieuws, maar Disney heeft hier echt een pareltje afgeleverd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(944,'The Hateful Eight',2015,'107',187,'2017-01-07',8,8,9,8,7,8,'Ik had deze Tarantino film in 2015 gemist. Het is nochtans weer een pareltje. De kritiek is ook terecht: Het doet niets nieuws, en Tarantino voert zijn vaste truucjes nog een keer op. Dat maakt het echter niet minder goed. Na een traag begin, barst het verhaal los, propvol van de boeiende dialogen. Niet voor iedereen, maar je weet wat je krijgt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(945,'Snowden',2016,'34',134,'2017-01-13',8,7,8,8,7,7,'In een poging om het verhaal van Edward Snowden aan het brede publiek te tonen, is deze film gemaakt. Ik snap niet goed waarom, want een documentaire was veel beter geweest. Toch probeert de film een en ander duidelijk te maken voor leken in de materie. Een must-see omdat dit een belangrijke gebeurtenis in de hedendaagse geschiedenis is. Maar voor de film zelf, hoef je het niet te doen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(946,'Suicide Squad',2016,'570',123,'2017-01-14',8,6,6,9,8,8,'Nog een poging van DC om een superhero franchise in filmvorm van de grond te krijgen, na een reeks mislukkingen. Deze film pakt het volgens mij ook verkeerd aan. Je krijgt geen tijd om de personages te leren kennen, en wordt direct in een vrij futloos verhaal gedropt. Een lichtpuntje is Jared Leto als Joker. Die draagt de film grotendeels. Niet slecht, maar just another superhero movie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(947,'Kubo and the Two Strings',2016,'571',101,'2017-01-15',8,8,7,8,7,7,'Een Aziatisch sprookje dat in een westers animatiepak gegoten wordt, is een riskante onderneming. Net als andere gelijkaardige films, valt deze film op door de visuele stijl. Het verhaal is niet ingewikkeld, maar door de aparte manier van vertellen, is het niet altijd evident om de niet uitgesproken gebeurtenissen te begrijpen. Interessant.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(948,'The Lobster',2015,'572',119,'2017-01-20',8,9,9,8,8,9,'Dit omschrijf ik het best als het toppunt van een geschifte regisseur/schrijver die met een bizarre wereld op de proppen komt. Via dit aparte concept, stelt hij maatschappelijke problemen aan de kaak. Ik kan weinig anders schrijven zonder spoilers, dus ik laat het hier maar bij. Apart en memorabel. En hierdoor niet voor iedereen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(949,'Hunt for the Wilderpeople',2016,'573',101,'2017-01-21',8,9,8,8,8,8,'Nooit zou ik dit soort film zelf uitkiezen, maar het werd mij door menig journalist aangeraden. En niet onterecht, zo blijkt. Dit aparte Nieuw-Zeelandse verhaal boeit van begin tot einde. De regisseur en cast tillen de plot naar een hoger niveau. Het is dus een slimme film, die hiet niet moet hebben van achtervolgingen en ontploffingen. Een verborgen en onderschat pareltje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(950,'Blended',2014,'375',117,'2017-02-05',4,NULL,NULL,NULL,NULL,NULL,'Af en toe is het tijd voor een romantische komedie. Meestal valt dat erg tegen, maar soms is er eens een meevaller. Deze film behoort tot de laatste categorie. Door de pers wordt deze film totaal afgebrand, maar ik heb er toch hartelijk om gelachen. Niet hoogstaand, maar wel ontspannend en feel-good.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(951,'The Revenant',2015,'574',156,'2017-02-05',8,8,8,9,7,8,'Een film van dergelijke duurtijd, die overladen is met prijzen en positieve kritieken, bekijk ik altijd met argwaan. Meestal is het de filmindustrie die een arthous film in de bloemen zet, maar waar een gewone liefhebber als ik weinig aan heeft. Deze film is echter een beklijvend en meeslepend avontuur, zich afspelend in een tijd waarover weinig andere films gaan: De Amerikaanse burgeroorlog. Het is een ribbenplakker geworden, waar je je tijd moet voor nemen. Een meesterwerk voor de cinefiel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(952,'Fifty Shades Darker',2017,'182',118,'2017-02-13',5,4,4,7,7,8,'Het vervolg op de zwakke verfilming van de beroemde boeken. De film kruist alle vakjes aan, maar loopt in dezelfde val als veel andere boekverfilmingen: Alles moet veel te snel uitgelegd en getoond worden. De serie begon zwak, en lijkt steeds zwakker te worden. Laat dit niet meer doen door preutse Amerikanen, aub.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(953,'Contact',1997,'16',150,'2017-02-17',8,9,9,8,7,9,'In 1997 was deze film niet echt een groot succes. Maar 20 jaar later is dat enigzins anders. Dit is is een van de weinige films die er in slaagt een revival mee te maken en ook de tand des tijds te doorstaan. De film zelf is boeiend en zit knap in mekaar. Het slaagt er in om net voldoende vragen te beantwoorden, en evengoed open te laten. Een ondergewaardeerde sci-fi klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(954,'The Amazing Spider-Man',2012,'575',136,'2017-02-18',8,6,7,7,6,7,'Door licentieproblemen en meningsverschillen is dit een reboot van de serie van een paar jaar er voor. Bizar, maar goed. De film probeert het iets anders aan te pakken, maar het is heel lastig om niet met de vorige serie te vergelijken. Het is beter dan de vorige serie, naar mijn mening, maar volstrekt onnodig. Deze serie zal om gelijkaardige redenen ook ter ziele gaan, over enkele jaren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(955,'Borowed Time',2012,'576',88,'2017-02-24',8,6,6,6,7,6,'Het is weer tijd voor een low-budget non-American film. Dit keer over de confrontatie tussen een oude verbitterde man, en een tiener zonder toekomst. Het is soms grappig, en probeert soms wat zwaarmoediger te worden. Het sleept mij echter niet mee, en schiet feitelijk overal te kort. Waarschijnlijk enkel leuk voor inwoners van de streek waar het gefilmd is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(956,'Transformers: Age of Extinction',2014,'98',165,'2017-03-02',8,4,3,6,7,8,'Waar veel comic of superhero verfilmingen last van hebben, is dat de origin story, de eerste film, wel goed is, maar alle vervolgen steeds minder zijn. Bij de Transformers reeks is dat misschien het allerergst. Deze vierde film in de reeks houdt vrij weinig steek. Het is een feest van CGI, zoals steeds, en het verhaal is inwisselbaar. Ook de duurtijd getuigt van enige arrogantie. Deze serie mag gerust stoppen, wat mij betreft. Dit is al uit mijn geheugen gewist.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(957,'Thunderball',1965,'469',130,'2017-03-11',8,7,7,7,7,6,'Met de vierde Bondfilm kwam de serie pas echt goed op dreef. Het is een van de klassiekers, met Sean Connery. Er zijn weinig woorden meer aan vuil te maken. Ik denk dat iedereen wel weet wat je kan verwachten: Een klassieke Bondfilm uit de sixties.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(958,'The Accountant',2016,'577',128,'2017-03-12',8,8,8,8,7,8,'Actiefilms gebaseerd op een boek zitten meestal wel goed. Er is meestal een goed plot om op terug te vallen. Dit is hier ook het geval. Het is een klassieke hero-actiefilm, zonder zich al te serieus te nemen. Gewoon goed gedaan, in zijn genre. Zeker goed genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(959,'As Good as It Gets',1997,'578',139,'2017-04-23',4,7,8,7,8,6,'Dit is een romantisch drama, soms komedie, die ik destijds heb gemist. Het genre en de plot is niet echt aanlokkelijk, maar het is zo\'n film die wel boeit als je hem ziet. Laten we eerlijk zijn, het is ook een klassieker in het romantische genre. Dialogen verrassen soms in een anderzijds vrij trage film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(960,'Jennifer Westfeldt',2011,'579',107,'2017-04-24',4,7,7,6,7,6,'Het lijkt wel de periode van de romantiek hier, maar ook nu is het er weer van gekomen. Lees de plot niet, want het lokt niet echt aan. Het biedt ook weinig nieuws: een romantische film met een lach en een traan. Niet echt 13 in een dozijn, door wat er in de loop van de film gebeurt. Maar ook geen klassieker in het genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(961,'A Monster Calls',2016,'580',108,'2017-04-30',8,9,9,9,8,8,'Dit lijkt op een sprookje, maar is in realiteit een donker verhaal over een kind dat moeite heeft met zijn huidige situatie. Schitterend beeld en geluid. Het is een echte ribbenplakker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(962,'Arrival',2016,'562',116,'2017-05-07',8,9,9,9,8,9,'Hoewel dit lijkt op nog een alien invasion film, is het onderliggende thema toch iets helemaal anders. Muziek en beeld dragen bij tot iets unieks. Als je geen actiefilm verwacht, kan dit wel eens een verrassing zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(963,'Sing',2016,'581',108,'2017-05-14',8,5,5,7,8,7,'Een animatiefilm van dertien in een dozijn, helaas. Als je de trailer niet hebt gezien, is het af en toe wel grappig. Maar daarnaast schiet er weinig over. Na enkele weken kon ik me nog met moeite iets herinneren, en begon deze film te verwarren met andere animatiefilms. Dat zegt genoeg.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(964,'Rogue One',2016,'513',133,'2017-05-25',8,8,7,8,8,8,'Terwijl de meestgehoorde kritiek toch wel terecht is (deze film is totaal overbodig in de Star Wars-saga), is het toch wel een leuk kijkstuk geworden. Het is een onderhoudende film, vooral omdat het Star Wars universum gewoon boeiend blijft. Toch is dit een wat overbodige film, en ruikt naar uitmelkerij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(965,'Assassin\'s Creed',2016,'582',115,'2017-05-26',8,6,6,7,7,7,'Het verfilmen van een game loopt zelden goed af. Ook hier zullen de fans van de game op hun honger blijven zitten. Voor leken is dit een vrij onderhoudende actiefilm, waar net voldoende wordt uitgelegd om te kunnen volgen. Een typisch \"De boeken zijn beter\" verhaal, maar toch niet slecht ook.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(966,'Mindhorn',2016,'583',89,'2017-06-05',8,8,8,7,8,7,'Knipogend naar de seventies detectiveseries, weet deze typisch Britse komedie wel te overtuigen. De absurditeit viert hoogtij. Hoewel de film in het middenstuk gewoon traag is, en begint te vervelen, vind ik dit absoluut en verborgen pareltje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(967,'Demain tout commence',2016,'584',118,'2017-06-05',8,9,9,8,9,8,'Wat lijkt op een Franse film over een onhandige propper met een dochtertje, neemt toch een enorme plottwist. Dit pakkende verhaal blijft boeien van begin tot einde, al moet er wel bij worden gezegd dat het budget voor visuele effecten wel op was na het eerste kwartier. Een van de onverwachte treffers van de laatste jaren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(968,'Morgan',2016,'585',92,'2017-06-07',8,7,7,7,7,8,'Het lijkt wel de nieuwe hype: films over AI. Deze film doet weinig nieuws, en doet het ook niet op een uitzonderlijke manier. Het lijkt soms zelfs wat low-budget. Toch blijf je op de een of andere manier aan het beeld gekluisterd. Onderhoudend en niet slecht. Maar wel voorspelbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(969,'The Mummy',2017,'586',210,'2017-06-23',5,7,7,8,8,7,'Het lijkt een onnodige remake van de film van enkele decennia geleden. Het is echter al bij al niet slecht, vooral de actiescènes zijn best indrukwekkend. Het is ook de start van het DC Dark Universe. Dat maakt het feitelijk een superhero-movie. Dat is meteen een negatieve connotatie, en wanneer je het eenmaal beseft, is je mening gekleurd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(970,'Ghost in the Shell',1995,'587',83,'2017-06-27',8,8,8,8,9,8,'Deze klassieker in het animatiegenre heb ik bekeken omdat de Amerikaanse remake uitkomt. Het is soms wat lastig om te volgen, omdat de gewoonlijke verhaalpatronen hier totaal afwezig zijn. Maar zet dat even opzij, en je kan zien dat dit een pareltje in zijn genre is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(971,'Get Out',2017,'588',104,'2017-06-28',8,8,8,8,7,7,'Deze film is niet wat het in eerste instantie lijkt. Het gaat feitelijk niet over vooroordelen en racisme. Het is ook geen gore horror, maar meer een constant ongemakkelijk gevoel. Er is een verrassende plottwist. Het is boeiend van begin tot einde, maar uiteindelijk wel wat teleurstellend. Origineel, maar niet echt memorabel. De cast en regie blinkt wel uit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(972,'Logan',2017,'147',137,'2017-06-30',8,8,8,9,7,8,'Dit zou de laatste film over Wolverine moeten worden in het X-men universum. Het is meteen ook een unieke film in de reeks. Waar de andere films kleurige feel-good superhero actiefilms waren, is dit donker, melancholisch en hard. Dit is wat het X-men universum altijd moest geweest zijn. Knap, op alle gebied. Alleen mis ik iets waardoor ik deze film minder snel zou vergeten...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(973,'The LEGO Batman Movie',2017,'589',104,'2017-07-01',8,7,7,8,8,7,'Deze spin-off van de eerdere LEGO film, is meer van het zelfde. Dat is niet noodzakelijk slecht, want de humor is goed, vooral voor volwassenen. Toch verslapt deze film meer en meer, naarmate hij vordert. Dan zie je toch dat het verhaal niet de eerste prioriteit was. Jammer, maar zeker genietbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(974,'Wonder Woman',2017,'590',141,'2017-07-04',5,7,6,8,7,8,'De volgende telg in het DC universe is Wonder Woman. Deze film doet het net iets anders dan Marvel. Het had enkele jaren geleden een grote hit kunnen zijn. Maar het voelt helaas al afgezaagd nu. De referenties naar de Eerste Wereldoorlog, en naar België zijn leuk. Het vervalt echter in een gewone boss-battle en eindigt op een sisser.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(975,'John Wick: Chapter 2',2017,'544',122,'2017-07-08',8,8,6,9,8,8,'Je weet wat je krijgt met John Wick: Spetterende actie en een flinterdun verhaal. Weinig anders over te zeggen. Alleen irriteert het me dat deze film op een duidelijke cliffhanger eindigt, voor het vervolg. Typisch en jammer. Kijk dus deel drie (dat op dit moment nog niet uit is) meteen ook maar. Of wacht tot het uit is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(976,'A Street Cat Named Bob',2016,'231',103,'2017-07-11',8,7,6,7,7,7,'De kat Bob is een echte internethype, een levende meme. Dit is de biografie van zijn baasje, en hoe de kat beroemd werd. Het is een feel-good verhaal, dat vooral kattenliefhebbers zal aanspreken. Leuk voor een zondagnamiddag, maar niet diepgaander dan dat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(977,'Ghost in the Shell',2017,'591',107,'2017-07-16',8,8,8,9,9,8,'Enkele weken heb ik het origineel gezien, een Japanse animatiefilm. Dit is de Amerikaanse remake, als \"gewone\" film. Het concept van respect voor het origineel is wel heel erg doorgedreven hier. Bepaalde scènes zijn perfecte replica\'s, en de soundtrack is zo goed als dezelfde. Deze film is toegankelijker dan het origineel, en is bijlange niet slecht. Het is wel echt deep sci-fi, dus daar moet je wel mee om kunnen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(978,'Brimstone',2016,'592',158,'2017-07-22',8,7,8,7,8,7,'Een ondergesneeuwde western, met Nederlandse invloeden. Dit hele donkere verhaal voelt constant ongemakkelijk aan, en is iets wat je niet snel zal vergeten. De verhaalvertelling in hoofdstukken is iets wat je vaker in westerns ziet, maar hier niet echt werkt. Hard en pakkend, en dus niet voor tere zieltjes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(979,'I.T.',2016,'481',95,'2017-07-23',8,2,2,5,6,6,'Het is gebruikelijk dat Hollywood een tweetal jaar na een gebeurtenis een hele reeks films over dat ondewerp maakt. Deze film gaat over privacy en het internet, zoals zovele tegenwoordig. Het is helaas ook een voorbeeld van hoe je dit zo slecht mogelijk doet. De film getuigt van een gebrek aan kennis over het onderwerp. Het eenvoudige clichéverhaal, wat trouwens meer op een eighties actiefilm gebaseerd lijkt te zijn, trekt op niets.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(980,'Clash of the Titans',2010,'355',106,'2017-08-05',8,5,4,7,7,8,'Dit is het zoveelste voorbeeld van een schitterende fantasy epos, die door tijdsgebrek de nek wordt omgewrongen. Veel te veel inhoud, waardoor elke character building ontbreekt. Hierdoor blijft er niets hangen, terwijl het toch niet zo moeilijk zou moeten zijn om iets deftigs te doen met de rijke Griekse mythologie. Verspilling van geld en tijd. Waarom hier geen serie van maken?','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(981,'Kong: Skull Island',2017,'593',118,'2017-08-08',8,6,5,7,7,8,'Dit is de meest recente in een lange rij van inspiratieloze en zinloze reboots. Het biedt een nieuwe versie van de King Kong films, die verder weinig met het origineel te maken heeft. Het is een leuk actie-avontuur, maar daar is ook alles mee gezegd. Het feit dat deze film het begin is van een nieuwe superhero reeks, is geen goed teken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(982,'Alien: Covenant',2017,'54',122,'2017-08-12',4,7,7,8,8,8,'Het vervolg op Prometheus, wat een prequel voor Alien was, veroorzaakte hoge verwachtingen. En het is geworden wat je ervan verwacht: Een typische Alien film, met de gebruikelijke spanning. Wat ook gebruikelijk is, is het aantal niet verklaarde verhaallijnen, en andere mysteries waar je geen antwoord op krijgt. Als je dat niet stoort, is dit best een goeie film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(983,'Baby Driver',2017,'493',112,'2017-08-15',5,6,6,9,9,8,'Een klassieke heist-movie met dergelijken namen in de cast, schept hoge verwachtingen. Die maakt deze film ook wel waar: het is een ritmische klassieke actiefilm geworden. Leuk voor een zondagnamiddag, maar meer ook niet. Echt memorabel kan je dit bezwaarlijk noemen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(984,'Split',2016,'53',117,'2017-08-26',8,7,8,6,7,8,'Een film van M. Night Shyamalan is altijd een beetje hit-or-miss. En na een aantal jaren is dit nog eens een hit. Het biedt precies wat zo\'n film qua spanning en sfeer moet geven, zonder een absolute klassieker te zijn. Het thema maakt het soms wat langdradig, en zelfs voorspelbaar. Maar je blijft toch kijken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(985,'The Circle',2017,'594',110,'2017-09-01',8,7,7,9,8,8,'Ondanks de overtuigende negatieve kritieken op deze film, was dit best boeiend. Ondanks het volledig missen van de realiteit van het gevaar van gebrek aan privacy, is dit wel best een onderhoudende film. Vooral de beeldvoering is vrij uniek. Erger je niet aan het verhollywooden van moeilijke onderwerpen, en je hebt een leuke avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(987,'You Only Live Twice',1967,'595',117,'2017-09-03',4,7,7,7,7,6,'De zesde Bondfilm (de vijfde officiële), is weer wat je er van kan verwachten. Niets hoogstaands of uitzonderlijk, maar wel weer een klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(988,'On Her Majesty\'s Secret Service',1969,'596',142,'2017-09-04',8,8,7,7,7,7,'Dit is de eerste (officiële) Bondfilm zonder Sean Connery. En het is echt wel een buitenbeentje in de reeks. Hij krijgt minder goede cijfers, maar het is toch een serieuzere en vooral donkerdere film geworden. Het probeert wat meer achtergrond te geven over Bond. Het was een riskante keuze, en zeker ook de nieuwe Bondvertolker ligt niet voor de hand. You love it or you hate it.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(990,'Wakefield',2016,'597',106,'2017-09-07',8,7,7,7,8,7,'Dit is zo\'n film waarbij de korte inhoud meteen interesse wekt. Het uitgangspunt is origineel. Je vraagt je echter tegelijk af hoe je hier een hele film over maakt. En daar knelt het schoentje. Dit had ook een kortfilm kunnen zijn. Het is in ieder geval iets anders, al vinden sommigen het iets te bizar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(991,'Angels & Demons',2009,'132',138,'2017-09-08',8,7,7,8,9,8,'Toen The Da Vinci Code een onverwachte hit werd, kwam al snel deze opvolger. Het doet weinig nieuws en borduurt verder op de succesformule van zijn voorganger. Laat voldoende tijd tussen, en dan is deze film zeker interessant. Maar zoals zo vaak is het origineel beter.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(992,'Inferno',2016,'132',121,'2017-09-10',8,7,7,8,9,8,'Deze derde film uit de The Da Vinci Code reeks, voelde duidelijk de bui al hangen. Er wordt koortsachtig geprobeerd om iets nieuws te doen. Onder het oppervlakkige laagje originaliteit, komt echter al weer snel de klassieke formule boven. Niet te snel achter de vorige films bekijken, en dan is deze film best OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(993,'The Man with the Golden Gun',1974,'30',125,'2017-09-16',8,7,7,7,7,6,'De volgende Bondfilm met Roger Moore. Wat kan je nog meer zeggen? Een klassieke Bondfilm. Ik hou persoonlijk meer van de sixties-sfeer. Deze film zit echt midden in de seventies.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(994,'The Spy Who Loved Me',1977,'595',125,'2017-09-21',8,6,6,6,7,7,'Dit is de eerste Bondfilm die, naar mijn gevoel, voor het eerste echt te veel wil doen. Het wordt door de technische beperkingen van de tijd echt ongeloofwaardig. Voor zover Bondfilms dat ooit geweest zijn. Deze hoort thuis in de Bondgeschiedenis, maar het is niet de beste film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(995,'Moonraker',1979,'595',126,'2017-09-22',8,5,6,5,7,7,'Waar de vorige film al over-the-top was, slaat deze film volledig de bal mis. In een tijd waarin Sci-fi het nieuwe buzzword was, moest Bond zeker mee. Het resultaat is, naar mijn mening, de slechtste Bondfilm. De broodnodige special effects in de ruimte worden volstrekt ongeloofwaardig als je dit op een hedendaagse TV bekijkt. Voor die tijd misschien OK, maar de tand des tijds is onverbiddellijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(996,'Jupiter Ascending',2015,'598,599',127,'2017-09-23',8,7,6,7,7,8,'Er was een tijd waarin deze blockbuster sci-fi films echte klassiekers waren. Nu zijn er echter zo veel van, dat je riskeert onopgemerkt te blijven. Bij deze film is dat ook het geval. De enkele interessante opflakkeringen kunnen deze film niet redden van de vergetelheid. Het is allemaal niet slecht, maar ook allemaal niet goed genoeg.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(997,'For Your Eyes Only',1981,'600',127,'2017-09-24',8,7,7,7,8,7,'Dit is misschien wel de beste Roger Moore Bondfilm. Het is een klassieker in de reeks, maar ook niet meer dan dat. Vooral de mengeling tussen seventies en eighties is memorabel. Voor de rest is er weinig over te zeggen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(998,'Power Rangers',2017,'601',124,'2017-09-30',8,NULL,NULL,NULL,NULL,NULL,'Een ding is duidelijk: Bekijk deze film alleen uit nostalgische overwegingen. Enkel de referenties naar de originele serie maken dit een leuke film. Het verhaal zelf is flinterdun, oppervlakkig en voorspelbaar. Het is echter leuk om eens de nieuwe CGI in het Power Ranger-universum te zien. Pure nostalgie. Maar laat het links liggen als je niets met de Power Rangers hebt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(999,'The Lost Boys',1987,'106',97,'2017-10-02',8,8,8,8,8,7,'Dit is weer zo\'n vergeten klassieker die volledig aan mij voorbij is gegaan. Het is ongetwijfeld de beste teen-horror film uit de eighties. Het past in het rijtje, en is eigenlijk geen slechte film. Hoewel de meesten vooral uit nostalgie praten, staat de film nog wel overeind tegenwoordig. Het eighties sfeertje moet je er wel bij nemen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1000,'Don\'t Breathe',2016,'541',88,'2017-10-31',8,7,7,8,7,7,'Op Halloween kan er altijd wel een claustrofobische horrorfilm bij. Deze film doet absoluut niets nieuws, maar alle clichés worden vrij rond gestrooid. Het is niet hoogstaand, maar wel snoep voor horrorliefhebbers. Het is vooral de constante spanning, en niet de blood-and-gore, die ik mij herinner. Die is zelfs vrij afwezig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1001,'War Machine',2017,'602',122,'2017-11-25',8,4,4,7,7,7,'Deze film heb ik bekeken na enkel de tag-line te hebben gelezen. Maar dat is helaas ook het beste wat deze film te bieden heeft. Na een sterke opening, verwatert het volledig. En het typetje van Brad Pitt wordt al heel snel gewoon irritant. Het enige wat over blijft is wat ongemakkelijke maatschappijkritiek. Jammer, maar geen aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1002,'Batman v Superman: Dawn of Justice',2016,'363',151,'2017-12-02',8,7,7,8,8,8,'Het cinematic universe van DC zit in het slop. Deze film wordt wereldwijd met de grond gelijk gemaakt. Ik vermoed dat ik een eigenaardige smaak heb, want ik kan het meeste wat DC maakt, wel smaken. Hoewel de titel gewoon afkeuring uitlokt, is dit bijlange zo slecht niet als de reviews doen vermoeden. Ik kon het echt appreciëren. Alleen word ik stilaan wel wat Superhero-moe.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1003,'Guardians of the Galaxy Vol. 2',2017,'514',136,'2017-12-09',8,6,6,8,8,7,'Na het onverwachte succes van de eerste film, waren de verwachtingen voor de sequel hooggespannen. Deze luchtige actiekomedie kon soms wel een glimlach veroorzaken, maar niet meer dan dat. Wat de eerste film goed deed, verwatert net in deze film. Leuk en ontspannend, maar helaas voer voor de vergetelheid. Teleurstellend, maar enkel omdat de eerste film zo verrassend was.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1004,'The Day After Tomorrow',2004,'603',124,'2017-12-10',8,6,6,8,7,7,'Tussen 2000 en 2010 werden we overspoeld door rampenfilms. Dit is er ook een in dat rijtje. Je weet wat je kan verwachten: Moraliteit, America en ongeloofwaardige actie. Dit is dus een echte popcorn-op-zondagnamiddag film. Hoewel de visuals in de bioscoop misschien nog wel voor wat spektakel zorgden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1005,'Goldfinger',1964,'30',110,'2017-08-28',8,7,7,6,7,6,'Volgens critici is dit nog steeds de beste Bondfilm uit de geschiedenis. Het doet in ieder geval alles wat een goeie Bondfilm moet doen. Dus in die zin is het de film die het meest trouw is aan de serie. Je weet wat je kan verwachten, het is een Bondfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1006,'Octopussy',1983,'600',131,'2017-10-15',8,7,7,7,7,7,'Halfweg de eighties worden de Bondfilms stilaan volwassen. Het knullige, wat vooral opvalt op hedendaagse TVs, is er wat af. Het is echter \"gewoon\" een Bondfilm, spectaculair in zijn tijd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1008,'A Clockwork Orange',1971,'248',136,'2017-12-12',8,8,8,8,7,7,'Hoe bizar ook, deze film had ik nog nooit gezien. Het is een klassieker en heeft dus ook weinig commentaar nodig. Het is in ieder geval niet voor iedereen. Er is een constant ongemakkelijk gevoel, maar toch wil je weten wat er gebeurt. Indrukwekkende sfeer en acteerprestaties alom.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1009,'A View to a Kill',1985,'600',131,'2017-12-14',8,7,7,7,8,7,'Dit zijn beslist de hoogdagen van het klassieke Bondgenre. Deze film doet alweer niets nieuws, en gebruikt alle elementen uit het klassieke recept. Bij elke film gaat de technologie echter zo sterk vooruit, dat het toendertijd heel indrukwekkend moet geweest zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1010,'Casino Royale',1967,'604',131,'2017-12-17',8,5,6,5,6,7,'Door allerlei juridische kwesties is deze film uiteindelijk een komisch buitenbeentje geworden. Het is iets erg bizars geworden. Het wil absurde humor zijn, maar slaat soms echt wel de plank mis. Hoe verder de film vordert, hoe erger de chaos wordt. Mocht dit geen Bondfilm geweest zijn, was hij al lang vergeten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1011,'The Living Daylights',1987,'600',130,'2017-12-23',8,7,7,7,7,7,'Timothy Dalton wordt door velen verguisd als Bond, maar ikzelf vind het een verademing. De iets donkerdere vertolking draagt bij tot een wat minder lichtverterend, maar wel serieuzer verhaal. You love it or you hate it. De meeste Bond-puristen zijn echter onverdeeld tegen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1012,'Marina',2013,'605',118,'2017-12-24',4,8,8,8,7,7,'Het verhaal van Rocco Granata is nu niet bepaald een aanlokkelijk plot, zou je denken. Het is echter een aangenaam romantisch verhaal geworden, zelfs pakkend op sommige momenten. Het donkere thema van gastarbeid onder het romantische verhaaltje, zal echter niet iedereen bevallen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1013,'License to Kill',1989,'600',133,'2018-03-06',8,7,7,7,7,7,'De tweede en laatste Bondfilm met Dalton heeft naar mijn mening een iets te eighties-feel. Het probeert, voor die tijd, een moderne film te maken, maar vervalt wel in de klassieke Bondpatronen. Gelukkig is de vertolking van Dalton van een beter niveau. Helaas zijn de Bond-puristen het niet met mij eens.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1015,'Blade Runner 2049',2017,'606',164,'2018-01-05',8,9,9,10,10,9,'Met enige argwaan zag ik een trailer van deze film, en ik was direct verkocht. De sfeer en muziek zijn onnavolgbaar. Het is echt een vervolg, dus geen remake. Maar de vrees dat deze film het origineel oneer ging aandoen, is niet gegrond. De film van het jaar, en het is nog maar 5 januari.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1016,'Tomorrow Never Dies',1997,'231',119,'2018-01-06',8,6,5,7,6,6,'De Bondfilms met Brosnan gaan meer en meer bergaf. Hier proberen ze nog, met enig succes, wat oosterse invloeden in een Bondfilm te krijgen. Inhoudelijk is dit echter flinterdun, en geloofwaardig is het ook al niet. Bond die met een gezins-BMW rijdt, dat ging me net iets te ver.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1017,'He Never Died',2015,'607',99,'2018-01-13',8,8,8,7,7,8,'De titel verraadt al waar deze film heen gaat, en dat wordt geen teleurstelling. Er is zelfs iets van een cultklassieker. Een ietwat teleurstellend slot kan echter de pret niet drukken. Een boeiende film, af en toe grappig, en vooral sterke actie. Het hoeft niet altijd zo megalomaan te zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1018,'The World Is Not Enough',1999,'608',128,'2018-01-19',8,6,5,7,7,6,'Nu zelfs de Bondmeisjes al niet meer kunnen acteren, bereikt de Bondfilm een triest dieptepunt. Een ongeloofwaardig verhaal, met al even ongeloofwaardige actie. Het is alles wat een klassieke Bondfilm niet goed maakt. Het blijft een Bondfilm, maar anders had deze film de tand des tijds niet doorstaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1019,'Bright',2017,'570',117,'2018-01-20',8,7,7,8,7,8,'Deze Sci-fi film wordt internationaal compleet met de grond gelijk gemaakt. Het probeert Amerikaanse maatschappelijke problemen op een alternatieve manier aan te kaarten, en dat wordt ze niet in dank afgenomen. Ik vind deze film echter best goed. Het verhaal laat wel enkele kansen liggen om dieper uit te werken. Iets trager en dieper, en het harde oordeel was waarschijnlijk wat milder. Het is een guilty pleasure. Het is not-done om dit goed te vinden, maar ach...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1021,'Moana',2016,'609',107,'2018-02-10',8,6,6,8,8,7,'Disney probeert elk jaar wel een nieuwe franchise te lanceren, en hopen dat er iets blijft plakken. Dat is gelukt met Frozen, en dat proberen ze nu ook met Moana. Het doet echter weinig origineels. Je kan stellen dat het iets donkerder is, vooral naar het einde toe, maar het blijft een Disney film met de vaste structuur, en de typische plakkende muziek. Goed, niet memorabel. Misschien enkel de muziek die in je hoofd blijft zitten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1022,'The Hitman\'s Bodyguard',2017,'610',118,'2018-02-24',8,8,7,8,8,8,'Een high-profile actiekomedie met Ryan Reynolds en Samual L. Jackson. Daar verwacht je vuurwerk van. Het stelt niet teleur. Het is geen klassieker, maar absoluut een genietbare avondvuller. Gewoon een oerdegelijke actiekomedie, volgens de regels van de kunst.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1023,'Bloodsport',1988,'611',92,'2018-04-01',4,4,4,6,7,6,'De grote doorbraak van Van Damme is een klassieker in het genre, maar kan de eighties niet overleven. Het verhaal is flinterdun en vol van de clichés. Omdat het zo lang geleden is, stoort dat minder, en wordt het wel weer eens leuk. Over het algemeen beter links laten liggen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1024,'The Meaning of Life',1983,'116',107,'2018-04-13',8,4,4,5,5,5,'De laatste film van Monty Python is zo absurd, dat het ongemakkelijk wordt. Waar de eerste films gewoon goeie komedies waren, is dit bij momenten ongelooflijk bizar. Voor mij gaat dit te ver. De enige reden om dit te kijken, is omdat ze krediet hebben opgebouwd met de vorige film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1025,'Star Wars: Episode VIII - The Last Jedi',2017,'473',152,'2018-04-15',8,8,8,8,9,8,'Van een Star Wars film uit een trilogie verwacht je net dat tikkeltje meer. Een teleurstelling is het niet, maar het is tegelijkertijd ook maar een film uit de rij. Niet meer dan dat. Geen teleurstelling, maar ook geen blijvende indruk. Het blijft Star Wars, dus er is altijd wel wat magie rond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1026,'Some Kind of Beautiful',2014,'612',99,'2018-04-27',4,6,6,6,6,6,'Soms is er een film die tijdens het zappen je aandacht trekt, en dat was hier het geval. Helaas is het een vrij gewone romantische komedie, met weinig anders om het lijf. Een perfecte film voor een regenachtige zondagnamiddag.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1027,'Bad Boys II',2003,'98',157,'2018-05-28',4,7,7,7,8,7,'Na het succes van de eerste film, heeft het vervolg wat last van arrogantie. De duurtijd zorgt er mee voor dat dit over het algemeen een teleurstelling is. Het blijft natuurlijk wel een leuk concept, en de wisselwerking tussen de hoofdrolspelers is weer goed, maar deze film had niet gemaakt moeten worden. Het doet precies hetzelfde als het origineel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1028,'Cirque du Freak: The Vampire\'s Assistant',2009,'25',109,'2018-06-18',4,6,5,8,7,7,'Soms heb je fantasy films met een sterke cast, waarbij de trailer het beste doet verwachten. Het komt echter vaak voor dat de film zelf de verwachtingen niet inlost. Helaas is dat hier ook het geval. Het sfeertje en de personages trekken aan, maar de uitwerking komt nooit van de grond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1029,'Game Night',2018,'613',100,'2018-06-30',8,8,8,7,9,8,'Het is best wel lang geleden dat ik nog zo gelachen heb met een klassieke komedie. Dit soort komedies komen ook al niet te vaak meer voor, en als ze dan al eens verschijnen, dan zijn de trailers beter dan de film zelf. Dit echter niet. De acteurs zijn heel goed gecast, want de timing van de humor maakt alles. Ook de muziek valt positief op.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1030,'Spirited Away',2001,'547',125,'2018-07-04',8,8,8,8,7,7,'Deze film wordt door velen aanzien als een van de meesterwerken van Studio Ghibli. Dus het moet wel iets zijn wat je kan appreciëren, het is niet voor iedereen. Ik kan wel de mythische status begrijpen. De personages en de sfeer ademen liefde van de makers uit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1031,'Rango',2011,'144',107,'2018-07-07',8,7,6,8,9,8,'Een animatiefilm in het wilde westen. Het is een originele input, en zit vol verwijzingen naar Fear and Loathing in Las Vegas. Een andere film waarin Johnny Depp de hoofdrol speelt. Best lachen, maar ook niet meer dan dat. De muziek en het sfeertje maken deze film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1032,'Koko Flanel',1990,'605',95,'2018-07-09',4,6,5,4,6,5,'In de jaren 90 waren er wel meerdere Belgische films met comedians. De films zijn stuk voor stuk mislukkingen, en zien er niet B, maar C uit. Koko Flanel hoort thuis in die lijst, maar is wel een van de betere. Af en toe best grappig, maar je moet door het amateurisme kijken, die toen de norm was in de Vlaamse filmscene.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1033,'Untouchable',2011,'614',112,'2018-08-02',8,8,8,8,9,8,'Dit is een hartverwarmend verhaal over hoe uitschot voor een gehandicapte man gaat zorgen. Hoewel er achteraf bekeken heel wat clichés in verwerkt zijn, valt het eigenlijk niet echt op. Ik heb ook af en toe hardop moeten lachen. Dat is iets waar ze in Hollywood nog iets kunnen van leren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1034,'Annihilation',2018,'536',115,'2018-08-10',8,7,8,9,8,8,'Dit lijkt in eerste instantie het zoveelste sci-fi verhaal van een team wetenschappers die in een buitenaards park gaan ronlopen. Midden in dat standaardverhaal is er echter een verrassende plot-twist, die het plots veel interessanter maakt. Je moet er wel wakker voor zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1035,'Deadpool 2',2018,'615',119,'2018-08-15',8,7,7,8,8,8,'Dit is precies de film die je zou verwachten. Deadpool ten voeten uit. Ik vond de eerste film eerder overhyped, en deze volgt precies in dat spoor. Leuk, en af en toe een beetje stout. Maar dat neemt niet weg dat ik me deze film bijna niet meer herinner.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1036,'The King of Kong: A Fistful of Quarters',2007,'533',119,'2018-08-15',8,7,7,6,7,7,'Deze docu over de beginjaren van gaming, en de eeuwige jacht op records, is een must-see voor gamers. Het is een wat gekleurde blik op hoe de Donkey Kong legende Billy Mitchell er blijkbaar alles voor over heeft om een record te behouden. Het lijkt eerder een maffioso, dan een gamer. Dat maakt het wel wat ongeloofwaardig en eenzijdig. Het geeft wel een blijk in een voor mij onbekende wereld.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1037,'Ferdinand',2017,'120',108,'2018-08-20',8,6,5,7,7,7,'Fox probeert ook al een tijdje mee te liften op de animatie-hype van de laatste jaren. Helaas vallen ze terug op Amerikaanse clichés, die weinig toevoegen aan het genre. Zeker omdat ik in deze periode ook echte pareltjes heb gezien, niet van Fox dan, maakt dit een moeilijk verhaal. Het is leuk voor de kleintjes, maar laat dit gerust links liggen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1038,'Coco',2017,'616',105,'2018-08-21',8,9,9,10,9,9,'Dit pareltje van een animatiefilm had ik bijna gemist. In al het geweld van animatiefilms leek dit verhaal niet echt op te vallen. Dat viel echter even mee. Het is een goeie komedie, zowel voor jong als oud. Maar bovenal is het een vertederend verhaal over familiebanden. Voor mij nu al de film van het jaar. De stijl en de muziek maken het helemaal af.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1039,'Black Panther',2018,'617',134,'2018-08-22',8,7,7,8,8,7,'Nu ik al het superhero-geweld wat moe aan het worden ben, liet ik in eerste instantie deze film aan mij voorbij gaan. Echter, door de goeie reviews, heb ik deze toch bekeken. En de reviews zijn op zich wel terecht. Het is een goeie superhero-film, zonder meer. De Amerikaanse politiek-correctheid en Black-clichés moet je er maar bij nemen. Al bij al blijft deze film niet bij mij hangen. Het is en blijft gewoon een superhero-movie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1040,'Edward Scissorhands',1990,'50',105,'2018-09-23',8,7,7,8,7,7,'Dit is een van de eerste wapenfeiten van de Tim Burton-Johnny Depp combo. Het mooie sprookje heeft echter niet echt de tand des tijds doorstaan, vind ik. Het is een vertederend verhaal, maar het is vooral nostalgie die spreekt. Hoewel de film best origineel uit de hoek komt, en de sfeer typisch Burton is, kon het me niet echt overtuigen om dit in de all-time hall-of-fame te zetten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1041,'Sicario',2015,'562',121,'2018-09-24',8,8,8,9,8,8,'Met veel aandacht kijk ik steeds uit naar een film van Denis Villeneuve. Dit is een donkere revenge-movie in het Zuid-Amerikaanse misdaadmilieu. En het stelt niet teleur. Hoewel het geen klassieker genoemd kan worden, zowel voor mij als voor de rest van de wereld, is het zeker een indrukwekkende actie/misdaadfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1042,'The Visit',2015,'53',94,'2018-11-02',8,7,7,9,8,8,'Een horrorfilm van M. Night Shyamalan betekent dat het met de sfeer wel goed zit. Het ietwat claustrofobische verhaal, waarbij er steeds iets onbekends om de hoek loert, weet de spanning op te bouwen. Alleen schiet het slot hierin wat te kort. Dat hebben wel meer van zijn films. Leuk voor een halloween-avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1043,'Incredibles 2',2018,'229',118,'2018-11-16',8,6,5,7,6,7,'Het vervolg op het inmiddels al vrij oude eerste deel, is meer van hetzelfde. Het verhaal is mager, en de gekende personages keren terug. De baby is de smaakmaker van deze film. Als die verhaallijn er niet had in gezeten (en als het voor ons niet zo herkenbaar zou geweest zijn), dan was er hier weinig aan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1044,'Ready Player One',2018,'8',140,'2018-11-16',8,6,5,7,8,8,'Midden in de VR-hype kon een tiener-actiefilm hierover niet ontbreken. Je kijkt voornamelijk naar CGI, en naar de Hollywood-interpretatie van waar VR naartoe zou kunnen gaan. Het verhaal is maar dunnetjes, en voorspelbaar. Wat verwacht je ook van zo\'n tienerfilm. Alleen de vele pop-culture referenties deden me opfleuren, want ze zijn heel erg talrijk. Een magere film, die geapprecieerd wordt door een gevoel van nostalgie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1045,'The Shape of Water',2017,'328',123,'2018-12-02',8,8,8,8,8,8,'Het wordt stilaan voorspelbaar: Als het Oscar-seizoen nadert, komen er wat arty films bovendrijven, die vooral geliefd zijn door de industrie. Deze film past in dat rijtje. Hoewel het duidelijk \"iets anders\" is, is het soms ook wat vergezocht. Het is een goeie film, maar de globale aanbidding vind ik er wat over.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1046,'Dark Crimes',2016,'618',92,'2018-12-07',8,5,5,7,7,7,'Uit de titel kan je afleiden dat dit een donkere misdaadfilm is. Maar het probeert dat net wat te hard. Het probeert een sfeer te scheppen, maar er is geen thema. Het lijkt op anderhalf uur gemiste kansen. Sommige personages en verhaallijnen hebben een enorm potentieel. Maar het eindigt allemaal op een sisser.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1047,'Three Billboards Outside Ebbing, Missouri',2017,'456',115,'2018-12-08',8,9,9,9,8,8,'Als je de korte inhoud van deze film op voorhand zou lezen, zou je dit al niet meer willen bekijken. Door de goeie kritieken ben ik er echter aan begonnen. Het stelde niet teleur. Een meeslepend verhaal, pijnlijk en bij tijden grappig. Films over diepmenselijke verhalen vallen of staan met de acteeprestaties. Deze film is een pareltje geworden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1048,'In Darkness',2018,'619',110,'2019-12-15',8,5,3,7,8,8,'Een klassieke misdaadthriller die steeds maar escaleert. Mocht ik nog geen honderden van deze films gezien hebben, zou ik dit echt goed vinden. Alleen ben ik al wat gepokt en gemazeld, waardoor alles wel wat voorspelbaar wordt. Wat ik echter onvergeeflijk vind, is het feit dat er een enorme fout in de verhaallijn zit, waardoor het einde niet meer klopt. Epic fail, wat mij betreft. Dit doet alle goeie intenties teniet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1049,'Crazy, Stupid, Love.',2011,'620',118,'2019-01-05',8,8,8,8,8,8,'Het was weer eens tijd voor een feel-good romantische komedie. Een Steve Carell op zijn retour, samen met Ryan Gosling. Het verhaal is voorspelbaar. Maar ik heb wel echt goed gelachen. Er is helemaal niets mis mee, maar er valt ook bitter weinig meer over te zeggen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1050,'Solo: A Star Wars Story',2018,'132',135,'2019-01-12',8,7,7,8,8,8,'Het jaarlijkse Star Wars uitmelkfestijn gaat vrolijk verder. Dit jaar is het de beurt aan de origin story van Han Solo. De film is alles geworden wat we er van konden verwachten. De Star Wars-magie is echter helemaal afwezig. Het is een must-see voor Star Wars-fans, uiteraard. De extra Star Wars-spark is er niet. De leken kunnen deze gerust overslaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1051,'Behemian Rhapsody',2018,'265',134,'2019-04-07',8,7,6,8,9,8,'De biografie van Freddie Mercury neemt soms een loopje met de realiteit. De casting is echter heel er goed. Vooral als je van de muziek van Queen houdt, is dit een no-brainer. Hou er alleen rekening mee dat het weer een over-romantisering van het leven van Freddie Mercury is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1052,'Kingsman: The Golden Circle',2017,'354',141,'2019-04-07',8,5,5,8,6,7,'De eerste Kingsman film was een positieve verrassing. Het was wat over-the-top, maar het was een degelijke actiefilm. Het tweede deel gaat er echter volledig over. Op het moment dat de actiescènes zo ongeloofwaardig worden, dat ze het verhaal schaden, haak ik af. Er kon trouwens ook gerust een uur af van de duurtijd. Jammer. Aan de cast zal het echter niet gelegen hebben.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1053,'Le Fidèle',2017,'455',130,'2019-04-19',8,7,7,8,7,7,'Een film over een vrouwelijke autosportcoureur met Matthias Schoenaerts klonk aanlokkelijk. Het is echter iets helemaal anders dan dat ik had verwacht. De film is een donkere misdaadfilm die steeds meer escaleert. Een feel-good movie is het allerminst. Mocht ik dit van tevoren geweten hebben, dan had ik dit waarschijnlijk nooit gekeken. Maar nu ben ik toch blij dat ik het gezien heb.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1054,'Sweet November',2001,'621',119,'2019-05-05',8,7,8,7,7,7,'Het periodieke verplichte stukje romantiek brak aan. Hoewel er doorheen de film altijd wel een gevoel bestaat dat er iets niet klopt, blijkt het achteraf een pakkend verhaal te zijn. Hoewel de cover hint naar een zeemzoet liefdesverhaal, is het dat feitelijk niet. Alle negatieve recensies ten spijt, ik vond het wel interessant.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1055,'BlacKkKlansman',2018,'158',135,'2019-05-05',4,6,6,7,8,8,'De plot van deze film leek heel interessant, maar het kwam er toch niet helemaal uit. De absurditeit en de seventies-vibe zorgen voor een heel aparte film. Achteraf bekeken was het wel wat dunnetjes. Af en toe gelachen, af en toe spannend, af en toe interessant. En af en toe ook te licht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1056,'Aquaman',2018,'273',143,'2019-06-21',8,6,5,8,7,8,'En toch heb ik me toch nog eens laten vangen door een superhero-movie. Alweer is het niets om over naar huis te schrijven. De origin story van Aquaman is net zoals alle andere: Het eerste deel interessant, gevolgd door een hopeloos overdreven actiegedeelte. Ik heb het gevoel dat het genre stagneert.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1057,'Glass',2019,'53',129,'2019-07-17',8,8,8,7,8,9,'Het idee dat 2 vorige films van deze regisseur (Unbreakable en Split) de opbouw zijn naar dit verhaal, is eerder onverwacht. Terwijl dit eigenlijk een superhero-movie zou moeten zijn, is de aanpak toch wat anders. Heel origineel, en alleen daarom verdient deze film al extra punten. Met liefde afgemaakt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1058,'Hacksaw Ridge',2016,'457',139,'2019-08-15',8,7,8,9,8,8,'Net als met alle Amerikaanse oorlogsfilms, moet je wat door het patriotisme en godsdienstigheid kijken, maar dan hou je wel een erg interessant, waar gebeurd, verhaal over. Het is eigenlijk een film in 2 delen: De kalme opbouw, gevolgd door de snoeiharde gevechten. Typisch Mel Gibson, dus. Niet de meest memorabele oorlogsfilm, maar wel origineel en met heel harde visuals.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1059,'Shazam!',2019,'622',132,'2019-08-21',8,6,6,7,7,7,'De superheroeskast raakt stilaan leeg, dus moeten we beginnen aan de minder bekende randfiguren. Dit is er zo een van. Hoewel de film best wel vermakelijk is als komedie, is er verder weinig aan. Het haalt alle clichés uit de kast, en brengt weinig nieuws. Puur als ontspannende komedie dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1060,'Pokémon Detective Pikachu',2019,'623',104,'2020-08-31',8,7,7,7,7,7,'Een film over Pikachu belooft eigenlijk niet veel goeds. Door de toch wat positieve kritieken heb ik deze film toch een kans gegeven, en het is toch wel iets anders dan verwacht. Iets minder politiek correct dan andere superhero-movies, of consoorten. Voor Pokémon-kenners ongetwijfeld een feest van herkenning.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1061,'Yardie',2018,'624',101,'2020-09-13',8,6,6,8,8,NULL,'Een misdaadfilm over enkele Jamaican-born kinderen. Het neemt zichzelf iets te serieus in dat het probeert de misdaadproblemen van Jamaica aan de kaak te stellen. Kijk je daar door, dan blijft een vrij onoriginele misdaadprent over, met weinig om het lijf. Niet memorabel genoeg, voor alle hype er rond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1062,'Alita: Battle Angel',2019,'221',122,'2020-10-05',8,6,7,9,6,7,'In de hoop om eens een iets andere superhero origin story te zien, probeerde ik deze even uit. Door de sterke cast, en Aziatische insteek, werd ik benieuwd. Vooral de Aziatische stijl maakt deze film boeiend. Het verhaal is echter maar dunnetjes, en het is ook een film zonder slot. Als de sequels beter worden, verdient het misschien een kans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1063,'Fantastic Beasts: The Crimes of Grindelwald',2018,'252',134,'2020-10-21',8,7,7,8,7,8,'De eerste Fantastic Beasts had me aangenaam verrast. Het was niet zomaar een Harry Potter-kloon. Dit vervolgverhaal doet echter helemaal niets extra\'s. Het is wat het is: Het vervolg. Dit is zo\'n filmreeks die je misschien eens kan overwegen als alle delen uitgekomen zijn. Niets zo frustrerend om eerst oudere films te moeten herbekijken, om de nieuwe nog te kunnen volgen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1064,'The Lion King',2019,'364',118,'2019-11-08',8,8,7,8,8,8,'Disney toont wel lef door zijn Heilige Huisjes een real-life remake te geven. Zo ook deze Lion King. Hoewel het een feest van herkenning is, en technisch indrukwekkend gedaan, kan ik me toch niet van de indruk ontdoen dat deze film minder een klassieker gaat worden dan het origineel. Zelfs zonder de nostalgie, wat ongetwijfeld een rol speelt. Leuk, maar misschien wat onnodig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1065,'Downsizing',2017,'527',135,'2019-12-28',4,9,9,8,8,7,'Een sci-fi satire over... Wel... Moeilijk uit te leggen. Het onderwerp, de personages, de scènes, allemaal ongelofelijk boeiend door de originele insteek. Dit onbekend pareltje is wat mij betreft een van de verrassingen van het jaar. Het verhaal eindigt een beetje op een sisser, maar dat weegt niet op tegen het originele concept.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1066,'Green Book',2018,'301',130,'2020-02-07',8,8,8,7,8,8,'Een gelauwerde biografie over een buitenwipper die een African-American pianist moet beschermen. Het is zeker genietbaar, maar het is een beetje te politiek correct voor mijn smaak. Het speelt in op het racisme in Amerika in de sixties, maar dat is hier minder van tel. Als je daar even door kijkt, is het wel een pareltje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1067,'Someone Great',2019,'625',92,'2020-02-15',8,3,2,6,7,6,'Een romantische film is bij mij altijd wat hit-or-miss. En dit is een prototype van een miss. Het oversimplistische verhaal boeit niet, de personages zijn oppervlakkig, en het is voorspelbaar als de pest. En daarbij worden mannen worden afgebeeld als domme apen. Duidelijk geschreven door een verbitterde gescheiden vrouw van middelbare leeftijd. Lang geleden dat ik nog zo\'n storende film heb gezien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1068,'Prospect',2018,'626',100,'2020-02-22',4,7,8,6,7,8,'Een relatief onbekende sci-fi thriller is altijd een risico op B-film kwaliteit. Je ziet het beperkte budget hier ook wel af en toe, maar door de sterke scènes, valt dat minder op. De film is boeiend, maar het slot is vrij teleurstellend. Dat is nu net wat het meeste blijft hangen, natuurlijk. Boeiend, een tikkeltje rauw, voor de liefhebber. Maar geen klassieker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1069,'Ford v Ferrari',2019,'147',152,'2020-03-22',4,7,7,8,7,8,'Het proberen toegankelijk maken van een sportfilm is niet makkelijk. Meestal worden er zoveel concessies gedaan, dat er nog weinig van de sport overblijft. Deze film balanceert op de grens daarvan. De sportactie is compleet onrealistisch, maar het brengt wel het race-gevoel goed over. Een twijfelgeval voor mij, maar zeker geen gedrocht als Driven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1070,'Bird Box',2018,'627',124,'2020-03-22',8,8,8,8,7,8,'In deze tijden van internet-hypes bekeek ik deze film met enige argwaan. Het is vrij low-budget, maar de spanning is te snijden, doorheen het hele verhaal. Wat het probeert te doen, doet het heel goed. En het pretendeert ook niets meer te zijn dan het is. Perfect voor een film, qua duur en wat het uiteindelijk open laat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1071,'The Good Liar',2019,'452',109,'2020-03-29',8,6,5,7,7,6,'Een misdaadfilm met zo\'n cast is genoeg om mij te triggeren, ongeacht waarover het gaat. Helaas blijkt dat dan ook het enige te zijn dat voor deze film pleit. Het verhaal is eigelijk vrij dun, en ook voorspelbaar. Het samenspel tussen de hoofdrolspelers is wel boeiend van begin tot einde.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1072,'Jojo Rabbit',2019,'573',108,'2020-04-04',8,8,8,8,7,7,'Films van Taika Waititi zijn niet voor iedereen, maar meestal wel voor mij. Ook deze film heeft een knotsgek uitgangspunt, en dan verwacht je een absurde komedie. Er zijn echter plottwists die deze film een heel andere smaak geven. Daarom apprecieer ik dit enorm. Knap uitgevoerd, vooral.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1073,'Star Wars: Episode IX - The Rise of Skywalker',2019,'425',142,'2020-04-19',8,7,6,8,9,9,'Als we het (dit keer wel) mogen geloven, dan is dit de negende en laatste Star Wars films in de Skywalker lijn. Daarmee zijn de verwachtingen meteen hoog. Tegelijk ook wat bevreesd, gezien de vorige twee films uit deze trilogie. Jammer genoeg stelt deze film teleur voor mij. Het is vooral een aaneenschakeling van actiescènes, met weinig binding. Leuk voor de bioscoop, maar het doet, wat mij betreft, toch wat oneer aan de serie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1074,'Star Wars: Episode VII - The Force Awakens',2015,'425',138,'2015-12-24',5,8,7,9,8,8,'Na al die jaren een nieuwe Star Wars in de Skywalker lijn. Wat zijn de verwachtingen hooggespannen. De bioscoopervaring zorgde er voor dat ik initieel heel positief was, maar na verloop van tijd begon ik te beseffen dat dit feitelijk een \"New Hope\"-remake is. Goed gedaan, een feest van nostalgie, maar eigenlijk wat goedkoop.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1075,'Den of Thieves',2018,'628',140,'2020-05-22',8,7,7,8,7,8,'Deze film is volledige onder de radar gereleased, maar na enkele maanden toch een hit geworden. Het is een stevige en onderhoudende actiefilm, perfect voor een ontspannende avond. Het is allemaal niet te moeilijk, maar wel goed gedaan, zonder meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1076,'Once Upon a Time... In Hollywood',2019,'107',161,'2020-05-30',4,8,8,9,9,8,'Een Tarantino-film is altijd wat speciaals, of er is een stevige hoek af. In dit geval is het laatste waar. Het is een biografie, waar enkele elementen aan zijn toegevoegd, en dat resulteert in iets aparts. Classic-Tarantino, want je bent van begin tot einde aan het scherm gekluisterd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1077,'Jexi',2019,'629,630',84,'2020-06-06',8,8,7,7,7,8,'Deze film wordt volledig afgebrand door de criciti, en ergens begrijp ik dat wel. Het is heel eenvoudig en plat. Aan de andere kant heb ik wel hartelijk gelachen. Een brainless comedy, vol met platte humor. Ik vond het goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1078,'Eurovision Song Contest: The Story of Fire Saga',2020,'391',123,'2020-06-27',8,8,8,8,9,8,'Je houdt toch wat je hart vast als je een film met Will Ferrell krijgt over het Songfestival. Je verwacht dat alles in het belachelijke wordt getrokken. En in zekere zin is dat ook wel het geval, alleen is het op dezelfde manier als ik er zelf, naar het echte festival kijk. Ze hebben het dus goed gedaan, met respect. En hilarisch, niet te vergeten. Classic.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1079,'Burlesque',2010,'631',119,'2020-06-29',4,6,6,8,8,7,'Vraag me niet hoe, maar ik betrapte me er op niet te kunnen stoppen met kijken naar deze musical. Niet direct mijn genre, nochtans. De cast doet er wel wat aan, vermoed ik. Het verhaal zelf is echter dunnetjes en voorspelbaar. Maar ach, het is een \"geloofbare\" musical, dus eerlijk is eerlijk, al bij al niet slecht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1080,'The Irishman',2019,'3',209,'2020-07-03',8,9,9,9,9,9,'Wat moet ik meer zeggen dan: Een Scorsese film met Robert De Niro, Al Pacino en Joe Pesci. Mic drop.\nEn het is een instant classic geworden. In deze tijden van superhero actiefilms is deze wat onder de radar gebleven. Maar wat een pareltje. Klassiek opgebouwd, perfect uitgevoerd. Voorlopig de film van het jaar voor mij. Maar ongetwijfeld niet voor iedereen, want het is klassiek \"traag\".','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1081,'Brightburn',2019,'632',90,'2020-07-25',8,8,7,9,8,9,'Af en toe eens een B-horrorfilm kan ik best smaken. Dit kan je moeilijk \"B\" noemen, maar het voelt wel zo\'n beetje aan. Knap gedaan, spannende momenten, en een beetje voorspelbaarheid. De constante onderstroom van spanning wordt aangevuld met echte gore. Leuk gedaan, een ode aan het genre.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1082,'Despicable Me 3',2017,'480,633',89,'2020-10-31',4,6,6,8,8,7,'Een derde film in een reeks komedies is meestel \"een moetje\". Vandaar dat ik deze film nog niet had bekeken. En ik blijk gelijk te hebben: Het is wel weer leuk en herkenbaar, een degelijke komedie. Maar niet meer dan dat. En dat waren de voorgaande films nu net wel. Wel leuk, maar overbodig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1083,'Knives Out',2019,'473',130,'2020-11-07',8,9,9,8,7,7,'Een klassieke \"Who Done It\", maar in een nieuw jasje gestoken. Het succes van deze films hangt vaak van 2 dingen af: De complexiteit van de misdaad zelf, en de sterkte van de cast. Beide zijn hier dik in orde. Het zal niet de meeste prijzen winnen, volgens mij, maar ik hou er echt van.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1085,'Dolemite Is My Name',2019,'330',118,'2020-11-21',8,8,8,8,8,8,'Eddy Murphy bewijst nog maar eens hoe sterk hij is als acteur. Dit is eigenlijk een biografie over een rap-pionier, maar valt ook als een komedie of drama te categoriseren. Ik zou het omschrijven als onderhoudend en boeiend. Je moet wel de Eddy Murphy van de eighties en nineties even uit je hoofd kunnen zetten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1087,'The Art of Self-Defense',2019,'634',104,'2020-11-26',8,8,9,8,8,8,'Soms kan je niet echt een genre plakken op een film. Zo ook hier. Komedie, actie, drama, misdaad? Van alles een beetje. Jesse Eisenberg doet \"zijn klassieke typetje\", en dat werkt wel. En het is ook weer zo\'n bizarre film, waar hij ook een patent lijkt op te hebben. Boeiend van begin tot einde. Het zit goed in mekaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1088,'Project Power',2020,'635,636',113,'2020-12-11',8,5,4,8,7,8,'Omdat de superheroes stilaan opraken, moet er iets anders worden gevonden. Deze film is verpakt als actie/misdaad, maar is eigenlijk gewoon een superhero-movie. Jamie Foxx en Joseph Gordon-Levitt zullen wel heel wat publiek lokken. Maar daar stopt de inhoud zowat. De cast is duidelijk beter dan de film. Voorspelbaar, een dun verhaaltje, weinig nieuws. Maar goed, de actie is wel OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1089,'6 Underground',2019,'98',128,'2020-12-12',8,6,6,8,7,8,'Als je een actiefilm van Michael Bay voorgeschoteld krijgt, weet je meestal wel wat je kan verwachten. Deze film stelt dan ook niet teleur, maar het is ook niet memorabel. Een half jaar later al compleet vergeten. Degelijk, dan maar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1090,'Junior',1994,'150',109,'2020-12-20',4,6,7,5,8,6,'Een film uit mijn kindertijd herbekijken, is altijd riskant. Je kan makkelijk de nostalgie doorprikken. Dit is feitelijk een klassieke komedie, typisch nineties. Niets speciaals, maar puur nostalgie, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1091,'Home Alone',1990,'130',103,'2020-12-24',4,8,8,7,8,7,'Over nostagie gesproken... Deze 100% Kerstclassic blijft de tand des tijds doorstaan. Natuurlijk is mijn blik wel wat gekleurd, maar objectief gezien is dit gewoon goed gemaakt. Niet te moeilijk, sfeervol, perfect voor Kerstavond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1092,'The Willoughbys',2020,'637',90,'2020-12-27',8,4,3,7,7,7,'Ik heb me alweer laten vangen door een leuke trailer op Netflix. Je denkt: \"Dit zal wel leuk zijn, op zijn minst grappig.\" Het risico op teleurstelling zou ik wel al moeten kunnen inschatten. Maar ik liet me toch weer vangen. Flinterdun, niet eens grappig, niet boeiend, niet origineel. Jammer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1094,'Beauty and the Beast',2017,'452',129,'2021-01-23',8,8,7,8,9,8,'Disney is bezig met het herwerken van zijn klassiekers met real-life acteurs, en deze past in dat rijtje. Hoewel het origineel best indruk maakte op mij, is dit toch wat minder. Dat heeft wat met de leeftijd te maken. En eerlijk, het is best goed gedaan. Met respect voor het origineel, en hier en daar wat nieuwe elementen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1096,'Sonic the Hedgehog',2020,'638',99,'2021-04-04',8,7,7,8,7,7,'Een geniale marketingtruuc ging deze film vooraf: Een grote controverse rondom het uiterlijk van Sonic organiseren. Het heeft voor mij wel gewerkt. Ik wou dit wel eens zien. De film zelf is best goed, eigenlijk. En dat helemaal onverwacht. Niets speciaals, maar mijn verwachtingen waren zo laag, dat het alleen maar kon meevallen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1097,'Thunder Force',2021,'639',106,'2021-04-14',8,5,5,7,7,6,'Na het decennium vol Superhero movies, was het dringend tijd voor wat parodieën. Dit is er daar eentje van. Soms eens grappig, maar eigenlijk te dunnetjes. Voorspelbaar en totaal niet boeiend. Een waste of time, maar slecht kan je het ook niet noemen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1098,'Good Boys',2019,'640',90,'2021-04-23',8,7,7,6,6,6,'Een komedie met kinderen in de hoofdrol is een riskante onderneming. Het kan helemaal mis gaan. Dat is hier niet het geval. Leuk, onderhoudend, en af en toe afwijkend van de grootste clichés. Het blijft natuurlijk Amerikaans, dus met voorbeeldkinderen die eigenlijk net wat te volwassen zijn. Maar leuk, dus.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1099,'Freaky',2020,'641',102,'2021-06-19',5,8,7,8,7,7,'Een teen slasher kan mij enkel bekoren als er ook de nodige humor in zit. Dat zit hier zeker goed. Hoewel het achteraf bekeken maar wat dunnetjes was, zijn de kill-scenes heel goed, en af en toe ontmijnd door wat grappen. Heel goed gedaan, ondanks dat dit een simpele slasher movie is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1100,'Torpedo',2019,'642',102,'2021-07-05',4,7,6,8,7,8,'De kwaliteit van de Vlaamse films zit al jaren in de lift. Ook deze film is duidelijk met een groot budget gemaakt. Het eerste deel is ook pakkend en boeiend. Maar het geheel verwatert helemaal naar het einde toe. Het wordt een voorspelbare thriller. Ik voelde me een beetje bedrogen, zeker na het sterke eerste deel. Gemiste kans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1101,'Keeping Up with the Joneses',2016,'643',105,'2021-07-20',4,6,6,8,7,7,'Een low budget komedie kan altijd alle kanten uit, maar dit is wel redelijk geslaagd. Totaal voorspelbaar, maar soms wel grappig. De actie is goed, maar het verhaal kan niet echt boeien tot het einde. De voor de hand liggende plot helpt daar natuurlijk niet bij. Niet slecht, maar toch een wat 13-in-een-dozijn film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1102,'Wish Dragon',2021,'644',98,'2021-07-31',8,8,8,8,6,7,'In de berg animatiefilms van de laatste jaren is het zoeken naar pareltjes. Die zitten er soms tussen. Meestal zijn het degene met de minste \"Amerikaanse flavour\". Dit is er net zo eentje. Japanse invloeden maken het minder voorspelbaar, en eigenlijk gewoon beter. En het is dan ook nog af en toe heel geestig, ook. Een meevaller.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1103,'Ruby Sparks',2012,'367',104,'2021-08-07',4,7,7,8,7,7,'Na Little Miss Sunshine waren de verwachtingen hoog gespannen. Dit is dan ook een heel boeiende film geworden, maar het slot laat helaas steken vallen. Opnieuw een gemiste kans, al is het zeker de tijd waard.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1104,'Murder on the Orient Express',2017,'462',114,'2021-08-14',8,9,9,5,8,8,'Een klassieke whodunit met Hercule Poirot. Het is, ondanks de sterke cast, echt een budget-film. Inhoudelijk is hier echter niets op aan te merken. Misschien ligt het aan mij, maar ik had echt niet door hoe het in elkaar zat. Het is er eentje die ik niet snel zal vergeten. Maar het past natuurlijk binnen mijn favoriete genres.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1105,'Sister Act',1992,'645',100,'2021-08-16',4,8,8,6,8,7,'Hoe kan het dat ik sommige klassiekers nog nooit gezien heb? Dit is er duidelijk eentje. Een typische komedie uit de tijd, die eighties-vibes ademt. Het blijft echter wel een goeie en onderhoudende komedie. De tand des tijds is niet mals geweest, maar het is een klassieker om een reden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1106,'Red Notice',2021,'224',118,'2021-11-29',8,7,7,8,8,8,'Een indrukwekkende cast met Dwayne Johnson en Ryan Reynolds lijkt het ideale recept voor een komische actiefilm. Het is ook best wel goed gedaan, maar je weet natuurlijk wat je kan verwachten. Niet echt memorabel, maar het kijkt lekker weg. Een leuke tijd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1107,'Lock, Stock and Two Smoking Barrels',1998,'230',107,'2021-12-16',4,8,8,8,8,7,'De nineties waren de speeltijd voor Guy Ritchie. Hij gooide er aan recordtempo dit soort misdaadfilms de deur uit. Ook deze kreeg destijds lovende commentaren, maar is niet op mijn radar gekomen. Het is ook niet zijn beste film, maar ik hou hier wel van. Je weet wat je krijgt in een Guy Ritchie-film met Jason Statham.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1108,'Black Widow',2021,'646',134,'2021-12-18',4,6,4,8,7,8,'De zoveelste superhero origin-story, en eentje om snel te vergeten. Niets nieuws onder de zon, en zeker niet een van de beste. Ik zie geen enkele reden om hier kostbare levensminuten aan te spenderen. Niet dat het zo slecht is, maar je wil toch eens iets anders dan die eenheidsworst.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1109,'New Kids Turbo',2010,'647',84,'2021-12-18',4,8,8,6,7,8,'Satirisch lachen met marginalen is altijd een hit tijdens de eindejaarsperiode. Deze film doet dat dan ook nog eens heel goed. Hilarisch absurd, maar wel polariserend: Je vindt het geweldig, of je haat het innig. Ik zit in groep 1.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1110,'The Unforgivable',2021,'648',112,'2021-12-21',8,9,9,8,6,6,'Door al het streaminggeweld raken er sommige pareltjes compleet ondergesneeuwd. Dit is zo\'n pareltje. Heel sterk geacteerd van Sandra Bullock, en een meeslepend verhaal. Helemaal geen feel-good, dus je moet het wel zien zitten. Maar geef het een kans en je zal het je niet beklagen. Zonder al dat visueel geweld kan je ook prachtige films maken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1111,'Don\'t Look Up',2021,'423',138,'2021-12-26',4,8,8,8,8,8,'De komedies die het meeste blijven hangen, zijn die die het meest herkenbaar zijn. Dit is een absurde komedie, maar ergens zou je het je zo kunnen voorstellen. Daarbij komt een indrukwekkende cast. Heel goed gedaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1112,'Cruella',2021,'649',134,'2022-01-08',8,7,7,8,7,8,'Het is de nieuwste rage: Focussen op een slechterik uit een Disney-sprookje, en daar een origin-story van maken. Zo ook deze Cruella. Visueel indrukwekkend, maar inhoudelijk heel wat minder. Een echte film-film, daarmee bedoel ik een echte Blockbuster met de bijbehorende magie. Maar daar blijft het een beetje bij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1113,'Nocturnal Animals',2016,'650',116,'2023-08-19',8,8,8,9,8,7,'Dit is zo\'n film waar je even mee moet gaan in de fantasie van de regisseur. Het is een beetje bizar, maar door de visuele stijl wel pakkend. Een film voor de filmliefhebber, maar minder voor een ontspannende avond in de zetel. Ga hier maar eens goed voor zitten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1114,'Love and Monsters',2020,'651',109,'2022-01-22',8,3,3,7,7,7,'In de categorie \"compleet overbodig\", schiet deze film echt de hoofdvogel. Dit is zo\'n film die frustreert, omdat je er tijd aan gespendeerd hebt. Verder is er ook geen enkele scene die ik onthouden heb, dus laat deze tienderflick rustig links liggen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1115,'Anon',2018,'175',100,'2022-01-24',8,8,8,9,8,8,'Deze film lift wat mee op het succes van Black Mirror: Je neemt de huidige maatschappij, verandert er 1 aspect van, en maakt een film over de gevolgen. En meestal is dat heel erg boeiend. De voorwaarde is wel dat de acteurs extra diepte geven aan dat verhaal, en dat is gelukkig hier het geval. Een onverwacht succes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1116,'Dirty Grandpa',2016,'652',102,'2022-03-19',4,8,7,7,8,7,'Eerder waren komedies met Robert De Niro al heel goed. Dit is er ook zo eentje. Helemaal niets diep of doordacht of zo. Gewoon een heerlijke ontspannen komedie. Heel goed gedaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1118,'The Adam Project',2022,'322',106,'2022-07-15',8,8,8,8,7,8,'Streaming-only films worden tot nu toe als minderwaardig bekeken. Deze film is duidelijk een klasse hoger. Het verhaal moet wel meer dragen dan bij een visueel spectaculaire blockbuster, maar door het \"timetravel\"-thema, blijft het boeiend van begin tot einde. Best goed, eigenlijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1119,'Jurassic World Dominion',2022,'534',147,'2022-07-16',5,8,8,9,8,8,'De Jurassic Park-franchise wordt helemaal uitgemolken. Dit is de zoveelste film in de reeks. Maar met dat verschil, dat het een soort tribute-film voor het origineel is. Beide filmreeksen worden hier aan elkaar gekoppeld. Het doet eigenlijk niets nieuws, maar door de nostalgiefactor heb ik hier wel van genoten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1120,'The Gray Man',2022,'653',122,'2022-08-27',8,6,6,7,7,7,'Een streaming-only film met Ryan Gosling en Chris Evans doet het beste verhopen. Maar het stelt helaas teleur. Een weinig origineel typisch CIA-verhaaltje, en wat actiescènes erbij. Ach ja, op een verdwaalde avond is het niet slecht, of zo.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1121,'John Wick: Chapter 3 - Parabellum',2019,'654',130,'2022-11-26',8,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1122,'The Noel Diary',2022,'655',99,'2023-12-17',8,7,7,8,7,7,'Om een goeie kerstfilm te maken, mag het er ook niet te heel erg dik op liggen. Het mag een feel-good story zijn, maar dan met een scherp kantje. Dit is precies dat. Het is niet echt \"Kerstig\", maar het gaat wel over de typische thema\'s. Leuk gedaan, perfect voor de feestdagen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1123,'I Believe in Santa',2022,'656',89,'2022-12-18',8,6,6,7,7,7,'Kerstfilmtijd, en wat is er beter dan een komedie over een volwassene die nog in de Kerstman gelooft. Eigenlijk wel goed gedaan, hoor. Niets op af te dingen. Geen te hoge verwachtingen, en het is een leuke film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1124,'The Polar Express',2004,'16',100,'2022-12-19',8,6,7,5,6,7,'In de hype-periode van de 3D-animatiefilms, kwam deze voorbij. Het animatiedeel is eigenlijk volstrekt overbodig, en heeft de tand des tijds helemaal niet doorstaan. Dat doet af van de film zelf, want het is een mooi sprookje, volledig in Kerstsfeer. Wacht 10 jaar, meng CGI met echte acteurs, en je krijgt een veel beter resultaat.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1125,'Father Christmas is Back',2021,'657',105,'2022-12-22',8,8,8,7,7,7,'In de berg Kerstfilms die elk jaar de revue passeert, zitten er altijd een paar voor volwassenen, zoals deze. Deze komedie is een Kerstfilm, maar had evengoed in een ander seizoen kunnen verschijnen. Het is gewoon een goede, klassieke Britse komedie, met een sterke cast.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1126,'The Pale Blue Eye',2022,'561',128,'2023-01-12',8,7,6,8,7,7,'Een leuke whodunit die zich afspeelt in de negentiende eeuw. Heel sterk geacteerd, en dat heeft deze film wel nodig, om wat meer gewicht te krijgen. Het zit best goed in mekaar, maar is zeker geen topper in het genre. Ik neig het zelfs enigzins voorspelbaar te noemen. Leuk qua sfeer en setting, maar gewoon niet goed genoeg.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1127,'Coming 2 America',2021,'330',110,'2023-02-23',8,7,7,7,8,7,'Een sequel van een klassieker in het eighties-comedy genre, meer dan 30 jaar na datum, is heel erg riskant. Maar deze film doet het eigenlijk heel goed. Al zal iemand die de eerste film niet gezien heeft destijds, het ook maar matig kunnen appreciëren. Kijkers die de eerste film een warm hart toedragen, zullen hier zeker van genieten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1128,'The Super Mario Bros. Movie',2023,'658',92,'2023-04-30',5,7,7,8,8,8,'Ik bekeek deze film meer \"in opdracht\", omdat Siebe het wou zien. Het was een aangename verrassing. Voor hem was het leuk, omdat het een toffe kinderfilm is. Voor mij was het leuk door de vele respectvolle referenties naar de games van weleer. Voor elk wat wils dus. Nintendo\'s QA heeft hier duidelijk wat te zeggen gehad.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1129,'The Equalizer',2014,'217',132,'2023-07-02',8,7,7,8,7,8,'Een actie/misdaadfilm met Denzel Washington, daar heb ik goeie herinneringen aan. Ik hoop dan meestal wel dat het meer de misdaad-kant opgaat, en niet de superhero-actie. Jammer genoeg gaat deze film de verkeerde richting uit. Best genietbaar, maar een beetje dunnetjes.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1130,'Mission: Impossible III',2006,'425',126,'2023-08-19',8,6,6,8,7,7,'De derde film uit de reeks kreeg duidelijk meer budget mee, maar is nog steeds even ongeloofwaardig. Een goeie actiefilm, maar denk er niet te veel over na. Je weet wat je krijgt met een film uit deze reeks. Als je niet te kritisch bent, is dit wel OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1131,'Ghostbusters: Afterlife',2021,'350',124,'2023-09-02',8,7,7,8,7,7,'Een hedendaagse remake van Ghostbusters, het meest bedoeld voor fans van het origineel. Er wordt gepoogd om er door wat jeugdsterren tegenaan te gooien, de levensduur van deze franchise te verlengen. Maar het is toch voornamelijk Paul Rudd die deze film draagt. Best OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1132,'Top Gun: Maverick',2022,'659',130,'2023-10-07',8,8,7,9,9,9,'Ach, Top Gun. Een groot risico op heiligschennis. Gelukkig heeft deze film het nodige respect voor het origineel. Maar eigenlijk is het compleet dezelfde als het origineel. De plot opbouw, de personages, zelfs tot het herwerken van enkele iconische scenes aan toe. Het is een heel spectaculaire actiefilm geworden. Het slot zelfs een beetje te spectaculair, want dan is de geloofwaardigheid compleet verdwenen. Maar wat een spectakel!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1133,'Robots',2023,'660',93,'2023-10-15',8,8,8,7,8,8,'Een Britse ietwat edgy comedy over een geloofwaardige toekomst waarin robots een integraal onderdeel zijn van de maatschappij. Maar dan in de vorm van een rom-com, die trouwens helemaal uit de hand loopt. Goed gelachen, hiermee.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1134,'The Santa Claus',1994,'661',97,'2023-12-03',8,6,6,6,7,7,'Deze inmiddels 29-jaar oude klassieker, is ideaal om de Kerstmaand mee af te trappen. Een klassieker, maar deze had ik nog nooit gezien. Best leuk, hoor, maar meer ook niet. De tand des tijds heeft het er niet veel van heel gelaten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1135,'Janeen Damian',2022,'662',93,'2024-12-06',8,6,5,7,7,6,'Het bestaat: De romatische Kerstfilm. En het heeft net zo weinig inhoud, als je kan vrezen. Het is helemaal niet origineel, of zo. Maar het is wel een pure feel-good film. Eentje waar je niet al te veel mag bij nadenken, omdat het nu eenmaal vrij simplistisch is, maar goed.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1136,'A Bad Moms Christmas',2017,'629',104,'2023-12-07',8,8,8,8,7,7,'\"Bad Moms\" is blijkbaar een heel ding. Helemaal aan mij voorbij gegaan. Deze film is een soort Christmas Special. Met een indrukwekkende cast behoort deze film wel degelijk tot de grappigste komedies van dit jaar, voor mij. Awkward, en soms cringe, maar net nog OK.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1137,'Best. Christmas. Ever.',2023,'663',82,'2023-12-08',8,7,7,8,7,7,'Deze Kerstfilm over familie en verplichtingen daarrond, is best onderhoudend. Soms ronduit grappig. En ik betrapte me er op echt mee te leven met de hoofdpersonages. Voor een melige Kerstfilm is dat best een prestatie. Een eche all-American Kerst feel-good movie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1138,'Elf',2003,'364',97,'2023-12-10',8,8,8,6,8,7,'Blijkbaar is dit ook een klassieker. En ook deze was helemaal onbekend voor mij. Je weet natuurlijk wat je krijgt in een komedie met Wil Ferrell. Hoewel dit net nog iets serieuzer bedoeld was dan zijn later werk, blijft dit toch best absurd. Maar ook ergens hartverwarmend. Gewoon goed gedaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1139,'Family Switch',2023,'336',106,'2023-12-11',8,7,6,8,7,7,'Dit moet ongetwijfeld een van de meest \"cringe\" films zijn geweest, die ik ooit heb gezien. Wat een aaneenschakeling van pijnlijke momenten. Maar je wil toch op een of andere manier weten hoe het afloopt. Ik ben blij dat ik het doorstaan heb, maar dat is het dan ook. Ergens moet je wel respect hebben over hoe over-the-top dit eigenlijk wel is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1140,'The Christmas Chronicles',2018,'664',104,'2023-12-13',8,8,8,8,8,8,'Wat moet je verwachten van een Kerstfilm, met Kurt Russell als kerstman? Wel, een van de beste Kerstfilms van de laatste jaren, naar mijn mening. Grappig en boeiend tot het einde. Heel goed gedaan, hier heb ik verrassend genoeg van genoten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1141,'The Christmas Chronicles: Part Two',2020,'130',112,'2023-12-14',8,4,4,8,8,8,'Hoe verrassend goed deel 1 was, hoe verrassend slecht deel 2 blijkt te zijn. Het vervolgverhaal slaat de plank volledig mis. Alles wat de eerste film zo goed maakte, is hier overboord gegooid en vervangen door kinderlijke eenvoud. De humor, het mysterie, er schiet niets meer van over. Heel erg jammer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1142,'Violent Night',2022,'665',112,'2023-12-16',8,9,9,9,8,9,'David Harbour is perfect gecast. Hij kan de lieve kerstman spelen, alsook de totaal losgeslagen psychopaat met voorhamer. Een hilarische Kerst-slasher met alle toeters en bellen. Humor, actie en gore. Die Hard met de kerstman. Dit was een van de films van het jaar voor mij.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1143,'Holidate',2020,'384',104,'2023-12-17',8,4,3,8,6,7,'Je kan ongetwijfeld al een en ander afleiden uit de titel. Deze vrij inhoudsloze rom-com met Kerst-thema, doet verder ook niets nieuws. Het toont wat zogenaamde ongelukkige mooie mensen, en die vinden dan het geluk. Dat was het dan. O wat is het leven lastig, voor deze mooie jeugdige mensen. Gewoon irritant dit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1144,'The Holiday Calendar',2018,'666',95,'2023-12-20',8,6,6,6,6,6,'Nog een poging tot een rom-com met Kerst-thema. En deze doet het al wat beter. Er is wat mysterie en wat scherpe kantjes. Toch al wat inhoud, dus. Het slaagt er wel in om het Kerstgevoel over te brengen, dus daar scoort het in ieder geval wel op.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1145,'National Lampoon\'s Christmas Vacation',1989,'667',97,'2023-12-21',8,7,7,5,8,7,'Nog een klassieker in het Kerst-thema. Dit keer uit 1989, met Chevy Chase. Met de National Lampoon film serie weet je wat je krijgt. Hoewel dit destijds waarschijnlijk hilarisch was, is humor toch iets wat met de tijd evolueert. Deze film is daar niet imuun tegen. Af en toe best OK, maar hopeloos verouderd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1146,'Candy Cane Lane',2023,'668',117,'2023-12-23',8,7,7,8,7,7,'Ik weet niet waarom, maar als Eddie Murphy een komedie maakt, moet ik hem gewoon zien. De laatste jaren maakt hij ook enkel pareltjes, al zijn het nooit blockbusters. Deze film is best oppervlakkig, maar best grappig, maar zeemzoet. Eddie Murphy draagt dit wel volledig, en tilt het naar een hoger niveau. Gelukkig, want het is voor de rest maar een mager beestje.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1147,'Dashing through the snow',2023,'669',92,'2023-12-28',8,7,7,8,8,8,'Je weet wat je krijgt met een komedie met Lil Rel Howery. Een soort RnB Kerstfilm met grappige situaties. Ik heb er best goed mee gelachen, maar het is vrij vergeetbaar. Absoluut geen klassieker, maar leuk tijdverdrijf.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1148,'The Holiday',2006,'47',136,'2023-12-29',8,7,7,6,6,6,'Er zijn heel veel bagger rom-coms, maar er zijn er ook die oprecht het genre naar een hoger niveau willen tillen. Dit is een heel onderhoudende film, maar het is natuurlijk \"dat\" genre: Heel simplistisch. Mooie mensen hebben o zo grote probleempjes. En dan vinden ze mekaar. Ach ja.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1149,'Godmothered',2020,'670',110,'2024-01-04',8,6,6,7,8,7,'Een komedie die gedragen wordt door Jillian Bell is wel altijd wat gelijkaardig. Het begint met een originele plot, maar verwatert al snel in een stroom van cliches. Wel soms grappig door de situatiehumor. Deze film kwam, ik keek ernaar, en vergat hem al weer snel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1151,'The Killer',2023,'79',118,'2024-01-07',8,9,9,8,8,9,'Wat regisseur David Fincher al aan rariteiten bijeen gemaakt heeft, kan je niet meer op twee handen tellen. Dit is een iets meer mainstream actie thriller. Michael Fassbender draagt de film in zijn eentje, en maakt het boeiend van begin tot einde. Het trage tempo zal niet iedereen aanspreken, maar mij nu net wel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1152,'Leo',2023,'671',102,'2024-01-24',8,8,8,8,8,6,'Zelf zou ik nooit een animatiefilm met Adam Sandler uitkiezen. Maar dit zou een fout zijn geweest. Af en toe krijg je eens een onverwachte hit in dit genre, grappig en pakkend. En buiten het irritante stemmetje van Sandler gerekend, is dit er zo eentje. Een van de betere animatiefilms van de laatste jaren.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1153,'Otherhood',2019,'672',100,'2024-01-25',8,8,8,7,7,7,'Een komedie over zogenaamde \"vrouwenproblemen\" van vrouwen op middelbare leeftijd, is nu niet bepaald een genre waar ik naar op zoek ben. Maar ik ben er dan toch maar ingerold, en eigenlijk is dit best OK. Het is een vrij intelligente film, een eerlijk verhaald. Geen topcinema, die ik me jaren zal herinneren, maar zeker onderhoudend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1154,'Everything Everywhere All at Once',2022,'673',139,'2024-04-06',8,8,9,9,8,8,'Ik heb altijd wat argwaan tegen een film die zo enorm veel prijzen kreeg. Maar je wil die dan toch zien. Je ziet meteen waarom. Deze hele artsy film is een technisch meesterwerk, gehuld in een complex verhaal. Het vinkt dus alle kruisjes aan om veel prijzen te pakken. Dit betekent echter niet dat het niet genietbaar is. Integendeel, dit is er eentje die bleef hangen. Topcinema.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1155,'Like Father',2018,'674',98,'2024-04-12',8,8,8,8,7,7,'Kristen Bell en Kelsey Grammer zijn net de acteurs die dit promofilmpje voor familiewaarden nodig had. Het is een reclamefilm voor Amerikaanse moraal, maar doet dat niet op een irritante en opdringerige manier. Daar zitten de regisseur en acteurs voor veel tussen. Het is een vertederend verhaal geworden, zeker onderhoudbaar en zet na tot nadenken. Deze vergat ik om de een of andere reden niet direct weer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1156,'The Batman',2022,'675',176,'2024-04-12',8,8,7,9,8,9,'We beginnen nog maar eens een nieuwe Batman-franchise, dit keer met Robert Pattinson. In tegenstelling tot wat ik verwachtte, is dit niet echt een origin story, al start het wel een filmreeks. Pattinson doet het ook zo slecht nog niet, ik zou zelfs zeggen: goed gecast. Een Batman-film moet het altijd hebben van de sfeer, en die zit hier zeker goed. Alleen voelt het zo zinloos.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1157,'The Queen\'s Corgi',2019,'676',85,'2024-05-01',8,5,4,4,6,6,'Deze animatiefilm heeft 2 Belgische regisseurs, en dat lokte ons er naar toe. Helaas is de animatiestijl al hopeloos verouderd, en is het verhaal echt heel erg dunnetjes uitgevallen. Dan schiet er nog weinig van over, buiten wat er in de trailer al zat. Geen aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1158,'Look Both Ways',2022,'677',110,'2024-05-03',8,7,7,8,7,7,'De Ridders van de Amerikaanse Moraal zijn weer sterk bezig, de laatste tijd. Deze film gaat over 2 parallelle tijdslijnen van 1 leven, die splitsen door 1 levenskeuze. Dat is op zich best origineel, en er komt ook een boeiende film uit als resultaat. Alleen moet je door de meligheid en cliches heen komen, en dat lukte me niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1159,'Uncharted',2022,'433',116,'2024-05-04',8,7,7,9,8,9,'Een film maken van een game-franchise is hit-or-miss. De Uncharted-reeks leent zich op papier goed tot verfilming, maar het is toch een beetje \"net niet\". Het is leuk gedaan, en visueel best indrukwekkend. Al kan ik me niet van de indruk ontdoen dat dit ook gewoon een serie kon geweest zijn. En dan bedoel ik niet een \"filmserie\", waar er overduidelijk naar gehint wordt.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1160,'Wish',2023,'569',95,'2024-05-17',8,3,3,8,7,7,'De hoogtijdagen van de alleenheerschappij op animatiefilms van Disney ligt al een hele tijd achter ons. Deze film heeft een grappig personage, en een aparte visuele stijl. En dan is dan ook alles wat vernoemenswaardig is. Het verhaal is veel te dunnetjes, voorspelbaar als de pest, en totaal niet boeiend. Misschien word ik te oud, maar we zijn ver verwijderd van de legendarische sprookjes van weleer. Deze film probeert daar veel te krampachtig aan vast te houden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1161,'Elemental',2023,'543',101,'2024-05-18',8,8,7,8,8,7,'Na net \"Wish\" te hebben bekeken, lag mijn hoop niet al te hoog. Maar onterecht, zo blijkt. Dit is al een veel vertederender verhaal, en ook heel wat origineler. Al is het nog steeds heel voorspelbaar. Toch lijkt dit heel wat beter uitgewerkt. Iedereen kan zich wel wat voorstellen bij \"de elementen\", en dat werkt echt wel vor dit verhaal. Disney zonder Pixar begint toch echt af te glijden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1162,'If',2024,'678',104,'2024-06-19',5,8,8,8,7,8,'Een hartverwarmend verhaal over opgroeien, en de uitdaginen die daarbij komen. Maar dan op een originele manier verteld. Het ziet er wat kinderachtig uit, maar dat lijkt het achteraf niet te zijn. Ryan Reynolds draagt de hele film, maar doet het wel erg sterk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1163,'Bullet Train',2022,'615',127,'2024-06-28',8,8,7,9,8,8,'Een actie/misdaadfilm die zich zowat volledig afspeelt op een trein, het is riskant. Dit is echter zo\'n pareltje dat maar eens in de zoveel jaar verschijnt. Het is eigenlijk niets nieuws, maar het is een heel erg boeiend kijkstuk, met goeie visuals. Zeker een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1164,'Beverly Hills Cop: Axel F',2024,'679',118,'2024-07-07',8,5,5,NULL,8,8,'Eentje om bij te schrijven op het lijstje met onnodige sequels. Helaas, zou ik durven zeggen, want deze film doet echt afbreuk aan de reputatie van zijn voorgangers. Buiten nostalgie heeft deze film echt niks om het lijf. Heb je de trailer gezien, dan heb je de film gezien. Een grote teleurstelling.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1165,'Free Guy',2021,'322',115,'2024-07-12',8,7,7,8,8,8,'Als je even meegaand bent, en als ik even kan negeren dat ik weet hoe games werken, en dat het ZEKER zo niet is, dan is dit best een goeie film. Verplaats je in hun universum, en dit is eigenlijk wel goed gedaan. Ryan Reynolds schittert weer, en dat geeft een extra dimensie. Leuk en boeiend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1166,'Road House',2024,'87',121,'2024-08-07',8,6,5,7,8,7,'Deze eighties remake wordt goed ontvangen, maar ik snap niet goed waarom. Totaal onrealistisch, en toch heel voorspelbaar. Het aantal slagen die het hoofdpersonage moet incasseren, zou de gemiddelde mens tot moes herleiden. Ik deed mijn best, maar ik besluit toch dat deze film tijdverlies is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1167,'Dream Scenario',2023,'680',102,'2024-08-14',8,8,8,7,7,7,'Nicolas Cage staat meer en meer garant op aparte films. Dit is er zeker zo eentje. Het plot is heel origineel, en daardoor blijft de film boeiend van begin tot einde. Maar vergis je neit, feel-good is het allerminst. Deze blijft even plakken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1168,'Ferrari',2023,'344',130,'2024-09-02',8,7,8,6,7,8,'De legende Enzo Ferrari spelen is geen cadeau voor Adam Driver, maar hij doet het heel behoorlijk. De CGI laat soms wat te wensen over, maar als docudrama kan dit zich meten met de besten. De keuzes die gemaakt worden om sommige aspecten al dan niet aan te raken, vind ik niet altijd even geslaagd. Boeiend is het zeker wel, als is dat heel subjectief.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1169,'Alien',1979,'80',137,'2024-09-05',8,8,9,7,8,8,'Wat kan je nog zeggen over een horror-klassieker als deze? Misschien dat het de tand des tijds heel goed doorstaat. Waarschijnlijk net door wat het niet toont, in tegenstelling tot veel recentere films in het genre. Een klassieker, natuurlijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1170,'The Little Things',2021,'681',128,'2024-09-07',8,6,6,7,7,7,'Een detective-thriller met Denzel Washington, Rami Malek en Jared Leto schept hele hoge verwachtingen. Aan de acteerprestaties ligt het niet, maar inhoudelijk is deze film wat dunnetjes. Ik vond het moeilijk om dit boeiend te blijven vinden, en had best vragen bij sommige plotwendingen. Te veel twijfel, om dit goed te vinden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1171,'Zombieland: Double Tap',2019,'433',99,'2024-11-09',8,6,6,7,7,7,'Tien jaar na het onverhoopte succes van de eerste film, is het tijd voor de sequel. De hoge verwachtingen worden echter niet ingelost. Het is natuurlijk een feest van herkenning, maar dat is het dan ook. Het is niks nieuws onder de zon, en wat mij betreft dan ook totaal overbodig.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1172,'Yesterday',2019,'32',116,'2024-11-24',8,7,7,7,9,8,'Films die alleen al door de tagline mijn interesse wekken, zijn heel dungezaaid. Die films hebben dan ook al een streepje voor op de rest. Helaas blijft deze film niet op het niveau van de start. Het zakt geleidelijk weg, en dat is echt een gemiste kans. Het blijft echter wel een aanrader, en zeker een tip voor een ontspannen avond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1173,'Nutcrackers',2024,'682',104,'2024-12-03',8,6,6,7,8,7,'Om het kerstseizoen af te trappen, kozen we een luchtige film met Ben Stiller. Althans, dat dachten we toch. Het is eigelijk een vrij triest verhaal, dat dan op het laatst typisch eindigt in een luchtige kerstfilm vol warmte. Het slaagt echter in geen enkel opzet: Niet grappig, niet ontroerend en niet boeiend. Jammer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1174,'Ernie Barbarash',2019,'683',85,'2024-12-10',8,2,2,7,7,7,'Dit was niet mijn keuze, laat mij dat voorop stellen. Deze slijmerige rom-com met acteurs op hun retour, doet wat mij betreft zowat alles fout. Er was blijkbaar geen budget om nog maar aan 90 minuten te geraken. Het einde maakt het helemaal af, met een moralistische boodschap over dierenwelzijn. Mijden als de pest, dit gedrocht.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1175,'Deck the Halls',2006,'384',93,'2024-12-11',8,3,3,6,7,7,'Laten we nog eens een blik uitgerangeerde nineties-acteurs open trekken, en een kerstfilm maken, moeten ze gedacht hebben. Deze inhoudsloze tijdsvulling heeft mij, met de beste wil, slechts een keer voorzichtig doen glimlachen, maar heeft mij vooral naar het einde doen uitkijken. Wat een verspilling van talent van de hoofdrolspelers.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1176,'Silent Night',2023,'201',104,'2025-12-12',8,7,7,9,8,9,'Ik dacht een ontspannende Kerst-actiefilm mee te pikken, maar was ik even mis. Dit ongelooflijk aangrijpend verhaal van een vader die zijn kind verliest, en op zoek gaat naar wraak, blijft echt plakken. Ontspannend is het allerminst, maar filmtechnisch ongelooflijk goed. Het is een belefenis, dat zeker.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1177,'Silent Night',2021,'684',92,'2024-12-13',8,8,8,7,8,8,'De tweede film deze maand met deze titel, heeft een heel ander opzet. Maar daarom blijft deze niet minder plakken. Het plot is origineel, en ik zou ook aanraden om dit niet op te zoeken vooraleer je kijkt. Dan zal dit wel een blijvende indruk nalaten. Kerstsfeer is niet echt een term die ik hierbij associeer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1178,'Jingle All the Way',1996,'685',89,'2024-12-14',8,5,4,5,7,7,'Na enkele ribbenplakkers deze maand, was het plan om een ontspannende komedie de reeks te laten doorbreken. En hoe kan je dat beter doen dan met deze klassieker? Wel... Vrij makkelijk, eigenlijk. Het is wel een klassieker, maar wel geen goeie, wat mij betreft. Arnold was al op zijn retour, en het vat met creativiteit was duidelijk op. Gewoon niet goed, laat ons eerlijk zijn...','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1179,'Simon Otto',2024,'686',91,'2024-12-15',8,7,8,7,7,7,'In de zee van animatiefilms zit er af en toe nog een zeldzaam pareltje. Dit is er zo eentje. Het start wat traag, en niet boeiend. Maar het wist mij wel mee te nemen. Af en toe grappig, en steeds boeiender. Zeker een meevaller, al is het nu ook niet de beste film ooit, of zo.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1180,'The Family Man',2000,'118',125,'2024-12-16',8,7,7,6,7,7,'In het jaar 2000 was dit een hit, maar toen was ik niet echt in de romatische periode. Deze heb ik dus destijds gemist. Ten onrechte, zo blijkt. Het was toen origineel, nu iets minder, maar dat maakt het niet minder boeiend. Een goed kijkstuk, dat je niet naar je tweede scherm doet grijpen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1181,'Noelle',2019,'281',100,'2024-12-17',8,7,7,8,7,7,'Er zijn af en toe eens verrassend goeie romatische komedies, zoals deze. De poster, tagline en korte inhoud lijken ongelooflijk saai, maar dat is deze film allerminst. Af en toe hardop lachen, dat alleen maakt het al een uitzondering in dit genre. Voorspelbaar is het echter wel, maar het is en blijft een kerstfilm, dus het is ze vergeven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1182,'Snøsøsteren',2024,'687',96,'2025-12-21',8,7,8,8,8,8,'In de hoop om eens iets origineels te vinden, kwam ik bij deze Noorse kerstfilm terecht. Echt origineel is het niet, maar alleen al het feit dat het niet de Hollywoodcliches probeert aan te stippen, maakt het al boeiend. Het pakkende verhaal en goeie kindacteurs, doen me veel voorspelbaarheid vergeten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1183,'Red One',2024,'688',123,'2024-12-22',8,5,5,4,6,7,'Qua Hollywood-pulp kan dit wel tellen: Een actiefilm met een legio aan bekende namen, in kerstthema. En natuurlijk volledig inhoudsloos. Tussen de slechte CGI door, zie je af en toe een goeie acteur. Maar zelfs die kan het dunne verhaaltje niet naar een hoger niveau brengen. Volstrekt nutteloze film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1184,'De Familie Claus',2020,'689',96,'2025-12-23',8,5,5,7,6,7,'Dit Belgo-Nederlandse kerstspektakel is een fiasco geworden. De beste acteurs van de Lage Landen ondervinden nu ook eens dat het niet zo eenvoudig is om een goeie familiefilm te maken. Het is een kinderfilm geworden, waarbij de lesjes van de acteerles driftig worden uitgebeeld. Tot het moment dat het storend word. Wat een teleurstelling!','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1185,'Jack in Time for Christmas',2024,'690',66,'2025-12-24',8,6,5,7,6,7,'Dit is iets wat moeilijk te beschrijven valt: Het is een soort kruising tussen een avonturenkomedie en een reisdocumentaire. Hoewel Jack Whitehall zijn typische zelf vertolkt, en dus ook af en toe best grappig is, is dit eigenlijk niet echt een film te noemen. Het is dan ook een twijfelgeval om in deze database op te nemen. Ach ja, ik heb wel gelachen. Maar het voelt wel heel erg amateuristisch.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1186,'Carry-On',2024,'691',119,'2024-12-26',8,7,8,8,7,8,'Als je zin hebt in een knaller van een misdaadthriller, dan is dit eentje voor op jouw lijst. De claustrofobische sfeer en acteerprestaties brengen dit echt tot een hoog niveau. Want inhoudelijk is het maar dunnetjes. Het blijft wel boeiend van begin tot einde, al verwatert deze film naar het einde toe naar een soort Die-Hard-kloon. Dat is oprecht jammer, want tot die tijd zat ik aan het scherm gekluisterd.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1187,'Genie',2023,'692',93,'2024-12-28',8,6,6,7,7,7,'Met enig argwaan begon ik eraan. Want een film met Melissa McCarthy, is meestal een film waarin Melissa McCarthy Melissa McCarthy doet. En dat is het dan. En eerlijk, dat is bij deze film ook wel wat het geval. Maar de regisseur slaagt er wel in om dat wat te camoufleren. Het resultaat is een onderhoudende rom-com. Beter dan verwacht, maar dat is het dan ook.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1188,'El Camino Christmas',2017,'693',89,'2024-12-29',8,7,7,8,7,7,'Een kerstfilm in de wild west, het is eens wat anders. Een misdaadfilm dan nog. Boeiend is het zeker. Sterker nog, aangrijpend zelfs. Het bouwt heel sterk op naar een einde, maar dat einde is jammer genoeg te voorspelbaar, en te feel-good om realistisch te zijn. Deze film is het levende bewijs dat het slot van een film het moeilijkste stuk is.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1189,'Spirited',2022,'694',127,'2024-12-30',8,6,6,8,6,7,'Wat kan er nu mis zijn met een zwarte komedie met Will Ferrell en Ryan Reynolds? Wel, het feit dat het eigenlijk een musical is, bijvoorbeeld. Een musical die de draak steekt met musicals, maar toch. Op sommige momenten koester je hoop dat deze film de verwachtingen waar maakt, maar die hoop gaat al snel weer liggen. Jammer van al dat gezang, anders was dit een topkomedie van 60 minuten geweest.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1190,'Tokyo Godfathers',2003,'695',92,'2024-12-05',8,8,8,8,7,7,'In een poging om eens iets anders te zien, gingen we deze Japanse animatiefilm aan. Zelfs met Engelstalige spraak, is deze film heel erg boeiend. Het is inmiddels een klassieker in het genre geworden, en niet zonder reden. Een feel-good kerstfilm, dat het net even wat anders aanpakt. Een schoon verhaal.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1191,'Daddy\'s Home',2015,'694',96,'2025-02-01',8,7,8,7,8,7,'Het idee van een komedie met Will Ferrell en Mark Wahlberg, is al interessant. Het is ook exact wat je er van verwacht. Sterker nog, het enorme cringe-gehalte maakt mij zelfs wat ongemakkelijk. Niet memorabel, maar een degelijke komedie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1192,'Unfrosted',2024,'696',97,'2025-03-01',8,7,7,8,7,7,'Dit is een vrij onbekende satire, en ik weet eerlijk gezegd nog steeds niet wat ik er mee moet. Het moest een biografie worden, vermoed ik. Maar dan is het ergens onderweg een absurde komedie geworden. Op een of andere manier boeiend, maar op zijn minst bizar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1193,'Indiana Jones and the Dial of Destiny',2023,'147',154,'2025-04-01',8,8,8,6,8,8,'Door de laatste Indian Jones-films, ben ik hier met de nodige argwaan aan begonnen. Aangezien het heilige huis al door de vorige films gesloopt werd, ben ik er dan toch maar aan begonnen. Het is een degelijke film, en past in de reeks, maar de magie is al enkele decennia verloren gegaan. De bij wijlen slechte CGI doet daar ook geen goed aan. Best genietbaar, maar ook vergeetbaar.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1194,'Deadpool & Wolverine',2024,'322',128,'2025-01-18',8,9,8,9,9,9,'De serieuze Wolverine, samen met Deadpool in een film, dat klinkt als een platte money-grab. Maar wat blijkt dat fout te zijn. Het is een boeiende, spannende en grappige actiekomedie, die geen moment verveelt. Hugh Jackman en Ryan Reynolds dragen het dunne verhaal wel volledig, maar dat mag de pret niet drukken. Wat een onverwacht success. Ook bij de kenners.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1195,'The Union',2024,'697',107,'2025-01-24',8,6,5,8,8,8,'Ik mag van geluk spreken dat ik deze film had genoteerd, anders was ik hem volkomen vergeten. En dat al na een maand. De zoveelste dertien-in-een-dozijn Netflix-actiefilm, met aan lager wal geraakte hoofdrolspelers. Hoewel dat laatste misschien wat oneerlijk is, vat het wel mijn gevoel best samen. Oninteressant.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1196,'Samaritan',2022,'698',102,'2025-02-03',8,7,7,8,7,7,'Opnieuw heb ik me laten vangen aan een film, door me te laten leiden door de cast. Met enkele bekende namen, nam de nostalgie het van me over. Inhoudelijk is er zeker potentieel, maar het wist me op geen moment te grijpen. Niet slecht, maar hier zat ongetwijfeld veel meer in.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1197,'Baywatch',2017,'533',116,'2025-03-07',8,7,6,7,8,8,'De originele Baywatch-serie is intussen een cult-hit, wat eigenlijk niet de bedoeling was. Het had een serieuze actieserie moeten worden. Deze film zet vol in op de absurditeit van de originele serie, en gaat nog een paar stappen verder. Met respect voor het origineel. Af en toe best grappig. Niet slecht, al bij al.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1198,'The Unbearable Weight of Massive Talent',2022,'699',107,'2025-04-12',8,8,9,8,8,8,'Wat Nicolas Cage de laatste tijd allemaal maakt, het is te bizar voor woorden. Ook deze satire over zichzelf is vrij uniek te noemen. Pedro Pascal en Cage dragen de film volledig, en doen dat met verve. Boeiend van begin tot einde, en met best grappig. Als je open staat voor iets anders, wordt dit een topavond.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1199,'A Man Called Otto',2022,'237',126,'2025-05-09',8,9,9,8,9,7,'Dit is iets wat ik niet zelf zou kiezen, maar dan zou ik wat gemist hebben. Een vertederend verhaal van een verbitterde man, prachtig in beeld gebracht. Het is normaal dat een film boeiend begint, en dan minder wordt naar het einde toe. Maar bij deze film is dat net omgekeerd. Eentje om in te kaderen. De muziek viel mij verder ook in positieve zin op.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1200,'Nonnas',2025,'700',111,'2025-05-31',8,7,7,7,7,7,'Een Netflix-only film met acteurs die geen A-films meer krijgen, geeft me geen vertrouwen. Dit is echter een onderhoudend verhaal over de typische American Dream propaganda. Een feel-good (bijna) Kerstfilm, maar het \"alles komt uiteindelijk wel goed\", stoort mij wel wat. Best OK, maar je moet wat meegaand zijn.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1201,'Mission: Impossible - Ghost Protocol',2011,'229',132,'2025-06-23',8,7,8,9,7,8,'De volgende iteratie in de MI-serie. Het blijven spectaculaire actiefilms, maar de geloofwaardigheid neemt steeds verder af. Het \"Computer Enhance\"-niveau stijgt met elke film wat meer. Een klassiek blockbuster spektakelstuk, zonder verassingen, maar zeker onderhoudend.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1202,'Mission: Impossible - Rogue Nation',2015,'701',121,'2025-06-24',8,7,7,9,8,8,'Niks nieuws: Een goeie blockbuster spektakelfilm, die steeds ongeloofwaardiger wordt. Toch blijven deze films min of meer boeien door het misdaad-element. Popcorn-time.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1203,'Mission: Impossible - Fallout',2018,'701',147,'2025-06-26',8,7,7,9,8,8,'Het uitmelken van deze serie blijft onverminderd doorgaan. Het is opnieuw een spektakelstuk, en is opnieuw totaal ongeloofwaardig. Maar goed, je weet wat je krijgt met deze films. Het is en blijft een ouderwetse blockbuster, waar iedereen het over heeft.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1204,'Legion',2010,'702',100,'2025-06-27',8,5,5,6,7,7,'In tijden van Supernatural sprak de korte inhoud ons wel aan. Jammer genoeg is de uitwerking echt B-film-like. De pacing is verwarrend, en hoewel het begin veelbelovend is, komt het er uiteindelijk nooit echt uit. Ook voel je totaal niet mee met de personages, en dat zou het enige zijn wat deze film kan redden. Dit voelt aan als een gemiste kans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1205,'Lilo & Stitch',2025,'703',108,'2025-07-02',8,8,8,8,7,7,'Een live-action remake van een tekenfilm is zeker geen garantie op succes. Maar in dit geval vind ik het een betere film dan het origineel. Het is minder kiddy, op de Disney-achtige cliches na. Een vertederend verhaal, is het resultaat. En ook af en toe grappig. Een aangename verrassing, al is dit nu niet echt een intelligente film, of zo.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1206,'Tenet',2020,'121',150,'2025-07-05',8,7,7,9,8,8,'Een film over time travel, daar gaan we dan. En zet je er maar eens goed voor, want het zal nodig zijn. Het steeds complexer wordende verhaal, vereist dat je deze film echt meerdere keren bekijkt. Regisseur Nolan staat dan nog eens garant voor superspectaculaire, maar bijna onvolgbare actie. Het resultaat is een memorabele crazy trip, maar eentje die eindigt met meer vragen dan antwoorden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1207,'Mission: Impossible - Dead Reckoning Part One',2023,'701',163,'2025-07-12',8,7,7,9,8,8,'Het uitmelken van deze filmserie bereikt nieuwe hoogtes, nu met het opsplitsen van een film in twee delen. Het volgende deel dat er pas over twee jaar aan komt, trouwens. Dit actiespektakel blijft natuurlijk pure fun, en helaas ook totaal ongeloofwaardig. Maar je weet wat je krijgt met de MI films.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1208,'Jurassic World: Rebirth',2025,'513',133,'2025-07-15',8,6,5,7,7,8,'Er worden tegenwoordig nog maar weinig nieuwe filmfranchises gestart. Op het schema van Kinepolis zijn maar liefst 6 van de 8 films sequels. De Jurassic Park/World reeks is er daar eentje van. Deze kruising van King-Kong met Jurassic Park, brengt helemaal niks nieuws. Sterker nog, het plot volgt zowat exact de eerste Jurassic Park film, maar dan met andere acteurs. Enkel voor de fans. Het momentum voor deze filmreeks is compleet verdwenen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1209,'The Wild Robot',2024,'417',102,'2025-07-20',8,8,8,8,8,9,'Ik herinner me dat ik deze film best goed vond. Grappig en meeslepend. Alleen blijkt dat ik deze ook al heel snel vergeten ben. En ik snap niet goed waarom. Overal lovende kritieken, ook door mij. Toch ontbreekt er blijkbaar iets. Nochtans absoluut een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1210,'F1: The Movie',2025,'659',155,'2025-07-22',5,7,6,8,7,8,'Als petrolhead kan ik de goeie autosportfilms op 1 hand tellen. Dus de argwaan was groot. Het viel uiteindelijk al bij al nog mee. Het surft mee op de drive-to-survive stijl, dus het neemt (heel) wat artistieke vrijheid. Qua motorsportfilm behoort het echter wel tot de betere, met enig respect voor de sport zelf. Veel gemiste kansen, maar zeker een onderhoudende actiefilm voor Jan met de Pet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1211,'Sinners',2025,'617',137,'2025-07-29',8,9,8,9,8,8,'Dit artistieke pareltje kwam toevallig op mijn pad. De combinatie van het bovennatuurlijke en Western-stijl geeft een prachtig resultaat. Hoewel het verhaal nadien wat dunnetjes blijkt, heb je dit tijdens de film amper door. De visuele stijl, de acteurs, alles draagt bij tot een heel boeiend kijkstuk. In tijden van sequel en Marvel-modder, blinkt dit goudklompje des te meer.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1212,'Oppenheimer',2023,'121',180,'2025-08-03',8,8,8,9,8,9,'Christopher Nolan die een docudrama maakt, je ziet het niet elke dag. Het is dan ook wat raar hoe veel marketing en blockbuster-like campagne er voor deze film is gevoerd. Het is een artistieke documentaire geworden, en dat maakt het niet makkelijker om te volgen. Op een goed geluidssysteem komt deze film beter tot zijn recht. Boeiend en interessant, maar ik voorzie dat de reacties gemengd zullen zijn. Dit is zeker niet voor iedereen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1213,'Brewster\'s Millions',1985,'18',102,'2025-10-12',8,6,6,5,6,6,'Een klassieke eighties-komedie die vooral leunt op de hoofdacteurs. Het verhaal is, zoals vaak uit die tijd, vrij dunnetjes. Maar het blijft wel boeiend. Het heeft de tand des tijds niet goed doorstaan, maar met de juiste mindset, is dit zeker te genieten.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1214,'A Haunting in Venice',2023,'462',103,'2025-10-25',8,6,6,8,7,7,'Af en toe heb ik wel eens zin een een klassieke \"whodunit\". Dit is een Poirot-verhaal, zoals er de laatste jaren wel meer zijn verschenen. Allleen is deze niet echt de beste van de laatste tijd. Voorspelbaar, weinig meeslepend, en wat langdradig. Het blijft boeien, maar enkel omdat je wil weten hoe de vork aan de steel zit.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1215,'Tron: Ares',2025,'704',119,'2025-10-27',5,7,6,8,9,8,'Een audiovisueel spektakel, dat is wat je mag verwachten van een Tron-film. En dat is deze zeer zeker. Helaas blijft het daar wel een beetje bij. Het dunne en voorspelbare plot, worden enkel daardoor gemaskeerd. Bijkomstig was de slechte audiokwaliteit in de bioscoop, en dit viel helemaal in duigen. Met goed geluid is dit ongetwijfeld erg spectaculair.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1217,'A Merry Little Ex-Mas',2025,'424',91,'2025-12-01',8,6,6,7,5,6,'De start van de Kerstmaand gaat traditioneel gepaard met een rom-com in Kerst-thema. Dit is er eentje, maar daarmee is het dan ook gezegd. Het is als komedie bedoeld, maar met de trailer heb je het wel gezien. Een goeie poging, maar weinig om het lijf.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1218,'The Holdovers',2023,'527',133,'2025-12-02',8,8,8,7,7,7,'In de zoektocht naar een Kerstfilm met enig niveau, kwam ik deze tegen. En vermoedelijk wordt dit de Kerstfilm van het jaar, voor mij. Inhoudelijk en acteertechnisch heel sterk, en soms ook wel een soort komedie. Boeiend, al start het wat traag. Als je een film wil waar je handje niet wordt vastgenomen, dan is dit een aanrader.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1219,'Hot Frosty',2024,'705',92,'2025-12-04',8,3,3,6,5,6,'Je weet dat een Kerst rom-com niet altijd inhoudelijk heel sterk is. En dan heb je van die films waarbij je bijna kwaad wordt, omdat je die tijd in je leven nooit meer terug krijgt. Deze hoort in de laatste categorie. Inhoudelijk nul, volstrekt voorspelbaar, en, om het zacht uit te drukken, matig acteerwerk. Burn it with fire.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1220,'The Ref',1994,'254',97,'2025-12-06',8,6,7,6,6,6,'Omdat de poel met Kerstfilms niet oneindig diep blijkt, ga ik steeds verder terug in de tijd. The Ref is een zwarte komedie in Kerst-thema. Denis Leary en Kevin Spacey dragen deze film, en tillen het vrij banale verhaal naar een hoger niveau. Zeker het kijken waard, al moet we wel houden van een iets tragere film.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1222,'Jingle Bell Heist',2025,'706',96,'2025-12-07',8,4,4,6,5,6,'Netflix moet jaarlijks verplicht een zeker quota aan Kerstfilms halen, en dit is er eentje die daar moet mee helpen. Het is een bij de haren getrokken verhaal, en draagt niks bij tot het medialandschap. De stijl verklapt echter dat ze het willen positioneren als een iets alternatievere Kerstfilm. Maar helaas, weinig kan helpen om dit soort bagger toch aanvaardbaar te maken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1223,'Last Christmas',2019,'707',103,'2025-12-12',8,8,8,7,8,7,'Je hebt hele slechte rom-coms, een select groepje hele goeie, en dan een groot middenveld. Deze film hoort bij het hogere middenveld. Nee, het is geen klassieker, maar in het genre is het zeker niet slecht. Emilia Clarke en Emma Thompson zijn lichtpuntjes in deze maand vol baggerfilms. Een mooi Kerstverhaal, zo kan ik het het beste omschrijven.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1224,'Feast of the Seven Fishes',2019,'708',99,'2025-12-14',8,6,6,8,8,7,'Een Kerstfilm in een Italiaanse familie in de USA, het lijkt wel origineel. De cast doet het geweldig, en de eighties-vibe draagt bij tot de sfeer. Alleen is de plot heel dun, en het mondt uit op een eenvoudige rom-com, met een heel abrupt einde. Dit krijgt lovende kritieken, maar ik vind het een gemiste kans.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1225,'Happiest Season',2020,'709',102,'2025-12-15',8,6,7,6,6,7,'Kristen Stewart verbaast me enigzins in deze film, want ze draagt het verhaal quasi helemaal zelf. Het typisch Amerikaanse coming-out verhaal binnen een elitaire familie, het is inmiddels een klassiek recept. Het is ongemakkelijk en cringe, tot bij het sterke einde. Alleen laat de happy end een indruk van ongeloofwaardigheid na. Maar het is een Kerstfilm, natuurlijk.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1226,'The Night Before',2015,'482',101,'2025-12-16',8,7,7,8,7,8,'Als je een film met Seth Rogen en James Franco krijgt, dan weet je welke absurditeit je krijgt. Het is een typisch mannenavontuur geworden, die af en toe hilarisch is, maar naar gewoonte naar het einde toe verwatert. Dit zouden perfecte kortfilms zijn, maar anderhalf uur is gewoon te hoog gegrepen om te blijven boeien. Af en toe goed gelachen, wel.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1227,'Krampus',2015,'710',98,'2025-12-21',8,7,5,8,7,8,'Het klassieke Krampus verhaal, in een modern jasje, kon me niet bekoren. Het begint sterk, maar het feit dat het klaarblijkelijk niemand wat kan schelen dat er kinderen aan de lopende band verdwijnen, dat lijkt me toch wat vergezocht. Wel kan het boeien tot het einde. Ik kon wel het audiovisuele waarderen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1228,'Oh. What. Fun.',2025,'711',106,'2025-12-22',8,6,6,7,7,7,'Meestal laat ik dit soort komedie met plezier aan mij voorbij gaan, maar door de indrukwekkende cast, kreeg ik deze toch op de plank. Ik had gevreesd voor Kerstpulp, maar dat is het eigenlijk niet. Het is een vrij aangenaam kijkstuk geworden, gewoon goed gedaan. Het is alleen helemaal mijn ding niet.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1229,'The Advent Calendar',2021,'712',104,'2025-12-23',8,8,8,8,7,7,'In een poging om eens \"iets anders\" te vinden als Kerstfilm, is deze Franse horrorthriller mij opgevallen. Hoewel de korte inhoud niet echt aantrekt, krijgt deze toch lovende kritieken. En zeker terecht. Boeiend, weinig horrorcliches, en visueel sterk. Gewoon goed, en dat is opvallend tussen de jaarlijkse Kerstbagger.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1230,'Mission: Impossible - The Final Reckoning',2025,'701',169,'2026-01-31',8,8,7,9,9,9,'De (voorlopig) laatste film in de reeks maakt weer alle verwachtingen waar. Prachtige actie, maar totaal ongeloofwaardig. Zeker als je iets van AI kent, moet je er je echt wel even over zetten. Heel goeie klassieke actie/avonturenfilm.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1231,'Terminal',2018,'713',95,'2026-02-14',8,6,5,9,8,8,'Af en toe laat ik me overtuigen door de cast van een film alleen. Zeker het begin maakt alle verwachtingen waar. De visuele stijl is van begin tot einde spot-on. Alleen is het verhaal zelf weinig origineel, zelfs heel voorspelbaar. Inclusief het slot. Daardoor is het echt underwhelming. Ik zie het potentieel, maar er is niks mee gedaan.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1232,'Crime 101',2026,'714',140,'2026-02-17',5,8,8,8,9,8,'Dit is typisch zo\'n film die je \"per ongeluk\" ziet, waar je anders nooit zou naar omkijken, maar die positief verrast. Deze kozen we in de bioscoop, bij gebrek aan beter. Ik heb er echter geen seconde spijt van gehad. Leuke stijl, goeie cast, boeiend verhaal. Origineel is het niet, het is een typische heist-movie. Maar het is wel een hele goeie.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1233,'Old School',2003,'149',88,'2026-02-27',8,7,7,7,8,7,'Een absurde komedie met Will Ferrell, zoals die enkel in het begin van deze eeuw gemaakt werden. Absurd, niet te moeilijk, en soms een beetje fout. Hilarisch kan je dit niet noemen, maar als parodie op het college-comedy genre, kan dit wel tellen.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1234,'Project Hail Mary',2026,'440',156,'2026-04-14',5,9,8,9,8,9,'Dit verrassend epische verhaal over de redding van de Aarde, zorgt voor een fantastische filmavond. Boeiend, meeslepend, ondanks de duurtijd. Beeld en geluid zijn indrukwekkend. Een puntje van kritiek is dat het wel 2 films in 1 lijken. Een avonturen epos gemengd met stevige actie. De actie is goed, maar is er naar mijn mening te veel aan. Het blijft wel een topper.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1235,'Anaconda',2025,'699',99,'2026-04-18',8,7,6,6,7,7,'Een metakomedie over het maken van een film, waarbij alles enorm escaleert. Tot het absurde toe. Jack Black en Paul Rudd dragen het wel, want het verhaal is nogal voorspelbaar. Al bij al een degelijke komedie, waarbij het B-film aspect toch niet helemaal verstopt kan worden.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1236,'The Super Mario Galaxy Movie',2026,'658',98,'2026-05-10',5,6,5,8,8,8,'De eerste Mario movie was een success. Een kinderfilm, maar met ruimte voor nostalgie. Deze tweede film is jammer genoeg heel wat minder. Het verhaal is dunnetjes, de personages herhalend. Waar de eerste film nog wat krediet kreeg omdat het iets nieuws was, is dat volledige weg hier. En wat er overblijft, is tijdsverspilling.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1237,'Disclosure Day',2026,'8',145,'2026-07-07',5,8,8,8,8,9,'Om de zoveel jaar komt Spielberg met een blockbuster, die net even wat anders probeert te zijn. Dit is een boeiende film, maar origineel is het niet echt. Het is eigenlijk een vrij simpel plot, dat echter wel op een meesterlijk spannende manier op de kijker wordt losgelaten, stukje voor stukje. Het resultaat is een boeiende film, maar met een, vind ik, onbevredigend slot. Iets minder actie, en iets meer mysterie, dat zou het voor mij beter maken.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1238,'The Karate Kid',1984,'102',126,'2026-07-07',8,8,8,7,7,7,'Deze klassieker blijft tijdloos. Hoewel, de opbouw van de film toont je duidelijk dat het uit een andere tijd komt. Maar het verhaal blijft staan, na al die tijd. De film krijgt dus wat extra krediet, door zijn status.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1),
(1239,'Over Your Dead Body',2026,'715',105,'2026-07-27',8,8,8,7,8,8,'Dit is hoe een zwarte komedie hoort te zijn. Grappig, spannend, en af en toe over-the-top. Blijft ook boeiend. Het is echter wel een duidelijke veramerikanisering van een bestaande film, met alle typische valkuilen van dien. Zeker het kijken waard, al vraag je je nadien wel af wat je net hebt gezien.','2026-11-07 17:19:05.355093','2026-11-07 17:19:05.355093',1);
